window.AMG_ASSESSMENTS={"version":1,"reviewedDate":"2026-09-12","domains":["Maryland regulation","General insurance","Life foundations","Policy types","Provisions, options and riders","Annuities","Federal taxation","Qualified plans"],"blueprint":[24,8,14,8,11,7,6,2],"forms":[{"id":"D","title":"Starting diagnostic","minutes":0,"questions":[{"lesson":"25","prompt":"A customer pays the first premium with an application and receives a conditional receipt. What determines whether interim protection exists?","options":["The date the customer first considered buying insurance","Payment alone in every case","The receipt’s stated conditions and the actual facts","The producer’s personal belief that approval is likely"],"answer":2,"explanation":"A conditional receipt has conditions. Neither a payment alone nor optimism establishes that they are satisfied; the exact wording and facts control.","id":"D-3-4","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Transamerica SEC filing — Example of issuance and conditional coverage terms","url":"https://www.sec.gov/Archives/edgar/data/778209/000119312520258994/d44935dex9926qi.htm"},{"title":"Protective Life — Maryland application and conditional receipt packet","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"}]},{"lesson":"09","prompt":"Nora passes the Maryland life producer exam on Friday. Her license application is still pending. What is her status for personally soliciting life insurance?","options":["Her employer’s insurer appointment supplies her personal license.","She must obtain the required license before soliciting.","Her passing score provides authority until the application is decided.","She can solicit if a licensed coworker countersigns later."],"answer":1,"explanation":"Passing the exam is one qualification. The individual license, entity license and insurer appointment have distinct purposes; later countersigning does not supply missing authority.","id":"D-1-1","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-101"},{"title":"Maryland Insurance §10-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-102"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-105"},{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-109"},{"title":"Maryland Insurance §10-111","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-111"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-120","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-120"},{"title":"Maryland Insurance §10-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-201"},{"title":"Maryland Insurance §10-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-202"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Prelicensing education change","url":"https://insurance.maryland.gov/Producer/pages/default.aspx"}]},{"lesson":"12","prompt":"A producer deposits a customer’s premium into an account used to pay personal household bills. What is the central concern?","options":["Misuse or commingling of money held in a fiduciary capacity","A lawful premium-mode discount","An automatic change of policy beneficiary","Creation of a new risk classification"],"answer":0,"explanation":"Premium money must be handled under the applicable fiduciary and account rules. It is not personal spending money; beneficiary, underwriting and payment-mode concepts do not justify the deposit.","id":"D-1-2","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"48","prompt":"A client may need most savings next year for housing. Before recommending a long-surrender-period annuity, which concern is central?","options":["Whether all annuities have identical withdrawal rules","Liquidity needs and the cost of access under the contract","Whether a high illustrated rate cancels surrender charges","The producer’s preferred commission schedule"],"answer":1,"explanation":"The recommendation must consider the consumer’s profile and liquidity. Compensation or an illustration does not remove withdrawal restrictions or surrender costs.","id":"D-6-4","domain":5,"scored":true,"sources":[{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"COMAR 31.09.12.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.02"},{"title":"COMAR 31.09.12.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.03"},{"title":"COMAR 31.09.12.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.04"},{"title":"COMAR 31.09.12.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.05"},{"title":"COMAR 31.09.12.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.06"},{"title":"COMAR 31.09.12.08","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.08"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §16-114","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-114"},{"title":"IRS Publication 575 — pension and annuity income","url":"https://www.irs.gov/publications/p575"},{"title":"IRS Publication 970 — education benefits","url":"https://www.irs.gov/publications/p970"}]},{"lesson":"54","prompt":"An owner withdraws only regular Roth IRA contributions already included in income, with no conversions or earnings reached. What is the general result?","options":["No federal income tax or early-distribution additional tax on that contribution basis","Ordinary income on all withdrawn dollars","The withdrawal becomes an employer deduction","The 10% additional tax always applies to contributions before age 59½"],"answer":0,"explanation":"Roth IRA ordering distributes regular contributions first. Their return is generally free of income and additional tax; earnings and conversions have separate rules.","id":"D-7-3","domain":6,"scored":true,"sources":[{"title":"IRS Publication 590-A — IRA contributions","url":"https://www.irs.gov/publications/p590a"},{"title":"IRS Publication 590-B — IRA distributions","url":"https://www.irs.gov/publications/p590b"},{"title":"IRS — 2026 IRA limits","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-ira-contribution-limits"},{"title":"IRS — 2026 cost-of-living adjustments","url":"https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500"},{"title":"IRS Topic 451 — individual retirement arrangements","url":"https://www.irs.gov/taxtopics/tc451"},{"title":"26 USC §408A — Roth IRA requirements","url":"https://www.law.cornell.edu/uscode/text/26/408A"}]},{"lesson":"49","prompt":"An individual beneficiary receives a conventional covered life death benefit in a lump sum. Assume no transfer-for-value or other special exception and no separate interest payment. What is the general federal income-tax treatment?","options":["The entire payment is ordinary income.","Only the total premiums are excluded.","The death benefit is excluded from gross income.","It is a deductible contribution by the beneficiary."],"answer":2,"explanation":"The ordinary death-benefit exclusion applies on these stated facts. Separately paid interest and special exceptions require their own treatment.","id":"D-7-1","domain":6,"scored":true,"sources":[{"title":"IRS Publication 525 — life insurance proceeds","url":"https://www.irs.gov/publications/p525"},{"title":"26 USC §72 — distributions and modified endowment contracts","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"SEC-filed 2026 policy tax disclosure","url":"https://www.sec.gov/Archives/edgar/data/771726/000119312526172890/d89381d485bpos.htm"},{"title":"IRS — Interest received","url":"https://www.irs.gov/taxtopics/tc403"},{"title":"26 USC §101 — death benefits and transfer exceptions","url":"https://www.law.cornell.edu/uscode/text/26/101"},{"title":"IRS Form 706 instructions — insurance and lifetime transfers","url":"https://www.irs.gov/instructions/i706"},{"title":"IRS Publication 502 — nondeductible life premiums","url":"https://www.irs.gov/publications/p502"}]},{"lesson":"33","prompt":"A policy names a primary beneficiary and a contingent beneficiary. The primary beneficiary dies before the insured; no other primary survives. Subject to the policy’s terms, who is next in line?","options":["The contingent beneficiary","The insurer as its own beneficiary","The deceased primary beneficiary’s employer automatically","The producer automatically"],"answer":0,"explanation":"A contingent beneficiary is the next designated recipient when the primary designation cannot take, subject to the contract and law. The unrelated parties do not become beneficiaries by default.","id":"D-5-1","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-212","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-212"},{"title":"NAIC — Beneficiary designations","url":"https://content.naic.org/article/consumer-insight-life-insurance"},{"title":"Maryland Courts — Probate and guardianship FAQs","url":"https://www.mdcourts.gov/orphanscourt/faqs"},{"title":"MIA Bulletin 26-22 — Maryland-sitused life policy and divorce example","url":"https://insurance.maryland.gov/Pages/Bulletins/Bulletin-26-22.aspx"},{"title":"Maryland Courts and Judicial Proceedings §10-804 — rule before October 1, 2026","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gcj&section=10-804"},{"title":"Maryland Courts and Judicial Proceedings §10-805 — existing contract exception","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gcj&section=10-805"},{"title":"2026 Chapter 509 — simultaneous-death changes effective October 1, 2026","url":"https://mgaleg.maryland.gov/2026RS/chapters_noln/Ch_509_hb0596T.pdf"},{"title":"Maryland Estates and Trusts §4-105 — wills, divorce and annulment","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=get&section=4-105"}]},{"lesson":"47","prompt":"A fixed indexed annuity references an equity index for interest credits. Which ownership statement is correct?","options":["The owner directly owns each index stock.","The annuityowner does not thereby own the stocks in the index.","The credit must equal the index’s entire total return.","The index reference removes all contract charges and restrictions."],"answer":1,"explanation":"Index-linked crediting is a contract formula, often with limits and conditions. It is not direct stock ownership or a promise to receive the full index return.","id":"D-6-3","domain":5,"scored":true,"sources":[{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"SEC — Indexed annuity mechanics","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated-investor-bulletin-indexed-annuities"},{"title":"SEC — Variable annuity operation and costs","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated-5"}]},{"lesson":"26","prompt":"A parent needs a death benefit only during a stated 18-year dependency period and prioritizes the initial premium. Which design most directly matches that temporary need?","options":["Immediate single-life annuity","A cash-refund annuity","Limited-pay whole life solely because payments end","Level term for the needed period"],"answer":3,"explanation":"Term provides protection for a specified period. Limited-pay whole life limits the premium-paying schedule rather than necessarily limiting coverage; annuities address income needs.","id":"D-4-1","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"COMAR 31.04.17.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.09"},{"title":"New York DFS — General explanations of term designs; Maryland rules taught separately","url":"https://www.dfs.ny.gov/consumers/life_insurance"},{"title":"State Farm — A return-of-premium product example","url":"https://www.statefarm.com/insurance/life/term-life/return-of-premium"}]},{"lesson":"38","prompt":"A policy has a covered $180,000 death benefit and $14,000 total outstanding loan principal and interest. Assume no other adjustments. What is payable?","options":["$166,000","$194,000","$180,000","$14,000"],"answer":0,"explanation":"The total policy debt reduces the proceeds: $180,000 − $14,000 = $166,000. Borrowed value is not an extra death benefit.","id":"D-5-3","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-207"},{"title":"Maryland Insurance §16-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-208"},{"title":"MetLife — whole-life loan and automatic premium loan mechanics","url":"https://www.metlife.com/support-and-manage/current-customers/individual-life-insurance/products/wl-faqs/"},{"title":"MetLife — universal-life withdrawals and policy debt","url":"https://www.metlife.com/support-and-manage/current-customers/individual-life-insurance/products/ul-faqs/"},{"title":"MassMutual — cash value and education funding","url":"https://www.massmutual.com/financial-wellness/building-a-financial-foundation"}]},{"lesson":"28","prompt":"A universal-life owner pays less than the illustrated planned premium for several years. Which statement is most accurate?","options":["The insurer must replace missing premiums with dividends.","The policy’s sufficiency depends on charges, values and applicable guarantees; flexible payments do not eliminate lapse risk.","Any positive payment guarantees lifetime coverage.","The face amount must increase by the missed payments."],"answer":1,"explanation":"Universal life can allow flexible premiums, but values and guarantee conditions must support the contract. An illustration is not a promise that any chosen payment will keep it active.","id":"D-4-3","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Universal life insurance","url":"https://insurance.maryland.gov/Consumer/Pages/Universal-Life-Insurance.aspx"},{"title":"NAIC — Life insurance designs","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NYDFS — General whole-life product explanations; New York-specific rules are not Maryland rules","url":"https://www.dfs.ny.gov/faqs/consumer_faqs/life_insurance?page=2"},{"title":"Nationwide — Indexed universal life guide; product illustrations, not universal rates","url":"https://financial.nationwide.com/media/pdf/FLM-1376AO.pdf"},{"title":"Nationwide — Indexed UL Accumulator III product disclosures","url":"https://www.nationwide.com/personal/insurance/life/permanent/indexed-universal/indexed-ul-accumulator-III/"},{"title":"Nationwide — No-lapse guarantee universal life","url":"https://www.nationwide.com/personal/insurance/life/permanent/universal/no-lapse-guarantee-UL-II/"}]},{"lesson":"06","prompt":"A policyowner may stop paying future premiums, while the insurer must perform its covered promise if contractual conditions are met. Which contract characteristic is illustrated?","options":["Bilateral because both parties must keep paying","Unilateral","A contract without consideration","Speculative"],"answer":1,"explanation":"In this insurance-contract sense, the insurer makes the enforceable promise. The owner need not promise lifelong payments; stopping can end coverage rather than create an obligation to continue paying.","id":"D-2-4","domain":1,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-204"}]},{"lesson":"18","prompt":"Arun is the insured, his sister owns the policy, and a charity is the beneficiary. Who ordinarily exercises the policy’s ownership rights?","options":["The charity solely because it is the beneficiary","Arun solely because his life is insured","The producer who submitted the application","The sister as owner"],"answer":3,"explanation":"Ownership, insured life and beneficiary are separate roles. Policy rights ordinarily belong to the owner, subject to assignments and irrevocable designations.","id":"D-3-1","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"}]},{"lesson":"30","prompt":"A couple’s policy pays its specified death benefit only after both insureds have died. Which design is described?","options":["Survivorship or second-to-die life","Joint first-to-die life","Annual renewable term on one person","A child term rider"],"answer":0,"explanation":"Survivorship life uses the second death as its trigger. Joint first-to-die pays at the first death; the other choices do not describe the two-life trigger.","id":"D-4-4","domain":3,"scored":true,"sources":[{"title":"New York Life — First-death and survivorship coverage","url":"https://www.newyorklife.com/articles/joint-life-insurance"},{"title":"MassMutual — Juvenile policy ownership","url":"https://blog.massmutual.com/insurance/milestone-birthday-life-insurance"},{"title":"MassMutual — Example spouse and child term riders; product-specific terms","url":"https://www.massmutual.com/worksiteassets/wi5077_2020.pdf"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §13-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-101"},{"title":"Maryland Insurance §13-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-105"},{"title":"Maryland Insurance §13-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-106"},{"title":"Maryland Insurance §13-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-107"},{"title":"Maryland Insurance §13-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-109"},{"title":"Maryland Insurance §13-112","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-112"},{"title":"COMAR 31.13.01.25","url":"https://regs.maryland.gov/us/md/exec/comar/31.13.01.25"}]},{"lesson":"19","prompt":"A family lists $220,000 of debts and final expenses plus $480,000 of future income needs. It has $150,000 of assets already available for those same needs. Ignoring growth and taxes, what is the remaining need?","options":["$700,000","$550,000","$850,000","$330,000"],"answer":1,"explanation":"Add the stated needs, then subtract resources available for those needs: $220,000 + $480,000 − $150,000 = $550,000. Do not add assets as another expense.","id":"D-3-2","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Life insurance and annuities","url":"https://insurance.maryland.gov/Consumer/Pages/Life.aspx"},{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Guardian — Human life value and estimating coverage needs","url":"https://www.guardianlife.com/life-insurance/how-much-life-insurance-do-you-need"},{"title":"Social Security Administration — Survivor eligibility","url":"https://www.ssa.gov/survivor/eligibility"},{"title":"Social Security Administration — Survivor benefit amounts","url":"https://www.ssa.gov/survivor/amount"},{"title":"Social Security Administration — Survivors benefits","url":"https://www.ssa.gov/pubs/EN-05-10084.pdf"}]},{"lesson":"55","prompt":"A former employer sends an eligible pretax plan distribution directly to the receiving traditional IRA trustee for the participant. What type of movement is this?","options":["An owner-paid 60-day rollover with mandatory 20% withholding","A taxable Roth conversion necessarily","A direct rollover","A 1035 life-to-annuity exchange"],"answer":2,"explanation":"The payee and destination establish a direct rollover on these facts. It differs from a payment to the participant, a Roth conversion and an insurance exchange.","id":"D-7-4","domain":6,"scored":true,"sources":[{"title":"IRS — retirement plan and IRA rollovers","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/rollovers-of-retirement-plan-and-ira-distributions"},{"title":"IRS Topic 413 — rollover eligibility and withholding","url":"https://www.irs.gov/taxtopics/tc413"},{"title":"IRS Publication 590-A — rollover requirements","url":"https://www.irs.gov/publications/p590a"},{"title":"IRS Publication 590-B — inherited IRA transfers","url":"https://www.irs.gov/publications/p590b"}]},{"lesson":"57","prompt":"A qualified plan uses a permitted employer-contribution vesting schedule. How vested are the employee’s own salary-deferral contributions?","options":["100% vested","Vested only after five years in every plan","Subject to the same unvested percentage as all employer contributions","Vested only after retirement age"],"answer":0,"explanation":"Employee salary-deferral contributions are fully vested. A permitted schedule may apply to employer contributions; vesting is distinct from unrestricted withdrawal access.","id":"D-8-1","domain":7,"scored":true,"sources":[{"title":"26 USC §401 — qualification requirements","url":"https://www.law.cornell.edu/uscode/text/26/401"},{"title":"IRS — 401(k) qualification requirements","url":"https://www.irs.gov/retirement-plans/plan-sponsor/401k-plan-qualification-requirements"},{"title":"IRS — vesting","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-vesting"},{"title":"IRS — 401(k) participant overview","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/401k-resource-guide-plan-participants-401k-plan-overview"},{"title":"IRS — contributions and payroll taxes","url":"https://www.irs.gov/retirement-plans/retirement-plan-faqs-regarding-contributions-are-retirement-plan-contributions-subject-to-withholding-for-fica-medicare-or-federal-income-tax"},{"title":"IRS — exceptions to early-distribution tax","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"},{"title":"IRS — required minimum distributions","url":"https://www.irs.gov/retirement-plans/retirement-plan-and-ira-required-minimum-distributions-faqs"},{"title":"IRS — Publication 560","url":"https://www.irs.gov/publications/p560"}]},{"lesson":"40","prompt":"A life-policy waiver-of-premium rider becomes effective after its required disability waiting period and conditions are satisfied. What is its basic function?","options":["Pay every medical bill","Replace the death benefit with wages","Make every illness automatically qualifying","Waive covered premiums under the rider"],"answer":3,"explanation":"A waiver rider affects covered premiums after its stated conditions. It is not medical expense insurance or an unconditional wage-replacement promise.","id":"D-5-4","domain":4,"scored":true,"sources":[{"title":"New York Life — waiver of premium and policy riders","url":"https://www.newyorklife.com/articles/your-policy-your-way"},{"title":"SEC-filed monthly-deduction disability rider","url":"https://www.sec.gov/Archives/edgar/data/906982/000119312518115620/d673390dex99d4.htm"},{"title":"Transamerica SEC-filed prospectus — disability waiver and income riders","url":"https://www.sec.gov/Archives/edgar/data/778209/000119312525112108/d909081d497.htm"},{"title":"Gerber Life — juvenile payment protection rider","url":"https://www.gerberlife.com/gl/gu/refguides?action=open"}]},{"lesson":"17","prompt":"An agent calls guaranty protection a reason to ignore an insurer’s financial condition. What is the appropriate correction?","options":["Guaranty protection has limits and must not be used as a sales inducement.","The protection eliminates the need for a licensed insurer.","The protection guarantees projected dividends.","Guaranty protection makes every policy benefit unlimited."],"answer":0,"explanation":"Guaranty protection is a limited statutory safety net, not a product guarantee or a permitted inducement. It does not replace licensing or financial review.","id":"D-1-4","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §12-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-203"},{"title":"Maryland Insurance §27-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-303"},{"title":"Maryland Insurance §27-304","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-304"},{"title":"Maryland Insurance §16-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-109"},{"title":"Maryland Insurance §17-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-102"},{"title":"Maryland Insurance §9-402","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-402"},{"title":"Maryland Insurance §9-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-403"},{"title":"Maryland Insurance §9-405","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-405"},{"title":"Maryland Insurance §9-407","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-407"},{"title":"Maryland Insurance §9-409","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-409"},{"title":"Maryland Insurance §9-414","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-414"},{"title":"Maryland Life & Health Insurance Guaranty Corporation — FAQs","url":"https://www.mdlifega.org/FAQ"}]},{"lesson":"03","prompt":"An insurer accepts life policies and then contracts with another insurer to share part of its exposure. Which arrangement is illustrated?","options":["A beneficiary assignment","A mutual-fund investment","Reinsurance","A policyowner’s deductible"],"answer":2,"explanation":"Reinsurance transfers or shares insurer exposure with another insurer. It does not itself rewrite the original insured’s beneficiary designation or turn the life policy into a deductible arrangement.","id":"D-2-2","domain":1,"scored":true,"sources":[{"title":"Society of Actuaries — Risk and Insurance","url":"https://www.soa.org/globalassets/assets/files/edu/P-21-05.pdf"},{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"}]},{"lesson":"24","prompt":"An applicant has an above-average expected mortality risk but is still acceptable for coverage at a higher rate. Which classification fits?","options":["Preferred","Uninsurable by definition","Substandard","Declined"],"answer":2,"explanation":"A substandard or rated risk can be accepted on adjusted terms. Preferred means more favorable risk; declined means the insurer does not accept the application as offered.","id":"D-3-3","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-504"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Consumer Financial Protection Bureau — MIB consumer reports","url":"https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/consumer-reporting-companies/companies-list/mib-inc/"},{"title":"MIB — Request and correct your consumer file","url":"https://www.mib.com/request_your_record.html"}]},{"lesson":"46","prompt":"A retiree chooses income for life with no period-certain or refund feature. If the retiree dies after three payments, what ordinarily happens?","options":["The beneficiary receives the original premium plus all prior payments.","All unused premium is necessarily refunded.","Payments stop under the pure-life choice.","Payments continue for a statutory ten years."],"answer":2,"explanation":"A pure-life option has no added refund or guaranteed period. Those protections require the corresponding contract option.","id":"D-6-2","domain":5,"scored":true,"sources":[{"title":"IRS — common annuity payment types","url":"https://www.irs.gov/retirement-plans/annuities-a-brief-description"},{"title":"NAIC — payout options and living benefits","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance Administration — annuity income options","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"},{"title":"Insured Retirement Institute — cash refund and annuity terms","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Florida insurance regulator — general payout descriptions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"}]},{"lesson":"05","prompt":"An insurer’s written producer agreement expressly permits collecting initial premiums. Which authority describes this permission?","options":["Apparent authority only","Express authority","An irrevocable assignment","Estoppel"],"answer":1,"explanation":"Express authority is specifically granted. Apparent authority concerns appearances attributable to the principal; estoppel and assignment are different doctrines.","id":"D-2-3","domain":1,"scored":true,"sources":[{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland reported opinion — scope of insurance agency authority","url":"https://www.courts.state.md.us/data/opinions/cosa/2012/0915s09.pdf"}]},{"lesson":"37","prompt":"An owner stops premiums and elects reduced paid-up insurance using the available value. What is the ordinary tradeoff?","options":["An automatic increase in the original benefit","The original benefit for a temporary extended term","Cash paid now with no continuing life coverage","A smaller paid-up permanent death benefit"],"answer":3,"explanation":"Reduced paid-up buys a smaller permanent benefit without further premiums. Extended term and cash surrender are different nonforfeiture choices.","id":"D-5-2","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-301"},{"title":"Maryland Insurance §16-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-303"},{"title":"Maryland Insurance §16-304","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-304"},{"title":"Maryland Insurance §16-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-210"},{"title":"New York Life — nonforfeiture and paid-up definitions","url":"https://www.newyorklife.com/resources/glossary"},{"title":"New York DFS — general nonforfeiture concepts","url":"https://www.dfs.ny.gov/consumers/life_insurance"}]},{"lesson":"57","prompt":"An employee says a qualified plan is exempt from written rules because the investments are conservative. What is missing?","options":["A conservative investment automatically supplies qualification.","Qualification means all employee withdrawals are tax free.","Qualification is simply a credit rating of an insurer.","Qualification depends on the plan’s terms and operation meeting legal requirements."],"answer":3,"explanation":"Qualification is a legal status tied to plan terms and administration. It is not an investment-risk label, an insurer rating or a blanket distribution-tax exemption.","id":"D-8-4","domain":7,"scored":true,"sources":[{"title":"26 USC §401 — qualification requirements","url":"https://www.law.cornell.edu/uscode/text/26/401"},{"title":"IRS — 401(k) qualification requirements","url":"https://www.irs.gov/retirement-plans/plan-sponsor/401k-plan-qualification-requirements"},{"title":"IRS — vesting","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-vesting"},{"title":"IRS — 401(k) participant overview","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/401k-resource-guide-plan-participants-401k-plan-overview"},{"title":"IRS — contributions and payroll taxes","url":"https://www.irs.gov/retirement-plans/retirement-plan-faqs-regarding-contributions-are-retirement-plan-contributions-subject-to-withholding-for-fica-medicare-or-federal-income-tax"},{"title":"IRS — exceptions to early-distribution tax","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"},{"title":"IRS — required minimum distributions","url":"https://www.irs.gov/retirement-plans/retirement-plan-and-ira-required-minimum-distributions-faqs"},{"title":"IRS — Publication 560","url":"https://www.irs.gov/publications/p560"}]},{"lesson":"27","prompt":"A whole-life contract requires 20 annual premiums and then remains in force as paid-up coverage under its terms. What ends after the twentieth payment?","options":["The insured’s lifetime coverage automatically","The required premium-paying period","The beneficiary’s designation automatically","Every policy value"],"answer":1,"explanation":"Limited-pay whole life separates premium duration from coverage duration. Paid-up does not mean expired or devoid of values.","id":"D-4-2","domain":3,"scored":true,"sources":[{"title":"NAIC — Life insurance designs","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NYDFS — General whole-life product explanations; New York-specific rules are not Maryland rules","url":"https://www.dfs.ny.gov/faqs/consumer_faqs/life_insurance?page=2"},{"title":"MassMutual — Whole life and premium-payment periods","url":"https://blog.massmutual.com/insurance/understanding-whole-life-insurance"},{"title":"Washington insurance regulator — Product definitions, graded-premium whole life","url":"https://www.insurance.wa.gov/sites/default/files/documents/life-accident-health-annuity-crediti-pcm_6_1.pdf"}]},{"lesson":"44","prompt":"In an annuity, whose life commonly measures life-contingent payments?","options":["The producer’s","The insurer’s chief executive’s","Every beneficiary’s jointly in all contracts","The annuitant’s"],"answer":3,"explanation":"The annuitant is the measuring life. The owner controls contractual rights and the beneficiary has designated death rights; these roles can differ.","id":"D-6-1","domain":5,"scored":true,"sources":[{"title":"NAIC — annuities overview","url":"https://content.naic.org/insurance-topics/annuities"},{"title":"NAIC — buyer’s guide for deferred annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Investor.gov — annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"Florida insurance regulator — general annuity role definitions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"},{"title":"Maryland Insurance Administration — Annuities 101","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"}]},{"lesson":"51","prompt":"A post-1982 nonqualified deferred annuity has $75,000 value and $60,000 basis. Its owner takes a $10,000 partial withdrawal before annuitization. Ignore charges and exceptions. How much is ordinary income?","options":["$15,000","$0","$10,000","$2,000"],"answer":2,"explanation":"The $15,000 gain comes out first. The $10,000 withdrawal is entirely within that gain; $15,000 is the pre-withdrawal gain, not the amount distributed.","id":"D-7-2","domain":6,"scored":true,"sources":[{"title":"IRS Publication 575 — annuity distributions","url":"https://www.irs.gov/publications/p575"},{"title":"26 USC §72 — annuity income and distribution rules","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"IRS Publication 939 — General Rule","url":"https://www.irs.gov/publications/p939"}]},{"lesson":"58","prompt":"A nonprofit eligible employer is considering a 403(b) arrangement. Which funding statement is correct?","options":["Any for-profit corporation becomes eligible by buying an annuity.","The number 403(b) means no retirement-plan rules apply.","An eligible 403(b) may use qualifying annuity contracts or custodial mutual-fund accounts.","Every 403(b) must buy whole life insurance."],"answer":2,"explanation":"Employer eligibility and permitted funding arrangements are separate requirements. A 403(b) is not confined to annuities and is not available to an ineligible employer solely because it buys one.","id":"D-8-2","domain":7,"scored":true,"sources":[{"title":"IRS — SEP plans","url":"https://www.irs.gov/retirement-plans/plan-sponsor/simplified-employee-pension-plan-sep"},{"title":"IRS — self-employed retirement plans and Keogh terminology","url":"https://www.irs.gov/retirement-plans/retirement-plans-for-self-employed-people"},{"title":"IRS — profit-sharing plans","url":"https://www.irs.gov/retirement-plans/choosing-a-retirement-plan-profit-sharing-plan"},{"title":"IRS — 401(k) plans","url":"https://www.irs.gov/retirement-plans/401k-plans"},{"title":"IRS — SIMPLE IRA plans","url":"https://www.irs.gov/retirement-plans/plan-sponsor/simple-ira-plan"},{"title":"IRS — 403(b) overview","url":"https://www.irs.gov/retirement-plans/403b-plan-fix-it-guide-403b-plan-overview"},{"title":"IRS — Notice 2024-2 — Roth SEP and SIMPLE options","url":"https://www.irs.gov/irb/2024-02_IRB#NOT-2024-2"},{"title":"IRS — vesting","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-vesting"},{"title":"IRS — exceptions to early-distribution tax","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"}]},{"lesson":"15","prompt":"A proposed new policy would be funded by borrowing against an existing life policy. Before treating the sale as unrelated new coverage, what must the producer investigate?","options":["Whether the applicant has ever owned an annuity","Only whether the original policy is immediately surrendered","Only whether the new insurer has a different name","Whether the transaction meets the replacement definition and triggers replacement duties"],"answer":3,"explanation":"Replacement can include specified use of existing values, not only immediate cancellation. Same-company identity and an unrelated annuity history do not settle the definition.","id":"D-1-3","domain":0,"scored":true,"sources":[{"title":"COMAR 31.09.05.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.02"},{"title":"COMAR 31.09.05.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.03"},{"title":"COMAR 31.09.05.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.04"},{"title":"COMAR 31.09.05.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.05"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.09.05.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.07"},{"title":"COMAR 31.09.05.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.10"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"}]},{"lesson":"01","prompt":"A shop’s blocked emergency exit increases the chance that an incident will cause serious harm. The blocked exit is best described as what?","options":["A hazard","A settlement option","Risk pooling","The resulting loss"],"answer":0,"explanation":"A hazard is a condition increasing the chance or severity of loss. Loss is the harm after the event; pooling and settlement describe other functions.","id":"D-2-1","domain":1,"scored":true,"sources":[]},{"lesson":"58","prompt":"A small employer establishes a standard SEP IRA rather than a grandfathered SARSEP. Who ordinarily makes its plan contributions?","options":["Only the insurer from policy dividends","Only beneficiaries after an employee dies","Employees through new SEP salary-reduction elections","The employer"],"answer":3,"explanation":"A regular SEP is employer funded. The old SARSEP salary-reduction arrangement is a different grandfathered design; a new ordinary SEP does not create that feature.","id":"D-8-3","domain":7,"scored":true,"sources":[{"title":"IRS — SEP plans","url":"https://www.irs.gov/retirement-plans/plan-sponsor/simplified-employee-pension-plan-sep"},{"title":"IRS — self-employed retirement plans and Keogh terminology","url":"https://www.irs.gov/retirement-plans/retirement-plans-for-self-employed-people"},{"title":"IRS — profit-sharing plans","url":"https://www.irs.gov/retirement-plans/choosing-a-retirement-plan-profit-sharing-plan"},{"title":"IRS — 401(k) plans","url":"https://www.irs.gov/retirement-plans/401k-plans"},{"title":"IRS — SIMPLE IRA plans","url":"https://www.irs.gov/retirement-plans/plan-sponsor/simple-ira-plan"},{"title":"IRS — 403(b) overview","url":"https://www.irs.gov/retirement-plans/403b-plan-fix-it-guide-403b-plan-overview"},{"title":"IRS — Notice 2024-2 — Roth SEP and SIMPLE options","url":"https://www.irs.gov/irb/2024-02_IRB#NOT-2024-2"},{"title":"IRS — vesting","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-vesting"},{"title":"IRS — exceptions to early-distribution tax","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"}]}]},{"id":"A","title":"Timed Form A","minutes":105,"questions":[{"lesson":"11","prompt":"A producer forges an applicant’s signature to meet an underwriting deadline, although the applicant later says the coverage was wanted. Which conclusion follows?","options":["Later approval automatically erases the forgery.","Only the insurer can discipline the producer’s state license.","The forgery remains a potential ground for producer discipline.","Forgery is relevant only if a death claim is denied."],"answer":2,"explanation":"Forging an insurance document is a statutory discipline ground. Later agreement or a paid claim does not turn the original act into an authorized signature.","id":"A-1-11","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"54","prompt":"A Roth IRA owner meets the applicable five-tax-year period and is over age 59½ when taking a distribution. Assume no unusual exception issue. What is the ordinary qualified-distribution result?","options":["The qualified distribution, including earnings, is federally income-tax free.","The distribution creates an employer deduction","Every qualified payment is subject to a 10% early-distribution tax.","All earnings remain ordinary income despite qualification."],"answer":0,"explanation":"The Roth qualified-distribution conditions allow federal tax-free treatment including earnings. Regular contribution returns and conversion clocks are separate rules when a distribution is not qualified.","id":"A-7-07","domain":6,"scored":false,"sources":[{"title":"IRS Publication 590-A — IRA contributions","url":"https://www.irs.gov/publications/p590a"},{"title":"IRS Publication 590-B — IRA distributions","url":"https://www.irs.gov/publications/p590b"},{"title":"IRS — 2026 IRA limits","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-ira-contribution-limits"},{"title":"IRS — 2026 cost-of-living adjustments","url":"https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500"},{"title":"IRS Topic 451 — individual retirement arrangements","url":"https://www.irs.gov/taxtopics/tc451"},{"title":"26 USC §408A — Roth IRA requirements","url":"https://www.law.cornell.edu/uscode/text/26/408A"}]},{"lesson":"45","prompt":"A fictional deferred annuity has $120,000 value and a 4% surrender charge on the full amount, with no allowance, MVA or other adjustment. What is net cash before tax?","options":["$120,000","$124,800","$115,200","$4,800"],"answer":2,"explanation":"The charge is $120,000 × 4% = $4,800; net is $115,200. Contract charges are separate from any federal income or additional tax.","id":"A-6-08","domain":5,"scored":false,"sources":[{"title":"NAIC — immediate and deferred classifications","url":"https://content.naic.org/insurance-topics/annuities"},{"title":"NAIC — deferred annuity buyer’s guide","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance §16-501","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-501"},{"title":"Maryland Insurance §16-503","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-503"},{"title":"Maryland Insurance §16-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-504"},{"title":"Insured Retirement Institute — annuity terminology","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Massachusetts insurance regulator — general bailout mechanics","url":"https://www.mass.gov/info-details/buying-life-insurance-and-annuities-in-massachusetts-part-three"},{"title":"SEC-filed 2026 annuity withdrawal provisions","url":"https://www.sec.gov/Archives/edgar/data/1048606/000110465926053840/tm265210d5_497.htm"}]},{"lesson":"04","prompt":"An insurer is incorporated in Virginia and licensed to transact in Maryland. How is its domicile classified from Maryland’s perspective?","options":["Foreign","Domestic","Alien","Unauthorized solely because it is from Virginia"],"answer":0,"explanation":"Foreign means organized in another U.S. state. Domestic means Maryland-organized; alien means organized outside the United States. Admission is a separate question.","id":"A-2-04","domain":1,"scored":true,"sources":[{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"},{"title":"NAIC — Insurance Topics","url":"https://content.naic.org/insurance-topics"},{"title":"Maryland insurer search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"},{"title":"Maryland Insurance §4-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=4-203"}]},{"lesson":"10","prompt":"A covered criminal prosecution has reached the producer’s initial court appearance, but no verdict has been entered. When does Maryland’s ordinary 30-day reporting clock start?","options":["Only after a guilty verdict","At the next license renewal","At the initial court appearance","After the producer finishes all appeals"],"answer":2,"explanation":"The criminal reporting duty is triggered by the initial court appearance, subject to the statutory exclusion for specified vehicle-law misdemeanors. Final disposition is the separate administrative-action trigger.","id":"A-1-06","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"09","prompt":"A Maryland agency hires a licensed life producer and an unlicensed receptionist. The receptionist begins recommending coverage amounts to callers. Which fact most directly defeats reliance on a clerical exception?","options":["The receptionist answers a telephone rather than email.","The receptionist’s actual duties now include solicitation or negotiation.","The producer uses an independent-contractor agreement.","The agency employs more than one person."],"answer":1,"explanation":"The exemption depends on duties and compensation. Substantive selling activity changes the analysis; the communication channel and agency headcount do not create or remove licensing authority.","id":"A-1-01","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-101"},{"title":"Maryland Insurance §10-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-102"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-105"},{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-109"},{"title":"Maryland Insurance §10-111","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-111"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-120","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-120"},{"title":"Maryland Insurance §10-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-201"},{"title":"Maryland Insurance §10-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-202"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Prelicensing education change","url":"https://insurance.maryland.gov/Producer/pages/default.aspx"}]},{"lesson":"36","prompt":"A beneficiary leaves death proceeds with the insurer under an interest-only settlement. What is paid periodically under that option?","options":["An automatic stock dividend","The stated interest, while the principal remains under the arrangement","The entire principal with every interest payment","A guaranteed number of life premiums"],"answer":1,"explanation":"The interest-only option separates periodic interest from retained principal. Rights to withdraw or distribute principal follow the arrangement; it is not repaid anew with each interest payment.","id":"A-5-06","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-209"},{"title":"Maryland Insurance §16-211","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-211"},{"title":"Maryland Insurance §16-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-108"},{"title":"Maryland Insurance §16-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-109"},{"title":"New York Life — claim kit and available settlement alternatives","url":"https://www.newyorklife.com/assets/docs/pdfs/nyl-internet/file-types/Life-Claim-Form.pdf"},{"title":"IRS — annuity payment forms","url":"https://www.irs.gov/retirement-plans/annuities-a-brief-description"},{"title":"New York Life — life income and joint-and-survivor definitions","url":"https://www.newyorklife.com/resources/glossary"}]},{"lesson":"10","prompt":"A Maryland producer changes a listed email address but keeps the same employer and residence. Which statement is correct?","options":["The ordinary 30-day license-information change duty still applies.","Updating the employer’s directory substitutes for notifying MIA.","The change can always wait until biennial renewal.","Only a residential move triggers any reporting."],"answer":0,"explanation":"The ordinary individual license-information rule includes email changes. An agency directory update does not establish that the required regulator notification occurred.","id":"A-1-25","domain":0,"scored":false,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"10","prompt":"An out-of-state regulator enters a final adverse administrative order against a Maryland producer. Which report is required under the ordinary rule?","options":["Wait until a Maryland client complains.","Report only if the order involves a felony conviction.","Send only an internal agency memo at the next renewal.","Report the covered action to the Commissioner within 30 days of final disposition, with relevant documents."],"answer":3,"explanation":"Covered adverse administrative actions have their own 30-day final-disposition rule and supporting-document requirement. They are not limited to criminal convictions.","id":"A-1-07","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"26","prompt":"A term policy allows conversion to a permitted permanent form within its conversion period without new evidence of insurability. What does this privilege protect?","options":["The opportunity to obtain the specified permanent coverage despite a later health change","The right to keep the original term premium forever","An automatic cash refund on every conversion","A guarantee that every permanent product is available"],"answer":0,"explanation":"Conversion protects access subject to its terms and deadlines. It does not necessarily preserve the old premium or permit any product and amount the owner chooses.","id":"A-4-02","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"COMAR 31.04.17.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.09"},{"title":"New York DFS — General explanations of term designs; Maryland rules taught separately","url":"https://www.dfs.ny.gov/consumers/life_insurance"},{"title":"State Farm — A return-of-premium product example","url":"https://www.statefarm.com/insurance/life/term-life/return-of-premium"}]},{"lesson":"38","prompt":"A valid life-policy loan accrues interest that the owner does not pay out of pocket. Which consequence must be monitored?","options":["Debt can grow and reduce available values and death proceeds, potentially threatening coverage.","The loan is always a separate unlimited death benefit.","Every unpaid interest dollar becomes a guaranteed dividend","Interest automatically disappears at the next anniversary."],"answer":0,"explanation":"Policy debt includes accrued interest as provided by the contract. Increasing debt can impair values and coverage; it is not free money or an extra benefit.","id":"A-5-08","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-207"},{"title":"Maryland Insurance §16-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-208"},{"title":"MetLife — whole-life loan and automatic premium loan mechanics","url":"https://www.metlife.com/support-and-manage/current-customers/individual-life-insurance/products/wl-faqs/"},{"title":"MetLife — universal-life withdrawals and policy debt","url":"https://www.metlife.com/support-and-manage/current-customers/individual-life-insurance/products/ul-faqs/"},{"title":"MassMutual — cash value and education funding","url":"https://www.massmutual.com/financial-wellness/building-a-financial-foundation"}]},{"lesson":"05","prompt":"An insurer supplies signs and business materials presenting a producer as its representative. A customer reasonably relies on that appearance, although the producer exceeded an undisclosed internal limit. Which authority issue should be examined?","options":["An automatic state-license expansion","A transfer of policy ownership","Authority created solely by any claim the producer makes","Apparent authority attributable to the principal’s conduct"],"answer":3,"explanation":"Apparent authority concerns the principal’s manifestations and reasonable reliance. A producer cannot create unlimited authority merely by asserting it.","id":"A-2-05","domain":1,"scored":true,"sources":[{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland reported opinion — scope of insurance agency authority","url":"https://www.courts.state.md.us/data/opinions/cosa/2012/0915s09.pdf"}]},{"lesson":"58","prompt":"A business has no accounting profit this year but wants to make a permitted contribution to its profit-sharing retirement plan. Which statement is accurate?","options":["A profit-sharing contribution automatically becomes a life-insurance dividend","Every profit-sharing plan requires employee salary reduction.","The name requires positive accounting profit before any contribution.","A contribution is not necessarily barred solely because the business had no profit."],"answer":3,"explanation":"A qualified profit-sharing design can allow discretionary employer contributions without requiring actual profits, subject to plan terms and legal limits. It differs from an employee elective 401(k) feature.","id":"A-8-02","domain":7,"scored":true,"sources":[{"title":"IRS — SEP plans","url":"https://www.irs.gov/retirement-plans/plan-sponsor/simplified-employee-pension-plan-sep"},{"title":"IRS — self-employed retirement plans and Keogh terminology","url":"https://www.irs.gov/retirement-plans/retirement-plans-for-self-employed-people"},{"title":"IRS — profit-sharing plans","url":"https://www.irs.gov/retirement-plans/choosing-a-retirement-plan-profit-sharing-plan"},{"title":"IRS — 401(k) plans","url":"https://www.irs.gov/retirement-plans/401k-plans"},{"title":"IRS — SIMPLE IRA plans","url":"https://www.irs.gov/retirement-plans/plan-sponsor/simple-ira-plan"},{"title":"IRS — 403(b) overview","url":"https://www.irs.gov/retirement-plans/403b-plan-fix-it-guide-403b-plan-overview"},{"title":"IRS — Notice 2024-2 — Roth SEP and SIMPLE options","url":"https://www.irs.gov/irb/2024-02_IRB#NOT-2024-2"},{"title":"IRS — vesting","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-vesting"},{"title":"IRS — exceptions to early-distribution tax","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"}]},{"lesson":"27","prompt":"An owner pays one required premium for a whole-life contract. What is the premium schedule called?","options":["Flexible premium requiring ongoing elections","Annual renewable","Ten-year certain","Single premium"],"answer":3,"explanation":"Single-premium life is funded by one required premium under the contract. That funding pattern differs from annually renewable term or an annuity payout period; tax classification needs separate review.","id":"A-4-03","domain":3,"scored":true,"sources":[{"title":"NAIC — Life insurance designs","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NYDFS — General whole-life product explanations; New York-specific rules are not Maryland rules","url":"https://www.dfs.ny.gov/faqs/consumer_faqs/life_insurance?page=2"},{"title":"MassMutual — Whole life and premium-payment periods","url":"https://blog.massmutual.com/insurance/understanding-whole-life-insurance"},{"title":"Washington insurance regulator — Product definitions, graded-premium whole life","url":"https://www.insurance.wa.gov/sites/default/files/documents/life-accident-health-annuity-crediti-pcm_6_1.pdf"}]},{"lesson":"02","prompt":"In a fictional pool of 2,500 comparable exposures, each has a 0.8% annual claim probability. What does 20 expected claims mean?","options":["Exactly 20 named people must claim this year","An average implied by the assumptions, not a guaranteed count or identification of claimants","The pool cannot experience 21 claims","Each member has a 20% claim probability"],"answer":1,"explanation":"2,500 × 0.008 = 20 expected claims. Expected frequency is a group average under assumptions, not an exact annual promise.","id":"A-2-02","domain":1,"scored":true,"sources":[]},{"lesson":"13","prompt":"An agent offers to return part of the commission to a buyer as an unlisted inducement prohibited by the applicable Maryland rule. The buyer says everyone benefits. What is the result?","options":["Agreement makes any rebate lawful.","The buyer’s agreement does not make the prohibited inducement lawful.","The insurer’s financial rating determines whether the inducement is allowed.","A rebate is permitted whenever the premium is paid annually."],"answer":1,"explanation":"An otherwise prohibited rebate or inducement is not legalized by customer consent, premium mode or insurer rating. Apply the actual statute and any express exception.","id":"A-1-16","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"Maryland Insurance §27-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-204"},{"title":"Maryland Insurance §27-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-205"},{"title":"Maryland Insurance §27-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-206"},{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-209"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"},{"title":"Maryland Insurance §27-214","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-214"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"}]},{"lesson":"12","prompt":"A producer receives premium money and neither promptly remits it nor places it in a separate premium account. Which ordinary remittance benchmark matters under Maryland’s premium-account rule?","options":["Thirty days after the policy anniversary","Close of the fifth calendar day including receipt","Close of the fifth business day following receipt","The next quarterly commission statement"],"answer":2,"explanation":"The rule defines prompt remittance using the fifth business day following receipt. If not promptly remitted, the money must be maintained in a compliant premium account.","id":"A-1-12","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"13","prompt":"To induce a switch, a producer knowingly tells a client that the existing policy has no cash value even though it does. Which misconduct best describes the misleading replacement tactic?","options":["Twisting through misrepresentation","A permitted guaranteed-insurability election","An automatic nonforfeiture choice","Lawful underwriting classification"],"answer":0,"explanation":"Using false or misleading comparisons to induce a policy change is twisting. A contractual election or legitimate risk classification does not describe deceptive sales statements.","id":"A-1-15","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"Maryland Insurance §27-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-204"},{"title":"Maryland Insurance §27-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-205"},{"title":"Maryland Insurance §27-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-206"},{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-209"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"},{"title":"Maryland Insurance §27-214","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-214"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"}]},{"lesson":"20","prompt":"A viatical broker receives compensation from a provider while negotiating for the viator. To whom is the broker’s statutory fiduciary duty owed?","options":["The policy’s former contingent beneficiary exclusively","The highest-paying provider instead","The producer’s original insurer exclusively","The viator"],"answer":3,"explanation":"The broker must follow the viator’s instructions and act in the viator’s best interest regardless of payment source. Compensation does not redirect that fiduciary duty.","id":"A-3-06","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §8-601","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-601"},{"title":"Maryland Insurance §8-602","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-602"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-604","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-604"},{"title":"Maryland Insurance §8-605","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605"},{"title":"Maryland Insurance §8-605.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605.1"},{"title":"Maryland Insurance §8-606","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-606"},{"title":"Maryland Insurance §8-607","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-607"},{"title":"Maryland Insurance §8-609","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-609"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"Maryland Insurance §8-610.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610.1"},{"title":"Maryland Insurance §27-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-403"}]},{"lesson":"46","prompt":"A life-with-15-years-certain option has made nine years of scheduled payments when the annuitant dies. What ordinarily continues under the guarantee?","options":["Payments for the beneficiary’s lifetime regardless of the guarantee","Fifteen new years beginning at death","No payments because every life option is pure life","The remaining six years of payments"],"answer":3,"explanation":"The certain period is measured from the original payment start. Nine years used leaves six guaranteed years; it does not restart at death or become the beneficiary’s life annuity.","id":"A-6-03","domain":5,"scored":true,"sources":[{"title":"IRS — common annuity payment types","url":"https://www.irs.gov/retirement-plans/annuities-a-brief-description"},{"title":"NAIC — payout options and living benefits","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance Administration — annuity income options","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"},{"title":"Insured Retirement Institute — cash refund and annuity terms","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Florida insurance regulator — general payout descriptions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"}]},{"lesson":"16","prompt":"An employee dies during the period in which the employee is entitled to convert group life, before the individual contract is effective. No conversion application or premium was submitted. Which rule applies?","options":["The amount available for conversion is payable under the group policy.","No benefit can be paid solely because the conversion premium was not submitted.","Only accumulated group premiums are returned.","The insurer must wait until a conversion application is signed by the deceased."],"answer":0,"explanation":"The statutory death-during-conversion protection does not depend on an application or first premium. It applies to the amount the insured was entitled to convert.","id":"A-1-22","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-302","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-302"},{"title":"Maryland Insurance §17-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-303"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"Maryland Insurance §17-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-104"}]},{"lesson":"23","prompt":"During field underwriting, an applicant asks the producer to omit a recent medical evaluation because the result was normal. Which response is appropriate?","options":["Promise that the insurer will never seek an attending physician statement.","Record the information requested by the application accurately and let underwriting evaluate it.","Replace the question with a less specific handwritten statement.","Omit it whenever the producer believes it is harmless."],"answer":1,"explanation":"Field underwriting requires complete, accurate collection of requested information. The producer should not decide to suppress it based on an informal assessment of significance.","id":"A-3-11","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"COMAR 31.04.17.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.06"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"FinCEN — Insurance company anti-money-laundering requirements","url":"https://www.fincen.gov/resources/statutes-regulations/guidance/anti-money-laundering-program-and-suspicious-activity"}]},{"lesson":"26","prompt":"A life policy’s death benefit declines on a stated schedule while the premium remains level during the selected period. Which design best fits?","options":["Straight whole life with a guaranteed level benefit","A life-income annuity","Decreasing term","Increasing term"],"answer":2,"explanation":"Decreasing term describes the scheduled benefit decline. Premium pattern and benefit pattern are separate; a level premium does not mean a level death benefit.","id":"A-4-01","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"COMAR 31.04.17.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.09"},{"title":"New York DFS — General explanations of term designs; Maryland rules taught separately","url":"https://www.dfs.ny.gov/consumers/life_insurance"},{"title":"State Farm — A return-of-premium product example","url":"https://www.statefarm.com/insurance/life/term-life/return-of-premium"}]},{"lesson":"19","prompt":"An estate consists mainly of a family business and real property. Survivors may need cash quickly for settlement costs without a forced sale. Which life-insurance use is most directly illustrated?","options":["A guarantee that assets never decline","Estate liquidity","Eliminating all estate-tax rules","Replacing the legal ownership records"],"answer":1,"explanation":"A death benefit can supply cash when estate assets are illiquid. It does not erase all taxes or transfer rules; ownership, beneficiary and tax planning still matter.","id":"A-3-04","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Life insurance and annuities","url":"https://insurance.maryland.gov/Consumer/Pages/Life.aspx"},{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Guardian — Human life value and estimating coverage needs","url":"https://www.guardianlife.com/life-insurance/how-much-life-insurance-do-you-need"},{"title":"Social Security Administration — Survivor eligibility","url":"https://www.ssa.gov/survivor/eligibility"},{"title":"Social Security Administration — Survivor benefit amounts","url":"https://www.ssa.gov/survivor/amount"},{"title":"Social Security Administration — Survivors benefits","url":"https://www.ssa.gov/pubs/EN-05-10084.pdf"}]},{"lesson":"12","prompt":"For a placement service where the insurer pays no commission, assume the Maryland statutory fee exception applies to a $2,400 premium. What is the maximum fee under its 15% ceiling?","options":["$360","$2,400","$240","$3,600"],"answer":0,"explanation":"The specified ceiling is $2,400 × 0.15 = $360. It is a conditional fee exception, not a surcharge permitted on every insurance sale.","id":"A-1-14","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"18","prompt":"A married owner validly purchases insurance on the owner’s own life and names a close friend as beneficiary. The friend does not depend financially on the owner. Which distinction matters?","options":["A friend’s lack of dependence automatically voids every self-procured policy.","Self-procured coverage generally allows this beneficiary choice.","The friend must own the policy to receive any benefit.","Only legal heirs can ever be beneficiaries of a self-procured policy."],"answer":1,"explanation":"The procurement requirement differs from beneficiary selection on one’s own life. Do not turn the interest required to obtain coverage on someone else into a universal beneficiary-eligibility test.","id":"A-3-02","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"}]},{"lesson":"25","prompt":"A policy issued at a higher premium is delivered with a required good-health statement and premium difference still outstanding. What should the producer establish before promising effectiveness?","options":["Only that the original application requested the lower premium","Only that the envelope was mailed","Only that the insurer assigned a policy number","Acceptance of the changed terms and satisfaction of the stated delivery and coverage conditions"],"answer":3,"explanation":"A policy number or shipment is not proof that counteroffer acceptance and delivery conditions have been satisfied. Apply the actual receipt and policy requirements.","id":"A-3-14","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Transamerica SEC filing — Example of issuance and conditional coverage terms","url":"https://www.sec.gov/Archives/edgar/data/778209/000119312520258994/d44935dex9926qi.htm"},{"title":"Protective Life — Maryland application and conditional receipt packet","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"}]},{"lesson":"06","prompt":"An applicant submits an application and premium. The insurer instead offers coverage with a higher premium because of underwriting. What is the changed offer ordinarily treated as?","options":["Automatic rescission of all insurance the applicant owns","A counteroffer requiring the applicant’s acceptance","A beneficiary assignment","Acceptance of every original term without change"],"answer":1,"explanation":"Offering materially different terms is a counteroffer. The applicant’s acceptance and applicable coverage conditions matter; submission alone does not establish agreement to the changed terms.","id":"A-2-06","domain":1,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-204"}]},{"lesson":"04","prompt":"A producer is asked to solicit ordinary life coverage for an insurer lacking Maryland authority. No statutory exception applies. The producer has an active license. What should the producer do?","options":["Proceed if the customer signs a waiver of state protections.","Proceed if the proposed insurer is highly rated.","Decline the unauthorized-insurer transaction.","Proceed because the producer license authorizes every insurer."],"answer":2,"explanation":"A producer license does not authorize representing an unauthorized insurer contrary to §4–203. Financial ratings and customer waivers do not supply an exception.","id":"A-1-24","domain":0,"scored":true,"sources":[{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"},{"title":"NAIC — Insurance Topics","url":"https://content.naic.org/insurance-topics"},{"title":"Maryland insurer search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"},{"title":"Maryland Insurance §4-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=4-203"}]},{"lesson":"33","prompt":"A beneficiary designation is irrevocable. The owner wants to make a change affecting the protected beneficiary’s rights. What should be checked?","options":["Whether the producer’s signature can replace every consent","Whether that beneficiary’s consent is required under the contract and law","Whether irrevocable means the beneficiary must be the insured","Whether every beneficiary designation expires at the next premium"],"answer":1,"explanation":"An irrevocable designation restricts changes affecting the beneficiary’s protected interest. It does not turn the beneficiary into the insured or make the producer the consenting party.","id":"A-5-02","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-212","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-212"},{"title":"NAIC — Beneficiary designations","url":"https://content.naic.org/article/consumer-insight-life-insurance"},{"title":"Maryland Courts — Probate and guardianship FAQs","url":"https://www.mdcourts.gov/orphanscourt/faqs"},{"title":"MIA Bulletin 26-22 — Maryland-sitused life policy and divorce example","url":"https://insurance.maryland.gov/Pages/Bulletins/Bulletin-26-22.aspx"},{"title":"Maryland Courts and Judicial Proceedings §10-804 — rule before October 1, 2026","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gcj&section=10-804"},{"title":"Maryland Courts and Judicial Proceedings §10-805 — existing contract exception","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gcj&section=10-805"},{"title":"2026 Chapter 509 — simultaneous-death changes effective October 1, 2026","url":"https://mgaleg.maryland.gov/2026RS/chapters_noln/Ch_509_hb0596T.pdf"},{"title":"Maryland Estates and Trusts §4-105 — wills, divorce and annulment","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=get&section=4-105"}]},{"lesson":"40","prompt":"A juvenile policy’s payor rider waives covered premiums after a qualifying payor event and waiting period. Who remains the life insured under the juvenile base policy?","options":["The payor solely because premiums were waived","Every member of the household","The child","The producer who submitted the rider"],"answer":2,"explanation":"The rider affects premium obligations after the payor event. It does not automatically replace the child as the insured life.","id":"A-5-12","domain":4,"scored":false,"sources":[{"title":"New York Life — waiver of premium and policy riders","url":"https://www.newyorklife.com/articles/your-policy-your-way"},{"title":"SEC-filed monthly-deduction disability rider","url":"https://www.sec.gov/Archives/edgar/data/906982/000119312518115620/d673390dex99d4.htm"},{"title":"Transamerica SEC-filed prospectus — disability waiver and income riders","url":"https://www.sec.gov/Archives/edgar/data/778209/000119312525112108/d909081d497.htm"},{"title":"Gerber Life — juvenile payment protection rider","url":"https://www.gerberlife.com/gl/gu/refguides?action=open"}]},{"lesson":"34","prompt":"A Maryland ordinary nonindustrial life policy uses an insurer-selected one-month grace period of at least 30 days after premiums other than the first. The insured dies during that grace period with the premium unpaid. Which result generally fits the provision?","options":["Only the cash value can ever be paid during grace.","The beneficiary must first reinstate a policy that never lapsed.","Coverage necessarily ended the moment the premium was due.","Coverage continues during grace, with the permitted unpaid-premium adjustment to proceeds."],"answer":3,"explanation":"Grace continues coverage for the stated period, subject to permitted premium adjustment. It is not the same as reinstating after lapse or extending the first-premium requirement.","id":"A-5-03","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-105"},{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-202"},{"title":"Maryland Insurance §16-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-203"},{"title":"Maryland Insurance §16-219","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-219"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.15.03.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.05"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"}]},{"lesson":"21","prompt":"Two business partners want insurance proceeds available to purchase a deceased partner’s ownership interest under their agreement. Which purpose best fits?","options":["Buy-sell funding","Employee group conversion","Key-person coverage solely for lost services","An executive’s personal disability waiver"],"answer":0,"explanation":"Buy-sell insurance funds an ownership-purchase obligation. Key-person insurance protects against the business’s loss of services; both can be needed but they solve different problems.","id":"A-3-07","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"MassMutual — Life insurance for business","url":"https://www.massmutual.com/business/business-life-insurance"},{"title":"MassMutual — Choosing a buy-sell arrangement","url":"https://blog.massmutual.com/work-business/business-buy-sell-right"},{"title":"New York Life — Business succession planning","url":"https://www.newyorklife.com/articles/business-succession-planning"}]},{"lesson":"48","prompt":"A producer recommends a replacement primarily because it pays a larger commission, without evaluating surrender costs or the consumer’s needs. Which concern is central?","options":["A replacement has no liquidity consequences once disclosed","The recommendation may put the producer’s interest ahead of the consumer’s under the best-interest rule.","Disclosing a commission automatically cures every deficient recommendation.","Higher compensation proves the recommendation is always better."],"answer":1,"explanation":"The rule addresses care, disclosure, conflicts and documentation. Compensation is not by itself a reasoned consumer benefit, and disclosure alone does not cure an unsuitable recommendation.","id":"A-6-07","domain":5,"scored":true,"sources":[{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"COMAR 31.09.12.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.02"},{"title":"COMAR 31.09.12.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.03"},{"title":"COMAR 31.09.12.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.04"},{"title":"COMAR 31.09.12.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.05"},{"title":"COMAR 31.09.12.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.06"},{"title":"COMAR 31.09.12.08","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.08"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §16-114","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-114"},{"title":"IRS Publication 575 — pension and annuity income","url":"https://www.irs.gov/publications/p575"},{"title":"IRS Publication 970 — education benefits","url":"https://www.irs.gov/publications/p970"}]},{"lesson":"22","prompt":"An insurer calculates a premium using mortality, assumed investment earnings and expenses. Which distinction separates a gross premium from the net insurance-cost calculation?","options":["The gross premium includes the expense loading.","The gross premium excludes all mortality assumptions.","The net premium guarantees a dividend.","Only the beneficiary’s age determines the gross premium."],"answer":0,"explanation":"Premium construction distinguishes the net mortality-and-interest calculation from gross premiums that also provide for expenses. A dividend is not created by the term net premium.","id":"A-3-09","domain":2,"scored":true,"sources":[{"title":"NAIC — A regulator’s introduction to the insurance industry, life pricing and products","url":"https://content.naic.org/sites/default/files/inline-files/prod_serv_marketreg_rii_zb.pdf"},{"title":"NAIC — Life insurance topic guide","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NAIC — Glossary of insurance terms","url":"https://content.naic.org/es/node/11821"},{"title":"SEC Investor.gov — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"}]},{"lesson":"30","prompt":"A creditor buys life coverage tied to an outstanding consumer loan, with the creditor receiving the covered amount owed. Which purpose best describes it?","options":["Credit life protecting the debt obligation","A personal policy that must pay every unrelated family expense","A retirement annuity protecting longevity","A survivorship estate policy on two lives"],"answer":0,"explanation":"Credit life is linked to the covered debt and ordinarily benefits the creditor for that obligation. It is not a substitute for assessing the family’s broader protection need.","id":"A-4-08","domain":3,"scored":true,"sources":[{"title":"New York Life — First-death and survivorship coverage","url":"https://www.newyorklife.com/articles/joint-life-insurance"},{"title":"MassMutual — Juvenile policy ownership","url":"https://blog.massmutual.com/insurance/milestone-birthday-life-insurance"},{"title":"MassMutual — Example spouse and child term riders; product-specific terms","url":"https://www.massmutual.com/worksiteassets/wi5077_2020.pdf"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §13-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-101"},{"title":"Maryland Insurance §13-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-105"},{"title":"Maryland Insurance §13-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-106"},{"title":"Maryland Insurance §13-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-107"},{"title":"Maryland Insurance §13-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-109"},{"title":"Maryland Insurance §13-112","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-112"},{"title":"COMAR 31.13.01.25","url":"https://regs.maryland.gov/us/md/exec/comar/31.13.01.25"}]},{"lesson":"37","prompt":"An owner elects extended-term nonforfeiture using the available policy value. Which outcome is ordinarily sought?","options":["The original permanent policy with no further funding under any conditions","Cash now and no continuing protection","Term protection for the original amount, adjusted as applicable, for a limited period","A smaller permanent paid-up amount"],"answer":2,"explanation":"Extended term generally maintains the stated death-benefit amount for a limited term purchased by the available value. Reduced paid-up and cash surrender are distinct choices.","id":"A-5-07","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-301"},{"title":"Maryland Insurance §16-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-303"},{"title":"Maryland Insurance §16-304","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-304"},{"title":"Maryland Insurance §16-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-210"},{"title":"New York Life — nonforfeiture and paid-up definitions","url":"https://www.newyorklife.com/resources/glossary"},{"title":"New York DFS — general nonforfeiture concepts","url":"https://www.dfs.ny.gov/consumers/life_insurance"}]},{"lesson":"53","prompt":"In 2026 a 52-year-old has $6,000 of eligible compensation and no spouse compensation available under a spousal-IRA rule. Ignoring other limits, what caps that person’s total regular traditional-plus-Roth IRA contributions?","options":["$15,000","$6,000","$7,500 to each account separately","$8,600"],"answer":1,"explanation":"The annual dollar limit and age catch-up do not override the compensation limit. Traditional and Roth regular contributions share the combined limit; the eligible compensation here is only $6,000.","id":"A-7-04","domain":6,"scored":true,"sources":[{"title":"IRS Publication 590-A — IRA contributions","url":"https://www.irs.gov/publications/p590a"},{"title":"IRS Publication 590-B — IRA distributions","url":"https://www.irs.gov/publications/p590b"},{"title":"IRS — 2026 IRA limits","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-ira-contribution-limits"},{"title":"IRS — 2026 cost-of-living adjustments","url":"https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500"},{"title":"IRS Topic 451 — individual retirement arrangements","url":"https://www.irs.gov/taxtopics/tc451"},{"title":"26 USC §401(a)(9) — distribution ages and beneficiaries","url":"https://www.law.cornell.edu/uscode/text/26/401"}]},{"lesson":"41","prompt":"A terminal-illness accelerated-benefit rider pays part of a death benefit early. Which consequence is central?","options":["The remaining benefit and other policy elements may be reduced under the rider.","The payment is always an extra benefit leaving all death proceeds unchanged.","Every acceleration necessarily waives all future premiums","Acceleration automatically converts the policy into comprehensive long-term-care insurance."],"answer":0,"explanation":"Acceleration ordinarily advances part of an existing benefit and affects remaining policy rights or values. It is not automatically an added death benefit, LTC policy or premium waiver.","id":"A-5-10","domain":4,"scored":true,"sources":[{"title":"COMAR 31.09.16.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.02"},{"title":"COMAR 31.09.16.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.03"},{"title":"COMAR 31.09.16.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.04"},{"title":"COMAR 31.09.16.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.05"},{"title":"COMAR 31.09.16.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.07"},{"title":"COMAR 31.09.16.08","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.08"},{"title":"COMAR 31.09.16.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.09"},{"title":"COMAR 31.09.16.11","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.11"},{"title":"COMAR 31.14.01.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.14.01.02"},{"title":"IRS Publication 525 — accelerated death benefits","url":"https://www.irs.gov/publications/p525"},{"title":"SEC-filed policy — an acceleration calculation","url":"https://www.sec.gov/Archives/edgar/data/778209/000119312525112108/d909081d497.htm"}]},{"lesson":"11","prompt":"An authorized life insurer initially accepts a life application submitted under Maryland’s narrow exception by a licensed but unappointed producer. Which action must occur within the applicable 30-day period?","options":["Return every premium regardless of the underwriting decision","Automatically issue the policy at the applied-for rate","Reject the application under the law or appoint the producer and make the required register entry","Convert the producer’s license to an adviser license"],"answer":2,"explanation":"The exception permits a qualifying application, with a 30-day reject-or-appoint/register obligation. Processing does not guarantee underwriting acceptance or immediate insurance coverage.","id":"A-1-08","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"56","prompt":"A client wants to exchange a nonqualified annuity for a life insurance policy and calls it a tax-free §1035 exchange. Which direction rule applies?","options":["An annuity-to-life exchange is not an allowed §1035 direction.","Only the premium payment mode decides §1035 eligibility","Every exchange between insurance products is allowed.","A surrender check endorsed to any insurer makes the direction allowed."],"answer":0,"explanation":"The statute permits specified directions, including life to annuity, but not annuity to life. Transaction form and other conditions matter as well; a new insurer alone does not create qualification.","id":"A-7-06","domain":6,"scored":true,"sources":[{"title":"26 USC §1035 — permitted insurance exchanges","url":"https://www.law.cornell.edu/uscode/text/26/1035"},{"title":"26 CFR §1.1035-1 — identity and exchange conditions","url":"https://www.law.cornell.edu/cfr/text/26/1.1035-1"},{"title":"IRS Revenue Ruling 2007-24 — check paid to owner","url":"https://www.irs.gov/irb/2007-21_IRB#RR-2007-24"},{"title":"IRS Revenue Procedure 2011-38 — partial annuity exchanges","url":"https://www.irs.gov/irb/2011-30_IRB#RP-2011-38"},{"title":"26 USC §7702A — MEC exchanges","url":"https://www.law.cornell.edu/uscode/text/26/7702A"},{"title":"COMAR 31.09.12.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.04"}]},{"lesson":"47","prompt":"A variable annuity’s separate-account investments decline. What should an owner distinguish from any optional contractual guarantee?","options":["FDIC protection of each securities account","A mandatory refund of all investment losses","Market performance of the chosen investments","A guarantee that every subaccount price is fixed"],"answer":2,"explanation":"Variable subaccount values reflect investment performance. Optional living or death guarantees have distinct terms, fees and conditions; they do not make every account value fixed.","id":"A-6-05","domain":5,"scored":true,"sources":[{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"SEC — Indexed annuity mechanics","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated-investor-bulletin-indexed-annuities"},{"title":"SEC — Variable annuity operation and costs","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated-5"}]},{"lesson":"15","prompt":"At a covered replacement application, the applicant asks not to have the replacement notice read aloud. What is still required?","options":["Discard the notice because reading was declined.","Replace the notice with a verbal promise of equal benefits.","Postpone all replacement disclosure until a claim.","Present, obtain the required signatures and leave the notice with the applicant."],"answer":3,"explanation":"Declining the reading does not eliminate presentation, signing and delivery of the required notice. A verbal assurance is not the required replacement record.","id":"A-1-19","domain":0,"scored":true,"sources":[{"title":"COMAR 31.09.05.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.02"},{"title":"COMAR 31.09.05.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.03"},{"title":"COMAR 31.09.05.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.04"},{"title":"COMAR 31.09.05.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.05"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.09.05.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.07"},{"title":"COMAR 31.09.05.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.10"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"}]},{"lesson":"50","prompt":"A life policy fails the applicable seven-pay test and is classified as a modified endowment contract. Which distribution distinction is central?","options":["MEC status makes every death benefit taxable in all cases.","Distributions generally use gain-first treatment, and certain loans are treated as distributions.","The seven-pay test simply divides the death benefit into seven equal deposits","MEC status guarantees that cash withdrawals are basis-first."],"answer":1,"explanation":"The seven-pay test is an actuarial premium test, not face amount divided by seven. MEC rules affect living distributions and loans; the general death-benefit exclusion is a separate topic.","id":"A-7-02","domain":6,"scored":true,"sources":[{"title":"26 USC §7702A — seven-pay test and contract changes","url":"https://www.law.cornell.edu/uscode/text/26/7702A"},{"title":"26 USC §72 — distributions and modified endowment contracts","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"SEC-filed 2026 policy tax disclosure","url":"https://www.sec.gov/Archives/edgar/data/771726/000119312526172890/d89381d485bpos.htm"},{"title":"IRS — MEC definition and distribution rules","url":"https://www.irs.gov/irb/2007-07_IRB"},{"title":"26 USC §101 — life death-benefit rule","url":"https://www.law.cornell.edu/uscode/text/26/101"}]},{"lesson":"55","prompt":"An eligible $80,000 pretax employer-plan distribution is paid to the participant, with 20% mandatory withholding. The participant wants to roll over the full eligible amount within 60 days. What is needed?","options":["Deposit only the $64,000 received and treat all $80,000 as rolled over.","Deposit $16,000 only because withholding is itself the rollover.","Deposit $80,000, including $16,000 from other funds to replace withholding.","Wait until the next required minimum distribution date"],"answer":2,"explanation":"The gross eligible distribution is $80,000; $16,000 was withheld and $64,000 received. Full rollover requires replacing the withheld amount. Withholding is a tax prepayment, not money transferred to the IRA.","id":"A-7-05","domain":6,"scored":true,"sources":[{"title":"IRS — retirement plan and IRA rollovers","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/rollovers-of-retirement-plan-and-ira-distributions"},{"title":"IRS Topic 413 — rollover eligibility and withholding","url":"https://www.irs.gov/taxtopics/tc413"},{"title":"IRS Publication 590-A — rollover requirements","url":"https://www.irs.gov/publications/p590a"},{"title":"IRS Publication 590-B — inherited IRA transfers","url":"https://www.irs.gov/publications/p590b"}]},{"lesson":"15","prompt":"An owner returns a covered replacement variable contract within the Maryland replacement return period after a market decline. Which refund description avoids an unsupported promise?","options":["Always refund the original premium plus all market losses.","Pay only the producer’s commission.","Apply the prescribed cash-surrender-value-plus-specified-fees-and-charges formula.","Use the old policy’s face amount as the refund."],"answer":2,"explanation":"Variable replacement contracts use the stated value-plus-charges rule, which differs from the ordinary full-premium refund. Do not promise that the return right erases investment losses.","id":"A-1-20","domain":0,"scored":true,"sources":[{"title":"COMAR 31.09.05.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.02"},{"title":"COMAR 31.09.05.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.03"},{"title":"COMAR 31.09.05.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.04"},{"title":"COMAR 31.09.05.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.05"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.09.05.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.07"},{"title":"COMAR 31.09.05.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.10"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"}]},{"lesson":"51","prompt":"A 45-year-old takes a $24,000 partial withdrawal from a 2020 nonqualified annuity with $100,000 value and $70,000 basis. There is no exception and no charge. What are the taxable amount and 10% additional federal tax?","options":["$30,000 taxable; $3,000 additional tax","$7,200 taxable; $720 additional tax","$0 taxable; $2,400 additional tax","$24,000 taxable; $2,400 additional tax"],"answer":3,"explanation":"The $30,000 gain comes out first, so all $24,000 distributed is taxable. The stated no-exception early-distribution tax is 10% of that taxable amount: $2,400, in addition to ordinary income tax.","id":"A-7-03","domain":6,"scored":true,"sources":[{"title":"IRS Publication 575 — annuity distributions","url":"https://www.irs.gov/publications/p575"},{"title":"26 USC §72 — annuity income and distribution rules","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"IRS Publication 939 — General Rule","url":"https://www.irs.gov/publications/p939"}]},{"lesson":"14","prompt":"An illustration contains a nonguaranteed column showing future policy values. The producer describes that column as contractually certain. What should the producer say instead?","options":["All illustrated values are guaranteed if printed.","Nonguaranteed means the insurer cannot pay those values.","Only the signature converts the projection into a guarantee.","Those values depend on nonguaranteed assumptions; distinguish them from the guaranteed values."],"answer":3,"explanation":"An illustration must distinguish guaranteed and nonguaranteed elements. Printing or signing a projection does not make its assumptions contractual guarantees.","id":"A-1-17","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"COMAR 31.09.09.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.06"},{"title":"COMAR 31.09.09.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.07"},{"title":"COMAR 31.09.09.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.09"},{"title":"COMAR 31.15.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.04"},{"title":"COMAR 31.15.03.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.05"},{"title":"COMAR 31.16.08.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.05"},{"title":"COMAR 31.16.08.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.06"},{"title":"COMAR 31.16.08.11","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.11"},{"title":"COMAR 31.16.08.17","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.17"}]},{"lesson":"35","prompt":"An ordinary Maryland policy lapsed 18 months ago. It was not surrendered, the applicable value has not been exhausted and no paid-up term has expired. What must still be satisfied for statutory reinstatement?","options":["Only a verbal promise to pay next year","No conditions because every lapse within three years automatically reinstates","Only a new beneficiary designation","The required application, evidence of insurability and payment of arrears and applicable indebtedness and interest"],"answer":3,"explanation":"The ordinary reinstatement opportunity has conditions and exclusions. Being within the time window does not itself restore coverage.","id":"A-5-05","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-210"},{"title":"Maryland Insurance §16-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-208"},{"title":"Maryland Insurance §16-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-107"},{"title":"Maryland Insurance §16-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-205"},{"title":"Maryland Insurance §16-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-215"},{"title":"Maryland Insurance §16-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-216"},{"title":"Maryland Insurance §16-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-104"},{"title":"Maryland Insurance §16-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-106"},{"title":"Nassau Life — 2026 filed prospectus, age/sex correction example","url":"https://www.sec.gov/Archives/edgar/data/796154/000110465926051351/tm261977d1_485bpos.htm"}]},{"lesson":"03","prompt":"A person cancels a planned hazardous activity entirely to remove that exposure. Which risk-handling method is illustrated?","options":["Reinsurance","Loss sharing after the event","Retention","Avoidance"],"answer":3,"explanation":"Avoidance removes participation in the exposure. Retention keeps it, reduction lessens it, and reinsurance is an insurer-to-insurer arrangement.","id":"A-2-03","domain":1,"scored":true,"sources":[{"title":"Society of Actuaries — Risk and Insurance","url":"https://www.soa.org/globalassets/assets/files/edu/P-21-05.pdf"},{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"}]},{"lesson":"28","prompt":"An indexed universal-life illustration shows a 0% index-credit floor. Which statement correctly limits that floor?","options":["It guarantees that every premium is fully refundable at all times.","It guarantees the index’s full positive return with no cap.","It does not necessarily prevent account value from declining after policy charges.","It removes all cost-of-insurance charges."],"answer":2,"explanation":"A crediting floor applies to the stated index-credit formula. Charges and other policy mechanics can still reduce values; caps and participation limits may constrain positive credits.","id":"A-4-04","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Universal life insurance","url":"https://insurance.maryland.gov/Consumer/Pages/Universal-Life-Insurance.aspx"},{"title":"NAIC — Life insurance designs","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NYDFS — General whole-life product explanations; New York-specific rules are not Maryland rules","url":"https://www.dfs.ny.gov/faqs/consumer_faqs/life_insurance?page=2"},{"title":"Nationwide — Indexed universal life guide; product illustrations, not universal rates","url":"https://financial.nationwide.com/media/pdf/FLM-1376AO.pdf"},{"title":"Nationwide — Indexed UL Accumulator III product disclosures","url":"https://www.nationwide.com/personal/insurance/life/permanent/indexed-universal/indexed-ul-accumulator-III/"},{"title":"Nationwide — No-lapse guarantee universal life","url":"https://www.nationwide.com/personal/insurance/life/permanent/universal/no-lapse-guarantee-UL-II/"}]},{"lesson":"24","prompt":"An insurer uses an MIB code as a clue and seeks clarification through the applicant and other authorized sources. Which interpretation is sound?","options":["MIB issues the applicant’s insurance license.","An MIB code always requires denial without further inquiry.","Every individual necessarily has a full MIB file.","MIB information supports underwriting investigation; it is not a complete medical record or an automatic final underwriting decision."],"answer":3,"explanation":"MIB is one information source and may prompt verification. The insurer remains responsible for its underwriting decision and should not treat a code as a complete history.","id":"A-3-13","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-504"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Consumer Financial Protection Bureau — MIB consumer reports","url":"https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/consumer-reporting-companies/companies-list/mib-inc/"},{"title":"MIB — Request and correct your consumer file","url":"https://www.mib.com/request_your_record.html"}]},{"lesson":"32","prompt":"An owner assigns a policy to a bank only as security for a loan. What type of assignment is described?","options":["Collateral assignment","A nonforfeiture election","A revocable beneficiary change with no creditor rights","Absolute assignment of every ownership right"],"answer":0,"explanation":"Collateral assignment transfers specified rights to secure an obligation. It differs from a complete transfer of ownership; the actual instrument controls the lender’s rights.","id":"A-5-01","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-204"},{"title":"Maryland Insurance §16-212","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-212"},{"title":"Maryland Insurance §12-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-206"},{"title":"New York Life — Ownership and assignment glossary","url":"https://www.newyorklife.com/resources/glossary"},{"title":"MassMutual — Life insurance as business loan collateral","url":"https://blog.massmutual.com/work-business/business-loan-life-insurance-collateral"},{"title":"MassMutual — Example collateral assignment terms","url":"https://www.massmutual.com/efiles/life/pdfs/f5308.pdf"}]},{"lesson":"14","prompt":"An insurer seeks the annual privacy-notice exception. It has kept disclosure practices unchanged but shares information outside the permitted exception categories. Does unchanged practice alone suffice?","options":["Yes; only whether the logo changed matters.","Yes; any prior notice eliminates all future obligations.","No; both the permitted-sharing condition and unchanged-practices condition must be satisfied.","No insurer may ever qualify for an annual-notice exception."],"answer":2,"explanation":"The exception has two substantive conditions. Unchanged practices alone do not qualify if sharing falls outside the allowed categories; the exception is also not universally unavailable.","id":"A-1-18","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"COMAR 31.09.09.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.06"},{"title":"COMAR 31.09.09.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.07"},{"title":"COMAR 31.09.09.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.09"},{"title":"COMAR 31.15.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.04"},{"title":"COMAR 31.15.03.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.05"},{"title":"COMAR 31.16.08.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.05"},{"title":"COMAR 31.16.08.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.06"},{"title":"COMAR 31.16.08.11","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.11"},{"title":"COMAR 31.16.08.17","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.17"}]},{"lesson":"24","prompt":"The underwriter needs the treating physician’s existing information about a diagnosed condition. Which source most directly supplies it?","options":["The insurer’s producer appointment register","An investigative consumer report about reputation","An attending physician statement","The beneficiary’s premium invoice"],"answer":2,"explanation":"An APS obtains information from the treating professional. It differs from personal-interview reports, agency authorization records and billing documents.","id":"A-3-12","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-504"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Consumer Financial Protection Bureau — MIB consumer reports","url":"https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/consumer-reporting-companies/companies-list/mib-inc/"},{"title":"MIB — Request and correct your consumer file","url":"https://www.mib.com/request_your_record.html"}]},{"lesson":"17","prompt":"A claims department refuses a life claim without a reasonable investigation of available information. Which Maryland regulatory topic is implicated?","options":["A producer’s premium-mode election","A permissible collateral assignment","Unfair claims settlement practices","Automatic paid-up additions"],"answer":2,"explanation":"Claims must be handled under the applicable settlement-practice standards. An unjustified denial without reasonable investigation is not a policyowner option or assignment.","id":"A-1-23","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §12-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-203"},{"title":"Maryland Insurance §27-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-303"},{"title":"Maryland Insurance §27-304","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-304"},{"title":"Maryland Insurance §16-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-109"},{"title":"Maryland Insurance §17-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-102"},{"title":"Maryland Insurance §9-402","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-402"},{"title":"Maryland Insurance §9-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-403"},{"title":"Maryland Insurance §9-405","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-405"},{"title":"Maryland Insurance §9-407","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-407"},{"title":"Maryland Insurance §9-409","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-409"},{"title":"Maryland Insurance §9-414","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-414"},{"title":"Maryland Life & Health Insurance Guaranty Corporation — FAQs","url":"https://www.mdlifega.org/FAQ"}]},{"lesson":"07","prompt":"An insurer drafts an unclear policy term that supports two reasonable interpretations after proper analysis. Which principle is generally relevant?","options":["Every disappointed expectation overrides clear wording.","The producer may rewrite the contract after the loss.","Ambiguity always voids the entire policy.","Genuine ambiguity in an adhesion contract is generally construed against its drafter, subject to governing law."],"answer":3,"explanation":"The ambiguity rule addresses genuinely unclear drafting, not every disagreement. Clear provisions, context and governing law still matter.","id":"A-2-07","domain":1,"scored":true,"sources":[{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-406","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-406"},{"title":"Maryland Court of Appeals — Clendenin Brothers: insurance contract interpretation","url":"https://www.mdcourts.gov/data/opinions/coa/2006/2a05m.pdf"},{"title":"Maryland appellate court — waiver and estoppel","url":"https://www.courts.state.md.us/data/opinions/cosa/1996/1299s95.pdf"}]},{"lesson":"34","prompt":"A policy’s two-year incontestability period has elapsed during the insured’s lifetime, subject to the applicable law. Which statement avoids overstating the clause?","options":["It limits specified validity challenges; it does not erase every exclusion or the nonpayment exception.","It means premiums are no longer required.","It restarts automatically on every beneficiary change","It guarantees payment for every event regardless of exclusions."],"answer":0,"explanation":"Incontestability concerns specified challenges to policy validity. Nonpayment and actual coverage provisions remain distinct; the clause is not universal coverage for all events.","id":"A-5-04","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-105"},{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-202"},{"title":"Maryland Insurance §16-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-203"},{"title":"Maryland Insurance §16-219","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-219"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.15.03.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.05"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"}]},{"lesson":"29","prompt":"A variable whole-life owner chooses separate-account investments that perform poorly. Which risk is central?","options":["The separate account is the same as a guaranteed bank deposit.","All separate-account losses must be reimbursed by the producer.","Poor performance automatically changes the policy to decreasing term.","Investment performance can affect values and benefits as the policy states."],"answer":3,"explanation":"Variable investment risk follows the contract. Some guarantees may exist, but the label variable does not promise protection from every loss or automatic product conversion.","id":"A-4-05","domain":3,"scored":true,"sources":[{"title":"FINRA — Insurance agents and variable-product authority","url":"https://www.finra.org/investors/investing/working-with-investment-professional/insurance-agents"},{"title":"FINRA Rule 2211 — Variable-product communications","url":"https://www.finra.org/rules-guidance/rulebooks/finra-rules/2211"},{"title":"SEC Investor.gov — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"},{"title":"SEC filing — Scheduled-premium variable whole life example, not a universal product promise","url":"https://www.sec.gov/Archives/edgar/data/742277/000119312526180744/d75572d485bpos.htm"},{"title":"Guardian — Adjustable life and permitted changes","url":"https://www.guardianlife.com/life-insurance/adjustable"},{"title":"SEC filing — Adjustable-life plan and premium mechanics","url":"https://www.sec.gov/Archives/edgar/data/789535/000119312520122165/d839488d485bpos.htm"},{"title":"NAIC — General life insurance product categories","url":"https://content.naic.org/insurance-topics/life-insurance"}]},{"lesson":"08","prompt":"A producer sees a new NAIC model law and immediately describes it as an enacted Maryland statute. What should be verified?","options":["Whether another state has discussed it","Whether and how Maryland adopted the relevant rule","Whether the model uses the word insurance in its title","Whether the producer belongs to a trade association"],"answer":1,"explanation":"NAIC develops models and supports regulators; adoption does not automatically enact state law. Maryland’s actual legal action controls the applicable rule.","id":"A-2-10","domain":1,"scored":false,"sources":[{"title":"FTC — Consumer Reports: What Insurers Need to Know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"MIA — 18 U.S.C. 1033–1034","url":"https://insurance.maryland.gov/Producer/pages/1033waiverinfo.aspx"},{"title":"SEC — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"},{"title":"NAIC — About","url":"https://content.naic.org/about"},{"title":"Insurance Compact — About","url":"https://www.insurancecompact.org/about"},{"title":"NCOIL — State legislators and model legislation","url":"https://ncoil.org/"}]},{"lesson":"43","prompt":"A guaranteed-insurability rider offers a stated future purchase option. The insured’s health has worsened. Which protection does the option ordinarily provide when validly exercised?","options":["Automatic exercise without observing any deadline","Unlimited additional coverage at the original premium rate","Purchase of the allowed additional coverage without new evidence of insurability","A guarantee that every future illness is covered by a health policy"],"answer":2,"explanation":"Guaranteed insurability concerns the evidence requirement for specified life coverage at defined times and amounts. Pricing, exercise deadlines and other terms still apply.","id":"A-5-11","domain":4,"scored":true,"sources":[{"title":"New York Life SEC-filed 2026 rider descriptions","url":"https://www.sec.gov/Archives/edgar/data/906982/000119312526149337/d91382d485bpos.htm"},{"title":"Union Security SEC-filed cost-of-living rider","url":"https://www.sec.gov/Archives/edgar/data/790531/000079053126000012/usicvulregtofile.htm"},{"title":"SEC-filed return-of-premium death benefit rider","url":"https://www.sec.gov/Archives/edgar/data/801019/000119312526166328/d714689d485bpos.htm"},{"title":"State Farm — return-of-premium term coverage","url":"https://www.statefarm.com/insurance/life/term-life/return-of-premium"}]},{"lesson":"10","prompt":"A producer finishes required CE on the license-expiration date and argues that it was completed before midnight. Which requirement was missed?","options":["CE is due only after the reinstatement application.","CE is due 15 days after expiration.","CE must be finished on the original licensing-exam date each year.","CE must ordinarily be completed at least 15 days before expiration."],"answer":3,"explanation":"The CE deadline precedes expiration by 15 days. It is separate from the renewal and reinstatement dates.","id":"A-1-05","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"02","prompt":"Applicants who privately know they have higher expected loss are more eager to buy the same coverage at the offered standard price. All answer truthfully. Which concept fits?","options":["Adverse selection","A guaranteed improvement in the pool’s mortality","Fraud necessarily","Contract waiver"],"answer":0,"explanation":"Adverse selection concerns who seeks coverage and can occur without dishonesty. Truthful answers do not remove differences in the applicants’ incentives.","id":"A-2-09","domain":1,"scored":false,"sources":[]},{"lesson":"48","prompt":"Before recommending a covered Maryland annuity transaction, a producer gathers age, objectives, income, assets and liquidity information. What is the purpose?","options":["To replace all disclosure and conflict obligations","To guarantee the highest possible return","To understand the consumer profile and support the recommendation under the care obligation","To prove that every applicant needs an annuity"],"answer":2,"explanation":"Profile information supports a reasoned recommendation. Care, disclosure, conflict management and documentation work together; gathering information alone does not satisfy every duty.","id":"A-6-06","domain":5,"scored":true,"sources":[{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"COMAR 31.09.12.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.02"},{"title":"COMAR 31.09.12.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.03"},{"title":"COMAR 31.09.12.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.04"},{"title":"COMAR 31.09.12.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.05"},{"title":"COMAR 31.09.12.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.06"},{"title":"COMAR 31.09.12.08","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.08"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §16-114","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-114"},{"title":"IRS Publication 575 — pension and annuity income","url":"https://www.irs.gov/publications/p575"},{"title":"IRS Publication 970 — education benefits","url":"https://www.irs.gov/publications/p970"}]},{"lesson":"18","prompt":"A person buys a policy on an unrelated stranger solely to profit from the stranger’s death. No qualifying relationship or lawful interest exists. Which requirement is missing at inception?","options":["A monthly premium mode","A contingent-beneficiary designation","A paid-up addition","Insurable interest"],"answer":3,"explanation":"When procuring coverage on another life, the required insurable interest must exist at inception. A payment mode or beneficiary structure does not cure a wagering arrangement.","id":"A-3-01","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"}]},{"lesson":"01","prompt":"A worker knowingly fabricates proof of a covered event to obtain insurance money. Which hazard category best fits the behavior?","options":["A physical hazard only","Morale hazard","An actuarial reserve","Moral hazard"],"answer":3,"explanation":"Deliberate deception is moral hazard. Morale hazard refers to carelessness or indifference; a physical condition and a reserve describe different ideas.","id":"A-2-01","domain":1,"scored":true,"sources":[]},{"lesson":"11","prompt":"A producer has written appointment documentation, but the insurer has not yet completed its register entry. What does the documentation permit under the stated Maryland rule?","options":["Act within the appointment and delegated authority before the register entry is finished","Bind every life risk without receipt conditions","Disregard the insurer’s written limits","Treat the appointment as a replacement for a state license"],"answer":0,"explanation":"Written documentation can support acting before the register entry, within authority. It does not replace the license or enlarge binding powers.","id":"A-1-09","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"49","prompt":"A beneficiary receives an otherwise excluded $300,000 life death benefit plus $4,500 of separately paid interest. Assume no special exception to the death-benefit exclusion. What is generally federal taxable income from these payments?","options":["$300,000","$4,500","$0","$304,500"],"answer":1,"explanation":"The general death-benefit exclusion applies to the $300,000, while separately paid interest is generally taxable. Combining the amounts in one payment does not make interest a tax-free death benefit.","id":"A-7-01","domain":6,"scored":true,"sources":[{"title":"IRS Publication 525 — life insurance proceeds","url":"https://www.irs.gov/publications/p525"},{"title":"26 USC §72 — distributions and modified endowment contracts","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"SEC-filed 2026 policy tax disclosure","url":"https://www.sec.gov/Archives/edgar/data/771726/000119312526172890/d89381d485bpos.htm"},{"title":"IRS — Interest received","url":"https://www.irs.gov/taxtopics/tc403"},{"title":"26 USC §101 — death benefits and transfer exceptions","url":"https://www.law.cornell.edu/uscode/text/26/101"},{"title":"IRS Form 706 instructions — insurance and lifetime transfers","url":"https://www.irs.gov/instructions/i706"},{"title":"IRS Publication 502 — nondeductible life premiums","url":"https://www.irs.gov/publications/p502"}]},{"lesson":"22","prompt":"Two applicants choose the same annual coverage and risk class. One pays annually and one pays monthly under a policy with a modal charge. Why can the monthly total be greater than the annual premium?","options":["Monthly payment automatically buys twelve times the face amount.","The payment mode can add financing or administrative costs.","The payment mode changes the beneficiary into the owner.","Annual payment guarantees the insured survives the year."],"answer":1,"explanation":"Premium mode describes payment frequency and can affect total cost. It does not by itself multiply coverage, promise survival or transfer policy roles.","id":"A-3-15","domain":2,"scored":false,"sources":[{"title":"NAIC — A regulator’s introduction to the insurance industry, life pricing and products","url":"https://content.naic.org/sites/default/files/inline-files/prod_serv_marketreg_rii_zb.pdf"},{"title":"NAIC — Life insurance topic guide","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NAIC — Glossary of insurance terms","url":"https://content.naic.org/es/node/11821"},{"title":"SEC Investor.gov — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"}]},{"lesson":"16","prompt":"An employee loses $110,000 of employer group life and becomes eligible for $45,000 under another group policy within the statutory period. Assume ordinary Maryland employment-termination conversion conditions. What is the maximum amount under the stated offset rule?","options":["$10,000 in every case","$65,000","$155,000","$110,000"],"answer":1,"explanation":"Subtract qualifying new group eligibility: $110,000 − $45,000 = $65,000. The possible $10,000 limit belongs to a separate entire-group or class-termination provision.","id":"A-1-21","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-302","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-302"},{"title":"Maryland Insurance §17-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-303"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"Maryland Insurance §17-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-104"}]},{"lesson":"30","prompt":"A joint first-to-die life policy covers two partners. The first insured dies in a covered event. What is the ordinary benefit trigger?","options":["Payment waits for the second death.","Payment occurs only when both reach retirement age.","The first death triggers the policy’s stated death benefit.","Each survivor automatically receives a new identical policy without conditions."],"answer":2,"explanation":"First-to-die joint life pays at the first covered death. Survivorship life uses the second death; continuing coverage and options depend on the actual contract.","id":"A-4-06","domain":3,"scored":true,"sources":[{"title":"New York Life — First-death and survivorship coverage","url":"https://www.newyorklife.com/articles/joint-life-insurance"},{"title":"MassMutual — Juvenile policy ownership","url":"https://blog.massmutual.com/insurance/milestone-birthday-life-insurance"},{"title":"MassMutual — Example spouse and child term riders; product-specific terms","url":"https://www.massmutual.com/worksiteassets/wi5077_2020.pdf"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §13-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-101"},{"title":"Maryland Insurance §13-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-105"},{"title":"Maryland Insurance §13-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-106"},{"title":"Maryland Insurance §13-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-107"},{"title":"Maryland Insurance §13-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-109"},{"title":"Maryland Insurance §13-112","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-112"},{"title":"COMAR 31.13.01.25","url":"https://regs.maryland.gov/us/md/exec/comar/31.13.01.25"}]},{"lesson":"31","prompt":"An employer holds the master group life contract and gives employees certificates. What does the certificate primarily do?","options":["Guarantee that coverage continues after every employment change without action","Make every employee owner of the employer’s master policy","Replace every statutory conversion right with new medical underwriting","Describe the employee’s covered protection and rights under the group arrangement"],"answer":3,"explanation":"A certificate communicates individual protection under the master policy. Group ownership, eligibility and continuation or conversion rights remain governed by the arrangement and law.","id":"A-4-07","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-203"},{"title":"Maryland Insurance §17-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-204"},{"title":"Maryland Insurance §17-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-206"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-307","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-307"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"OPM — Federal Employees’ Group Life Insurance","url":"https://www.opm.gov/healthcare-insurance/life-insurance/"},{"title":"VA — Servicemembers’ Group Life Insurance","url":"https://www.va.gov/life-insurance/options-eligibility/sgli/"},{"title":"VA — Veterans’ Group Life Insurance","url":"https://www.va.gov/life-insurance/options-eligibility/vgli/"}]},{"lesson":"09","prompt":"An otherwise-qualified relative is issued a Maryland temporary producer license on January 10 under §10–120. What is the stated duration from its effective date?","options":["6 months","15 months","2 years","30 days"],"answer":1,"explanation":"Maryland’s specified temporary producer license lasts 15 months. The 30-day period concerns the Commissioner’s decision on the application, not this license’s duration.","id":"A-1-02","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-101"},{"title":"Maryland Insurance §10-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-102"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-105"},{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-109"},{"title":"Maryland Insurance §10-111","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-111"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-120","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-120"},{"title":"Maryland Insurance §10-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-201"},{"title":"Maryland Insurance §10-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-202"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Prelicensing education change","url":"https://insurance.maryland.gov/Producer/pages/default.aspx"}]},{"lesson":"45","prompt":"A retiree pays one lump sum for an annuity whose income begins three months after purchase. Which description combines funding and timing accurately?","options":["Annual renewable annuity","A life-policy return-of-premium benefit","Single-premium immediate annuity","Flexible-premium deferred annuity solely because payment waits three months"],"answer":2,"explanation":"Single premium describes one contribution; immediate generally means income begins within one year. Immediate does not mean that the first payment must occur on the same day.","id":"A-6-02","domain":5,"scored":true,"sources":[{"title":"NAIC — immediate and deferred classifications","url":"https://content.naic.org/insurance-topics/annuities"},{"title":"NAIC — deferred annuity buyer’s guide","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance §16-501","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-501"},{"title":"Maryland Insurance §16-503","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-503"},{"title":"Maryland Insurance §16-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-504"},{"title":"Insured Retirement Institute — annuity terminology","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Massachusetts insurance regulator — general bailout mechanics","url":"https://www.mass.gov/info-details/buying-life-insurance-and-annuities-in-massachusetts-part-three"},{"title":"SEC-filed 2026 annuity withdrawal provisions","url":"https://www.sec.gov/Archives/edgar/data/1048606/000110465926053840/tm265210d5_497.htm"}]},{"lesson":"12","prompt":"A premium account contains $9,000, all needed for net premiums, return premiums and unremitted deposits. The producer wants to withdraw $2,000 for an anticipated commission. What controls?","options":["The bank balance proves that any amount may be withdrawn.","A personal promise to repay makes every withdrawal permitted.","Future commission expectations override the minimum balance.","The withdrawal cannot leave the account below the required aggregate obligations."],"answer":3,"explanation":"Only authorized withdrawals are permitted, and required obligations must remain funded. A bank balance or expected future earning does not establish freely available agency income.","id":"A-1-13","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"08","prompt":"An insurer offers less favorable terms partly because of a consumer report. The producer says no FCRA adverse-action notice is needed because the application was not denied. What is wrong?","options":["The reporting agency automatically becomes the underwriter.","An oral premium quote waives all report-dispute rights.","Only a total denial can ever be adverse action.","Less favorable terms based on the report can be adverse action requiring notice."],"answer":3,"explanation":"Adverse action can include unfavorable terms, not just denial. Required notice identifies the agency and relevant rights and explains that the agency did not make the insurer’s decision.","id":"A-2-08","domain":1,"scored":true,"sources":[{"title":"FTC — Consumer Reports: What Insurers Need to Know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"MIA — 18 U.S.C. 1033–1034","url":"https://insurance.maryland.gov/Producer/pages/1033waiverinfo.aspx"},{"title":"SEC — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"},{"title":"NAIC — About","url":"https://content.naic.org/about"},{"title":"Insurance Compact — About","url":"https://www.insurancecompact.org/about"},{"title":"NCOIL — State legislators and model legislation","url":"https://ncoil.org/"}]},{"lesson":"27","prompt":"A client confuses a 20-pay whole-life policy with 20-year term because both mention twenty years. Which distinction resolves the confusion?","options":["The first limits scheduled premium payments; the second specifies a protection period.","Both always have identical cash values.","The number alone establishes the beneficiary’s payout option","Both necessarily end all benefits at year twenty."],"answer":0,"explanation":"Premium-paying duration and coverage duration differ. Limited-pay whole life can continue as paid-up permanent coverage, while term protection is defined by its term.","id":"A-4-09","domain":3,"scored":false,"sources":[{"title":"NAIC — Life insurance designs","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NYDFS — General whole-life product explanations; New York-specific rules are not Maryland rules","url":"https://www.dfs.ny.gov/faqs/consumer_faqs/life_insurance?page=2"},{"title":"MassMutual — Whole life and premium-payment periods","url":"https://blog.massmutual.com/insurance/understanding-whole-life-insurance"},{"title":"Washington insurance regulator — Product definitions, graded-premium whole life","url":"https://www.insurance.wa.gov/sites/default/files/documents/life-accident-health-annuity-crediti-pcm_6_1.pdf"}]},{"lesson":"09","prompt":"An insurance agency names an unlicensed operations manager as the sole principal contact for its Maryland producer license. What must be corrected?","options":["An entity never needs a contact if its workers are licensed.","Only a reinsurer may be the contact.","The designated principal contact must be a licensed insurance producer.","The agency must instead designate one of its policyholders."],"answer":2,"explanation":"The business-entity requirement is a designated licensed producer. Neither customer status nor a purely operational title satisfies that requirement.","id":"A-1-03","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-101"},{"title":"Maryland Insurance §10-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-102"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-105"},{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-109"},{"title":"Maryland Insurance §10-111","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-111"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-120","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-120"},{"title":"Maryland Insurance §10-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-201"},{"title":"Maryland Insurance §10-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-202"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Prelicensing education change","url":"https://insurance.maryland.gov/Producer/pages/default.aspx"}]},{"lesson":"10","prompt":"A typical Maryland resident life producer completes 24 approved CE hours, including two ethics hours. Assuming no exception, what remains deficient?","options":["No deficiency exists because the overall total is 24.","At least one more ethics hour is needed to meet the three-hour ethics minimum.","All 24 hours must be ethics.","The producer needs 24 additional hours solely because the life exam was passed."],"answer":1,"explanation":"The ordinary rule is 24 total hours including at least three ethics hours. Meeting the total does not cure a shortfall in the required component.","id":"A-1-04","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"11","prompt":"An insurer terminates one appointment for a routine business reason. The producer holds other appointments and an active license. Which distinction matters?","options":["Termination of an appointment is separate from revocation of the state producer license.","Every appointment termination automatically revokes all licenses.","A state license is valid only while one particular insurer retains the producer.","The former insurer can cancel unrelated insurers’ appointments."],"answer":0,"explanation":"An insurer controls its relationship; state licensing discipline is a separate matter. Remaining authority must be checked, but one termination does not itself establish statewide revocation.","id":"A-1-26","domain":0,"scored":false,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"39","prompt":"A participating policy’s dividend buys small paid-up additions. What changes?","options":["All future dividends become guaranteed.","The policy is automatically surrendered","Additional paid-up life coverage and associated values are purchased under the option.","The entire base premium obligation necessarily ends."],"answer":2,"explanation":"Paid-up additions are additional units, not proof that the whole base policy is paid up. Dividend availability remains nonguaranteed unless a specific contractual promise says otherwise.","id":"A-5-09","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-206"},{"title":"IRS — interest on deposited insurance dividends","url":"https://www.irs.gov/taxtopics/tc403"},{"title":"New York Life — dividend and paid-up definitions","url":"https://www.newyorklife.com/resources/glossary"},{"title":"Guardian — dividends and returns","url":"https://www.guardianlife.com/life-insurance/whole-life/dividends-and-returns-explained"},{"title":"MassMutual — dividend options","url":"https://www.massmutual.com/worksiteassets/wi5002.pdf"},{"title":"SEC-filed policy — one-year term dividend option","url":"https://www.sec.gov/Archives/edgar/data/317411/000119312510000115/dex9926d2.htm"},{"title":"MetLife — dividend changes and premium offset","url":"https://www.metlife.com/content/dam/metlifecom/us/homepage/support-and-manage/current-customers/individual-life-insurance/pdf/22044-Client-Dividend-Flyer-7-1A.pdf"},{"title":"Wisconsin OCI — separately identifies dividends shortening a premium-paying period","url":"https://oci.wi.gov/Documents/OCIForms/22-801.pdf"}]},{"lesson":"57","prompt":"A participant has $9,000 of fully vested employee salary deferrals and $5,000 of employer contributions that are 40% vested. Ignoring earnings, what is vested?","options":["$5,600","$11,000","$2,000","$14,000"],"answer":1,"explanation":"Keep the sources separate: all $9,000 of employee deferrals plus 40% of $5,000, or $2,000, gives $11,000. Vesting describes ownership, not necessarily immediate unrestricted access.","id":"A-8-01","domain":7,"scored":true,"sources":[{"title":"26 USC §401 — qualification requirements","url":"https://www.law.cornell.edu/uscode/text/26/401"},{"title":"IRS — 401(k) qualification requirements","url":"https://www.irs.gov/retirement-plans/plan-sponsor/401k-plan-qualification-requirements"},{"title":"IRS — vesting","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-vesting"},{"title":"IRS — 401(k) participant overview","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/401k-resource-guide-plan-participants-401k-plan-overview"},{"title":"IRS — contributions and payroll taxes","url":"https://www.irs.gov/retirement-plans/retirement-plan-faqs-regarding-contributions-are-retirement-plan-contributions-subject-to-withholding-for-fica-medicare-or-federal-income-tax"},{"title":"IRS — exceptions to early-distribution tax","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"},{"title":"IRS — required minimum distributions","url":"https://www.irs.gov/retirement-plans/retirement-plan-and-ira-required-minimum-distributions-faqs"},{"title":"IRS — Publication 560","url":"https://www.irs.gov/publications/p560"}]},{"lesson":"46","prompt":"A joint-and-survivor annuity pays $2,400 monthly while both annuitants live and 50% after the specified first death. What is the survivor’s monthly payment?","options":["$1,200","$2,400","$600","$4,800"],"answer":0,"explanation":"The stated survivor percentage applies to the stated payment: $2,400 × 50% = $1,200. The actual trigger and percentage must be read from the option.","id":"A-6-04","domain":5,"scored":true,"sources":[{"title":"IRS — common annuity payment types","url":"https://www.irs.gov/retirement-plans/annuities-a-brief-description"},{"title":"NAIC — payout options and living benefits","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance Administration — annuity income options","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"},{"title":"Insured Retirement Institute — cash refund and annuity terms","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Florida insurance regulator — general payout descriptions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"}]},{"lesson":"20","prompt":"A policyowner sells an existing life policy to a settlement provider. Which transaction has occurred?","options":["A sale of policy interests under the settlement arrangement","An automatic conversion of the policy to an annuity","A death-benefit claim by the insured while still alive","A routine premium-mode change"],"answer":0,"explanation":"A settlement transfers specified policy ownership and benefit interests for consideration. It differs from a claim, premium election or automatic product conversion.","id":"A-3-05","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §8-601","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-601"},{"title":"Maryland Insurance §8-602","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-602"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-604","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-604"},{"title":"Maryland Insurance §8-605","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605"},{"title":"Maryland Insurance §8-605.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605.1"},{"title":"Maryland Insurance §8-606","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-606"},{"title":"Maryland Insurance §8-607","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-607"},{"title":"Maryland Insurance §8-609","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-609"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"Maryland Insurance §8-610.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610.1"},{"title":"Maryland Insurance §27-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-403"}]},{"lesson":"23","prompt":"An applicant notices a material error after signing the application. What should the producer do?","options":["Keep both conflicting answers hidden from underwriting.","Use the insurer’s correction process and obtain the applicant’s required acknowledgment.","Assume the producer report always overrides the signed application.","Silently alter the signed answer to speed approval."],"answer":1,"explanation":"Corrections must be authorized and documented through the required process. A producer must not silently replace an applicant’s representation or conceal conflicting facts.","id":"A-3-10","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"COMAR 31.04.17.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.06"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"FinCEN — Insurance company anti-money-laundering requirements","url":"https://www.fincen.gov/resources/statutes-regulations/guidance/anti-money-laundering-program-and-suspicious-activity"}]},{"lesson":"11","prompt":"Five months after ending an insurer appointment, a producer deletes the appointment documentation because no policies remain in the agency. What is wrong?","options":["Records need be kept only until the final commission is paid.","Appointment records must be retained during the appointment and at least five years after termination.","Only the client is required to keep appointment records.","Appointment records and all client records share a universal five-month rule."],"answer":1,"explanation":"The appointment-specific retention period is active appointment plus at least five years. It is not shortened by the agency’s current policy count or commission timing.","id":"A-1-10","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"44","prompt":"An annuityowner funds a contract now and plans to begin income eight years later. Which phase is the contract ordinarily in before income begins?","options":["Accumulation","A life-policy contestability phase","Annuitization solely because the first premium was paid","The death-claim settlement phase"],"answer":0,"explanation":"The accumulation phase precedes the selected income phase. Funding is not itself necessarily an election to annuitize.","id":"A-6-01","domain":5,"scored":true,"sources":[{"title":"NAIC — annuities overview","url":"https://content.naic.org/insurance-topics/annuities"},{"title":"NAIC — buyer’s guide for deferred annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Investor.gov — annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"Florida insurance regulator — general annuity role definitions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"},{"title":"Maryland Insurance Administration — Annuities 101","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"}]},{"lesson":"19","prompt":"A family needs $42,000 a year for ten years plus $95,000 of one-time expenses. It has $115,000 of resources available for those needs. Ignore taxes, inflation and investment returns. What is the additional lump-sum need?","options":["$515,000","$400,000","$630,000","$305,000"],"answer":1,"explanation":"Income need is $42,000 × 10 = $420,000. Add $95,000 and subtract $115,000 to obtain $400,000; do not subtract the one-time expenses or add the available resources.","id":"A-3-03","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Life insurance and annuities","url":"https://insurance.maryland.gov/Consumer/Pages/Life.aspx"},{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Guardian — Human life value and estimating coverage needs","url":"https://www.guardianlife.com/life-insurance/how-much-life-insurance-do-you-need"},{"title":"Social Security Administration — Survivor eligibility","url":"https://www.ssa.gov/survivor/eligibility"},{"title":"Social Security Administration — Survivor benefit amounts","url":"https://www.ssa.gov/survivor/amount"},{"title":"Social Security Administration — Survivors benefits","url":"https://www.ssa.gov/pubs/EN-05-10084.pdf"}]},{"lesson":"21","prompt":"A corporation owns and is beneficiary of life coverage on an essential employee to fund recruiting and disrupted operations after the employee’s death. Which use is described?","options":["A personal mortgage decreasing-term plan","Key-person insurance","Dependent group life payable to the employee’s family","A cross-purchase among shareholders"],"answer":1,"explanation":"The employer’s loss of an essential worker’s services is the key-person exposure. A shareholder buyout and employee-family protection have different owners, recipients and purposes.","id":"A-3-08","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"MassMutual — Life insurance for business","url":"https://www.massmutual.com/business/business-life-insurance"},{"title":"MassMutual — Choosing a buy-sell arrangement","url":"https://blog.massmutual.com/work-business/business-buy-sell-right"},{"title":"New York Life — Business succession planning","url":"https://www.newyorklife.com/articles/business-succession-planning"}]},{"lesson":"19","prompt":"A household analysis includes an income-replacement need and a mortgage payoff. The planned income figure already includes all future mortgage payments. What must the producer check?","options":["Potential double counting of the same mortgage need","An automatic requirement to add the mortgage three times","Whether beneficiaries must repay all death benefits","A rule that debts can never be included in needs analysis"],"answer":0,"explanation":"Needs analysis must coordinate assumptions. Including both full mortgage payoff and the same future mortgage payments can overstate the need unless the plan deliberately adjusts one component.","id":"A-3-16","domain":2,"scored":false,"sources":[{"title":"Maryland Insurance Administration — Life insurance and annuities","url":"https://insurance.maryland.gov/Consumer/Pages/Life.aspx"},{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Guardian — Human life value and estimating coverage needs","url":"https://www.guardianlife.com/life-insurance/how-much-life-insurance-do-you-need"},{"title":"Social Security Administration — Survivor eligibility","url":"https://www.ssa.gov/survivor/eligibility"},{"title":"Social Security Administration — Survivor benefit amounts","url":"https://www.ssa.gov/survivor/amount"},{"title":"Social Security Administration — Survivors benefits","url":"https://www.ssa.gov/pubs/EN-05-10084.pdf"}]}]},{"id":"B","title":"Timed Form B","minutes":105,"questions":[{"lesson":"47","prompt":"An annuity’s market value adjustment can change the surrender amount based on interest-rate conditions and the contract formula. What should be explained?","options":["An MVA is distinct from the surrender-charge schedule and can affect net proceeds.","An MVA guarantees the original deposit can always be withdrawn without adjustment.","An MVA is the same as direct ownership of index shares","Every MVA is always a fixed 10% federal tax."],"answer":0,"explanation":"The contract’s MVA and surrender charge are separate adjustments. Their direction and amount depend on the specified formula; neither is the federal early-distribution tax.","id":"B-6-05","domain":5,"scored":true,"sources":[{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"SEC — Indexed annuity mechanics","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated-investor-bulletin-indexed-annuities"},{"title":"SEC — Variable annuity operation and costs","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated-5"}]},{"lesson":"19","prompt":"A family assumes Social Security survivor benefits will always replace all of the deceased worker’s former earnings. What should the needs analysis do?","options":["Assume every beneficiary receives the same amount forever.","Subtract the worker’s entire salary as a guaranteed benefit.","Check actual eligibility and estimated benefits before using them as a resource.","Ignore all survivor benefits even when verified."],"answer":2,"explanation":"Survivor eligibility and amounts depend on program rules and the family’s facts. Use supportable estimates without assuming either universal full replacement or universal absence.","id":"B-3-15","domain":2,"scored":false,"sources":[{"title":"Maryland Insurance Administration — Life insurance and annuities","url":"https://insurance.maryland.gov/Consumer/Pages/Life.aspx"},{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Guardian — Human life value and estimating coverage needs","url":"https://www.guardianlife.com/life-insurance/how-much-life-insurance-do-you-need"},{"title":"Social Security Administration — Survivor eligibility","url":"https://www.ssa.gov/survivor/eligibility"},{"title":"Social Security Administration — Survivor benefit amounts","url":"https://www.ssa.gov/survivor/amount"},{"title":"Social Security Administration — Survivors benefits","url":"https://www.ssa.gov/pubs/EN-05-10084.pdf"}]},{"lesson":"25","prompt":"An applicant has paid no premium and has no receipt providing interim coverage. The insurer issues an offer requiring delivery, payment and stated acceptance conditions. What establishes the start of coverage?","options":["The applicant’s bank balance alone","The first sales conversation automatically","Satisfaction of the actual contract and delivery conditions","The producer’s submission timestamp in every case"],"answer":2,"explanation":"Without an applicable interim promise, the issue and delivery conditions control. Conversation, submission and available funds do not themselves satisfy a required payment or acceptance.","id":"B-3-14","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Transamerica SEC filing — Example of issuance and conditional coverage terms","url":"https://www.sec.gov/Archives/edgar/data/778209/000119312520258994/d44935dex9926qi.htm"},{"title":"Protective Life — Maryland application and conditional receipt packet","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"}]},{"lesson":"11","prompt":"A producer petitions for review of a Commissioner’s order and immediately resumes the conduct prohibited by that order, assuming an automatic stay. What is the mistake?","options":["An insurer appointment replaces the court’s decision.","A petition automatically reverses every order.","Seeking judicial review does not automatically establish a stay; the applicable court process controls.","Only a policyholder may seek any review of an insurance order."],"answer":2,"explanation":"The filing itself is not blanket permission to disregard an order. Review and stay are separate procedural matters.","id":"B-1-25","domain":0,"scored":false,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"31","prompt":"Employees contribute part of their group-life premium. What is that funding arrangement called?","options":["Noncontributory","Single-premium paid-up life necessarily","Contributory","An insurer mutual assessment solely because workers pay"],"answer":2,"explanation":"Contributory means employees contribute to premium funding. It does not by itself specify permanent coverage, an insurer ownership form or all participation conditions.","id":"B-4-07","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-203"},{"title":"Maryland Insurance §17-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-204"},{"title":"Maryland Insurance §17-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-206"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-307","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-307"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"OPM — Federal Employees’ Group Life Insurance","url":"https://www.opm.gov/healthcare-insurance/life-insurance/"},{"title":"VA — Servicemembers’ Group Life Insurance","url":"https://www.va.gov/life-insurance/options-eligibility/sgli/"},{"title":"VA — Veterans’ Group Life Insurance","url":"https://www.va.gov/life-insurance/options-eligibility/vgli/"}]},{"lesson":"46","prompt":"A contract provides payments for ten years only, with no lifetime promise. The recipient is alive after the final scheduled payment. What happens?","options":["Another ten-year period begins automatically.","All prior payments are reclaimed because the recipient survived","Life payments must continue because every annuity payout is lifetime.","The period-certain payments end."],"answer":3,"explanation":"Period certain only is not life with period certain. The words describing a lifetime promise materially change what continues after the period.","id":"B-6-03","domain":5,"scored":true,"sources":[{"title":"IRS — common annuity payment types","url":"https://www.irs.gov/retirement-plans/annuities-a-brief-description"},{"title":"NAIC — payout options and living benefits","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance Administration — annuity income options","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"},{"title":"Insured Retirement Institute — cash refund and annuity terms","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Florida insurance regulator — general payout descriptions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"}]},{"lesson":"12","prompt":"A producer labels a payment a “lead fee,” but the unlicensed recipient actually recommends particular policy terms and persuades buyers. Which fact governs the licensing analysis?","options":["The real selling activity, regardless of the payment label","Whether the recommended policy is term rather than permanent","The word “lead” on the invoice alone","Whether the recipient is paid by check or cash"],"answer":0,"explanation":"Actual conduct and compensation rules control. Renaming sales compensation does not turn substantive solicitation into a clerical referral.","id":"B-1-14","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"49","prompt":"An owner fully surrenders an ordinary non-MEC life policy for $92,000 with $65,000 of adjusted basis and no loan, fee or other adjustment. What is the generally taxable gain?","options":["$27,000","$92,000","$0","$65,000"],"answer":0,"explanation":"On these facts, surrender proceeds less adjusted basis equals gain: $92,000 − $65,000 = $27,000, generally ordinary income. This differs from the death-benefit exclusion.","id":"B-7-01","domain":6,"scored":true,"sources":[{"title":"IRS Publication 525 — life insurance proceeds","url":"https://www.irs.gov/publications/p525"},{"title":"26 USC §72 — distributions and modified endowment contracts","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"SEC-filed 2026 policy tax disclosure","url":"https://www.sec.gov/Archives/edgar/data/771726/000119312526172890/d89381d485bpos.htm"},{"title":"IRS — Interest received","url":"https://www.irs.gov/taxtopics/tc403"},{"title":"26 USC §101 — death benefits and transfer exceptions","url":"https://www.law.cornell.edu/uscode/text/26/101"},{"title":"IRS Form 706 instructions — insurance and lifetime transfers","url":"https://www.irs.gov/instructions/i706"},{"title":"IRS Publication 502 — nondeductible life premiums","url":"https://www.irs.gov/publications/p502"}]},{"lesson":"45","prompt":"A client makes one contribution but defers annuity income for twelve years. Why is it incorrect to call the contract immediate solely because it uses one premium?","options":["One contribution always begins income within a year.","Single versus periodic describes funding; immediate versus deferred describes income timing.","A single contribution creates an automatic life death benefit","Deferred annuities must require monthly premiums."],"answer":1,"explanation":"Two classification dimensions are involved. A single-premium contract can be deferred; funding frequency does not alone set the income start date.","id":"B-6-02","domain":5,"scored":true,"sources":[{"title":"NAIC — immediate and deferred classifications","url":"https://content.naic.org/insurance-topics/annuities"},{"title":"NAIC — deferred annuity buyer’s guide","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance §16-501","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-501"},{"title":"Maryland Insurance §16-503","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-503"},{"title":"Maryland Insurance §16-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-504"},{"title":"Insured Retirement Institute — annuity terminology","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Massachusetts insurance regulator — general bailout mechanics","url":"https://www.mass.gov/info-details/buying-life-insurance-and-annuities-in-massachusetts-part-three"},{"title":"SEC-filed 2026 annuity withdrawal provisions","url":"https://www.sec.gov/Archives/edgar/data/1048606/000110465926053840/tm265210d5_497.htm"}]},{"lesson":"33","prompt":"A beneficiary survives the insured but dies before choosing a settlement option. Why should the producer avoid assuming that the contingent beneficiary automatically replaces the primary?","options":["The producer may select whichever recipient replies first","A contingent always takes whenever payment has not yet cleared.","The insurer automatically becomes beneficiary after two deaths.","The primary’s surviving the insured can vest rights; the contract and succession facts control the later payment."],"answer":3,"explanation":"Death order and vested rights matter. A primary’s death after the insured is a different fact from dying first; payment timing alone does not establish the contingent’s entitlement.","id":"B-5-12","domain":4,"scored":false,"sources":[{"title":"Maryland Insurance §16-212","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-212"},{"title":"NAIC — Beneficiary designations","url":"https://content.naic.org/article/consumer-insight-life-insurance"},{"title":"Maryland Courts — Probate and guardianship FAQs","url":"https://www.mdcourts.gov/orphanscourt/faqs"},{"title":"MIA Bulletin 26-22 — Maryland-sitused life policy and divorce example","url":"https://insurance.maryland.gov/Pages/Bulletins/Bulletin-26-22.aspx"},{"title":"Maryland Courts and Judicial Proceedings §10-804 — rule before October 1, 2026","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gcj&section=10-804"},{"title":"Maryland Courts and Judicial Proceedings §10-805 — existing contract exception","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gcj&section=10-805"},{"title":"2026 Chapter 509 — simultaneous-death changes effective October 1, 2026","url":"https://mgaleg.maryland.gov/2026RS/chapters_noln/Ch_509_hb0596T.pdf"},{"title":"Maryland Estates and Trusts §4-105 — wills, divorce and annulment","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=get&section=4-105"}]},{"lesson":"04","prompt":"A company’s stockholders own the insurer, while its policyholders are customers under their contracts. Which ownership form is described?","options":["A government benefit plan","A purchasing group that is automatically an insurer","Stock insurer","Mutual insurer owned by policyholders"],"answer":2,"explanation":"A stock company is owned by shareholders. Policyholder ownership describes the mutual form; buying a policy does not itself make the customer a shareholder.","id":"B-2-04","domain":1,"scored":true,"sources":[{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"},{"title":"NAIC — Insurance Topics","url":"https://content.naic.org/insurance-topics"},{"title":"Maryland insurer search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"},{"title":"Maryland Insurance §4-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=4-203"}]},{"lesson":"05","prompt":"A producer has express authority to solicit applications. Taking ordinary incidental steps reasonably needed to carry out that task illustrates which additional category?","options":["A guaranty-corporation appointment","Unlimited apparent authority based only on the producer’s words","Implied authority","An absolute assignment"],"answer":2,"explanation":"Implied authority concerns acts reasonably incidental to express authority. It is not a general power to bind any risk or alter every policy provision.","id":"B-2-05","domain":1,"scored":true,"sources":[{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland reported opinion — scope of insurance agency authority","url":"https://www.courts.state.md.us/data/opinions/cosa/2012/0915s09.pdf"}]},{"lesson":"10","prompt":"A producer says reaching age 65 automatically exempts every Maryland licensee from continuing education. What is the accurate response?","options":["Every producer becomes exempt at 65 regardless of history.","Any reduction or exemption must satisfy its stated statutory conditions; age alone is not a blanket exemption.","Only current commission volume decides CE.","Continuing education applies only before the first license."],"answer":1,"explanation":"Maryland has specified provisions and exceptions, including service-history conditions. An age-only generalization omits the conditions that determine eligibility.","id":"B-1-06","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"13","prompt":"A lender threatens an applicant with unrelated adverse treatment unless the applicant buys insurance through the lender’s preferred producer, in circumstances prohibited by the applicable rule. Which concern is central?","options":["A required group conversion notice","Coercion or intimidation in insurance sales","A voluntary beneficiary election","An ordinary mortality classification"],"answer":1,"explanation":"The pressure described is coercive sales conduct. It is not an actuarial classification or the policyowner’s free election of a beneficiary.","id":"B-1-16","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"Maryland Insurance §27-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-204"},{"title":"Maryland Insurance §27-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-205"},{"title":"Maryland Insurance §27-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-206"},{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-209"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"},{"title":"Maryland Insurance §27-214","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-214"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"}]},{"lesson":"33","prompt":"A designation directs descendants of a deceased named beneficiary to take that beneficiary’s family branch share. Which distribution concept is described?","options":["Per capita among surviving named beneficiaries only","Interest-only settlement","Per stirpes","A collateral assignment"],"answer":2,"explanation":"Per stirpes distributes by family branch. Per capita generally allocates by head among the applicable beneficiaries; payout options and creditor assignments answer different questions.","id":"B-5-02","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-212","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-212"},{"title":"NAIC — Beneficiary designations","url":"https://content.naic.org/article/consumer-insight-life-insurance"},{"title":"Maryland Courts — Probate and guardianship FAQs","url":"https://www.mdcourts.gov/orphanscourt/faqs"},{"title":"MIA Bulletin 26-22 — Maryland-sitused life policy and divorce example","url":"https://insurance.maryland.gov/Pages/Bulletins/Bulletin-26-22.aspx"},{"title":"Maryland Courts and Judicial Proceedings §10-804 — rule before October 1, 2026","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gcj&section=10-804"},{"title":"Maryland Courts and Judicial Proceedings §10-805 — existing contract exception","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gcj&section=10-805"},{"title":"2026 Chapter 509 — simultaneous-death changes effective October 1, 2026","url":"https://mgaleg.maryland.gov/2026RS/chapters_noln/Ch_509_hb0596T.pdf"},{"title":"Maryland Estates and Trusts §4-105 — wills, divorce and annulment","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=get&section=4-105"}]},{"lesson":"03","prompt":"A business keeps a financial reserve to pay a specified exposure itself instead of transferring it to an insurer. Which method describes keeping that exposure?","options":["Avoidance","An annuity settlement","Policy conversion","Retention"],"answer":3,"explanation":"Retention means bearing the exposure. A reserve can help fund it; it does not remove the exposure as avoidance would.","id":"B-2-02","domain":1,"scored":true,"sources":[{"title":"Society of Actuaries — Risk and Insurance","url":"https://www.soa.org/globalassets/assets/files/edu/P-21-05.pdf"},{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"}]},{"lesson":"46","prompt":"A refund-life option defines a $160,000 refundable purchase amount. The annuitant dies after $105,000 has been paid. Ignoring adjustments, what remains under the refund minimum?","options":["$105,000","$160,000","$265,000","$55,000"],"answer":3,"explanation":"The defined unpaid refund amount is $160,000 − $105,000 = $55,000. Cash versus installment refund determines how that remainder is paid.","id":"B-6-04","domain":5,"scored":true,"sources":[{"title":"IRS — common annuity payment types","url":"https://www.irs.gov/retirement-plans/annuities-a-brief-description"},{"title":"NAIC — payout options and living benefits","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance Administration — annuity income options","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"},{"title":"Insured Retirement Institute — cash refund and annuity terms","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Florida insurance regulator — general payout descriptions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"}]},{"lesson":"08","prompt":"A person with a covered dishonesty felony seeks insurance work affecting interstate commerce and points to a state producer license as sufficient. Which additional issue must be checked?","options":["Whether only current policyowners are subject to federal law","Whether written regulatory consent is required under the applicable federal restriction","Whether the employer can waive the federal rule orally","Whether the license automatically erases the federal restriction"],"answer":1,"explanation":"Federal restrictions for specified convictions and state licensing are distinct. Required written consent cannot be replaced simply by a license or employer assurance.","id":"B-2-08","domain":1,"scored":true,"sources":[{"title":"FTC — Consumer Reports: What Insurers Need to Know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"MIA — 18 U.S.C. 1033–1034","url":"https://insurance.maryland.gov/Producer/pages/1033waiverinfo.aspx"},{"title":"SEC — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"},{"title":"NAIC — About","url":"https://content.naic.org/about"},{"title":"Insurance Compact — About","url":"https://www.insurancecompact.org/about"},{"title":"NCOIL — State legislators and model legislation","url":"https://ncoil.org/"}]},{"lesson":"42","prompt":"A child term rider permits conversion to a specified amount of permanent coverage at the stated age without new medical evidence. Which information is needed to know the right precisely?","options":["Only the base policy’s current loan balance","The rider’s conversion deadline, permitted amount and available form","The child’s preferred insurer regardless of the rider","A universal legal promise of unlimited coverage"],"answer":1,"explanation":"Family-rider conversion rights are contractual. Amounts, ages and forms must be read from the actual rider rather than inferred as universal terms.","id":"B-5-10","domain":4,"scored":true,"sources":[{"title":"State Farm — family life and separate term riders","url":"https://www.statefarm.com/insurance/life/resources/why-buy-life-insurance"},{"title":"State Farm — universal life rider descriptions","url":"https://www.statefarm.com/insurance/life/universal-life/universal-life-insurance"},{"title":"State Farm — term rider conversion and child coverage","url":"https://www.statefarm.com/insurance/life/term-life/select-term"},{"title":"New York Life SEC-filed 2026 prospectus — child and other-insured riders","url":"https://www.sec.gov/Archives/edgar/data/906982/000119312526149337/d91382d485bpos.htm"},{"title":"Guardian — rider functions","url":"https://www.guardianlife.com/life-insurance/riders"}]},{"lesson":"02","prompt":"An insurer adds many largely independent, comparable exposures. What does the law of large numbers most directly support?","options":["More predictable average loss experience in relative terms","A guarantee against every correlated catastrophe","A promise that total claims decrease","Certainty about each individual’s death date"],"answer":0,"explanation":"Larger comparable independent groups can stabilize averages. Total claims may rise, and shared events can undermine independence; individual outcomes remain uncertain.","id":"B-2-03","domain":1,"scored":true,"sources":[]},{"lesson":"21","prompt":"Three shareholders each own policies on the other shareholders to fund purchases of their interests under an agreement. Which structure is described?","options":["Cross-purchase","A single key-person policy for operational loss","A group certificate issued by the employer","Entity purchase where the corporation owns all policies"],"answer":0,"explanation":"In a cross-purchase, owners fund purchases from one another, often with policies they own on the other owners. Entity purchase uses entity-owned coverage for the entity’s redemption obligation.","id":"B-3-07","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"MassMutual — Life insurance for business","url":"https://www.massmutual.com/business/business-life-insurance"},{"title":"MassMutual — Choosing a buy-sell arrangement","url":"https://blog.massmutual.com/work-business/business-buy-sell-right"},{"title":"New York Life — Business succession planning","url":"https://www.newyorklife.com/articles/business-succession-planning"}]},{"lesson":"18","prompt":"At policy inception, a company buys life coverage on its chief scientist based on a substantial economic interest in that person’s continued life. Which justification is most relevant?","options":["The producer’s commission entitlement","A lawful economic insurable interest","The scientist’s consent alone as a substitute for every interest requirement","The company’s desire to speculate on strangers"],"answer":1,"explanation":"A substantial economic interest can support insurable interest on another person’s life, with required consent and other conditions also evaluated. Consent alone does not make every wager lawful.","id":"B-3-01","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"}]},{"lesson":"15","prompt":"An owner requests a loan against existing life values. Under the covered Maryland replacement-chapter notice provision, what must the existing insurer address?","options":["An automatic determination that every new policy is tax free","A guarantee that loans never reduce benefits","Only the owner’s new mailing address","Possible effects on policy elements and values through the required notice within 14 business days"],"answer":3,"explanation":"The existing insurer’s value-removal notice explains possible policy effects. It is separate from a tax ruling and must follow the stated timing and circumstances.","id":"B-1-20","domain":0,"scored":true,"sources":[{"title":"COMAR 31.09.05.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.02"},{"title":"COMAR 31.09.05.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.03"},{"title":"COMAR 31.09.05.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.04"},{"title":"COMAR 31.09.05.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.05"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.09.05.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.07"},{"title":"COMAR 31.09.05.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.10"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"}]},{"lesson":"55","prompt":"An IRA owner moves funds directly from one IRA trustee to another three times in one year. How does the once-per-12-month IRA rollover limit ordinarily apply?","options":["The second transfer automatically violates the limit.","Every transfer must first be paid to the owner.","The limit is three per calendar year for every IRA movement","Direct trustee-to-trustee transfers are not subject to that owner-paid rollover limit."],"answer":3,"explanation":"The one-per-12-month rule applies to specified IRA-to-IRA 60-day rollovers, not direct trustee transfers. It is not a universal calendar-year cap on all retirement-account movements.","id":"B-7-06","domain":6,"scored":true,"sources":[{"title":"IRS — retirement plan and IRA rollovers","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/rollovers-of-retirement-plan-and-ira-distributions"},{"title":"IRS Topic 413 — rollover eligibility and withholding","url":"https://www.irs.gov/taxtopics/tc413"},{"title":"IRS Publication 590-A — rollover requirements","url":"https://www.irs.gov/publications/p590a"},{"title":"IRS Publication 590-B — inherited IRA transfers","url":"https://www.irs.gov/publications/p590b"}]},{"lesson":"10","prompt":"A producer discovers the license expired yesterday and plans to submit reinstatement today. When may new insurance business resume under the rule taught?","options":["During the whole one-year reinstatement window","Whenever the producer expects retroactive approval","As soon as a draft application is saved","After reinstatement is effective"],"answer":3,"explanation":"The reinstatement window and potential retroactive treatment do not authorize business while expired. Effective reinstatement is the relevant threshold.","id":"B-1-26","domain":0,"scored":false,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"10","prompt":"A producer files a complete reinstatement application 90 days after license expiration. Assuming requirements are met, can the producer rely on the ordinary within-60-day retroactive provision?","options":["No; this application is in the prospective reinstatement period.","Yes; every premium collected during expiration creates retroactivity.","Yes; every application within one year is retroactive.","No; reinstatement is categorically unavailable after day 60."],"answer":0,"explanation":"The ordinary one-year window includes different effective-date rules. Applications beyond 60 days receive prospective reinstatement, and expired status is not authority to conduct business.","id":"B-1-04","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"56","prompt":"A qualifying §1035 exchange moves a life contract worth $95,000 with $55,000 adjusted basis into an eligible annuity, with no cash, debt relief or other adjustment. What basis generally carries into the new contract?","options":["$0","$40,000","$95,000","$55,000"],"answer":3,"explanation":"A qualifying exchange generally carries basis and defers gain rather than resetting basis to value. The $40,000 gain is not erased merely because recognition is deferred.","id":"B-7-07","domain":6,"scored":false,"sources":[{"title":"26 USC §1035 — permitted insurance exchanges","url":"https://www.law.cornell.edu/uscode/text/26/1035"},{"title":"26 CFR §1.1035-1 — identity and exchange conditions","url":"https://www.law.cornell.edu/cfr/text/26/1.1035-1"},{"title":"IRS Revenue Ruling 2007-24 — check paid to owner","url":"https://www.irs.gov/irb/2007-21_IRB#RR-2007-24"},{"title":"IRS Revenue Procedure 2011-38 — partial annuity exchanges","url":"https://www.irs.gov/irb/2011-30_IRB#RP-2011-38"},{"title":"26 USC §7702A — MEC exchanges","url":"https://www.law.cornell.edu/uscode/text/26/7702A"},{"title":"COMAR 31.09.12.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.04"}]},{"lesson":"45","prompt":"An annuity’s fictional bailout clause waives a specified surrender charge only if the renewal credited rate falls below 2%. The new rate is 2.25%. What follows under those facts?","options":["The stated rate trigger has not been met.","The owner must receive a new lifetime payout automatically","The waiver necessarily erases all taxes regardless of the rate.","Any rate decline automatically triggers the clause."],"answer":0,"explanation":"A contract-specific threshold must actually be crossed. A rate that is lower than last year but still above the threshold does not satisfy this clause.","id":"B-6-08","domain":5,"scored":false,"sources":[{"title":"NAIC — immediate and deferred classifications","url":"https://content.naic.org/insurance-topics/annuities"},{"title":"NAIC — deferred annuity buyer’s guide","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance §16-501","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-501"},{"title":"Maryland Insurance §16-503","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-503"},{"title":"Maryland Insurance §16-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-504"},{"title":"Insured Retirement Institute — annuity terminology","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Massachusetts insurance regulator — general bailout mechanics","url":"https://www.mass.gov/info-details/buying-life-insurance-and-annuities-in-massachusetts-part-three"},{"title":"SEC-filed 2026 annuity withdrawal provisions","url":"https://www.sec.gov/Archives/edgar/data/1048606/000110465926053840/tm265210d5_497.htm"}]},{"lesson":"39","prompt":"A policyowner takes a participating dividend in cash rather than leaving it to accumulate. Which distinction matters?","options":["Every dividend automatically increases the face amount.","The cash-dividend election differs from interest earned on dividends left with the insurer.","The choice guarantees next year’s dividend","Cash dividends are always stock-market capital gains."],"answer":1,"explanation":"Dividend use is an owner election. Leaving dividends to accumulate can produce separately treated interest; receiving cash does not guarantee future dividends or buy additions.","id":"B-5-09","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-206"},{"title":"IRS — interest on deposited insurance dividends","url":"https://www.irs.gov/taxtopics/tc403"},{"title":"New York Life — dividend and paid-up definitions","url":"https://www.newyorklife.com/resources/glossary"},{"title":"Guardian — dividends and returns","url":"https://www.guardianlife.com/life-insurance/whole-life/dividends-and-returns-explained"},{"title":"MassMutual — dividend options","url":"https://www.massmutual.com/worksiteassets/wi5002.pdf"},{"title":"SEC-filed policy — one-year term dividend option","url":"https://www.sec.gov/Archives/edgar/data/317411/000119312510000115/dex9926d2.htm"},{"title":"MetLife — dividend changes and premium offset","url":"https://www.metlife.com/content/dam/metlifecom/us/homepage/support-and-manage/current-customers/individual-life-insurance/pdf/22044-Client-Dividend-Flyer-7-1A.pdf"},{"title":"Wisconsin OCI — separately identifies dividends shortening a premium-paying period","url":"https://oci.wi.gov/Documents/OCIForms/22-801.pdf"}]},{"lesson":"24","prompt":"Underwriting finds the applicant’s expected risk more favorable than the standard class and offers the insurer’s lower-rate category. Which classification fits?","options":["Declined","Substandard","Automatic guaranteed issue with no classification","Preferred"],"answer":3,"explanation":"Preferred reflects more favorable risk under the insurer’s permitted criteria. Substandard is less favorable; declined is a decision not to offer the requested coverage.","id":"B-3-12","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-504"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Consumer Financial Protection Bureau — MIB consumer reports","url":"https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/consumer-reporting-companies/companies-list/mib-inc/"},{"title":"MIB — Request and correct your consumer file","url":"https://www.mib.com/request_your_record.html"}]},{"lesson":"20","prompt":"A viator wants to reverse a settlement within the applicable ordinary rescission period. What must be included in the return under the rule taught?","options":["Proceeds and the specified premiums and loan interest paid by the provider","Nothing; ordinary rescission always allows keeping all proceeds","Only the broker’s business card","Only the difference between proceeds and original policy premiums"],"answer":0,"explanation":"Rescission unwinds the transaction with required repayment. It is not a right to recover the policy while retaining the money paid and ignoring specified provider expenditures.","id":"B-3-06","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §8-601","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-601"},{"title":"Maryland Insurance §8-602","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-602"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-604","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-604"},{"title":"Maryland Insurance §8-605","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605"},{"title":"Maryland Insurance §8-605.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605.1"},{"title":"Maryland Insurance §8-606","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-606"},{"title":"Maryland Insurance §8-607","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-607"},{"title":"Maryland Insurance §8-609","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-609"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"Maryland Insurance §8-610.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610.1"},{"title":"Maryland Insurance §27-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-403"}]},{"lesson":"13","prompt":"A competitor knowingly spreads false statements about another insurer’s financial condition to harm its business. Which unfair-practice concept is most directly involved?","options":["A policy loan election","An insurer’s good-faith underwriting decision","A lawful needs analysis","Defamation"],"answer":3,"explanation":"False statements that malign an insurer’s financial condition fit the defamation topic. Legitimate analysis and policyowner elections do not describe that conduct.","id":"B-1-15","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"Maryland Insurance §27-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-204"},{"title":"Maryland Insurance §27-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-205"},{"title":"Maryland Insurance §27-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-206"},{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-209"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"},{"title":"Maryland Insurance §27-214","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-214"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"}]},{"lesson":"10","prompt":"A business entity’s designated producer learns that information specifically covered by §10–106(c)(1) has changed. Which clock applies to that specific duty?","options":["Written notice within 10 days of the change","The general 30-day individual contact-change period in every case","The insurer’s five-business-day replacement-notification period","The next two-year renewal date"],"answer":0,"explanation":"The designated-contact rule has a specific 10-day requirement. Similar-looking individual, replacement and renewal clocks address different events.","id":"B-1-05","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"22","prompt":"A buyer compares participating and nonparticipating life policies. Which statement correctly treats participating dividends?","options":["They are mandatory fixed interest credited to every policy.","They must always be used to reduce the face amount.","They depend on divisible surplus and are not guaranteed merely because the policy participates.","They are payments from stock-market index ownership in all cases."],"answer":2,"explanation":"Participation can entitle an owner to share in divisible surplus through dividends when declared. It does not guarantee an amount or prescribe only one dividend use.","id":"B-3-09","domain":2,"scored":true,"sources":[{"title":"NAIC — A regulator’s introduction to the insurance industry, life pricing and products","url":"https://content.naic.org/sites/default/files/inline-files/prod_serv_marketreg_rii_zb.pdf"},{"title":"NAIC — Life insurance topic guide","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NAIC — Glossary of insurance terms","url":"https://content.naic.org/es/node/11821"},{"title":"SEC Investor.gov — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"}]},{"lesson":"07","prompt":"An insurer intentionally gives up a known contractual right through authorized conduct. Which concept is described?","options":["Waiver","Adverse selection","An applicant’s misrepresentation","An automatic assignment of all benefits"],"answer":0,"explanation":"Waiver is an intentional relinquishment of a known right. Estoppel additionally concerns preventing inconsistent assertion under the applicable reliance circumstances; the other choices concern different events.","id":"B-2-07","domain":1,"scored":true,"sources":[{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-406","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-406"},{"title":"Maryland Court of Appeals — Clendenin Brothers: insurance contract interpretation","url":"https://www.mdcourts.gov/data/opinions/coa/2006/2a05m.pdf"},{"title":"Maryland appellate court — waiver and estoppel","url":"https://www.courts.state.md.us/data/opinions/cosa/1996/1299s95.pdf"}]},{"lesson":"14","prompt":"A producer leaves a prospect with a handwritten illustration that silently substitutes a higher nonguaranteed rate for the approved presentation. What is the appropriate response?","options":["Use compliant approved illustration material and accurately disclose guaranteed and nonguaranteed elements.","Promise the substituted rate because the prospect signed it.","Treat handwritten estimates as exempt from accuracy duties.","Describe the rate as guaranteed if last year’s experience was favorable."],"answer":0,"explanation":"Presentation format does not excuse inaccurate or noncompliant illustrations. Past results and signatures do not guarantee the substituted assumptions.","id":"B-1-17","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"COMAR 31.09.09.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.06"},{"title":"COMAR 31.09.09.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.07"},{"title":"COMAR 31.09.09.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.09"},{"title":"COMAR 31.15.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.04"},{"title":"COMAR 31.15.03.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.05"},{"title":"COMAR 31.16.08.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.05"},{"title":"COMAR 31.16.08.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.06"},{"title":"COMAR 31.16.08.11","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.11"},{"title":"COMAR 31.16.08.17","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.17"}]},{"lesson":"48","prompt":"A Maryland producer recommends a covered annuity and records only “customer liked it,” without the collected profile or recommendation basis. Which obligation is insufficiently addressed?","options":["A requirement to guarantee all future rates","The insured’s life-policy conversion election","Automatic proof of consumer best interest through a signature","Documentation of the recommendation and supporting information"],"answer":3,"explanation":"The rule requires records supporting the recommendation and its basis. A preference statement alone does not document the relevant facts, care and disclosures.","id":"B-6-06","domain":5,"scored":true,"sources":[{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"COMAR 31.09.12.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.02"},{"title":"COMAR 31.09.12.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.03"},{"title":"COMAR 31.09.12.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.04"},{"title":"COMAR 31.09.12.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.05"},{"title":"COMAR 31.09.12.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.06"},{"title":"COMAR 31.09.12.08","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.08"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §16-114","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-114"},{"title":"IRS Publication 575 — pension and annuity income","url":"https://www.irs.gov/publications/p575"},{"title":"IRS Publication 970 — education benefits","url":"https://www.irs.gov/publications/p970"}]},{"lesson":"26","prompt":"A return-of-premium term policy reaches the end of its term with the insured alive. What determines the survival payment?","options":["A universal rule returning all charges on every term policy","The policy’s return-of-premium conditions and defined eligible premiums","The amount of the largest possible death benefit in every case","An automatic gain equal to stock-market returns"],"answer":1,"explanation":"Return-of-premium is a specified feature with conditions and a defined amount. It is not inherent in all term insurance and may exclude certain charges or require the policy to remain in force.","id":"B-4-09","domain":3,"scored":false,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"COMAR 31.04.17.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.09"},{"title":"New York DFS — General explanations of term designs; Maryland rules taught separately","url":"https://www.dfs.ny.gov/consumers/life_insurance"},{"title":"State Farm — A return-of-premium product example","url":"https://www.statefarm.com/insurance/life/term-life/return-of-premium"}]},{"lesson":"20","prompt":"A healthy older policyowner asks about selling an existing policy in Maryland. The producer says the settlement framework only covers terminally ill insureds. What is the correct distinction?","options":["Every healthy owner’s policy is automatically exempt from all settlement rules.","Maryland’s viator framework is not limited to terminally or chronically ill insureds.","A healthy owner can only request a death claim.","The owner’s age alone guarantees a particular settlement price."],"answer":1,"explanation":"The Maryland statute expressly uses a broader viator framework. Applicability and transaction requirements still need review; health status alone does not exclude every sale.","id":"B-3-05","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §8-601","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-601"},{"title":"Maryland Insurance §8-602","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-602"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-604","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-604"},{"title":"Maryland Insurance §8-605","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605"},{"title":"Maryland Insurance §8-605.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605.1"},{"title":"Maryland Insurance §8-606","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-606"},{"title":"Maryland Insurance §8-607","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-607"},{"title":"Maryland Insurance §8-609","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-609"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"Maryland Insurance §8-610.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610.1"},{"title":"Maryland Insurance §27-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-403"}]},{"lesson":"35","prompt":"An ordinary policy is reinstated after the insured gives a material false statement in the reinstatement application. What distinction matters for contestability?","options":["The original beneficiary designation is automatically invalid.","Reinstatement always makes every statement permanently incontestable immediately.","Specified reinstatement facts can be subject to their own contestability period under the applicable law.","The insurer may contest any unrelated original fact forever without limitation"],"answer":2,"explanation":"Maryland separately addresses contestability of reinstatement facts. That is not a license to reopen every original issue indefinitely or to ignore the relevant periods and standards.","id":"B-5-05","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-210"},{"title":"Maryland Insurance §16-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-208"},{"title":"Maryland Insurance §16-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-107"},{"title":"Maryland Insurance §16-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-205"},{"title":"Maryland Insurance §16-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-215"},{"title":"Maryland Insurance §16-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-216"},{"title":"Maryland Insurance §16-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-104"},{"title":"Maryland Insurance §16-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-106"},{"title":"Nassau Life — 2026 filed prospectus, age/sex correction example","url":"https://www.sec.gov/Archives/edgar/data/796154/000110465926051351/tm261977d1_485bpos.htm"}]},{"lesson":"38","prompt":"A missed premium is paid through an elected automatic premium loan while sufficient loan value exists. Which statement is correct?","options":["It uses a policy loan to pay the premium and creates or increases debt.","It converts every policy to paid-up life.","It is a free insurer contribution with no interest.","It works even when the contract has no available loan value"],"answer":0,"explanation":"An automatic premium loan is still a loan. The election, available value, interest and continued coverage conditions apply.","id":"B-5-08","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-207"},{"title":"Maryland Insurance §16-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-208"},{"title":"MetLife — whole-life loan and automatic premium loan mechanics","url":"https://www.metlife.com/support-and-manage/current-customers/individual-life-insurance/products/wl-faqs/"},{"title":"MetLife — universal-life withdrawals and policy debt","url":"https://www.metlife.com/support-and-manage/current-customers/individual-life-insurance/products/ul-faqs/"},{"title":"MassMutual — cash value and education funding","url":"https://www.massmutual.com/financial-wellness/building-a-financial-foundation"}]},{"lesson":"34","prompt":"An owner returns a newly delivered policy within the applicable free-look period. Which function does free look serve?","options":["An automatic extension of a lapsed policy","A defined right to review and return the contract under the applicable refund terms","An unlimited lifetime right to recover every premium","A substitute for the grace period on every later premium"],"answer":1,"explanation":"Free look is tied to delivery and a defined review-and-return period. Grace concerns later premium payment, and reinstatement concerns lapse.","id":"B-5-03","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-105"},{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-202"},{"title":"Maryland Insurance §16-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-203"},{"title":"Maryland Insurance §16-219","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-219"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.15.03.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.05"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"}]},{"lesson":"15","prompt":"A replacing insurer identifies a covered replacement after receiving the specified completed application. How should it treat notification of the affected existing insurer?","options":["Wait until the new policy’s first anniversary.","Follow the applicable five-business-day notification requirement.","Assume the producer’s notice to the applicant also notifies the old insurer.","Notify only after the old insurer denies a claim."],"answer":1,"explanation":"The replacing insurer has its own notification duty with the stated five-business-day trigger. Producer-to-applicant disclosure serves a different recipient and purpose.","id":"B-1-19","domain":0,"scored":true,"sources":[{"title":"COMAR 31.09.05.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.02"},{"title":"COMAR 31.09.05.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.03"},{"title":"COMAR 31.09.05.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.04"},{"title":"COMAR 31.09.05.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.05"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.09.05.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.07"},{"title":"COMAR 31.09.05.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.10"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"}]},{"lesson":"48","prompt":"A client already has tax deferral in a traditional IRA and is considering an annuity inside it. Which consideration is sound?","options":["An annuity inside an IRA is automatically exempt from every recommendation rule","Evaluate the annuity’s non-tax features, costs and guarantees; it adds no separate layer of IRA tax deferral.","The IRA eliminates every surrender charge in any annuity.","The annuity doubles the IRA’s income-tax deduction automatically."],"answer":1,"explanation":"An IRA already has its own tax treatment. Evaluate insurance guarantees, income design, costs and restrictions rather than selling redundant deferral as an additional tax benefit.","id":"B-6-07","domain":5,"scored":true,"sources":[{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"COMAR 31.09.12.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.02"},{"title":"COMAR 31.09.12.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.03"},{"title":"COMAR 31.09.12.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.04"},{"title":"COMAR 31.09.12.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.05"},{"title":"COMAR 31.09.12.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.06"},{"title":"COMAR 31.09.12.08","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.08"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §16-114","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-114"},{"title":"IRS Publication 575 — pension and annuity income","url":"https://www.irs.gov/publications/p575"},{"title":"IRS Publication 970 — education benefits","url":"https://www.irs.gov/publications/p970"}]},{"lesson":"36","prompt":"A beneficiary selects a fixed-period settlement. Which quantity is selected first?","options":["The duration of payments","The number of future premiums the insured must pay","The insured’s new risk class","A guaranteed lifetime regardless of the period"],"answer":0,"explanation":"Fixed period sets the duration, with available funds and stated interest assumptions determining payment size. Fixed amount instead chooses payment size and lets duration follow.","id":"B-5-06","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-209"},{"title":"Maryland Insurance §16-211","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-211"},{"title":"Maryland Insurance §16-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-108"},{"title":"Maryland Insurance §16-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-109"},{"title":"New York Life — claim kit and available settlement alternatives","url":"https://www.newyorklife.com/assets/docs/pdfs/nyl-internet/file-types/Life-Claim-Form.pdf"},{"title":"IRS — annuity payment forms","url":"https://www.irs.gov/retirement-plans/annuities-a-brief-description"},{"title":"New York Life — life income and joint-and-survivor definitions","url":"https://www.newyorklife.com/resources/glossary"}]},{"lesson":"57","prompt":"An employee makes pretax salary deferrals to a qualifying 401(k). Which ordinary payroll distinction is correct?","options":["Employer-plan qualification makes all later distributions tax free","Deferrals are an income-tax credit equal to the whole contribution.","Pretax automatically excludes the amounts from all payroll taxes.","The deferrals generally reduce current federal income-tax wages but remain subject to applicable Social Security and Medicare taxes."],"answer":3,"explanation":"Income-tax deferral differs from employment-tax exclusion. Later pretax distributions also generally have income-tax consequences unless another rule applies.","id":"B-8-02","domain":7,"scored":true,"sources":[{"title":"26 USC §401 — qualification requirements","url":"https://www.law.cornell.edu/uscode/text/26/401"},{"title":"IRS — 401(k) qualification requirements","url":"https://www.irs.gov/retirement-plans/plan-sponsor/401k-plan-qualification-requirements"},{"title":"IRS — vesting","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-vesting"},{"title":"IRS — 401(k) participant overview","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/401k-resource-guide-plan-participants-401k-plan-overview"},{"title":"IRS — contributions and payroll taxes","url":"https://www.irs.gov/retirement-plans/retirement-plan-faqs-regarding-contributions-are-retirement-plan-contributions-subject-to-withholding-for-fica-medicare-or-federal-income-tax"},{"title":"IRS — exceptions to early-distribution tax","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"},{"title":"IRS — required minimum distributions","url":"https://www.irs.gov/retirement-plans/retirement-plan-and-ira-required-minimum-distributions-faqs"},{"title":"IRS — Publication 560","url":"https://www.irs.gov/publications/p560"}]},{"lesson":"26","prompt":"An annual renewable term policy is renewed as the insured ages under its guaranteed renewal privilege. What typically changes according to its schedule?","options":["The premium generally increases with attained age.","The coverage automatically becomes paid-up whole life.","The beneficiary automatically becomes the insurer.","The premium is guaranteed to decrease each year."],"answer":0,"explanation":"Renewability preserves the stated opportunity to continue without new evidence under the privilege, while premiums generally rise with age. It does not itself convert the product or fix the original price.","id":"B-4-01","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"COMAR 31.04.17.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.09"},{"title":"New York DFS — General explanations of term designs; Maryland rules taught separately","url":"https://www.dfs.ny.gov/consumers/life_insurance"},{"title":"State Farm — A return-of-premium product example","url":"https://www.statefarm.com/insurance/life/term-life/return-of-premium"}]},{"lesson":"32","prompt":"A policy’s entire-contract clause identifies the policy and attached application as the agreement. A producer relies on an unattached sales note to contradict a clear provision. Which issue should be examined?","options":["Whether the beneficiary may delete all exclusions after death","What documents constitute the contract and who has authority to change it","Whether premium mode determines the complete contract","Whether every sales note automatically replaces issued terms"],"answer":1,"explanation":"The entire-contract provision and change-authority requirements identify the binding documents and permitted amendments. An informal sales note is not automatically an authorized alteration.","id":"B-5-01","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-204"},{"title":"Maryland Insurance §16-212","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-212"},{"title":"Maryland Insurance §12-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-206"},{"title":"New York Life — Ownership and assignment glossary","url":"https://www.newyorklife.com/resources/glossary"},{"title":"MassMutual — Life insurance as business loan collateral","url":"https://blog.massmutual.com/work-business/business-loan-life-insurance-collateral"},{"title":"MassMutual — Example collateral assignment terms","url":"https://www.massmutual.com/efiles/life/pdfs/f5308.pdf"}]},{"lesson":"27","prompt":"A current-assumption whole-life policy distinguishes guaranteed values from values based on current insurer assumptions. What should the producer emphasize?","options":["Current assumptions can change within the contract; guaranteed provisions are a separate reference.","A current-assumption design has no contractual provisions.","Any change always requires the owner to surrender immediately","Every current scale is guaranteed for life."],"answer":0,"explanation":"Interest-sensitive or current-assumption designs must be read for their guarantees and adjustable elements. A current illustration is not an unconditional promise that its assumptions will persist.","id":"B-4-03","domain":3,"scored":true,"sources":[{"title":"NAIC — Life insurance designs","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NYDFS — General whole-life product explanations; New York-specific rules are not Maryland rules","url":"https://www.dfs.ny.gov/faqs/consumer_faqs/life_insurance?page=2"},{"title":"MassMutual — Whole life and premium-payment periods","url":"https://blog.massmutual.com/insurance/understanding-whole-life-insurance"},{"title":"Washington insurance regulator — Product definitions, graded-premium whole life","url":"https://www.insurance.wa.gov/sites/default/files/documents/life-accident-health-annuity-crediti-pcm_6_1.pdf"}]},{"lesson":"11","prompt":"An independent producer has good-faith cause to suspect insurance fraud but no criminal judgment. What does the Maryland reporting rule require?","options":["A written report to the Fraud Division based on the good-faith concern","Delete the file to avoid retaining disputed information","Silence until a final conviction","Publicly accuse the applicant before preserving evidence"],"answer":0,"explanation":"The duty is based on good-faith cause, not proof of conviction. Report through the required channel with relevant facts; preserve records and do not equate suspicion with established guilt.","id":"B-1-10","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"53","prompt":"A worker may contribute to a traditional IRA but is covered by an employer retirement plan and has income within an applicable deduction phaseout. Which distinction matters?","options":["Every permitted traditional IRA contribution is fully deductible.","Employer-plan participation always prohibits any IRA contribution.","An IRA deduction is automatically a dollar-for-dollar tax credit","Contribution eligibility and deductibility are separate questions."],"answer":3,"explanation":"Participation and income can limit a deduction without necessarily prohibiting a contribution. Deduction, contribution limit and tax credit are different concepts.","id":"B-7-04","domain":6,"scored":true,"sources":[{"title":"IRS Publication 590-A — IRA contributions","url":"https://www.irs.gov/publications/p590a"},{"title":"IRS Publication 590-B — IRA distributions","url":"https://www.irs.gov/publications/p590b"},{"title":"IRS — 2026 IRA limits","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-ira-contribution-limits"},{"title":"IRS — 2026 cost-of-living adjustments","url":"https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500"},{"title":"IRS Topic 451 — individual retirement arrangements","url":"https://www.irs.gov/taxtopics/tc451"},{"title":"26 USC §401(a)(9) — distribution ages and beneficiaries","url":"https://www.law.cornell.edu/uscode/text/26/401"}]},{"lesson":"43","prompt":"An accidental-death rider is attached to a life policy. The insured dies from an illness, outside the rider’s covered accidental trigger. Which distinction matters?","options":["Every death is accidental for rider purposes.","The base policy may pay a covered death benefit even though the accidental rider does not add its benefit.","Failure of the rider trigger always eliminates every base death benefit.","The rider automatically refunds all premiums after any illness death"],"answer":1,"explanation":"Base coverage and supplemental rider triggers are separate. A rider’s nonpayment does not necessarily establish that the base claim is excluded.","id":"B-5-11","domain":4,"scored":true,"sources":[{"title":"New York Life SEC-filed 2026 rider descriptions","url":"https://www.sec.gov/Archives/edgar/data/906982/000119312526149337/d91382d485bpos.htm"},{"title":"Union Security SEC-filed cost-of-living rider","url":"https://www.sec.gov/Archives/edgar/data/790531/000079053126000012/usicvulregtofile.htm"},{"title":"SEC-filed return-of-premium death benefit rider","url":"https://www.sec.gov/Archives/edgar/data/801019/000119312526166328/d714689d485bpos.htm"},{"title":"State Farm — return-of-premium term coverage","url":"https://www.statefarm.com/insurance/life/term-life/return-of-premium"}]},{"lesson":"12","prompt":"Two carriers allow their premiums to be held in one compliant premium account, and no special rule prohibits it. Which statement is accurate?","options":["Any two carriers in one account always constitute prohibited commingling.","A shared account removes the minimum-balance requirement.","Permission allows unlimited personal withdrawals.","Permitted multi-carrier premiums may share a separate premium account."],"answer":3,"explanation":"Maryland distinguishes permitted premium-account deposits from mixing with operating or personal accounts. Carrier permission does not eliminate restrictions on withdrawals or required balances.","id":"B-1-11","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"09","prompt":"A person proposes to act as a Maryland viatical settlement provider before registering, relying on an ordinary life producer license. Which rule applies?","options":["Registration is needed only after the insured dies.","The provider may wait 30 days after the first negotiation under the broker rule.","Ordinary producer authority eliminates all settlement registration.","The provider must register before acting or holding itself out in that role."],"answer":3,"explanation":"Provider and broker registration triggers differ. The provider registers before acting; the broker’s separate timing rule cannot be imported into the provider role.","id":"B-1-03","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-101"},{"title":"Maryland Insurance §10-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-102"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-105"},{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-109"},{"title":"Maryland Insurance §10-111","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-111"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-120","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-120"},{"title":"Maryland Insurance §10-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-201"},{"title":"Maryland Insurance §10-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-202"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Prelicensing education change","url":"https://insurance.maryland.gov/Producer/pages/default.aspx"}]},{"lesson":"06","prompt":"A small premium may result in a large covered benefit, while another insured might pay many premiums without a claim during the term. Which contract characteristic does this illustrate?","options":["A promise of equal exchanged dollars in every outcome","Aleatory","A speculative investment guarantee","A contract without a legal purpose"],"answer":1,"explanation":"Aleatory contracts involve values exchanged that can be unequal depending on uncertain events. The insurer’s promise is governed by the contract, not equal dollar repayment to every owner.","id":"B-2-06","domain":1,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-204"}]},{"lesson":"12","prompt":"A producer wants to transfer bank interest from the premium account to the agency operating account. Which condition is specifically relevant?","options":["The carrier’s written consent","The agent’s annual production target","Only the owner’s verbal instruction to the bookkeeper","The insured’s death"],"answer":0,"explanation":"The premium-account rule requires carrier written consent for this interest transfer. It also preserves the required account balance and other applicable withdrawal conditions.","id":"B-1-12","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"18","prompt":"A valid life policy is assigned years after issue. Someone assumes the original insurable-interest test must be retaken at every premium payment. Which distinction should be applied?","options":["The interest requirement never applies at any time.","The ordinary inception requirement is separate from lawful later ownership transfers and anti-wagering or settlement rules.","Every assignment necessarily creates a new insured life.","A premium-mode change automatically voids the original interest."],"answer":1,"explanation":"Insurable interest is ordinarily tested when coverage on another is procured. Later assignments have their own legal requirements; do not impose a universal monthly requalification rule.","id":"B-3-02","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"}]},{"lesson":"19","prompt":"A needs worksheet totals $480,000. Existing life coverage provides $125,000 for those needs. Of $55,000 in liquid assets, $40,000 is reserved for another purpose and unavailable. What is the unmet need?","options":["$355,000","$410,000","$340,000","$300,000"],"answer":2,"explanation":"Only $15,000 of the liquid assets is available. Subtract $125,000 of coverage and $15,000 of usable assets from $480,000: the gap is $340,000. Subtracting all $55,000 would double-allocate the reserved funds.","id":"B-3-03","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Life insurance and annuities","url":"https://insurance.maryland.gov/Consumer/Pages/Life.aspx"},{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Guardian — Human life value and estimating coverage needs","url":"https://www.guardianlife.com/life-insurance/how-much-life-insurance-do-you-need"},{"title":"Social Security Administration — Survivor eligibility","url":"https://www.ssa.gov/survivor/eligibility"},{"title":"Social Security Administration — Survivor benefit amounts","url":"https://www.ssa.gov/survivor/amount"},{"title":"Social Security Administration — Survivors benefits","url":"https://www.ssa.gov/pubs/EN-05-10084.pdf"}]},{"lesson":"35","prompt":"A policy misstated age, and the applicable Maryland adjustment provision governs. What is the usual benefit adjustment approach?","options":["Always void the policy without considering the adjustment provision.","Increase the benefit by the number of years misstated","Use the amount the premium would have purchased at the true age, subject to the statute’s specific rules.","Always refund only the last premium regardless of the policy."],"answer":2,"explanation":"The ordinary age-misstatement adjustment relates premium to the true-age rate. Maryland has additional age-limit conditions, so the rule is not an automatic rescission in every case.","id":"B-5-04","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-210"},{"title":"Maryland Insurance §16-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-208"},{"title":"Maryland Insurance §16-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-107"},{"title":"Maryland Insurance §16-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-205"},{"title":"Maryland Insurance §16-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-215"},{"title":"Maryland Insurance §16-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-216"},{"title":"Maryland Insurance §16-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-104"},{"title":"Maryland Insurance §16-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-106"},{"title":"Nassau Life — 2026 filed prospectus, age/sex correction example","url":"https://www.sec.gov/Archives/edgar/data/796154/000110465926051351/tm261977d1_485bpos.htm"}]},{"lesson":"23","prompt":"A producer wants to include private impressions of an applicant in the file. Which standard best fits field underwriting?","options":["Omit material information if it might delay commission.","Report relevant factual observations accurately through authorized channels.","Replace objective facts with assumptions about ethnicity.","Promise the applicant that all observations guarantee acceptance."],"answer":1,"explanation":"Field reports should convey relevant, accurate observations within law and procedure. Protected traits, unsupported assumptions and compensation concerns do not justify unfair or misleading reporting.","id":"B-3-11","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"COMAR 31.04.17.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.06"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"FinCEN — Insurance company anti-money-laundering requirements","url":"https://www.fincen.gov/resources/statutes-regulations/guidance/anti-money-laundering-program-and-suspicious-activity"}]},{"lesson":"58","prompt":"A participant takes a no-exception early distribution from a SIMPLE IRA during the applicable first two years of participation. Which additional-tax rate is the specified special rule?","options":["25%","0% because all SIMPLE contributions are vested","10% in every case","50% of the account balance regardless of the distribution"],"answer":0,"explanation":"The first-two-year SIMPLE rule generally substitutes 25% for the usual 10% early-distribution additional tax where applicable. Full vesting does not itself eliminate distribution taxes.","id":"B-8-01","domain":7,"scored":true,"sources":[{"title":"IRS — SEP plans","url":"https://www.irs.gov/retirement-plans/plan-sponsor/simplified-employee-pension-plan-sep"},{"title":"IRS — self-employed retirement plans and Keogh terminology","url":"https://www.irs.gov/retirement-plans/retirement-plans-for-self-employed-people"},{"title":"IRS — profit-sharing plans","url":"https://www.irs.gov/retirement-plans/choosing-a-retirement-plan-profit-sharing-plan"},{"title":"IRS — 401(k) plans","url":"https://www.irs.gov/retirement-plans/401k-plans"},{"title":"IRS — SIMPLE IRA plans","url":"https://www.irs.gov/retirement-plans/plan-sponsor/simple-ira-plan"},{"title":"IRS — 403(b) overview","url":"https://www.irs.gov/retirement-plans/403b-plan-fix-it-guide-403b-plan-overview"},{"title":"IRS — Notice 2024-2 — Roth SEP and SIMPLE options","url":"https://www.irs.gov/irb/2024-02_IRB#NOT-2024-2"},{"title":"IRS — vesting","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-vesting"},{"title":"IRS — exceptions to early-distribution tax","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"}]},{"lesson":"15","prompt":"A policyowner claims that a properly completed replacement notice makes the surrender of an appreciated life policy automatically tax free. What is correct?","options":["Any surrender is tax free when the new insurer accepts the money.","Every replacement notice is an IRS exchange approval.","The producer’s signature resets the old policy’s tax basis to its cash value.","Replacement compliance and federal tax treatment are separate; the actual transaction controls taxation."],"answer":3,"explanation":"Disclosure compliance does not establish a qualifying §1035 exchange or erase surrender gain. Tax treatment depends on the movement of value and applicable federal rules.","id":"B-1-21","domain":0,"scored":true,"sources":[{"title":"COMAR 31.09.05.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.02"},{"title":"COMAR 31.09.05.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.03"},{"title":"COMAR 31.09.05.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.04"},{"title":"COMAR 31.09.05.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.05"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.09.05.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.07"},{"title":"COMAR 31.09.05.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.10"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"}]},{"lesson":"44","prompt":"A contract owner chooses the annuity’s permitted beneficiary. The annuitant is a different person. Which role distinction is correct?","options":["The annuitant automatically owns every right solely because payments use that life.","The owner and annuitant must be identical in every annuity","The owner exercises contractual control; the annuitant is the measuring life.","The beneficiary must always be the producer."],"answer":2,"explanation":"An annuity can have different owner, annuitant and beneficiary roles. Rights and death triggers must be read from the contract rather than merged into one person by assumption.","id":"B-6-01","domain":5,"scored":true,"sources":[{"title":"NAIC — annuities overview","url":"https://content.naic.org/insurance-topics/annuities"},{"title":"NAIC — buyer’s guide for deferred annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Investor.gov — annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"Florida insurance regulator — general annuity role definitions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"},{"title":"Maryland Insurance Administration — Annuities 101","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"}]},{"lesson":"08","prompt":"A client assumes securities registration of a variable contract means the government guarantees its investment performance. Which statement is correct?","options":["A prospectus is unnecessary whenever registration exists.","Registration replaces all state insurance requirements.","Registration guarantees that the subaccounts cannot decline.","Registration is not government endorsement or a return guarantee."],"answer":3,"explanation":"Variable products remain subject to investment risk and relevant insurance and securities requirements. Registration and a prospectus provide a regulatory framework and disclosures, not guaranteed returns.","id":"B-2-09","domain":1,"scored":false,"sources":[{"title":"FTC — Consumer Reports: What Insurers Need to Know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"MIA — 18 U.S.C. 1033–1034","url":"https://insurance.maryland.gov/Producer/pages/1033waiverinfo.aspx"},{"title":"SEC — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"},{"title":"NAIC — About","url":"https://content.naic.org/about"},{"title":"Insurance Compact — About","url":"https://www.insurancecompact.org/about"},{"title":"NCOIL — State legislators and model legislation","url":"https://ncoil.org/"}]},{"lesson":"17","prompt":"An insurer offers a low claim payment and knowingly misrepresents policy provisions to make the claimant accept. Which issue is presented?","options":["A producer’s express authority to collect applications","Unfair claims settlement conduct","A permitted dividend election","A valid change in the annuitant’s measuring life"],"answer":1,"explanation":"Misrepresenting relevant coverage provisions during claim settlement is a regulatory concern. It is not transformed into a policy election because the claimant may accept the offer.","id":"B-1-24","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §12-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-203"},{"title":"Maryland Insurance §27-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-303"},{"title":"Maryland Insurance §27-304","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-304"},{"title":"Maryland Insurance §16-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-109"},{"title":"Maryland Insurance §17-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-102"},{"title":"Maryland Insurance §9-402","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-402"},{"title":"Maryland Insurance §9-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-403"},{"title":"Maryland Insurance §9-405","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-405"},{"title":"Maryland Insurance §9-407","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-407"},{"title":"Maryland Insurance §9-409","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-409"},{"title":"Maryland Insurance §9-414","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-414"},{"title":"Maryland Life & Health Insurance Guaranty Corporation — FAQs","url":"https://www.mdlifega.org/FAQ"}]},{"lesson":"11","prompt":"After receiving the covered termination notice, a producer wants to submit comments under §10–118. Which procedure fits?","options":["Submit comments within 30 days after receipt and simultaneously send a copy to the insurer.","Send comments only to the client and consider them filed.","Wait for the next appointment to begin.","Assume comments automatically restore the terminated appointment."],"answer":0,"explanation":"The statute provides a 30-day response period and an insurer-copy requirement. Comments do not by themselves reinstate the business relationship.","id":"B-1-08","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"20","prompt":"A broker negotiating for a viator arranges to purchase the policy through a covered indirect interest in the buyer. Which issue arises under Maryland’s specific rule?","options":["An ordinary conversion without any conflict rule","An automatic exception whenever the viator is healthy","The prohibition on the broker’s direct or specified indirect purchase of a policy subject to the brokerage contract","A mandatory requirement that every broker become the buyer"],"answer":2,"explanation":"The broker’s purchase prohibition is separate from ordinary compensation disclosure. An indirect arrangement within the statute cannot be treated as conflict-free merely because another entity signs the purchase.","id":"B-3-16","domain":2,"scored":false,"sources":[{"title":"Maryland Insurance §8-601","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-601"},{"title":"Maryland Insurance §8-602","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-602"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-604","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-604"},{"title":"Maryland Insurance §8-605","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605"},{"title":"Maryland Insurance §8-605.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605.1"},{"title":"Maryland Insurance §8-606","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-606"},{"title":"Maryland Insurance §8-607","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-607"},{"title":"Maryland Insurance §8-609","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-609"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"Maryland Insurance §8-610.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610.1"},{"title":"Maryland Insurance §27-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-403"}]},{"lesson":"28","prompt":"A universal-life policy’s values are declining because charges exceed credits and funding. The owner hears “flexible premium” and stops paying entirely. What must be evaluated?","options":["Whether flexibility means charges have ceased permanently","Whether value and any guarantee conditions are sufficient to maintain coverage","Whether the policy automatically pays its face amount while the insured lives","Whether every monthly deduction becomes a dividend"],"answer":1,"explanation":"Payment flexibility operates within policy mechanics. Charges, values and specific no-lapse guarantee conditions must be reviewed; flexibility alone does not make coverage permanently self-funding.","id":"B-4-04","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Universal life insurance","url":"https://insurance.maryland.gov/Consumer/Pages/Universal-Life-Insurance.aspx"},{"title":"NAIC — Life insurance designs","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NYDFS — General whole-life product explanations; New York-specific rules are not Maryland rules","url":"https://www.dfs.ny.gov/faqs/consumer_faqs/life_insurance?page=2"},{"title":"Nationwide — Indexed universal life guide; product illustrations, not universal rates","url":"https://financial.nationwide.com/media/pdf/FLM-1376AO.pdf"},{"title":"Nationwide — Indexed UL Accumulator III product disclosures","url":"https://www.nationwide.com/personal/insurance/life/permanent/indexed-universal/indexed-ul-accumulator-III/"},{"title":"Nationwide — No-lapse guarantee universal life","url":"https://www.nationwide.com/personal/insurance/life/permanent/universal/no-lapse-guarantee-UL-II/"}]},{"lesson":"19","prompt":"An analysis estimates the economic value of a worker’s future contributions after considering income, personal consumption and a discount rate. Which approach is being used?","options":["A simple face-amount refund","A policy’s automatic premium loan","A beneficiary per-stirpes allocation","Human life value"],"answer":3,"explanation":"Human life value estimates the present economic value of future contributions. It differs from itemizing survivors’ specific needs and from policy operation options.","id":"B-3-04","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Life insurance and annuities","url":"https://insurance.maryland.gov/Consumer/Pages/Life.aspx"},{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Guardian — Human life value and estimating coverage needs","url":"https://www.guardianlife.com/life-insurance/how-much-life-insurance-do-you-need"},{"title":"Social Security Administration — Survivor eligibility","url":"https://www.ssa.gov/survivor/eligibility"},{"title":"Social Security Administration — Survivor benefit amounts","url":"https://www.ssa.gov/survivor/amount"},{"title":"Social Security Administration — Survivors benefits","url":"https://www.ssa.gov/pubs/EN-05-10084.pdf"}]},{"lesson":"21","prompt":"An employer pays a bonus intended to help an executive buy personally owned life coverage. What should be identified before calling it employer-owned key-person insurance?","options":["Only whether the executive works full time","Only who wrote the bonus check","Who owns the policy and receives its benefits under the actual bonus arrangement","Whether the premium is paid in January"],"answer":2,"explanation":"An executive-bonus arrangement can support employee-owned coverage. Funding a bonus does not by itself establish employer ownership or make the employer the beneficiary.","id":"B-3-08","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"MassMutual — Life insurance for business","url":"https://www.massmutual.com/business/business-life-insurance"},{"title":"MassMutual — Choosing a buy-sell arrangement","url":"https://blog.massmutual.com/work-business/business-buy-sell-right"},{"title":"New York Life — Business succession planning","url":"https://www.newyorklife.com/articles/business-succession-planning"}]},{"lesson":"31","prompt":"An employee assumes a government life-insurance program and the employer’s private group policy have identical eligibility, benefits and continuation rules. What is the sound approach?","options":["Review each program’s own eligibility and provisions.","Treat every government program as a personal annuity.","Assume neither arrangement can name a beneficiary","Apply every private group provision to every government program."],"answer":0,"explanation":"Government and private arrangements can serve related needs but have distinct governing provisions. Identify the actual program before importing eligibility or continuation rules.","id":"B-4-08","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-203"},{"title":"Maryland Insurance §17-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-204"},{"title":"Maryland Insurance §17-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-206"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-307","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-307"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"OPM — Federal Employees’ Group Life Insurance","url":"https://www.opm.gov/healthcare-insurance/life-insurance/"},{"title":"VA — Servicemembers’ Group Life Insurance","url":"https://www.va.gov/life-insurance/options-eligibility/sgli/"},{"title":"VA — Veterans’ Group Life Insurance","url":"https://www.va.gov/life-insurance/options-eligibility/vgli/"}]},{"lesson":"09","prompt":"An employee explains that Maryland eliminated mandatory prelicensing education in October 2024, so the employee intends to skip the regular life licensing exam. Which correction is needed?","options":["Only insurer appointments remain necessary.","The change eliminated all licensing requirements.","The change replaced the examination with ordinary renewal CE.","The education prerequisite changed; applicable examination and application requirements remain."],"answer":3,"explanation":"Prelicensing education, the initial exam and renewal CE are different requirements. The 2024 education change did not remove the regular licensing examination.","id":"B-1-01","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-101"},{"title":"Maryland Insurance §10-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-102"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-105"},{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-109"},{"title":"Maryland Insurance §10-111","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-111"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-120","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-120"},{"title":"Maryland Insurance §10-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-201"},{"title":"Maryland Insurance §10-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-202"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Prelicensing education change","url":"https://insurance.maryland.gov/Producer/pages/default.aspx"}]},{"lesson":"52","prompt":"Under a stated fixed-annuity General Rule calculation, investment in the contract is $72,000 and expected return is $180,000. What percentage of each payment is initially excluded, subject to the basis-recovery cap?","options":["40%","60%","100%","2.5%"],"answer":0,"explanation":"The exclusion ratio is $72,000 ÷ $180,000 = 40%. The other 60% is generally taxable while that ratio applies; the total excluded amount is capped by investment recovered.","id":"B-7-03","domain":6,"scored":true,"sources":[{"title":"26 USC §72 — annuity income and distribution rules","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"IRS Publication 939 — General Rule","url":"https://www.irs.gov/publications/p939"},{"title":"IRS Publication 575 — annuity distributions","url":"https://www.irs.gov/publications/p575"}]},{"lesson":"29","prompt":"An adjustable-life owner wants to increase the death benefit significantly. Which statement is appropriate?","options":["The contract may require evidence of insurability for an increase.","Only premium mode can ever be changed under adjustable life","An increase necessarily converts the contract into an annuity.","Every adjustment must be allowed without underwriting."],"answer":0,"explanation":"Adjustable life allows specified changes, subject to the contract. Increasing insurer risk may require evidence; adjustability is not unrestricted authority to change every term.","id":"B-4-05","domain":3,"scored":true,"sources":[{"title":"FINRA — Insurance agents and variable-product authority","url":"https://www.finra.org/investors/investing/working-with-investment-professional/insurance-agents"},{"title":"FINRA Rule 2211 — Variable-product communications","url":"https://www.finra.org/rules-guidance/rulebooks/finra-rules/2211"},{"title":"SEC Investor.gov — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"},{"title":"SEC filing — Scheduled-premium variable whole life example, not a universal product promise","url":"https://www.sec.gov/Archives/edgar/data/742277/000119312526180744/d75572d485bpos.htm"},{"title":"Guardian — Adjustable life and permitted changes","url":"https://www.guardianlife.com/life-insurance/adjustable"},{"title":"SEC filing — Adjustable-life plan and premium mechanics","url":"https://www.sec.gov/Archives/edgar/data/789535/000119312520122165/d839488d485bpos.htm"},{"title":"NAIC — General life insurance product categories","url":"https://content.naic.org/insurance-topics/life-insurance"}]},{"lesson":"11","prompt":"An insurer must send the producer a copy of a required discipline-related termination notice after notifying the Commissioner. Which ordinary period applies to that copy?","options":["15 years after the appointment began","Only at the producer’s next renewal","15 days after the required regulator notice","Five business days after the original policy application"],"answer":2,"explanation":"The copy-to-producer period is 15 days after the required notice. The producer’s separate comment period runs from receiving it.","id":"B-1-07","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"50","prompt":"A 40-year-old receives a $35,000 distribution from a MEC with $90,000 value and $60,000 basis. No exception applies. What taxable portion and 10% additional tax result under the gain-first rule?","options":["$5,000 taxable; $500 additional tax","$30,000 taxable; $3,000 additional tax","$0 taxable; $0 additional tax","$35,000 taxable; $3,500 additional tax"],"answer":1,"explanation":"Gain is $30,000 and is distributed first. The remaining $5,000 is basis. The additional tax is 10% of the $30,000 includible amount, not every dollar withdrawn.","id":"B-7-02","domain":6,"scored":true,"sources":[{"title":"26 USC §7702A — seven-pay test and contract changes","url":"https://www.law.cornell.edu/uscode/text/26/7702A"},{"title":"26 USC §72 — distributions and modified endowment contracts","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"SEC-filed 2026 policy tax disclosure","url":"https://www.sec.gov/Archives/edgar/data/771726/000119312526172890/d89381d485bpos.htm"},{"title":"IRS — MEC definition and distribution rules","url":"https://www.irs.gov/irb/2007-07_IRB"},{"title":"26 USC §101 — life death-benefit rule","url":"https://www.law.cornell.edu/uscode/text/26/101"}]},{"lesson":"12","prompt":"A formerly licensed and appointed life producer receives qualifying renewal commissions on earlier business under the statutory exception. What should be distinguished?","options":["All compensation to a former licensee is necessarily prohibited.","Permitted renewal or deferred compensation is different from authority to conduct new unlicensed sales.","The exception authorizes all future solicitation.","Receiving any renewal commission automatically renews a license."],"answer":1,"explanation":"The exception concerns qualifying renewal or deferred commissions. It neither bans every such payment nor grants current authority to sell, solicit or negotiate.","id":"B-1-13","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"14","prompt":"An applicant is told that consent to one information disclosure permits every future disclosure for any purpose. Which principle corrects this?","options":["Privacy rules apply only after a claim.","Use and disclosure remain subject to applicable notices, authorizations, exceptions and limits.","A producer may publish application details if names are omitted but the person remains identifiable.","Any one consent eliminates all privacy rules."],"answer":1,"explanation":"Insurance privacy duties depend on the type, purpose and authority for disclosure. One permission is not unlimited authority for unrelated uses.","id":"B-1-18","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"COMAR 31.09.09.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.06"},{"title":"COMAR 31.09.09.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.07"},{"title":"COMAR 31.09.09.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.09"},{"title":"COMAR 31.15.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.04"},{"title":"COMAR 31.15.03.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.05"},{"title":"COMAR 31.16.08.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.05"},{"title":"COMAR 31.16.08.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.06"},{"title":"COMAR 31.16.08.11","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.11"},{"title":"COMAR 31.16.08.17","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.17"}]},{"lesson":"01","prompt":"An insured becomes careless about precautions because “the insurer will pay anyway,” without falsifying anything. Which concept best fits?","options":["A collateral assignment","Moral hazard based on deliberate fraud","Morale hazard","A peril that has already caused death"],"answer":2,"explanation":"Morale hazard is carelessness or indifference associated with insurance. Deliberate dishonesty is moral hazard; the scenario has not stated an actual loss event.","id":"B-2-01","domain":1,"scored":true,"sources":[]},{"lesson":"30","prompt":"A parent buys juvenile life on a child with a payor rider. What must be kept separate?","options":["A parent’s premium payment and automatic ownership by the insurer","A child’s age and a guaranteed retirement payout","The insured child’s coverage and the rider’s qualifying event affecting the payor","The child’s life and every future employer’s group policy"],"answer":2,"explanation":"Juvenile life insures the child. A payor rider addresses specified premium consequences if its conditions affecting the payor occur; it does not change whose life is insured.","id":"B-4-06","domain":3,"scored":true,"sources":[{"title":"New York Life — First-death and survivorship coverage","url":"https://www.newyorklife.com/articles/joint-life-insurance"},{"title":"MassMutual — Juvenile policy ownership","url":"https://blog.massmutual.com/insurance/milestone-birthday-life-insurance"},{"title":"MassMutual — Example spouse and child term riders; product-specific terms","url":"https://www.massmutual.com/worksiteassets/wi5077_2020.pdf"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §13-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-101"},{"title":"Maryland Insurance §13-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-105"},{"title":"Maryland Insurance §13-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-106"},{"title":"Maryland Insurance §13-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-107"},{"title":"Maryland Insurance §13-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-109"},{"title":"Maryland Insurance §13-112","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-112"},{"title":"COMAR 31.13.01.25","url":"https://regs.maryland.gov/us/md/exec/comar/31.13.01.25"}]},{"lesson":"09","prompt":"A nonresident producer’s home-state license is no longer in good standing. The producer assumes the Maryland nonresident license is unaffected because its printed expiration date is later. What should the producer recognize?","options":["Nonresident authority is a permanent nationwide license.","The printed date overrides all home-state requirements.","A client’s signature restores the home-state license.","Continuing nonresident authority depends on applicable home-state standing and Maryland requirements, not merely the printed date."],"answer":3,"explanation":"Home-state standing is central to nonresident authority. A displayed expiration date is not proof that all ongoing qualifications remain met.","id":"B-1-02","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-101"},{"title":"Maryland Insurance §10-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-102"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-105"},{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-109"},{"title":"Maryland Insurance §10-111","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-111"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-120","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-120"},{"title":"Maryland Insurance §10-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-201"},{"title":"Maryland Insurance §10-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-202"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Prelicensing education change","url":"https://insurance.maryland.gov/Producer/pages/default.aspx"}]},{"lesson":"24","prompt":"A life applicant is a victim of domestic violence. Which Maryland distinction is appropriate?","options":["A producer may disclose abuse information publicly to justify a quote.","Victim status is always a sufficient reason to decline.","Victim status is protected; medical conditions have a separate statutory rule.","The insurer must ignore every medical condition in every circumstance."],"answer":2,"explanation":"The statute protects against specified adverse uses of victim status or abuse information and separately addresses medical-condition consideration. Neither a blanket adverse status rule nor unrestricted disclosure is justified.","id":"B-3-13","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-504"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Consumer Financial Protection Bureau — MIB consumer reports","url":"https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/consumer-reporting-companies/companies-list/mib-inc/"},{"title":"MIB — Request and correct your consumer file","url":"https://www.mib.com/request_your_record.html"}]},{"lesson":"26","prompt":"An increasing-term design provides death protection that rises under its stated formula. Which feature must be checked to know the actual amount?","options":["The annuitant’s life expectancy","The owner’s chosen dividend option on another policy","The contractual increase schedule or formula","The assumption that all term has a level benefit"],"answer":2,"explanation":"Increasing term is not one universal amount schedule. The policy specifies the benefit changes; other products’ dividends and annuity concepts do not determine it.","id":"B-4-02","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"COMAR 31.04.17.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.09"},{"title":"New York DFS — General explanations of term designs; Maryland rules taught separately","url":"https://www.dfs.ny.gov/consumers/life_insurance"},{"title":"State Farm — A return-of-premium product example","url":"https://www.statefarm.com/insurance/life/term-life/return-of-premium"}]},{"lesson":"37","prompt":"An owner elects cash surrender rather than reduced paid-up or extended term. What is the ordinary coverage consequence?","options":["All policy debt is ignored when determining net value","The original death benefit necessarily continues forever.","The surrendered coverage ends and the applicable net surrender value is paid.","The insurer must provide both cash and identical free coverage."],"answer":2,"explanation":"Cash surrender exchanges the policy for its applicable net value and ends the surrendered protection. Loans, charges and tax consequences still need evaluation.","id":"B-5-07","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-301"},{"title":"Maryland Insurance §16-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-303"},{"title":"Maryland Insurance §16-304","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-304"},{"title":"Maryland Insurance §16-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-210"},{"title":"New York Life — nonforfeiture and paid-up definitions","url":"https://www.newyorklife.com/resources/glossary"},{"title":"New York DFS — general nonforfeiture concepts","url":"https://www.dfs.ny.gov/consumers/life_insurance"}]},{"lesson":"16","prompt":"An eligible employee converts Maryland group life after leaving work. Which expectation is incorrect?","options":["That the statutory conversion can avoid new evidence of insurability","That attained age and the available form affect the individual premium","That the application and first premium must meet the applicable deadline","That the individual policy must retain the former group premium and every supplementary rider"],"answer":3,"explanation":"Conversion preserves a coverage opportunity under stated terms. It does not guarantee the old group price or carry all disability and supplementary benefits into the individual policy.","id":"B-1-23","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-302","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-302"},{"title":"Maryland Insurance §17-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-303"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"Maryland Insurance §17-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-104"}]},{"lesson":"23","prompt":"An applicant’s signed application leaves a requested material item blank. The producer assumes underwriting will read the blank as “no.” What is the appropriate next action?","options":["Insert a favorable answer without contacting the applicant.","Destroy the application and retain only a premium receipt.","Obtain the missing answer through the authorized process.","Treat every blank as a warranty of no risk."],"answer":2,"explanation":"A blank is not a reliable response to a requested fact. Complete the application accurately with the applicant’s required participation rather than inventing or concealing information.","id":"B-3-10","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"COMAR 31.04.17.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.06"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"FinCEN — Insurance company anti-money-laundering requirements","url":"https://www.fincen.gov/resources/statutes-regulations/guidance/anti-money-laundering-program-and-suspicious-activity"}]},{"lesson":"16","prompt":"An employer terminates its entire covered group life policy. An employee has six years of coverage. Which provision must be examined rather than automatically importing ordinary job-termination conversion amounts?","options":["A rule requiring the employee to pass new medical underwriting in every conversion","Only the individual-policy reinstatement rule","The separate group-policy/class-termination rule, including its permitted lesser-of limit","A universal unlimited continuation at the old group price"],"answer":2,"explanation":"The entire-group/class-termination provision has its own five-year condition and possible lesser-of adjusted loss or $10,000 limit. Ordinary employment-termination conversion is a different event.","id":"B-1-22","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-302","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-302"},{"title":"Maryland Insurance §17-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-303"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"Maryland Insurance §17-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-104"}]},{"lesson":"11","prompt":"The Commissioner requests electronically stored appointment records. Which retrieval period is taught for that specific Maryland rule?","options":["Within 10 calendar months","Within 10 working days of the request","At any time during the five-year retention period","Only after the next market-conduct examination"],"answer":1,"explanation":"Retention and retrieval are different duties. Electronic appointment records must be retrievable within 10 working days of the request.","id":"B-1-09","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"04","prompt":"An insurer receives a strong independent financial-strength rating. Which conclusion is justified?","options":["The rating replaces policy terms.","The rating guarantees every projected dividend.","The rating issues the producer’s state license.","The rating is an opinion useful for evaluation, not a guarantee that all future obligations are risk free."],"answer":3,"explanation":"Ratings can inform financial review but are opinions that can change. They are not contractual guarantees, licensing documents or promises of projected dividends.","id":"B-2-10","domain":1,"scored":false,"sources":[{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"},{"title":"NAIC — Insurance Topics","url":"https://content.naic.org/insurance-topics"},{"title":"Maryland insurer search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"},{"title":"Maryland Insurance §4-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=4-203"}]},{"lesson":"54","prompt":"A Roth IRA owner withdrew the regular contribution basis already. The next dollars come from a recent taxable conversion before its separate five-year period has elapsed; the owner is under 59½ and has no exception. Which issue must be checked?","options":["The conversion-related additional-tax rule, even though the conversion income was already taxed","A guarantee that every conversion principal withdrawal is penalty free immediately","Ordinary income tax a second time on the same converted principal in every case","An automatic employer-plan RMD"],"answer":0,"explanation":"Roth ordering and separate conversion clocks matter. Previously taxed converted principal is not simply taxed again as ordinary income, but an early withdrawal can trigger the stated additional-tax rule.","id":"B-7-05","domain":6,"scored":true,"sources":[{"title":"IRS Publication 590-A — IRA contributions","url":"https://www.irs.gov/publications/p590a"},{"title":"IRS Publication 590-B — IRA distributions","url":"https://www.irs.gov/publications/p590b"},{"title":"IRS — 2026 IRA limits","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-ira-contribution-limits"},{"title":"IRS — 2026 cost-of-living adjustments","url":"https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500"},{"title":"IRS Topic 451 — individual retirement arrangements","url":"https://www.irs.gov/taxtopics/tc451"},{"title":"26 USC §408A — Roth IRA requirements","url":"https://www.law.cornell.edu/uscode/text/26/408A"}]}]},{"id":"C","title":"Timed Form C","minutes":105,"questions":[{"lesson":"53","prompt":"An IRA owner turns 73 in 2026 and is subject to the ordinary first-RMD rule. If the first RMD is delayed until April 1, 2027, what other deadline must be planned for?","options":["The second RMD is automatically due April 1, 2028.","The 2027 RMD is still due by December 31, 2027.","No further RMD is due until 2028.","All RMDs end once the owner takes the first one"],"answer":1,"explanation":"Delaying the first distribution can place two RMDs in the following calendar year. The first-year April deadline does not move all later annual deadlines.","id":"C-7-05","domain":6,"scored":true,"sources":[{"title":"IRS Publication 590-A — IRA contributions","url":"https://www.irs.gov/publications/p590a"},{"title":"IRS Publication 590-B — IRA distributions","url":"https://www.irs.gov/publications/p590b"},{"title":"IRS — 2026 IRA limits","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-ira-contribution-limits"},{"title":"IRS — 2026 cost-of-living adjustments","url":"https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500"},{"title":"IRS Topic 451 — individual retirement arrangements","url":"https://www.irs.gov/taxtopics/tc451"},{"title":"26 USC §401(a)(9) — distribution ages and beneficiaries","url":"https://www.law.cornell.edu/uscode/text/26/401"}]},{"lesson":"34","prompt":"An ordinary life policy is still within its grace period. The owner asks whether reinstatement paperwork is required just to pay the late premium within that period. Which distinction applies?","options":["Grace continues the policy for the stated period; reinstatement addresses coverage after a lapse.","Grace eliminates the need to pay the premium at all","Every late payment automatically requires new underwriting.","Grace and reinstatement are identical procedures."],"answer":0,"explanation":"An active grace period is distinct from lapse and reinstatement. The owner still owes the premium under the policy, but being within grace does not itself establish a lapse.","id":"C-5-03","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-105"},{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-202"},{"title":"Maryland Insurance §16-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-203"},{"title":"Maryland Insurance §16-219","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-219"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.15.03.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.05"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"}]},{"lesson":"14","prompt":"An insurer has qualifying limited information-sharing practices but changed the previously disclosed privacy practices. Can it rely solely on limited sharing to skip the annual notice?","options":["Yes; privacy notice duties end once a first premium is paid.","No; the annual-notice exception also requires the specified practices to remain unchanged.","No; the exception depends only on the applicant’s age.","Yes; the unchanged-practices condition is never relevant."],"answer":1,"explanation":"The annual-notice exception requires both conditions. Changing the practices can defeat it even when information sharing remains within otherwise permitted categories.","id":"C-1-18","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"COMAR 31.09.09.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.06"},{"title":"COMAR 31.09.09.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.07"},{"title":"COMAR 31.09.09.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.09"},{"title":"COMAR 31.15.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.04"},{"title":"COMAR 31.15.03.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.05"},{"title":"COMAR 31.16.08.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.05"},{"title":"COMAR 31.16.08.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.06"},{"title":"COMAR 31.16.08.11","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.11"},{"title":"COMAR 31.16.08.17","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.17"}]},{"lesson":"37","prompt":"An owner compares a smaller permanent paid-up benefit with the original amount for a limited term. Which pair of nonforfeiture choices is being compared?","options":["Accidental death and guaranteed insurability","Reduced paid-up and extended term","A collateral assignment and a revocable beneficiary","Cash surrender and an interest-only settlement"],"answer":1,"explanation":"Reduced paid-up changes the permanent amount; extended term uses value for temporary protection at the applicable original amount. The other pairs concern different policy functions.","id":"C-5-07","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-301"},{"title":"Maryland Insurance §16-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-303"},{"title":"Maryland Insurance §16-304","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-304"},{"title":"Maryland Insurance §16-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-210"},{"title":"New York Life — nonforfeiture and paid-up definitions","url":"https://www.newyorklife.com/resources/glossary"},{"title":"New York DFS — general nonforfeiture concepts","url":"https://www.dfs.ny.gov/consumers/life_insurance"}]},{"lesson":"07","prompt":"An applicant accidentally gives an incorrect fact without the intent to deceive. Which statement avoids collapsing different legal concepts?","options":["The error automatically transfers ownership to the insurer.","An innocent error can never affect underwriting or policy rights under any law.","Every mistake proves intentional fraud.","An incorrect representation is not automatically fraud; materiality and the applicable legal standard still matter."],"answer":3,"explanation":"Fraud has elements beyond simple inaccuracy. At the same time, an incorrect statement can matter under the applicable materiality and policy rules even without the stated intent.","id":"C-2-06","domain":1,"scored":true,"sources":[{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-406","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-406"},{"title":"Maryland Court of Appeals — Clendenin Brothers: insurance contract interpretation","url":"https://www.mdcourts.gov/data/opinions/coa/2006/2a05m.pdf"},{"title":"Maryland appellate court — waiver and estoppel","url":"https://www.courts.state.md.us/data/opinions/cosa/1996/1299s95.pdf"}]},{"lesson":"19","prompt":"A client wants a legacy for heirs and money to meet settlement expenses, but a large part of wealth is tied up in a farm. Which analysis should guide the amount and ownership design?","options":["The assumption that every death benefit is excluded from every possible tax","The stated estate and liquidity needs, available resources, beneficiary arrangement and applicable tax rules","A rule that all life proceeds must be paid to the estate","The farm’s acreage alone"],"answer":1,"explanation":"The use can be estate conservation or liquidity, but ownership and beneficiary design affect the outcome. Income-tax exclusion does not automatically resolve estate-tax inclusion or liquidity timing.","id":"C-3-04","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Life insurance and annuities","url":"https://insurance.maryland.gov/Consumer/Pages/Life.aspx"},{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Guardian — Human life value and estimating coverage needs","url":"https://www.guardianlife.com/life-insurance/how-much-life-insurance-do-you-need"},{"title":"Social Security Administration — Survivor eligibility","url":"https://www.ssa.gov/survivor/eligibility"},{"title":"Social Security Administration — Survivor benefit amounts","url":"https://www.ssa.gov/survivor/amount"},{"title":"Social Security Administration — Survivors benefits","url":"https://www.ssa.gov/pubs/EN-05-10084.pdf"}]},{"lesson":"05","prompt":"A producer tells a customer “I can change any exclusion,” but the insurer has not granted or held out that authority. What is the best conclusion from the statement alone?","options":["Any assertion automatically creates express authority.","Every employee has unrestricted contractual power.","The customer’s belief always rewrites clear policy terms without further facts.","The producer’s assertion alone does not establish authority to change exclusions."],"answer":3,"explanation":"Authority must be supported by the principal’s grant or legally relevant manifestations and facts. A producer cannot simply confer unlimited powers on oneself.","id":"C-2-10","domain":1,"scored":false,"sources":[{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland reported opinion — scope of insurance agency authority","url":"https://www.courts.state.md.us/data/opinions/cosa/2012/0915s09.pdf"}]},{"lesson":"15","prompt":"An owner is exercising a contractual conversion that satisfies an express exclusion from the Maryland replacement chapter. What is the correct approach?","options":["Ignore all contract and tax consequences because a chapter exclusion applies.","Assume every future surrender is also excluded.","Use the exclusion to waive unrelated licensing requirements.","Apply the exclusion’s actual conditions instead of automatically treating every policy change as a covered replacement."],"answer":3,"explanation":"Scope comes first. A specific contractual-conversion exclusion can affect replacement procedures without eliminating all other applicable duties or tax analysis.","id":"C-1-21","domain":0,"scored":true,"sources":[{"title":"COMAR 31.09.05.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.02"},{"title":"COMAR 31.09.05.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.03"},{"title":"COMAR 31.09.05.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.04"},{"title":"COMAR 31.09.05.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.05"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.09.05.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.07"},{"title":"COMAR 31.09.05.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.10"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"}]},{"lesson":"29","prompt":"A prospect compares variable whole life with variable universal life. Which feature should not be inferred simply from the word variable?","options":["The relevance of separate-account choices","The need to review investment risks","The presence of investment-linked features","Whether the premium schedule is flexible"],"answer":3,"explanation":"Variable describes investment-related features. Whole-life versus universal-life design determines other mechanics, including premium flexibility; the single word variable does not settle those mechanics.","id":"C-4-09","domain":3,"scored":false,"sources":[{"title":"FINRA — Insurance agents and variable-product authority","url":"https://www.finra.org/investors/investing/working-with-investment-professional/insurance-agents"},{"title":"FINRA Rule 2211 — Variable-product communications","url":"https://www.finra.org/rules-guidance/rulebooks/finra-rules/2211"},{"title":"SEC Investor.gov — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"},{"title":"SEC filing — Scheduled-premium variable whole life example, not a universal product promise","url":"https://www.sec.gov/Archives/edgar/data/742277/000119312526180744/d75572d485bpos.htm"},{"title":"Guardian — Adjustable life and permitted changes","url":"https://www.guardianlife.com/life-insurance/adjustable"},{"title":"SEC filing — Adjustable-life plan and premium mechanics","url":"https://www.sec.gov/Archives/edgar/data/789535/000119312520122165/d839488d485bpos.htm"},{"title":"NAIC — General life insurance product categories","url":"https://content.naic.org/insurance-topics/life-insurance"}]},{"lesson":"03","prompt":"A proposed risk produces losses that cannot reasonably be measured or defined. Why is that a problem for ordinary insurability?","options":["Premiums are unrelated to expected losses.","A loss must be sufficiently definite and measurable to evaluate the promise and cost.","Risk pooling can identify exact future events without assumptions.","Every pure risk must be accepted regardless of measurability."],"answer":1,"explanation":"Insurable-risk features include definable and measurable losses alongside other conditions. Pure-risk status alone does not make every exposure suitable for insurance.","id":"C-2-03","domain":1,"scored":true,"sources":[{"title":"Society of Actuaries — Risk and Insurance","url":"https://www.soa.org/globalassets/assets/files/edu/P-21-05.pdf"},{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"}]},{"lesson":"47","prompt":"A fixed indexed annuity applies a 60% participation rate to an 8% index increase, with no other limit under this fictional formula. What is the credit?","options":["8%","4.8%","13.33%","60%"],"answer":1,"explanation":"8% × 60% = 4.8%. The actual contract can have other limits, methods and conditions; the owner does not automatically receive the index’s entire return.","id":"C-6-05","domain":5,"scored":true,"sources":[{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"SEC — Indexed annuity mechanics","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated-investor-bulletin-indexed-annuities"},{"title":"SEC — Variable annuity operation and costs","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated-5"}]},{"lesson":"03","prompt":"A company installs better safety controls but continues the underlying activity. Which risk-management method is shown?","options":["Speculative gain","Reduction","Complete avoidance","Automatic transfer of all losses to employees"],"answer":1,"explanation":"Reduction lowers likelihood or severity while exposure remains. Avoidance would remove the activity; the facts state no financial transfer contract.","id":"C-2-02","domain":1,"scored":true,"sources":[{"title":"Society of Actuaries — Risk and Insurance","url":"https://www.soa.org/globalassets/assets/files/edu/P-21-05.pdf"},{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"}]},{"lesson":"21","prompt":"A business has both a potential loss of a founder’s services and a contractual obligation to buy the founder’s shares after death. What should the analysis recognize?","options":["Any key-person death benefit necessarily transfers the shares.","One purpose automatically eliminates the other.","These are separate funding needs that may require coordinated coverage.","A buy-sell agreement makes beneficiary design irrelevant."],"answer":2,"explanation":"Operational loss and ownership purchase are distinct. Insurance proceeds alone do not automatically transfer shares; the agreement, policy ownership and beneficiary arrangement must align.","id":"C-3-08","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"MassMutual — Life insurance for business","url":"https://www.massmutual.com/business/business-life-insurance"},{"title":"MassMutual — Choosing a buy-sell arrangement","url":"https://blog.massmutual.com/work-business/business-buy-sell-right"},{"title":"New York Life — Business succession planning","url":"https://www.newyorklife.com/articles/business-succession-planning"}]},{"lesson":"35","prompt":"An owner surrendered the policy for cash and later seeks ordinary statutory reinstatement as if it were only a missed-premium lapse. What is the issue?","options":["A new premium mode reverses the surrender.","Every surrendered policy is automatically reinstatable without conditions.","Cash surrender falls outside the stated ordinary reinstatement opportunity.","A beneficiary’s written request always recreates the old contract"],"answer":2,"explanation":"The Maryland reinstatement provision has exclusions, including surrender for cash. A surrender should not be treated as the same event as a qualifying unpaid-premium lapse.","id":"C-5-05","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-210"},{"title":"Maryland Insurance §16-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-208"},{"title":"Maryland Insurance §16-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-107"},{"title":"Maryland Insurance §16-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-205"},{"title":"Maryland Insurance §16-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-215"},{"title":"Maryland Insurance §16-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-216"},{"title":"Maryland Insurance §16-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-104"},{"title":"Maryland Insurance §16-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-106"},{"title":"Nassau Life — 2026 filed prospectus, age/sex correction example","url":"https://www.sec.gov/Archives/edgar/data/796154/000110465926051351/tm261977d1_485bpos.htm"}]},{"lesson":"04","prompt":"Members join a group to purchase liability coverage collectively. The group says that buying together automatically makes it an insurer. Which distinction matters?","options":["Purchasing together eliminates the need for a policy.","Group membership guarantees payment of every loss from member donations.","Every group of buyers automatically receives a certificate of authority.","A purchasing group arranges buying; that fact alone does not make it the risk-bearing insurer."],"answer":3,"explanation":"Distribution and risk-bearing roles are separate. A purchasing arrangement does not by itself establish an insurer or its legal authority.","id":"C-2-04","domain":1,"scored":true,"sources":[{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"},{"title":"NAIC — Insurance Topics","url":"https://content.naic.org/insurance-topics"},{"title":"Maryland insurer search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"},{"title":"Maryland Insurance §4-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=4-203"}]},{"lesson":"09","prompt":"An employer’s salaried employee administers only the employer’s own benefits and receives no insurer compensation. What is the appropriate way to analyze a producer-license exception?","options":["Assume salary exempts every type of insurance sales work.","Check the specific employee-benefits exception and all its conditions.","Assume no statutory exception can ever apply.","Treat the employer’s benefit enrollment form as an insurer appointment."],"answer":1,"explanation":"The law contains conditional exceptions. Employer-benefit administration without insurer compensation can qualify on the specified facts; salary alone is not a universal exemption.","id":"C-1-03","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-101"},{"title":"Maryland Insurance §10-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-102"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-105"},{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-109"},{"title":"Maryland Insurance §10-111","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-111"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-120","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-120"},{"title":"Maryland Insurance §10-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-201"},{"title":"Maryland Insurance §10-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-202"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Prelicensing education change","url":"https://insurance.maryland.gov/Producer/pages/default.aspx"}]},{"lesson":"45","prompt":"An accumulation-phase death-benefit formula promises the greater of eligible adjusted premiums or account value. Those amounts are $130,000 and $122,000, with no other adjustments. What is the contractual benefit under that formula?","options":["$130,000","$122,000","$8,000","$252,000"],"answer":0,"explanation":"The stated greater-of formula selects $130,000. This is a contract-benefit calculation, not a conclusion that the annuity payment is federally income-tax-free life-insurance proceeds.","id":"C-6-08","domain":5,"scored":false,"sources":[{"title":"NAIC — immediate and deferred classifications","url":"https://content.naic.org/insurance-topics/annuities"},{"title":"NAIC — deferred annuity buyer’s guide","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance §16-501","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-501"},{"title":"Maryland Insurance §16-503","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-503"},{"title":"Maryland Insurance §16-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-504"},{"title":"Insured Retirement Institute — annuity terminology","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Massachusetts insurance regulator — general bailout mechanics","url":"https://www.mass.gov/info-details/buying-life-insurance-and-annuities-in-massachusetts-part-three"},{"title":"SEC-filed 2026 annuity withdrawal provisions","url":"https://www.sec.gov/Archives/edgar/data/1048606/000110465926053840/tm265210d5_497.htm"}]},{"lesson":"10","prompt":"A producer wants to resume after a license has been expired for more than one year. Which pathway ordinarily applies under the rules taught?","options":["A temporary license issued solely because a prior license existed","Unlimited late reinstatement without new requirements","The initial-license pathway with applicable requirements","Automatic renewal upon paying one old commission"],"answer":2,"explanation":"Ordinary reinstatement is limited to the stated one-year period. After that window, the applicant uses the initial-license process and applicable qualifications.","id":"C-1-04","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"10","prompt":"A nonresident producer satisfies qualifying home-state CE under reciprocal requirements. Which statement avoids overstating Maryland’s ordinary resident rule?","options":["An insurer appointment is proof that home-state CE was completed.","Every nonresident must duplicate all resident Maryland CE regardless of reciprocity.","Nonresident status exempts the producer from every licensing rule.","Qualifying home-state compliance may satisfy Maryland CE for the nonresident."],"answer":3,"explanation":"Nonresident reciprocity is distinct from the regular Maryland resident hours rule. It does not eliminate all other authority and maintenance requirements.","id":"C-1-06","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"06","prompt":"A policy promises payment only when a covered event and the contract’s required conditions are satisfied. Which characteristic best describes those requirements?","options":["An unconditional refund agreement","A contract that must pay every possible event","Conditional","A bilateral promise to keep paying premiums forever"],"answer":2,"explanation":"Insurance promises depend on applicable conditions. The term does not mean the insurer may arbitrarily refuse a covered claim; it means the actual contractual conditions matter.","id":"C-2-05","domain":1,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-204"}]},{"lesson":"29","prompt":"A variable universal-life buyer wants both premium flexibility and investment choices. Which combination should be explained?","options":["A promise that investment gains always cover all insurance charges","Flexible funding subject to policy sufficiency, plus separate-account investment risk","A fixed bank deposit with no investment exposure","Guaranteed unlimited funding flexibility with no lapse risk"],"answer":1,"explanation":"VUL combines universal-life funding mechanics with variable investment features. Neither part eliminates the need for adequate funding, charges review or attention to guarantees.","id":"C-4-05","domain":3,"scored":true,"sources":[{"title":"FINRA — Insurance agents and variable-product authority","url":"https://www.finra.org/investors/investing/working-with-investment-professional/insurance-agents"},{"title":"FINRA Rule 2211 — Variable-product communications","url":"https://www.finra.org/rules-guidance/rulebooks/finra-rules/2211"},{"title":"SEC Investor.gov — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"},{"title":"SEC filing — Scheduled-premium variable whole life example, not a universal product promise","url":"https://www.sec.gov/Archives/edgar/data/742277/000119312526180744/d75572d485bpos.htm"},{"title":"Guardian — Adjustable life and permitted changes","url":"https://www.guardianlife.com/life-insurance/adjustable"},{"title":"SEC filing — Adjustable-life plan and premium mechanics","url":"https://www.sec.gov/Archives/edgar/data/789535/000119312520122165/d839488d485bpos.htm"},{"title":"NAIC — General life insurance product categories","url":"https://content.naic.org/insurance-topics/life-insurance"}]},{"lesson":"36","prompt":"A retained-asset account is offered for death proceeds. A beneficiary assumes it is an FDIC-insured bank checking account merely because drafts can be written. Which correction is needed?","options":["The insurer-backed arrangement and applicable disclosures must be understood; draft access does not establish FDIC insurance.","The drafts are guaranteed stock dividends.","The account necessarily has no insurer credit exposure","Every account with drafts is automatically FDIC insured."],"answer":0,"explanation":"A retained-asset account is generally an insurer obligation under its terms. A check-like feature alone does not turn it into an insured bank deposit.","id":"C-5-06","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-209"},{"title":"Maryland Insurance §16-211","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-211"},{"title":"Maryland Insurance §16-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-108"},{"title":"Maryland Insurance §16-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-109"},{"title":"New York Life — claim kit and available settlement alternatives","url":"https://www.newyorklife.com/assets/docs/pdfs/nyl-internet/file-types/Life-Claim-Form.pdf"},{"title":"IRS — annuity payment forms","url":"https://www.irs.gov/retirement-plans/annuities-a-brief-description"},{"title":"New York Life — life income and joint-and-survivor definitions","url":"https://www.newyorklife.com/resources/glossary"}]},{"lesson":"48","prompt":"A proposed annuity replacement would restart surrender charges and surrender a valuable existing benefit. What should the recommendation assess?","options":["The tradeoff between lost benefits, new costs and the consumer’s actual needs","Only the producer’s prior sales volume","Only the new contract’s most favorable illustrated rate","An assumption that every replacement improves liquidity"],"answer":0,"explanation":"A replacement comparison must consider what is lost and gained, costs and the consumer profile. A selected illustration number is not the entire recommendation basis.","id":"C-6-07","domain":5,"scored":true,"sources":[{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"COMAR 31.09.12.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.02"},{"title":"COMAR 31.09.12.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.03"},{"title":"COMAR 31.09.12.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.04"},{"title":"COMAR 31.09.12.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.05"},{"title":"COMAR 31.09.12.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.06"},{"title":"COMAR 31.09.12.08","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.08"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §16-114","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-114"},{"title":"IRS Publication 575 — pension and annuity income","url":"https://www.irs.gov/publications/p575"},{"title":"IRS Publication 970 — education benefits","url":"https://www.irs.gov/publications/p970"}]},{"lesson":"31","prompt":"An employer-funded noncontributory Maryland group-life arrangement excludes a person who has made a permitted written rejection. Why does “noncontributory” alone not settle every eligibility issue?","options":["The statute and policy include stated eligibility conditions and exceptions.","A written rejection automatically makes the insurer a mutual company.","Noncontributory means no one has any life coverage.","Funding by the employer always removes all employee choices and statutory exceptions"],"answer":0,"explanation":"The ordinary noncontributory coverage requirement must be read with its written-rejection and other stated exceptions. Funding classification is not the entire eligibility rule.","id":"C-4-07","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-203"},{"title":"Maryland Insurance §17-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-204"},{"title":"Maryland Insurance §17-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-206"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-307","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-307"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"OPM — Federal Employees’ Group Life Insurance","url":"https://www.opm.gov/healthcare-insurance/life-insurance/"},{"title":"VA — Servicemembers’ Group Life Insurance","url":"https://www.va.gov/life-insurance/options-eligibility/sgli/"},{"title":"VA — Veterans’ Group Life Insurance","url":"https://www.va.gov/life-insurance/options-eligibility/vgli/"}]},{"lesson":"16","prompt":"A covered Maryland employer group plan insures an employee for $70,000 and proposes $90,000 of spouse dependent coverage under the rule taught. What is the issue?","options":["Dependent coverage cannot exceed the employee’s amount under that rule.","Every spouse must be insured for twice the employee’s amount.","Dependent coverage is always prohibited.","The group conversion period automatically raises the employee’s benefit to $90,000."],"answer":0,"explanation":"Maryland permits specified dependent coverage but limits its amount to the employee’s or member’s coverage under this provision. Permission to cover dependents is not permission for any amount.","id":"C-1-22","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-302","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-302"},{"title":"Maryland Insurance §17-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-303"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"Maryland Insurance §17-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-104"}]},{"lesson":"35","prompt":"A policy expressly excludes a particular aviation activity, and the insured dies while engaged in that excluded activity. Which question is separate from whether the policy is contestable?","options":["Whether all aviation deaths are excluded under every policy","Whether incontestability erases every coverage exclusion","Whether the beneficiary may change the exclusion retroactively","Whether the actual exclusion applies to the facts"],"answer":3,"explanation":"An exclusion addresses the scope of covered events. Contestability addresses specified validity challenges; the policy wording and facts must be applied without importing a universal aviation exclusion.","id":"C-5-04","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-210"},{"title":"Maryland Insurance §16-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-208"},{"title":"Maryland Insurance §16-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-107"},{"title":"Maryland Insurance §16-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-205"},{"title":"Maryland Insurance §16-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-215"},{"title":"Maryland Insurance §16-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-216"},{"title":"Maryland Insurance §16-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-104"},{"title":"Maryland Insurance §16-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-106"},{"title":"Nassau Life — 2026 filed prospectus, age/sex correction example","url":"https://www.sec.gov/Archives/edgar/data/796154/000110465926051351/tm261977d1_485bpos.htm"}]},{"lesson":"44","prompt":"An owner begins scheduled withdrawals from an accumulated annuity without electing a lifetime income option. Which inference is unsafe?","options":["That tax treatment depends on the kind of distribution","That the contract’s withdrawal provisions should be reviewed","That periodic withdrawals necessarily constitute an irrevocable lifetime annuitization election","That account values may change as withdrawals occur"],"answer":2,"explanation":"A recurring payment schedule does not by itself prove annuitization or a lifetime guarantee. The actual election and contractual arrangement determine those features.","id":"C-6-01","domain":5,"scored":true,"sources":[{"title":"NAIC — annuities overview","url":"https://content.naic.org/insurance-topics/annuities"},{"title":"NAIC — buyer’s guide for deferred annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Investor.gov — annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"Florida insurance regulator — general annuity role definitions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"},{"title":"Maryland Insurance Administration — Annuities 101","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"}]},{"lesson":"01","prompt":"A policy covers a specified death benefit even though the family’s actual future income loss could be greater. What explains why payment is not automatically an exact reimbursement of that economic loss?","options":["The policy cannot pay more than total premiums.","The beneficiary may demand unlimited additional payment.","Life insurance generally pays the stated contractual benefit rather than measuring every dollar of actual loss as indemnity.","The producer decides the amount after death without reference to the contract."],"answer":2,"explanation":"Life benefits are valued contractual promises, subject to terms and adjustments. Insurable interest and the contract matter, but payment is not automatically an itemized reimbursement of every family expense.","id":"C-2-01","domain":1,"scored":true,"sources":[]},{"lesson":"27","prompt":"A graded-premium whole-life contract uses lower initial premiums followed by a stated higher schedule. Which description is accurate?","options":["The initial premium is guaranteed never to rise.","Graded premium always means every death benefit is graded in the same way.","The premium schedule changes as specified; review it separately from any graded death-benefit feature.","The higher scheduled premium is necessarily an unauthorized insurer surcharge"],"answer":2,"explanation":"Graded-premium and graded-benefit features describe different elements. The premium-paying schedule must be disclosed and understood without assuming the same benefit pattern.","id":"C-4-02","domain":3,"scored":true,"sources":[{"title":"NAIC — Life insurance designs","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NYDFS — General whole-life product explanations; New York-specific rules are not Maryland rules","url":"https://www.dfs.ny.gov/faqs/consumer_faqs/life_insurance?page=2"},{"title":"MassMutual — Whole life and premium-payment periods","url":"https://blog.massmutual.com/insurance/understanding-whole-life-insurance"},{"title":"Washington insurance regulator — Product definitions, graded-premium whole life","url":"https://www.insurance.wa.gov/sites/default/files/documents/life-accident-health-annuity-crediti-pcm_6_1.pdf"}]},{"lesson":"48","prompt":"A producer uses a form disclosing compensation but never acts with reasonable care in comparing the consumer’s needs and the recommended annuity. Which conclusion is correct?","options":["A signed disclosure always establishes best interest.","Care applies only if the consumer later loses money","Disclosure alone does not satisfy the separate care obligation.","Compensation disclosure replaces the consumer profile."],"answer":2,"explanation":"The four obligations are related but separate: care, disclosure, conflicts and documentation. Signing one disclosure is not a substitute for a sound recommendation process.","id":"C-6-06","domain":5,"scored":true,"sources":[{"title":"SEC Investor.gov — Annuities","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/annuities"},{"title":"NAIC — Buyer’s Guide to Annuities","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"COMAR 31.09.12.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.02"},{"title":"COMAR 31.09.12.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.03"},{"title":"COMAR 31.09.12.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.04"},{"title":"COMAR 31.09.12.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.05"},{"title":"COMAR 31.09.12.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.06"},{"title":"COMAR 31.09.12.08","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.08"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §16-114","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-114"},{"title":"IRS Publication 575 — pension and annuity income","url":"https://www.irs.gov/publications/p575"},{"title":"IRS Publication 970 — education benefits","url":"https://www.irs.gov/publications/p970"}]},{"lesson":"49","prompt":"An owner borrows against an in-force non-MEC life policy, then later allows the heavily indebted policy to lapse. Why is a tax review important at lapse?","options":["The beneficiary’s age alone decides loan tax treatment","Every policy loan remains tax free forever regardless of termination.","Lapse always makes the whole original death benefit taxable.","Debt extinguished in the termination can affect proceeds and create taxable gain beyond basis."],"answer":3,"explanation":"An ordinary in-force non-MEC loan and termination with debt are different events. Debt relief at lapse or surrender can contribute to a gain calculation; the amount and basis must be established.","id":"C-7-01","domain":6,"scored":true,"sources":[{"title":"IRS Publication 525 — life insurance proceeds","url":"https://www.irs.gov/publications/p525"},{"title":"26 USC §72 — distributions and modified endowment contracts","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"SEC-filed 2026 policy tax disclosure","url":"https://www.sec.gov/Archives/edgar/data/771726/000119312526172890/d89381d485bpos.htm"},{"title":"IRS — Interest received","url":"https://www.irs.gov/taxtopics/tc403"},{"title":"26 USC §101 — death benefits and transfer exceptions","url":"https://www.law.cornell.edu/uscode/text/26/101"},{"title":"IRS Form 706 instructions — insurance and lifetime transfers","url":"https://www.irs.gov/instructions/i706"},{"title":"IRS Publication 502 — nondeductible life premiums","url":"https://www.irs.gov/publications/p502"}]},{"lesson":"22","prompt":"An insurer lowers its assumed future investment earnings while keeping mortality and expenses unchanged in a simplified premium model. What direction would generally put pressure on the needed premium?","options":["Exactly double in every contract","No possible effect, because interest is never a pricing factor","Upward, because less investment income is assumed to help fund the benefit","Downward, because lower earnings always fund more benefits"],"answer":2,"explanation":"In the simplified relationship, less assumed interest means more premium funding may be needed, all else equal. The direction does not establish a universal numeric increase or an actual rate quote.","id":"C-3-09","domain":2,"scored":true,"sources":[{"title":"NAIC — A regulator’s introduction to the insurance industry, life pricing and products","url":"https://content.naic.org/sites/default/files/inline-files/prod_serv_marketreg_rii_zb.pdf"},{"title":"NAIC — Life insurance topic guide","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NAIC — Glossary of insurance terms","url":"https://content.naic.org/es/node/11821"},{"title":"SEC Investor.gov — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"}]},{"lesson":"30","prompt":"A family protection arrangement provides permanent coverage on one person and term protection on additional family members. What must be examined before assuming equal benefits for everyone?","options":["A rule that one premium means identical permanent coverage on all lives","Only the family surname","The base policy and each rider’s insured person, amount, term and conditions","The base insured’s beneficiary designation as proof of each rider’s conversion terms"],"answer":2,"explanation":"Family arrangements combine components with different coverage and rights. One package or premium does not make every component identical.","id":"C-4-06","domain":3,"scored":true,"sources":[{"title":"New York Life — First-death and survivorship coverage","url":"https://www.newyorklife.com/articles/joint-life-insurance"},{"title":"MassMutual — Juvenile policy ownership","url":"https://blog.massmutual.com/insurance/milestone-birthday-life-insurance"},{"title":"MassMutual — Example spouse and child term riders; product-specific terms","url":"https://www.massmutual.com/worksiteassets/wi5077_2020.pdf"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §13-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-101"},{"title":"Maryland Insurance §13-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-105"},{"title":"Maryland Insurance §13-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-106"},{"title":"Maryland Insurance §13-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-107"},{"title":"Maryland Insurance §13-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-109"},{"title":"Maryland Insurance §13-112","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-112"},{"title":"COMAR 31.13.01.25","url":"https://regs.maryland.gov/us/md/exec/comar/31.13.01.25"}]},{"lesson":"10","prompt":"A producer reports a covered criminal matter only after conviction. The initial court appearance occurred four months earlier. What distinction explains the potential reporting failure?","options":["Neither clock applies to a currently appointed producer.","The criminal clock ordinarily starts at initial court appearance, whereas the administrative-action clock uses final disposition.","Reporting is optional unless the license expires during the proceeding.","Both clocks always start at final conviction."],"answer":1,"explanation":"Identify the kind of proceeding before selecting a deadline. Waiting for conviction can miss the criminal-reporting requirement even though final disposition is relevant to a different duty.","id":"C-1-05","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-115","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-115"},{"title":"Maryland Insurance §10-116","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116"},{"title":"Maryland Insurance §10-116.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-116.1"},{"title":"Maryland Insurance §10-117","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-117"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Changes on a license","url":"https://insurance.maryland.gov/Producer/Pages/How-to-Make-Changes-on-a-License.aspx"}]},{"lesson":"12","prompt":"An agency owner voluntarily deposits money into a compliant premium account to keep it adequately funded. What is the correct distinction?","options":["The deposit removes all limits on withdrawals.","Every voluntary deposit is necessarily misappropriation.","The deposit turns every customer premium into owner equity.","A permitted voluntary deposit does not authorize mixing the premium account with ordinary operating or personal accounts."],"answer":3,"explanation":"The regulation permits specified deposits while retaining separate-account and minimum-balance restrictions. Deposit permission is not blanket permission to use fiduciary funds personally.","id":"C-1-11","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"30","prompt":"A borrower’s credit-life protection declines as the covered debt is paid down. What broader household need may remain even if that debt is fully protected?","options":["An automatic need for an immediate annuity on the creditor","No possible life-insurance need of any kind","Income support and other expenses beyond the covered debt","Only the creditor’s future business profits"],"answer":2,"explanation":"Debt protection is a specific purpose. Paying off a loan does not necessarily replace lost earnings, services, education funding or other household needs.","id":"C-4-08","domain":3,"scored":true,"sources":[{"title":"New York Life — First-death and survivorship coverage","url":"https://www.newyorklife.com/articles/joint-life-insurance"},{"title":"MassMutual — Juvenile policy ownership","url":"https://blog.massmutual.com/insurance/milestone-birthday-life-insurance"},{"title":"MassMutual — Example spouse and child term riders; product-specific terms","url":"https://www.massmutual.com/worksiteassets/wi5077_2020.pdf"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §13-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-101"},{"title":"Maryland Insurance §13-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-105"},{"title":"Maryland Insurance §13-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-106"},{"title":"Maryland Insurance §13-107","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-107"},{"title":"Maryland Insurance §13-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-109"},{"title":"Maryland Insurance §13-112","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=13-112"},{"title":"COMAR 31.13.01.25","url":"https://regs.maryland.gov/us/md/exec/comar/31.13.01.25"}]},{"lesson":"02","prompt":"A pool contains many exposures affected by one common event. Which caution limits a simplistic “larger always means predictable” claim?","options":["Correlation guarantees fewer total claims.","Correlation can cause many losses together and weakens the independence assumption.","A large pool legally cannot experience a common event.","The law of large numbers identifies each future claimant."],"answer":1,"explanation":"The familiar averaging principle relies on suitable comparable exposures and independence assumptions. Correlated events can produce concentrated losses despite a large headcount.","id":"C-2-09","domain":1,"scored":false,"sources":[]},{"lesson":"45","prompt":"A deferred annuity has a paid-up nonforfeiture benefit available when contributions stop. What should the owner avoid assuming?","options":["That the actual contract category and applicable law matter","That surrender and stopping new contributions are different events","That nonforfeiture guarantees an unrestricted full refund of all premiums on demand","That existing values can support a stated benefit"],"answer":2,"explanation":"Nonforfeiture preserves specified values or benefits under the relevant law and contract. It does not necessarily provide unrestricted access or a full-premium refund; scope exceptions matter.","id":"C-6-02","domain":5,"scored":true,"sources":[{"title":"NAIC — immediate and deferred classifications","url":"https://content.naic.org/insurance-topics/annuities"},{"title":"NAIC — deferred annuity buyer’s guide","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance §16-501","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-501"},{"title":"Maryland Insurance §16-503","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-503"},{"title":"Maryland Insurance §16-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-504"},{"title":"Insured Retirement Institute — annuity terminology","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Massachusetts insurance regulator — general bailout mechanics","url":"https://www.mass.gov/info-details/buying-life-insurance-and-annuities-in-massachusetts-part-three"},{"title":"SEC-filed 2026 annuity withdrawal provisions","url":"https://www.sec.gov/Archives/edgar/data/1048606/000110465926053840/tm265210d5_497.htm"}]},{"lesson":"46","prompt":"A retiree wants a guaranteed lifetime payment and a minimum total for beneficiaries if death occurs early. Which feature most directly adds the latter protection to lifetime income?","options":["A life-with-refund option","Pure life with no added guarantee","A fixed monthly withdrawal with no lifetime promise","A period-certain-only option with no life component"],"answer":0,"explanation":"A refund-life option combines life income with its defined minimum total. Pure life lacks the added minimum; fixed withdrawals and period-only payments do not establish lifelong income.","id":"C-6-03","domain":5,"scored":true,"sources":[{"title":"IRS — common annuity payment types","url":"https://www.irs.gov/retirement-plans/annuities-a-brief-description"},{"title":"NAIC — payout options and living benefits","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance Administration — annuity income options","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"},{"title":"Insured Retirement Institute — cash refund and annuity terms","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Florida insurance regulator — general payout descriptions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"}]},{"lesson":"20","prompt":"An insured in a covered settlement has a life expectancy greater than one year. Under the disclosed Maryland health-status contact limit taught, how often may contact ordinarily occur at most?","options":["Once each week","Once each month under the one-year-or-less category","Once every three months","Once every day"],"answer":2,"explanation":"The rule distinguishes more than one year from one year or less. The former uses a maximum once every three months; the latter allows the stated monthly frequency.","id":"C-3-06","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §8-601","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-601"},{"title":"Maryland Insurance §8-602","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-602"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-604","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-604"},{"title":"Maryland Insurance §8-605","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605"},{"title":"Maryland Insurance §8-605.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605.1"},{"title":"Maryland Insurance §8-606","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-606"},{"title":"Maryland Insurance §8-607","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-607"},{"title":"Maryland Insurance §8-609","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-609"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"Maryland Insurance §8-610.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610.1"},{"title":"Maryland Insurance §27-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-403"}]},{"lesson":"50","prompt":"A MEC is exchanged into another life policy in a qualifying exchange. Which statement about MEC classification is generally correct?","options":["Every exchange automatically removes MEC status.","Changing the insurer alone restarts the contract as non-MEC.","A new beneficiary alone eliminates the seven-pay classification","MEC status carries to the replacement contract under the applicable rules."],"answer":3,"explanation":"MEC status is not erased merely through a qualifying exchange or insurer change. Exchange qualification and distribution classification are separate questions.","id":"C-7-02","domain":6,"scored":true,"sources":[{"title":"26 USC §7702A — seven-pay test and contract changes","url":"https://www.law.cornell.edu/uscode/text/26/7702A"},{"title":"26 USC §72 — distributions and modified endowment contracts","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"SEC-filed 2026 policy tax disclosure","url":"https://www.sec.gov/Archives/edgar/data/771726/000119312526172890/d89381d485bpos.htm"},{"title":"IRS — MEC definition and distribution rules","url":"https://www.irs.gov/irb/2007-07_IRB"},{"title":"26 USC §101 — life death-benefit rule","url":"https://www.law.cornell.edu/uscode/text/26/101"}]},{"lesson":"08","prompt":"A variable-life salesperson holds only ordinary state life authority. What must be evaluated before completing a securities sale?","options":["Whether a state life license automatically covers every securities permission","Whether the word life eliminates investment regulation","The applicable securities registration and sales requirements in addition to state insurance authority","Whether a client can waive all registration rules"],"answer":2,"explanation":"Variable products combine insurance and securities features. The relevant authorities and sales requirements both apply; customer consent does not waive them.","id":"C-2-08","domain":1,"scored":true,"sources":[{"title":"FTC — Consumer Reports: What Insurers Need to Know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"MIA — 18 U.S.C. 1033–1034","url":"https://insurance.maryland.gov/Producer/pages/1033waiverinfo.aspx"},{"title":"SEC — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"},{"title":"NAIC — About","url":"https://content.naic.org/about"},{"title":"Insurance Compact — About","url":"https://www.insurancecompact.org/about"},{"title":"NCOIL — State legislators and model legislation","url":"https://ncoil.org/"}]},{"lesson":"57","prompt":"An employee separates from service in the year the employee turns 55 and considers a distribution from that employer’s qualifying plan. Which distinction should be examined?","options":["Age 55 automatically makes every IRA withdrawal tax free.","The exception necessarily eliminates ordinary income tax on pretax money.","Separating years earlier automatically satisfies the year-55 trigger upon a later birthday","A plan-specific separation-from-service exception may avoid the early-distribution additional tax, but it is not the same exception for an IRA."],"answer":3,"explanation":"The exception depends on the plan and separation timing, with specific rules. Relief from additional tax does not itself remove ordinary income tax or carry the same exception into an IRA.","id":"C-8-02","domain":7,"scored":true,"sources":[{"title":"26 USC §401 — qualification requirements","url":"https://www.law.cornell.edu/uscode/text/26/401"},{"title":"IRS — 401(k) qualification requirements","url":"https://www.irs.gov/retirement-plans/plan-sponsor/401k-plan-qualification-requirements"},{"title":"IRS — vesting","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-vesting"},{"title":"IRS — 401(k) participant overview","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/401k-resource-guide-plan-participants-401k-plan-overview"},{"title":"IRS — contributions and payroll taxes","url":"https://www.irs.gov/retirement-plans/retirement-plan-faqs-regarding-contributions-are-retirement-plan-contributions-subject-to-withholding-for-fica-medicare-or-federal-income-tax"},{"title":"IRS — exceptions to early-distribution tax","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"},{"title":"IRS — required minimum distributions","url":"https://www.irs.gov/retirement-plans/retirement-plan-and-ira-required-minimum-distributions-faqs"},{"title":"IRS — Publication 560","url":"https://www.irs.gov/publications/p560"}]},{"lesson":"58","prompt":"A self-employed professional encounters the older term Keogh or HR-10 plan. What does the term refer to in this context?","options":["An annuity available only to public-school employees","A Roth IRA with no contribution limits","A qualified retirement plan for the self-employed, which can use defined-contribution or defined-benefit designs","One uniquely required life-insurance product"],"answer":2,"explanation":"Keogh is an older label for qualified plans for self-employed people, not a single insurance product. Plan design and legal requirements determine the actual arrangement.","id":"C-8-01","domain":7,"scored":true,"sources":[{"title":"IRS — SEP plans","url":"https://www.irs.gov/retirement-plans/plan-sponsor/simplified-employee-pension-plan-sep"},{"title":"IRS — self-employed retirement plans and Keogh terminology","url":"https://www.irs.gov/retirement-plans/retirement-plans-for-self-employed-people"},{"title":"IRS — profit-sharing plans","url":"https://www.irs.gov/retirement-plans/choosing-a-retirement-plan-profit-sharing-plan"},{"title":"IRS — 401(k) plans","url":"https://www.irs.gov/retirement-plans/401k-plans"},{"title":"IRS — SIMPLE IRA plans","url":"https://www.irs.gov/retirement-plans/plan-sponsor/simple-ira-plan"},{"title":"IRS — 403(b) overview","url":"https://www.irs.gov/retirement-plans/403b-plan-fix-it-guide-403b-plan-overview"},{"title":"IRS — Notice 2024-2 — Roth SEP and SIMPLE options","url":"https://www.irs.gov/irb/2024-02_IRB#NOT-2024-2"},{"title":"IRS — vesting","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-vesting"},{"title":"IRS — exceptions to early-distribution tax","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"}]},{"lesson":"12","prompt":"A producer retains an annuity recommendation file for five years after the insurer completes the covered transaction and then deletes it. Which period applies to that file under the Maryland annuity rule?","options":["Seven years after the insurer completes the transaction","One year after the producer’s next renewal","Only until the surrender period expires","Five years after an unrelated appointment ends"],"answer":0,"explanation":"The annuity recommendation record rule uses seven years from transaction completion. Appointment retention and product surrender periods are separate clocks.","id":"C-1-14","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"24","prompt":"An adverse action is based partly on a consumer report. The notice says the reporting agency made the insurance decision and that disputes are forbidden. What is wrong?","options":["Dispute rights depend solely on the producer’s permission.","The reporting agency always decides coverage.","Only favorable underwriting actions require any report notice.","The insurer made the decision; required notice explains relevant access and dispute rights."],"answer":3,"explanation":"The notice must distinguish the agency’s report from the insurer’s decision and describe the applicable rights. Blaming the agency and denying dispute rights misstates those duties.","id":"C-3-13","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-504"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Consumer Financial Protection Bureau — MIB consumer reports","url":"https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/consumer-reporting-companies/companies-list/mib-inc/"},{"title":"MIB — Request and correct your consumer file","url":"https://www.mib.com/request_your_record.html"}]},{"lesson":"16","prompt":"An insured assigns only a specified group-life benefit under a valid arrangement. An assignee claims the assignment must include every unrelated policy right. Which response is correct?","options":["Every assignment is automatically absolute.","The producer chooses the scope after the insured dies.","Determine the rights actually assigned; a limited assignment does not necessarily transfer all rights.","Group-life rights can never be assigned."],"answer":2,"explanation":"The Maryland arrangement can assign any or all specified rights. Its actual scope, along with notice and other requirements, controls what the assignee receives.","id":"C-1-23","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-302","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-302"},{"title":"Maryland Insurance §17-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-303"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"Maryland Insurance §17-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-104"}]},{"lesson":"27","prompt":"A straight whole-life policy requires scheduled premiums throughout its stated premium-paying lifetime. Which design differs primarily by limiting the number of required payments?","options":["Limited-pay whole life","A fixed-period annuity payout","A credit-life certificate","Annual renewable term"],"answer":0,"explanation":"Limited-pay whole life shortens the required premium-paying period while retaining permanent coverage under its terms. The other choices change broader product or payout features.","id":"C-4-03","domain":3,"scored":true,"sources":[{"title":"NAIC — Life insurance designs","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NYDFS — General whole-life product explanations; New York-specific rules are not Maryland rules","url":"https://www.dfs.ny.gov/faqs/consumer_faqs/life_insurance?page=2"},{"title":"MassMutual — Whole life and premium-payment periods","url":"https://blog.massmutual.com/insurance/understanding-whole-life-insurance"},{"title":"Washington insurance regulator — Product definitions, graded-premium whole life","url":"https://www.insurance.wa.gov/sites/default/files/documents/life-accident-health-annuity-crediti-pcm_6_1.pdf"}]},{"lesson":"25","prompt":"A producer receives a signed good-health statement that reveals a significant change since the application. The producer has no authority to waive the delivery condition. What is the proper response?","options":["Alter the statement to match the earlier application.","Follow the insurer’s reporting and delivery instructions before representing coverage as effective.","Ignore the change because a policy number exists.","Declare the receipt unconditional without reading it."],"answer":1,"explanation":"Report the actual change and apply the insurer’s requirements. The producer should not conceal new information or waive conditions beyond delegated authority.","id":"C-3-14","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Transamerica SEC filing — Example of issuance and conditional coverage terms","url":"https://www.sec.gov/Archives/edgar/data/778209/000119312520258994/d44935dex9926qi.htm"},{"title":"Protective Life — Maryland application and conditional receipt packet","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"}]},{"lesson":"20","prompt":"A settlement proposal arrives within two years of policy issue. The seller says an exception applies. What must be reviewed?","options":["Only whether the provider likes the policy","The specific statutory exception and required independent evidence and documents","An assumption that every early sale is exempt","Only whether the offer price exceeds cash value"],"answer":1,"explanation":"Maryland’s early-settlement restriction has specific exceptions and evidentiary requirements. A favorable price or unsupported assertion does not establish one.","id":"C-3-05","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §8-601","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-601"},{"title":"Maryland Insurance §8-602","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-602"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-604","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-604"},{"title":"Maryland Insurance §8-605","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605"},{"title":"Maryland Insurance §8-605.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605.1"},{"title":"Maryland Insurance §8-606","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-606"},{"title":"Maryland Insurance §8-607","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-607"},{"title":"Maryland Insurance §8-609","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-609"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"Maryland Insurance §8-610.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610.1"},{"title":"Maryland Insurance §27-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-403"}]},{"lesson":"39","prompt":"An illustration suggests future dividends might eventually offset the owner’s out-of-pocket premiums. Which statement is accurate?","options":["The illustration guarantees that all premium obligations end on the shown date.","A premium offset is the same as surrendering the policy","The offset depends on nonguaranteed dividends unless the contract separately guarantees it.","Dividends must be paid even if no divisible surplus is declared."],"answer":2,"explanation":"A projected dividend offset can fail if dividends change. It is not the same as contractually paid-up coverage or a guarantee that no additional out-of-pocket payment will be needed.","id":"C-5-09","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-206"},{"title":"IRS — interest on deposited insurance dividends","url":"https://www.irs.gov/taxtopics/tc403"},{"title":"New York Life — dividend and paid-up definitions","url":"https://www.newyorklife.com/resources/glossary"},{"title":"Guardian — dividends and returns","url":"https://www.guardianlife.com/life-insurance/whole-life/dividends-and-returns-explained"},{"title":"MassMutual — dividend options","url":"https://www.massmutual.com/worksiteassets/wi5002.pdf"},{"title":"SEC-filed policy — one-year term dividend option","url":"https://www.sec.gov/Archives/edgar/data/317411/000119312510000115/dex9926d2.htm"},{"title":"MetLife — dividend changes and premium offset","url":"https://www.metlife.com/content/dam/metlifecom/us/homepage/support-and-manage/current-customers/individual-life-insurance/pdf/22044-Client-Dividend-Flyer-7-1A.pdf"},{"title":"Wisconsin OCI — separately identifies dividends shortening a premium-paying period","url":"https://oci.wi.gov/Documents/OCIForms/22-801.pdf"}]},{"lesson":"09","prompt":"A Maryland licensed producer explains policy choices to an existing client while acting as that client’s producer. Someone insists that every such explanation requires an additional adviser license. Which response reflects the statute?","options":["The word adviser creates authority without a license.","All paid policy analysis is exempt regardless of the person’s role.","The adviser subtitle includes an exception for a licensed producer acting as a producer for a client.","The producer license replaces viatical-provider registration as well."],"answer":2,"explanation":"Apply the defined adviser role and its actual exceptions. The producer-client exception is narrower than saying any person may provide unrestricted paid insurance advice.","id":"C-1-01","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-101"},{"title":"Maryland Insurance §10-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-102"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-105"},{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-109"},{"title":"Maryland Insurance §10-111","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-111"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-120","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-120"},{"title":"Maryland Insurance §10-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-201"},{"title":"Maryland Insurance §10-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-202"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Prelicensing education change","url":"https://insurance.maryland.gov/Producer/pages/default.aspx"}]},{"lesson":"43","prompt":"A cost-of-living rider offers an adjustment according to a stated index and election rules. Which conclusion is appropriate?","options":["Assume every policy automatically doubles annually.","Apply the rider’s formula, limits and election requirements.","Guarantee unlimited increases without checking rider terms","Treat any inflation statistic as the contractual formula."],"answer":1,"explanation":"Rider benefits are defined by their own triggers and limits. Cost-of-living language does not establish a universal increase amount or remove the need to follow the contract.","id":"C-5-12","domain":4,"scored":false,"sources":[{"title":"New York Life SEC-filed 2026 rider descriptions","url":"https://www.sec.gov/Archives/edgar/data/906982/000119312526149337/d91382d485bpos.htm"},{"title":"Union Security SEC-filed cost-of-living rider","url":"https://www.sec.gov/Archives/edgar/data/790531/000079053126000012/usicvulregtofile.htm"},{"title":"SEC-filed return-of-premium death benefit rider","url":"https://www.sec.gov/Archives/edgar/data/801019/000119312526166328/d714689d485bpos.htm"},{"title":"State Farm — return-of-premium term coverage","url":"https://www.statefarm.com/insurance/life/term-life/return-of-premium"}]},{"lesson":"23","prompt":"A producer delivers a policy but never reviews an exclusion that differs from the client’s expectation. Which delivery responsibility is most relevant?","options":["Assume delivery eliminates every duty to explain differences.","Return the producer’s license instead of discussing the policy","Explain the issued coverage, important terms and any differences from the application or presentation.","Promise that verbal expectations always override the written exclusion."],"answer":2,"explanation":"Delivery is an opportunity to review the actual issued contract, not simply hand over a document. The producer should accurately identify differences without inventing coverage.","id":"C-3-11","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"COMAR 31.04.17.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.06"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"FinCEN — Insurance company anti-money-laundering requirements","url":"https://www.fincen.gov/resources/statutes-regulations/guidance/anti-money-laundering-program-and-suspicious-activity"}]},{"lesson":"04","prompt":"A highly rated insurer is organized outside the United States but lacks authority for the proposed Maryland life transaction. No exception applies. Which two issues must remain distinct?","options":["Alien domicile classification and authorization to transact in Maryland","The customer’s citizenship and the producer’s commission percentage","An insurer’s foreign office and the customer’s beneficiary designation","A high rating and an automatic Maryland certificate of authority"],"answer":0,"explanation":"Domicile describes where the insurer is organized; admission concerns legal authority to transact. Neither foreign organization nor a rating alone establishes Maryland authorization.","id":"C-1-25","domain":0,"scored":false,"sources":[{"title":"NAIC insurance glossary","url":"https://content.naic.org/consumer_glossary"},{"title":"NAIC — Insurance Topics","url":"https://content.naic.org/insurance-topics"},{"title":"Maryland insurer search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"},{"title":"Maryland Insurance §4-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=4-203"}]},{"lesson":"46","prompt":"An annuity pays a fixed $1,800 each month for life. Prices rise substantially over ten years. What risk remains even if every contractual payment arrives?","options":["Loss of purchasing power from inflation","Automatic termination after ten years","A guarantee that the real value doubles","Failure to receive the promised nominal payment necessarily"],"answer":0,"explanation":"A fixed dollar promise protects the stated nominal payment, not necessarily its purchasing power. Inflation can erode what the same amount buys.","id":"C-6-04","domain":5,"scored":true,"sources":[{"title":"IRS — common annuity payment types","url":"https://www.irs.gov/retirement-plans/annuities-a-brief-description"},{"title":"NAIC — payout options and living benefits","url":"https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities.pdf"},{"title":"Maryland Insurance Administration — annuity income options","url":"https://insurance.maryland.gov/Consumer/Documents/agencyhearings/Annuities.pdf"},{"title":"Insured Retirement Institute — cash refund and annuity terms","url":"https://www.irionline.org/programs/education/annuities-glossary/"},{"title":"Florida insurance regulator — general payout descriptions","url":"https://www.myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview"}]},{"lesson":"18","prompt":"A policy separates owner, insured and beneficiary. The owner wants to make a permitted change while all parties are alive. What must be checked in addition to identifying the owner?","options":["Any assignment, irrevocable designation or contract restriction affecting the right","Only the insured’s job title","Whether the premium was paid by mail","Only the beneficiary’s current income"],"answer":0,"explanation":"Ownership powers can be limited by transferred rights, irrevocable interests and terms. Policy roles should be identified without assuming every owner can exercise every power without consent.","id":"C-3-01","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"}]},{"lesson":"51","prompt":"A 67-year-old fully surrenders a nonqualified annuity for $118,000 net proceeds with $82,000 adjusted basis. There are no other adjustments. What ordinary-income gain is recognized?","options":["$36,000","$82,000","$0 because the owner is over 59½","$118,000"],"answer":0,"explanation":"Net proceeds less basis produce $36,000 gain. Age may remove the ordinary age-based additional tax, but it does not make annuity gain free of income tax.","id":"C-7-03","domain":6,"scored":true,"sources":[{"title":"IRS Publication 575 — annuity distributions","url":"https://www.irs.gov/publications/p575"},{"title":"26 USC §72 — annuity income and distribution rules","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"IRS Publication 939 — General Rule","url":"https://www.irs.gov/publications/p939"}]},{"lesson":"11","prompt":"A producer demands that a customer’s complaint be ignored because no insurer appointment has been terminated. What is the flaw?","options":["A complaint automatically revokes the license without process.","The Commissioner’s investigation and discipline authority does not depend on an insurer first terminating an appointment.","Insurers alone can enforce Maryland’s Insurance Article.","An active appointment prevents all government investigations."],"answer":1,"explanation":"Insurer relationship decisions and regulator enforcement are distinct. The Commissioner can investigate within statutory authority, with the applicable process for sanctions.","id":"C-1-09","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"09","prompt":"An applicant’s relative dies while owning an insurance agency. The applicant starts soliciting immediately, assuming the relative’s license passed through the estate. What is missing?","options":["Temporary licensing is mandatory for every relative whether or not the person applies.","Only a copy of the death certificate is needed for unlimited selling.","The applicant must obtain the applicable temporary or ordinary authority before acting; a license is not automatically inherited.","The executor’s signature automatically appoints the applicant with every insurer."],"answer":2,"explanation":"Temporary authority is available only under specified qualifications and a completed licensing process. Family relationship alone does not convey a license or insurer appointment.","id":"C-1-02","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-101","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-101"},{"title":"Maryland Insurance §10-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-102"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-105","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-105"},{"title":"Maryland Insurance §10-106","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-106"},{"title":"Maryland Insurance §10-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-109"},{"title":"Maryland Insurance §10-111","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-111"},{"title":"Maryland Insurance §10-119","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-119"},{"title":"Maryland Insurance §10-120","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-120"},{"title":"Maryland Insurance §10-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-201"},{"title":"Maryland Insurance §10-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-202"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"MIA — Producer initial and renewal licenses","url":"https://insurance.maryland.gov/Producer/Pages/Producer-Initial-and-Renewal-Licenses.aspx"},{"title":"MIA — Prelicensing education change","url":"https://insurance.maryland.gov/Producer/pages/default.aspx"}]},{"lesson":"22","prompt":"An applicant compares fixed and variable life coverage. What is a central difference in the account structure and investment exposure?","options":["Variable products use separate-account investment options with investment risk borne as stated by the policyowner.","Fixed policies are direct ownership of every general-account security.","All variable benefits are guaranteed to exceed fixed benefits.","Variable always means a fixed premium can never be required."],"answer":0,"explanation":"Investment-account structure and risk distinguish variable products. Fixed versus variable is separate from premium flexibility, and neither label guarantees superior returns.","id":"C-3-15","domain":2,"scored":false,"sources":[{"title":"NAIC — A regulator’s introduction to the insurance industry, life pricing and products","url":"https://content.naic.org/sites/default/files/inline-files/prod_serv_marketreg_rii_zb.pdf"},{"title":"NAIC — Life insurance topic guide","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NAIC — Glossary of insurance terms","url":"https://content.naic.org/es/node/11821"},{"title":"SEC Investor.gov — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"}]},{"lesson":"11","prompt":"The Commissioner imposes a producer sanction for misappropriation and also seeks restitution for a customer’s financial injury. Which statement fits the discipline statute?","options":["Restitution can accompany applicable licensing sanctions and penalties.","Restitution is impossible if a license is suspended.","A producer may choose to pay a penalty in exchange for guaranteed immunity from all other consequences.","Only the original premium amount can ever be relevant to a financial injury."],"answer":0,"explanation":"The statute permits specified penalties instead of or in addition to suspension or revocation and can require restitution. One consequence does not automatically exclude all others.","id":"C-1-08","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"13","prompt":"Two applicants of the same class and essentially the same risk are offered different benefits for reasons prohibited by the applicable discrimination rule. What should the producer distinguish?","options":["Unfair discrimination from lawful differences supported by permitted risk factors","Every underwriting difference is prohibited regardless of risk","The producer may replace underwriting rules with personal preferences","The premium payment channel alone proves a lawful classification"],"answer":0,"explanation":"Unfair discrimination is not the same as every risk-based classification. A lawful distinction requires permitted factors and compliance with the applicable rule.","id":"C-1-16","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"Maryland Insurance §27-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-204"},{"title":"Maryland Insurance §27-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-205"},{"title":"Maryland Insurance §27-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-206"},{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-209"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"},{"title":"Maryland Insurance §27-214","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-214"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"}]},{"lesson":"19","prompt":"A nonworking parent provides child care and household services. Why can life insurance still be relevant despite no wage income?","options":["Replacing those services can create a measurable financial need.","The parent must be the household’s highest earner.","Only payroll wages can create any insurable economic loss.","A lack of wages makes every life policy a speculative investment."],"answer":0,"explanation":"Needs analysis includes services and responsibilities, not only salary. Replacing child care or other work can require money even when no paycheck was lost.","id":"C-3-03","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Life insurance and annuities","url":"https://insurance.maryland.gov/Consumer/Pages/Life.aspx"},{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Guardian — Human life value and estimating coverage needs","url":"https://www.guardianlife.com/life-insurance/how-much-life-insurance-do-you-need"},{"title":"Social Security Administration — Survivor eligibility","url":"https://www.ssa.gov/survivor/eligibility"},{"title":"Social Security Administration — Survivor benefit amounts","url":"https://www.ssa.gov/survivor/amount"},{"title":"Social Security Administration — Survivors benefits","url":"https://www.ssa.gov/pubs/EN-05-10084.pdf"}]},{"lesson":"08","prompt":"A compact product-filing question is mistakenly sent to an organization of state legislators as if it administered the Insurance Compact. Which body actually administers the compact product-review process?","options":["NCOIL as the licensing office for individual producers","The Interstate Insurance Product Regulation Commission","A local producer trade association","The individual client’s employer"],"answer":1,"explanation":"The IIPRC administers the Insurance Compact’s covered product standards and review process. NCOIL brings legislators together and develops model legislation; it is not the compact administrator.","id":"C-2-07","domain":1,"scored":true,"sources":[{"title":"FTC — Consumer Reports: What Insurers Need to Know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"MIA — 18 U.S.C. 1033–1034","url":"https://insurance.maryland.gov/Producer/pages/1033waiverinfo.aspx"},{"title":"SEC — Variable life insurance","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/variable-life"},{"title":"NAIC — About","url":"https://content.naic.org/about"},{"title":"Insurance Compact — About","url":"https://www.insurancecompact.org/about"},{"title":"NCOIL — State legislators and model legislation","url":"https://ncoil.org/"}]},{"lesson":"28","prompt":"A policy credits indexed interest using a participation rate and cap. The index rises 12%, the participation rate is 75%, and the cap is 7%. Assume that simple formula and no other adjustment. What is the credited rate?","options":["5.25%","9%","12%","7%"],"answer":3,"explanation":"First apply participation: 12% × 75% = 9%. The 7% cap limits the credit to 7%. This fictional formula is not a universal indexed-policy rule or a guarantee of actual returns.","id":"C-4-04","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Universal life insurance","url":"https://insurance.maryland.gov/Consumer/Pages/Universal-Life-Insurance.aspx"},{"title":"NAIC — Life insurance designs","url":"https://content.naic.org/insurance-topics/life-insurance"},{"title":"NYDFS — General whole-life product explanations; New York-specific rules are not Maryland rules","url":"https://www.dfs.ny.gov/faqs/consumer_faqs/life_insurance?page=2"},{"title":"Nationwide — Indexed universal life guide; product illustrations, not universal rates","url":"https://financial.nationwide.com/media/pdf/FLM-1376AO.pdf"},{"title":"Nationwide — Indexed UL Accumulator III product disclosures","url":"https://www.nationwide.com/personal/insurance/life/permanent/indexed-universal/indexed-ul-accumulator-III/"},{"title":"Nationwide — No-lapse guarantee universal life","url":"https://www.nationwide.com/personal/insurance/life/permanent/universal/no-lapse-guarantee-UL-II/"}]},{"lesson":"16","prompt":"A group conversion notice is late. An employee concludes the right to apply now lasts forever. Which statement is accurate?","options":["A late notice removes every conversion deadline permanently.","A late notice converts the group certificate into cash surrender value.","A late notice automatically requires a new medical examination.","The statutory extension has a stated additional period and outer limit; it is not unlimited."],"answer":3,"explanation":"Maryland’s notice rule can extend the application-and-payment period, but the additional 15-day period after notice is subject to the specified outer limit. It does not create unlimited continuation.","id":"C-1-26","domain":0,"scored":false,"sources":[{"title":"Maryland Insurance §17-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-201"},{"title":"Maryland Insurance §17-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-202"},{"title":"Maryland Insurance §17-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-209"},{"title":"Maryland Insurance §17-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-301"},{"title":"Maryland Insurance §17-302","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-302"},{"title":"Maryland Insurance §17-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-303"},{"title":"Maryland Insurance §17-308","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-308"},{"title":"Maryland Insurance §17-309","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-309"},{"title":"Maryland Insurance §17-310","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-310"},{"title":"Maryland Insurance §17-311","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-311"},{"title":"Maryland Insurance §17-104","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-104"}]},{"lesson":"12","prompt":"An agency calculates withdrawals using an average commission percentage rather than actual commissions. Which supporting condition matters under the Maryland rule taught?","options":["A carrier letter stating the average commission percentage","A new policy’s free-look expiration alone","A customer’s beneficiary designation","A producer’s informal guess based on last month"],"answer":0,"explanation":"Use of average commissions has a carrier-letter condition and must not undermine the required account balance. An estimated percentage without that support is insufficient.","id":"C-1-12","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"52","prompt":"An annuitant has recovered the full investment in a fixed annuity through excluded payment portions under the applicable General Rule. What is the general treatment of subsequent payments?","options":["Permanently excluded using the old ratio with no cap","Taxed only if the annuitant is under age 59½","Fully taxable under the stated basis-recovery rule","Automatically treated as tax-free life death proceeds"],"answer":2,"explanation":"For the stated rule, the exclusion stops when investment has been fully recovered. The earlier ratio is not an unlimited exclusion beyond basis.","id":"C-7-04","domain":6,"scored":true,"sources":[{"title":"26 USC §72 — annuity income and distribution rules","url":"https://www.law.cornell.edu/uscode/text/26/72"},{"title":"IRS Publication 939 — General Rule","url":"https://www.irs.gov/publications/p939"},{"title":"IRS Publication 575 — annuity distributions","url":"https://www.irs.gov/publications/p575"}]},{"lesson":"21","prompt":"A corporation is obligated to redeem a deceased owner’s shares and owns the policies funding that obligation. Which buy-sell structure is shown?","options":["An executive-bonus policy owned by the employee solely for family benefit","Entity purchase or stock redemption","Cross-purchase with the surviving shareholders as policyowners","A group conversion right held by each employee"],"answer":1,"explanation":"Entity purchase has the entity funding its redemption obligation. Cross-purchase instead places the purchasing obligation and corresponding policy ownership with the other owners.","id":"C-3-07","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"MassMutual — Life insurance for business","url":"https://www.massmutual.com/business/business-life-insurance"},{"title":"MassMutual — Choosing a buy-sell arrangement","url":"https://blog.massmutual.com/work-business/business-buy-sell-right"},{"title":"New York Life — Business succession planning","url":"https://www.newyorklife.com/articles/business-succession-planning"}]},{"lesson":"12","prompt":"A producer proposes an undisclosed flat credit-card surcharge unrelated to actual processing expense. Which distinction is required by Maryland’s specified credit-card exception?","options":["Any amount is allowed if called a convenience fee.","The exception concerns actual incurred expenses and required disclosure of payment methods and expenses.","Card expenses become guaranteed policy cash value.","All premium payments must be made by credit card."],"answer":1,"explanation":"The allowed actual-expense provision is not permission for an arbitrary undisclosed markup. Disclosures and accepted payment alternatives matter.","id":"C-1-13","domain":0,"scored":true,"sources":[{"title":"COMAR 31.03.03.01","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.01"},{"title":"COMAR 31.03.03.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.02"},{"title":"COMAR 31.03.03.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.03"},{"title":"COMAR 31.03.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.03.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.09.12.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.10"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §27-216","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-216"},{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"}]},{"lesson":"11","prompt":"During a disciplinary inquiry, a producer intentionally withholds records required by a proper regulatory request. Which professional response was required instead?","options":["Destroy older records whenever they might be unfavorable.","Wait for the next insurer commission audit regardless of the regulator’s deadline.","Provide only documents selected by the accused customer.","Preserve retrievable records and comply with the lawful request."],"answer":3,"explanation":"Record duties and proper regulatory orders must be followed. Selective destruction or postponement does not become lawful because the producer disputes the underlying concern.","id":"C-1-10","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"20","prompt":"A settlement owner changes a beneficiary or ownership interest. Under the Maryland disclosure duty taught, what is required toward the insured?","options":["Wait until the insured dies.","Assume every prior privacy notice communicates the specific change.","Notify only the original producer if that producer is no longer involved.","Communicate the covered change within 20 days after it occurs."],"answer":3,"explanation":"The specified ownership-or-beneficiary change communication has its own 20-day duty toward the insured. It differs from underwriting verification, proceeds payment and rescission clocks.","id":"C-3-16","domain":2,"scored":false,"sources":[{"title":"Maryland Insurance §8-601","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-601"},{"title":"Maryland Insurance §8-602","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-602"},{"title":"Maryland Insurance §8-603","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-603"},{"title":"Maryland Insurance §8-604","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-604"},{"title":"Maryland Insurance §8-605","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605"},{"title":"Maryland Insurance §8-605.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-605.1"},{"title":"Maryland Insurance §8-606","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-606"},{"title":"Maryland Insurance §8-607","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-607"},{"title":"Maryland Insurance §8-609","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-609"},{"title":"Maryland Insurance §8-610","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610"},{"title":"Maryland Insurance §8-610.1","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=8-610.1"},{"title":"Maryland Insurance §27-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-403"}]},{"lesson":"11","prompt":"An insurer signs a business agreement giving a producer office support and compensation terms. The producer treats the agreement as conclusive proof of all Maryland licensing and appointment requirements. Which analysis is correct?","options":["Verify the state license, business agreement and appointment separately.","Office support establishes unlimited binding authority.","A compensation contract always issues the state license.","An appointment replaces the need for an authorized insurer."],"answer":0,"explanation":"These documents serve related but different functions. The agreement sets business terms; it is not itself proof of state licensure, every appointment step or unlimited authority.","id":"C-1-07","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §10-103","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-103"},{"title":"Maryland Insurance §10-118","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-118"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"},{"title":"Maryland Insurance §2-108","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-108"},{"title":"Maryland Insurance §2-210","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-210"},{"title":"Maryland Insurance §2-215","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=2-215"},{"title":"Maryland Insurance §27-802","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-802"},{"title":"COMAR 31.03.13.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.04"},{"title":"COMAR 31.03.13.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.05"},{"title":"COMAR 31.03.13.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.03.13.06"},{"title":"MIA — Company and producer authority search","url":"https://insurance.maryland.gov/Consumer/Pages/CompanySearchInstructions.aspx"}]},{"lesson":"42","prompt":"A base insured dies while a child term rider has a provision continuing the child’s term protection paid up to the rider’s specified age. What should be emphasized?","options":["The continuation is the specified term protection, not automatically permanent whole life.","The continuation must equal an unlimited future conversion amount","Paid up always means lifelong permanent coverage.","The child automatically becomes the deceased base insured."],"answer":0,"explanation":"Paid-up describes funding; term describes coverage duration. A rider can continue paid-up term until its stated endpoint without promising lifelong permanent protection.","id":"C-5-11","domain":4,"scored":true,"sources":[{"title":"State Farm — family life and separate term riders","url":"https://www.statefarm.com/insurance/life/resources/why-buy-life-insurance"},{"title":"State Farm — universal life rider descriptions","url":"https://www.statefarm.com/insurance/life/universal-life/universal-life-insurance"},{"title":"State Farm — term rider conversion and child coverage","url":"https://www.statefarm.com/insurance/life/term-life/select-term"},{"title":"New York Life SEC-filed 2026 prospectus — child and other-insured riders","url":"https://www.sec.gov/Archives/edgar/data/906982/000119312526149337/d91382d485bpos.htm"},{"title":"Guardian — rider functions","url":"https://www.guardianlife.com/life-insurance/riders"}]},{"lesson":"15","prompt":"A producer electronically presents individualized sales materials for a covered replacement. Which delivery point specifically matters for providing printed electronic materials under the rule taught?","options":["Only if the old insurer files a complaint","No later than policy delivery","Five years after termination of the proposed contract","Only at the insured’s death"],"answer":1,"explanation":"Electronically presented replacement materials have a printed-delivery requirement no later than delivery. That is distinct from long-term insurer document retention.","id":"C-1-20","domain":0,"scored":true,"sources":[{"title":"COMAR 31.09.05.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.02"},{"title":"COMAR 31.09.05.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.03"},{"title":"COMAR 31.09.05.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.04"},{"title":"COMAR 31.09.05.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.05"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.09.05.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.07"},{"title":"COMAR 31.09.05.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.10"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"}]},{"lesson":"59","prompt":"A family has $410,000 of stated needs. Its $175,000 life benefit is reduced by $35,000 total policy debt. Of a $220,000 investment account, only 40% is available for those needs. Ignoring other adjustments, what is the gap?","options":["$182,000","$147,000","$322,000","$50,000"],"answer":0,"explanation":"Net life proceeds are $175,000 − $35,000 = $140,000. Available investments are $220,000 × 40% = $88,000. The unmet need is $410,000 − $140,000 − $88,000 = $182,000. Use net proceeds and only the resources actually available.","id":"C-3-02","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance Administration — life insurance guide","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"Maryland Insurance §12-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-201"},{"title":"Maryland Insurance §16-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-202"},{"title":"Maryland Insurance §16-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-204"},{"title":"COMAR 31.09.05.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.04"},{"title":"Maryland Insurance Administration — universal life funding","url":"https://insurance.maryland.gov/Consumer/Pages/Universal-Life-Insurance.aspx"}]},{"lesson":"55","prompt":"A plan participant wants to roll over a required minimum distribution to an IRA and defer its tax. Which rule applies?","options":["The producer may convert an RMD into a direct rollover by changing the payee.","An RMD is not an eligible rollover distribution.","Only the amount above the RMD is necessarily ineligible","Every plan payment becomes eligible if moved within 60 days."],"answer":1,"explanation":"RMD amounts cannot be rolled over under the eligible-distribution rule. A direct payee or timely redeposit does not make an otherwise ineligible RMD eligible.","id":"C-7-06","domain":6,"scored":true,"sources":[{"title":"IRS — retirement plan and IRA rollovers","url":"https://www.irs.gov/retirement-plans/plan-participant-employee/rollovers-of-retirement-plan-and-ira-distributions"},{"title":"IRS Topic 413 — rollover eligibility and withholding","url":"https://www.irs.gov/taxtopics/tc413"},{"title":"IRS Publication 590-A — rollover requirements","url":"https://www.irs.gov/publications/p590a"},{"title":"IRS Publication 590-B — inherited IRA transfers","url":"https://www.irs.gov/publications/p590b"}]},{"lesson":"24","prompt":"An underwriter orders personal interviews about an applicant’s character and mode of living. Which information source and rule issue fit?","options":["A beneficiary assignment","A policy’s guaranteed cash-value table","An attending physician statement with no consumer-report rules possible","An investigative consumer report, with applicable additional disclosure requirements"],"answer":3,"explanation":"Personal interviews of this kind describe an investigative consumer report. Such reports have additional FCRA disclosure requirements beyond simply collecting a medical statement.","id":"C-3-12","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-504","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-504"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Consumer Financial Protection Bureau — MIB consumer reports","url":"https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/consumer-reporting-companies/companies-list/mib-inc/"},{"title":"MIB — Request and correct your consumer file","url":"https://www.mib.com/request_your_record.html"}]},{"lesson":"14","prompt":"A prospect reads an advertisement implying an indexed insurance product is directly sponsored or guaranteed by the government, although it is not. What is the appropriate correction?","options":["Use smaller print as a universal cure for a contradictory headline.","Treat an index name as proof of government sponsorship.","Keep the implication if no individual salesperson says it aloud.","Accurately identify the insurer and product and remove the misleading guarantee implication."],"answer":3,"explanation":"Advertising must not mislead about identity, guarantees or relationships. An index reference and fine print do not automatically cure a false overall impression.","id":"C-1-17","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"COMAR 31.09.09.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.06"},{"title":"COMAR 31.09.09.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.07"},{"title":"COMAR 31.09.09.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.09.09"},{"title":"COMAR 31.15.03.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.04"},{"title":"COMAR 31.15.03.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.15.03.05"},{"title":"COMAR 31.16.08.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.05"},{"title":"COMAR 31.16.08.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.06"},{"title":"COMAR 31.16.08.11","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.11"},{"title":"COMAR 31.16.08.17","url":"https://regs.maryland.gov/us/md/exec/comar/31.16.08.17"}]},{"lesson":"56","prompt":"An owner receives a surrender check from a nonqualified annuity and endorses it to another insurer, claiming a 60-day §1035 exchange. Which distinction matters?","options":["The check becomes a qualified retirement distribution merely because an insurer issued it","Every insurance check may be redeposited tax free within 60 days.","Endorsement alone always supplies a qualifying direct exchange.","The retirement-plan 60-day rollover concept does not make an owner-received annuity surrender a qualifying §1035 exchange."],"answer":3,"explanation":"Insurance exchange rules differ from retirement-account rollover rules. Receiving and endorsing a surrender check is not automatically a qualifying §1035 exchange; the actual required exchange structure matters.","id":"C-7-07","domain":6,"scored":false,"sources":[{"title":"26 USC §1035 — permitted insurance exchanges","url":"https://www.law.cornell.edu/uscode/text/26/1035"},{"title":"26 CFR §1.1035-1 — identity and exchange conditions","url":"https://www.law.cornell.edu/cfr/text/26/1.1035-1"},{"title":"IRS Revenue Ruling 2007-24 — check paid to owner","url":"https://www.irs.gov/irb/2007-21_IRB#RR-2007-24"},{"title":"IRS Revenue Procedure 2011-38 — partial annuity exchanges","url":"https://www.irs.gov/irb/2011-30_IRB#RP-2011-38"},{"title":"26 USC §7702A — MEC exchanges","url":"https://www.law.cornell.edu/uscode/text/26/7702A"},{"title":"COMAR 31.09.12.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.12.04"}]},{"lesson":"26","prompt":"A client’s term coverage is renewable to a specified age but its conversion privilege ends earlier. What is the key distinction?","options":["A conversion deadline ends every other policy right immediately","Renewal automatically extends conversion forever.","Conversion and renewal always preserve the same premium.","Renewal and conversion are separate rights with potentially different deadlines."],"answer":3,"explanation":"Renewal continues term protection under its terms; conversion changes to a permitted permanent form. Their limits and premium rules can differ.","id":"C-4-01","domain":3,"scored":true,"sources":[{"title":"Maryland Insurance Administration — Consumer guide to life insurance","url":"https://insurance.maryland.gov/consumer/documents/publications/lifeinsurance.pdf"},{"title":"COMAR 31.04.17.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.09"},{"title":"New York DFS — General explanations of term designs; Maryland rules taught separately","url":"https://www.dfs.ny.gov/consumers/life_insurance"},{"title":"State Farm — A return-of-premium product example","url":"https://www.statefarm.com/insurance/life/term-life/return-of-premium"}]},{"lesson":"17","prompt":"A claimant is told that a company’s internal practice overrides the written life-policy provisions and permits an unexplained denial. Which is the sound response?","options":["Only the producer’s recollection determines benefits.","Evaluate the contract and applicable claim-handling law; internal practice does not excuse an unlawful denial.","The beneficiary must buy a new policy before asking for a reason.","Internal practice always replaces the contract."],"answer":1,"explanation":"Claim handling must follow the policy and law. Internal preferences and unrelated sales conditions do not authorize denial of a valid contractual claim.","id":"C-1-24","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §12-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-203"},{"title":"Maryland Insurance §27-303","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-303"},{"title":"Maryland Insurance §27-304","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-304"},{"title":"Maryland Insurance §16-109","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-109"},{"title":"Maryland Insurance §17-102","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=17-102"},{"title":"Maryland Insurance §9-402","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-402"},{"title":"Maryland Insurance §9-403","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-403"},{"title":"Maryland Insurance §9-405","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-405"},{"title":"Maryland Insurance §9-407","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-407"},{"title":"Maryland Insurance §9-409","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-409"},{"title":"Maryland Insurance §9-414","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=9-414"},{"title":"Maryland Life & Health Insurance Guaranty Corporation — FAQs","url":"https://www.mdlifega.org/FAQ"}]},{"lesson":"38","prompt":"A covered $260,000 death benefit is subject to a $21,500 policy loan and $1,500 accrued loan interest. Assume no other adjustments. What is payable?","options":["$238,500","$260,000","$283,000","$237,000"],"answer":3,"explanation":"Both loan principal and interest reduce proceeds: $260,000 − $21,500 − $1,500 = $237,000. Subtracting only principal misses the accrued debt.","id":"C-5-08","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-207"},{"title":"Maryland Insurance §16-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-208"},{"title":"MetLife — whole-life loan and automatic premium loan mechanics","url":"https://www.metlife.com/support-and-manage/current-customers/individual-life-insurance/products/wl-faqs/"},{"title":"MetLife — universal-life withdrawals and policy debt","url":"https://www.metlife.com/support-and-manage/current-customers/individual-life-insurance/products/ul-faqs/"},{"title":"MassMutual — cash value and education funding","url":"https://www.massmutual.com/financial-wellness/building-a-financial-foundation"}]},{"lesson":"13","prompt":"A sales presentation uses a fabricated insurer balance sheet to reassure prospects about financial strength. Which issue is most directly implicated?","options":["A lawful return-of-premium feature","A standard conditional receipt","A permissible actuarial classification","False financial statements and deceptive representation"],"answer":3,"explanation":"Fabricated financial information is deceptive. It is not a permissible sales illustration merely because the purpose is to reassure a prospect.","id":"C-1-15","domain":0,"scored":true,"sources":[{"title":"Maryland Insurance §27-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-202"},{"title":"Maryland Insurance §27-203","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-203"},{"title":"Maryland Insurance §27-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-204"},{"title":"Maryland Insurance §27-205","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-205"},{"title":"Maryland Insurance §27-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-206"},{"title":"Maryland Insurance §27-208","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-208"},{"title":"Maryland Insurance §27-209","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-209"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"},{"title":"Maryland Insurance §27-214","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-214"},{"title":"Maryland Insurance §10-130","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-130"},{"title":"Maryland Insurance §10-126","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=10-126"}]},{"lesson":"23","prompt":"A client asks the producer to sign the client’s name because the client is busy. What should the producer do?","options":["Use the insurer’s lawful authorized signature procedure rather than impersonating the client.","Sign the name and hide who completed it.","Ask an unlicensed coworker to imitate the signature.","Treat premium payment as every required signature in all transactions"],"answer":0,"explanation":"Required signatures and authorization must be obtained through a valid process. A producer should not forge or conceal the signer’s identity for convenience.","id":"C-3-10","domain":2,"scored":true,"sources":[{"title":"Maryland Insurance §12-202","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-202"},{"title":"Maryland Insurance §12-207","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-207"},{"title":"COMAR 31.04.17.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.04.17.06"},{"title":"Protective Life — Maryland application packet, a carrier-specific example","url":"https://www.lad3.protective.com/protectivelife/forms/pdf/ICC21-400R_MD_short.pdf"},{"title":"Federal Trade Commission — Consumer reports: what insurers need to know","url":"https://www.ftc.gov/business-guidance/resources/consumer-reports-what-insurers-need-know"},{"title":"FinCEN — Insurance company anti-money-laundering requirements","url":"https://www.fincen.gov/resources/statutes-regulations/guidance/anti-money-laundering-program-and-suspicious-activity"}]},{"lesson":"15","prompt":"An applicant will use new life coverage to replace a policy by electing extended term under the old policy’s nonforfeiture option. Why can the replacement rules apply even though some old coverage continues?","options":["Replacement applies only when the old contract disappears the same day.","A covered reduction or alteration caused by the new purchase can meet the replacement definition.","Only a change in insurer name is relevant.","Extended term automatically makes every new purchase exempt."],"answer":1,"explanation":"Replacement is broader than complete surrender. Evaluate the specified effect on old coverage and the connection to the new purchase, together with scope and knowledge conditions.","id":"C-1-19","domain":0,"scored":true,"sources":[{"title":"COMAR 31.09.05.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.02"},{"title":"COMAR 31.09.05.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.03"},{"title":"COMAR 31.09.05.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.04"},{"title":"COMAR 31.09.05.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.05"},{"title":"COMAR 31.09.05.06","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.06"},{"title":"COMAR 31.09.05.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.07"},{"title":"COMAR 31.09.05.10","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.05.10"},{"title":"Maryland Insurance §27-213","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=27-213"}]},{"lesson":"41","prompt":"A hypothetical accelerated-benefit rider advances $60,000 of death benefit but applies a $6,000 discount, paying $54,000 cash. A $150,000 base death benefit has no other adjustments. What remains if the rider deducts the amount accelerated?","options":["$90,000","$96,000","$150,000","$204,000"],"answer":0,"explanation":"The assumed reduction is the $60,000 amount accelerated, not the discounted cash received: $150,000 − $60,000 = $90,000. The actual rider’s formula must always be read.","id":"C-5-10","domain":4,"scored":true,"sources":[{"title":"COMAR 31.09.16.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.02"},{"title":"COMAR 31.09.16.03","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.03"},{"title":"COMAR 31.09.16.04","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.04"},{"title":"COMAR 31.09.16.05","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.05"},{"title":"COMAR 31.09.16.07","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.07"},{"title":"COMAR 31.09.16.08","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.08"},{"title":"COMAR 31.09.16.09","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.09"},{"title":"COMAR 31.09.16.11","url":"https://regs.maryland.gov/us/md/exec/comar/31.09.16.11"},{"title":"COMAR 31.14.01.02","url":"https://regs.maryland.gov/us/md/exec/comar/31.14.01.02"},{"title":"IRS Publication 525 — accelerated death benefits","url":"https://www.irs.gov/publications/p525"},{"title":"SEC-filed policy — an acceleration calculation","url":"https://www.sec.gov/Archives/edgar/data/778209/000119312525112108/d909081d497.htm"}]},{"lesson":"32","prompt":"An owner makes an absolute assignment of the policy’s ownership rights. Which event is different from merely naming a beneficiary?","options":["The insured life automatically changes to the assignee.","Only the frequency of premium payments changes.","Ownership rights are transferred as provided by the assignment.","The policy automatically becomes group insurance"],"answer":2,"explanation":"An absolute assignment transfers ownership rights; a beneficiary designation identifies a recipient under the policy. Neither necessarily changes the insured life.","id":"C-5-01","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-201","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-201"},{"title":"Maryland Insurance §16-204","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-204"},{"title":"Maryland Insurance §16-212","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-212"},{"title":"Maryland Insurance §12-206","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=12-206"},{"title":"New York Life — Ownership and assignment glossary","url":"https://www.newyorklife.com/resources/glossary"},{"title":"MassMutual — Life insurance as business loan collateral","url":"https://blog.massmutual.com/work-business/business-loan-life-insurance-collateral"},{"title":"MassMutual — Example collateral assignment terms","url":"https://www.massmutual.com/efiles/life/pdfs/f5308.pdf"}]},{"lesson":"33","prompt":"A policy directs equal shares to the surviving members of a designated beneficiary class, by head under its stated per-capita wording. Which allocation principle applies?","options":["Per stirpes through each deceased member’s branch regardless of wording","Per capita","A premium waiver","A fixed-amount annuity settlement"],"answer":1,"explanation":"Per capita divides by head among the applicable recipients. Per-stirpes branch substitution and settlement payment patterns are different concepts.","id":"C-5-02","domain":4,"scored":true,"sources":[{"title":"Maryland Insurance §16-212","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gin&section=16-212"},{"title":"NAIC — Beneficiary designations","url":"https://content.naic.org/article/consumer-insight-life-insurance"},{"title":"Maryland Courts — Probate and guardianship FAQs","url":"https://www.mdcourts.gov/orphanscourt/faqs"},{"title":"MIA Bulletin 26-22 — Maryland-sitused life policy and divorce example","url":"https://insurance.maryland.gov/Pages/Bulletins/Bulletin-26-22.aspx"},{"title":"Maryland Courts and Judicial Proceedings §10-804 — rule before October 1, 2026","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gcj&section=10-804"},{"title":"Maryland Courts and Judicial Proceedings §10-805 — existing contract exception","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gcj&section=10-805"},{"title":"2026 Chapter 509 — simultaneous-death changes effective October 1, 2026","url":"https://mgaleg.maryland.gov/2026RS/chapters_noln/Ch_509_hb0596T.pdf"},{"title":"Maryland Estates and Trusts §4-105 — wills, divorce and annulment","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=get&section=4-105"}]}]}],"lessons":[{"id":"01","number":1,"title":"Risk, perils and hazards","version":2,"questions":[{"topic":"Peril","review":"vocabulary","prompt":"Marcus dies while his children still depend on his income. In this life-insurance example, which fact identifies the peril?","options":["His children depend on his income.","Marcus’s death.","A dangerous condition at his workplace.","The premium he pays each month."],"answer":1,"explanations":["Dependence on his income describes the family’s financial exposure.","His death is the event that causes the loss of his financial support.","A dangerous condition is a hazard: it can increase the chance of a loss.","A premium is the price of coverage, not the event that causes the loss."],"id":"L01-01","lesson":"01","domain":1,"explanation":"His death is the event that causes the loss of his financial support."},{"topic":"Physical hazard","review":"hazards","prompt":"A worker’s protective equipment is defective. Before any accident occurs, the defective equipment is best classified as what?","options":["A physical hazard.","A completed loss.","A life-insurance benefit.","Uncertainty about the stock market."],"answer":0,"explanations":["It is a tangible condition that increases danger, so it is a physical hazard.","No accident or resulting loss has occurred in this example.","A benefit is an amount payable under a policy, not a dangerous condition.","This is a physical defect in equipment, not an investment uncertainty."],"id":"L01-02","lesson":"01","domain":1,"explanation":"It is a tangible condition that increases danger, so it is a physical hazard."},{"topic":"Moral versus morale hazard","review":"hazards","prompt":"Someone intentionally falsifies a death certificate to obtain an insurance payment. Which label best describes the dishonest behavior?","options":["Morale hazard.","Physical hazard.","Moral hazard.","Pure risk with no dishonest conduct."],"answer":2,"explanations":["Morale hazard concerns carelessness or indifference because of insurance, rather than deliberate deception.","Physical hazard concerns a tangible condition, such as defective equipment.","The intentional deception is the defining clue for moral hazard.","The scenario explicitly describes deliberate falsification; that is the clue for moral hazard."],"id":"L01-03","lesson":"01","domain":1,"explanation":"The intentional deception is the defining clue for moral hazard."},{"topic":"Morale hazard","review":"hazards","prompt":"An insured person starts ignoring safety precautions because they believe insurance will take care of any loss. Which hazard does that attitude illustrate?","options":["Morale hazard.","Moral hazard involving an intentionally false claim.","A physical defect in the safety equipment.","A loss that has already happened."],"answer":0,"explanations":["Insurance has encouraged indifference to avoiding loss: the classic morale-hazard distinction.","The scenario describes carelessness, not a scheme to submit a false claim.","The stated problem is the person’s attitude. No defective equipment is described.","The example describes an attitude that increases danger, not a completed loss."],"id":"L01-04","lesson":"01","domain":1,"explanation":"Insurance has encouraged indifference to avoiding loss: the classic morale-hazard distinction."},{"topic":"Exposure","review":"vocabulary","prompt":"Priya’s household relies on the financial support she provides. Before any death occurs, what does that dependence describe?","options":["A death benefit already paid.","Financial exposure to losing her support.","A loss that has already happened.","A condition that makes her death more likely."],"answer":1,"explanations":["Nothing in the scenario says a policy benefit has been paid.","The household is vulnerable to a possible future loss of support; this is exposure.","The possible event has not occurred, so this is not an already-realized loss.","Dependence on financial support does not itself make the parent more likely to die."],"id":"L01-05","lesson":"01","domain":1,"explanation":"The household is vulnerable to a possible future loss of support; this is exposure."},{"topic":"Risk versus loss","review":"vocabulary","prompt":"An agent describes uncertainty about when a client might die and how that would affect the family’s finances. Which term best fits the uncertainty?","options":["A premium.","An already-paid claim.","Risk.","The amount of a contractual death benefit."],"answer":2,"explanations":["A premium is the price of insurance coverage; it does not name the uncertainty.","A paid claim concerns a benefit after the conditions for payment are met.","Uncertainty about the timing and financial effects of loss is risk.","A contractual benefit is a policy provision. Risk names uncertainty about loss."],"id":"L01-06","lesson":"01","domain":1,"explanation":"Uncertainty about the timing and financial effects of loss is risk."},{"topic":"Pure versus speculative risk","review":"hazards","prompt":"Which example involves speculative risk?","options":["Buying a stock that could rise or fall in value.","A household facing the possible loss of a parent’s financial support.","The possibility of a fatal accident.","The possibility of a house fire."],"answer":0,"explanations":["The investment offers a chance of economic gain as well as a chance of loss.","The underlying exposure offers no opportunity for economic gain from losing that support; it is a pure risk.","This is a possibility of loss without a corresponding opportunity for economic gain from the accident.","A house fire presents a chance of loss or no loss, with no opportunity for gain from the fire itself."],"id":"L01-07","lesson":"01","domain":1,"explanation":"The investment offers a chance of economic gain as well as a chance of loss."},{"topic":"Loss versus benefit","review":"vocabulary","prompt":"After an insured parent dies, the family loses the support that parent would have provided. Which statement best describes the loss and the life-insurance payment?","options":["The insurer must reimburse every future expense without a limit.","The loss is the financial harm; the death benefit is payable according to the policy contract.","The loss and the premium are always the same amount.","A guarantee that the family will never face financial hardship."],"answer":1,"explanations":["Life insurance does not promise unlimited reimbursement of every expense.","Keep the financial consequence separate from the contractual benefit used to help address it.","A premium is the price of coverage, not a measure of the family’s loss.","Life insurance pays according to its contract; it cannot guarantee every future financial outcome."],"id":"L01-08","lesson":"01","domain":1,"explanation":"Keep the financial consequence separate from the contractual benefit used to help address it."}]},{"id":"02","number":2,"title":"Pooling, large numbers and adverse selection","version":2,"questions":[{"prompt":"Marcus has paid far less in premiums than his policy’s death benefit. What makes a larger covered benefit possible?","options":["His premiums are the only money available for his claim.","The insurer spreads risk across many policies and owes the benefit under the contract.","The law of large numbers guarantees Marcus will survive.","The benefit automatically equals every future expense the family loses."],"answer":1,"review":"scenario","explanations":["Pooling is not a personal savings arrangement. His own premiums do not set the limit of a covered benefit.","Correct. Risk pooling supports the insurer’s obligations; the policy determines the covered benefit.","The law concerns group experience. It makes no promise about Marcus’s survival.","The policy controls the benefit. It does not promise to replace every future household expense."],"id":"L02-01","lesson":"02","domain":1,"explanation":"Correct. Risk pooling supports the insurer’s obligations; the policy determines the covered benefit."},{"prompt":"What is a direct purpose of risk pooling?","options":["Share the financial burden of covered losses across a group.","Prevent every insured person from dying.","Make every policyholder pay exactly the same premium.","Guarantee that actual claims equal the expected claim count."],"answer":0,"review":"pooling","explanations":["Correct. Pooling spreads financial risk across many exposures.","Insurance addresses financial consequences; it does not prevent death.","Members can have different benefits and risk classifications. Pooling does not require identical premiums.","Pooling supports financial risk sharing; actual claim experience can still differ from expectations."],"id":"L02-02","lesson":"02","domain":1,"explanation":"Correct. Pooling spreads financial risk across many exposures."},{"prompt":"Which statement best describes the law of large numbers?","options":["A large pool always has fewer total claims than a small pool.","A large pool identifies exactly which people will have claims.","A larger group of comparable, largely independent risks tends to have a more predictable average loss.","Every person in the pool must pay an identical premium."],"answer":2,"review":"pooling","explanations":["A larger pool can have more total claims. The key idea is more reliable average experience.","Group estimates cannot identify individual outcomes.","Correct. Look for group size, comparable exposures and predictability of the average.","Comparable exposures help statistical estimates. Pooling does not require identical premiums or policy benefits."],"id":"L02-03","lesson":"02","domain":1,"explanation":"Correct. Look for group size, comparable exposures and predictability of the average."},{"prompt":"In the invented example, 1,000 people each have a 1% annual claim probability. What does “10 expected claims” mean?","options":["The claim count averages 10 across many possible outcomes; this year’s count can differ.","There must be exactly 10 claims this year.","The insurer knows the names of 10 people who will die.","Every person now has a 10% annual chance of a claim."],"answer":0,"review":"pooling","explanations":["Correct. 1,000 × 0.01 = 10 is an expectation, not a guaranteed result.","Actual experience can be above or below its expected value.","An expected group count does not identify any individual.","Ten is the expected group count. Each person's assumed annual probability remains 1%."],"id":"L02-04","lesson":"02","domain":1,"explanation":"Correct. 1,000 × 0.01 = 10 is an expectation, not a guaranteed result."},{"prompt":"One claim above expectation changes the rate from 1% to 2% in a 100-person group. In a 10,000-person group, it changes the rate to 1.01%. What does this comparison show?","options":["The larger group has a lower assumed risk for each person.","One additional claim has a smaller effect on a larger group’s claim rate.","The larger group cannot have an unexpectedly bad year.","A larger group automatically lowers every policy's contractual benefit."],"answer":1,"review":"pooling","explanations":["The example keeps each person’s assumed annual probability at 1% in every group.","Correct. One divided by a larger number produces a smaller rate change. This illustrates sensitivity, not a guaranteed outcome.","Uncertainty remains. This single comparison does not describe every possible year.","Group size does not automatically change the benefit promised by an individual policy."],"id":"L02-05","lesson":"02","domain":1,"explanation":"Correct. One divided by a larger number produces a smaller rate change. This illustrates sensitivity, not a guaranteed outcome."},{"prompt":"Applicants who know they have a greater chance of a life-insurance claim are especially likely to seek coverage at standard rates. Which concept fits?","options":["Risk avoidance.","The law of large numbers.","Adverse selection.","Risk pooling."],"answer":2,"review":"selection","explanations":["Risk avoidance means avoiding an exposure. This describes who is drawn to an insurance offer.","The law of large numbers concerns average experience as a comparable group grows.","Correct. The tendency of higher-risk people to seek coverage at standard rates is adverse selection.","Pooling combines exposures. This question describes the selection pattern among people especially interested in the offer."],"id":"L02-06","lesson":"02","domain":1,"explanation":"Correct. The tendency of higher-risk people to seek coverage at standard rates is adverse selection."},{"prompt":"Does adverse selection require an applicant to lie?","options":["Yes. It is another name for deliberately filing a false claim.","No. It describes a selection pattern that can occur without dishonesty.","No. It means all applicants have exactly equal risk.","Yes. Adverse selection begins only after a dishonest claim has been paid."],"answer":1,"review":"selection","explanations":["Deliberate falsification is a separate issue. The selection pattern itself does not require a lie.","Correct. Higher-risk people may seek coverage more eagerly even when they answer every question truthfully.","Adverse selection is about a difference in risk among people seeking coverage.","The selection pattern can occur when people seek coverage, before any claim and without dishonesty."],"id":"L02-07","lesson":"02","domain":1,"explanation":"Correct. Higher-risk people may seek coverage more eagerly even when they answer every question truthfully."},{"prompt":"Why does an insurer use underwriting?","options":["To evaluate applications and classify risk using permitted information and rules.","To remove all uncertainty from every life policy.","To guarantee that no high-risk person ever applies.","To treat every application as the same risk without reviewing it."],"answer":0,"review":"selection","explanations":["Correct. Underwriting helps the insurer assess what it accepts and address adverse selection.","Underwriting improves assessment; it does not make future losses certain.","Underwriting evaluates applications. It cannot prevent people from applying or eliminate selection effects.","Underwriting evaluates differences in risk rather than assuming all applications are identical."],"id":"L02-08","lesson":"02","domain":1,"explanation":"Correct. Underwriting helps the insurer assess what it accepts and address adverse selection."}]},{"id":"03","number":3,"title":"Handling risk and reinsurance","version":1,"questions":[{"id":"L03-01","prompt":"Marcus decides not to participate in a recreational climbing trip. Which method addresses that particular exposure?","options":["Reduction","Avoidance","Retention","Reinsurance"],"answer":1,"explanations":["Reduction keeps the exposure but lowers its likelihood or severity.","Avoidance removes participation in the specified exposure.","Retention keeps responsibility for costs.","Reinsurance is risk transfer between insurers."],"topics":["2.1.06"],"review":1,"lesson":"03","domain":1,"explanation":"Avoidance removes participation in the specified exposure."},{"id":"L03-02","prompt":"A family adds a handrail but continues using the stairs. Which description fits?","options":["The chance of a fall is reduced.","All risk has been avoided.","The family has transferred costs to an insurer.","The family has created reinsurance."],"answer":0,"explanations":["The precaution reduces a hazard while the exposure remains.","Using the stairs still creates exposure.","There is no insurance contract in these facts.","No insurer-to-insurer agreement exists."],"topics":["2.1.09"],"review":1,"lesson":"03","domain":1,"explanation":"The precaution reduces a hazard while the exposure remains."},{"id":"L03-03","prompt":"Elena chooses to pay small losses from savings. What is she doing with the financial risk?","options":["Avoiding it","Reinsuring it","Retaining it","Eliminating it"],"answer":2,"explanations":["The exposure remains.","Reinsurance requires insurers.","She keeps responsibility for paying those losses.","Funding a loss does not make it impossible."],"topics":["2.1.07"],"review":1,"lesson":"03","domain":1,"explanation":"She keeps responsibility for paying those losses."},{"id":"L03-04","prompt":"What does a life-insurance contract primarily transfer?","options":["Every consequence of a death","The physical possibility of death","Ownership of the insured person","A specified financial obligation for a covered event"],"answer":3,"explanations":["Emotional and other losses remain.","Insurance cannot remove mortality.","A policy creates contractual rights, not ownership of a person.","The insurer accepts a defined payment obligation under the contract."],"topics":["2.1.10"],"review":2,"lesson":"03","domain":1,"explanation":"The insurer accepts a defined payment obligation under the contract."},{"id":"L03-05","prompt":"Which arrangement most directly illustrates sharing?","options":["One person keeps all costs in a savings account.","A group spreads a financial burden among its members.","A person stops taking part in an activity.","An insurer rejects every application."],"answer":1,"explanations":["This illustrates retention.","The burden is distributed among participants.","This illustrates avoidance.","Rejection does not itself describe sharing."],"topics":["2.1.08"],"review":2,"lesson":"03","domain":1,"explanation":"The burden is distributed among participants."},{"id":"L03-06","prompt":"Which set of characteristics generally supports insurability?","options":["An intentional gain, impossible to measure, affecting everyone identically","A guaranteed profit with no chance of loss","Comparable exposures and accidental, measurable losses with estimable costs","A loss whose cause, amount and probability can never be estimated"],"answer":2,"explanations":["Intentional speculative gains and unmeasurable results are poor foundations for insurance.","A profit opportunity is not the same as a pure loss exposure.","These characteristics help define and price an insurance obligation.","Inability to estimate the loss undermines pricing."],"topics":["2.1.11"],"review":3,"lesson":"03","domain":1,"explanation":"These characteristics help define and price an insurance obligation."},{"id":"L03-07","prompt":"A life insurer cedes part of its risk to a reinsurer. In the ordinary arrangement, who still owes the policyholder the promised covered benefit?","options":["The original insurer","Only the reinsurer","The producer personally","The policyholder’s employer"],"answer":0,"explanations":["The original insurer retains its policy obligation; reinsurance is a separate contract.","The reinsurer’s obligation is generally to the ceding insurer.","A producer is not the policy’s benefit-paying insurer.","No employer obligation is stated."],"topics":["2.1.14"],"review":4,"lesson":"03","domain":1,"explanation":"The original insurer retains its policy obligation; reinsurance is a separate contract."},{"id":"L03-08","prompt":"Which example contains speculative risk rather than only pure risk?","options":["A person may die during a policy term.","A stair user may fall or remain uninjured.","A family may suffer a fire or no fire.","An investor buys shares that may gain or lose value."],"answer":3,"explanations":["The stated outcomes are loss or no loss.","The stated outcomes are loss or no loss.","The stated outcomes are loss or no loss.","Speculative risk includes a possibility of financial gain as well as loss."],"topics":["2.1.11"],"review":3,"lesson":"03","domain":1,"explanation":"Speculative risk includes a possibility of financial gain as well as loss."}]},{"id":"04","number":4,"title":"Insurers and distribution","version":2,"questions":[{"id":"L04-01","prompt":"A shareholder-owned insurer formed in Virginia is authorized in Maryland. Which description is consistent with all facts?","options":["Mutual, domestic and nonadmitted","Stock, foreign and admitted","Stock, alien and nonadmitted","Fraternal, domestic and admitted"],"answer":1,"explanations":["Every listed dimension conflicts with the facts.","Shareholders indicate stock; Virginia formation indicates foreign; Maryland authority indicates admitted.","Another U.S. state is foreign, not alien, and authorization is stated.","No fraternal structure or Maryland formation is stated."],"topics":["2.2.01","2.2.04","2.2.06"],"review":0,"lesson":"04","domain":1,"explanation":"Shareholders indicate stock; Virginia formation indicates foreign; Maryland authority indicates admitted."},{"id":"L04-02","prompt":"Which insurer is domestic relative to Maryland?","options":["One with an office in Baltimore but formed in Ohio","Every insurer authorized in Maryland","One formed under Maryland law","Every mutual insurer"],"answer":2,"explanations":["Office location does not determine domicile.","Authorization and domicile are separate.","Domestic refers to formation in the state being considered.","Ownership structure does not determine domicile."],"topics":["2.2.06"],"review":2,"lesson":"04","domain":1,"explanation":"Domestic refers to formation in the state being considered."},{"id":"L04-03","prompt":"What primarily distinguishes a stock insurer from a mutual insurer?","options":["Shareholder ownership versus policyholder ownership","Admission versus nonadmission","U.S. formation versus overseas formation","Selling life insurance versus selling annuities"],"answer":0,"explanations":["Ownership is the relevant distinction.","Either structure can be admitted.","Domicile is a different dimension.","Both structures can offer authorized products."],"topics":["2.2.01"],"review":1,"lesson":"04","domain":1,"explanation":"Ownership is the relevant distinction."},{"id":"L04-04","prompt":"Which statement about assessment arrangements is most accurate?","options":["Every mutual policy requires unlimited assessments.","A strong financial rating eliminates assessment provisions.","Assessment terms are the same as state admission.","Possible member assessments depend on the organization and contract terms."],"answer":3,"explanations":["Do not generalize assessment terms to every mutual policy.","A rating does not rewrite the contract.","Assessments and authorization answer different questions.","Check the particular assessment structure and its terms."],"topics":["2.2.01"],"review":1,"lesson":"04","domain":1,"explanation":"Check the particular assessment structure and its terms."},{"id":"L04-05","prompt":"A benefit society uses a membership structure and a common bond. Which category best fits?","options":["A stock exchange","A fraternal benefit society","A securities regulator","A rating agency"],"answer":1,"explanations":["A stock exchange is not this insurer structure.","Membership and common bond are distinguishing fraternal features.","The society is not a regulator.","Rating agencies issue opinions, not member insurance benefits."],"topics":["2.2.02"],"review":1,"lesson":"04","domain":1,"explanation":"Membership and common bond are distinguishing fraternal features."},{"id":"L04-06","prompt":"What does an insurer’s high financial-strength rating establish?","options":["A state guarantee of every claim","Permission for any producer to sell its policies","A rating organization’s financial-strength opinion at that time","Unlimited guaranty-corporation protection"],"answer":2,"explanations":["A rating is not a state guarantee.","Producer authority is separate.","Ratings are opinions and can change.","Statutory limits and exclusions still apply."],"topics":["2.2.07","2.2.09"],"review":3,"lesson":"04","domain":1,"explanation":"Ratings are opinions and can change."},{"id":"L04-07","prompt":"An independent producer has contracts with several insurers. What must the producer still verify before acting for one?","options":["That all insurers charge identical rates","That the producer owns the insurer","That the insurer is domestic in every state","The applicable license, appointment and contractual authority"],"answer":3,"explanations":["Identical rates are not required.","Ownership is not necessary.","An insurer cannot be domestic in every state merely because it operates there.","Independent distribution does not grant unrestricted authority."],"topics":["2.2.08"],"review":4,"lesson":"04","domain":1,"explanation":"Independent distribution does not grant unrestricted authority."},{"id":"L04-08","prompt":"An association buys coverage from an insurer for eligible members. Which conclusion follows merely from buying coverage as a group?","options":["The association has become an insurer.","It can disregard insurer licensing requirements.","It is purchasing coverage, but does not thereby become the insurer.","Every member automatically receives government life insurance."],"answer":2,"explanations":["Purchasing coverage does not establish underwriting authority.","Licensing rules still apply.","Separate the purchaser from the carrier’s insurance obligation.","Government-program eligibility is not created by association purchase."],"topics":["2.2.03","2.2.05"],"review":4,"lesson":"04","domain":1,"explanation":"Separate the purchaser from the carrier’s insurance obligation."},{"id":"L04-09","prompt":"A Maryland producer is asked to solicit an ordinary life policy for an unauthorized insurer, with no statutory exception applying. What should the producer do?","options":["Proceed because the producer’s license authorizes every insurer.","Proceed if the insurer has a strong financial rating.","Collect the premium but avoid signing the application.","Decline to act for the unauthorized insurer and verify lawful authority."],"answer":3,"explanations":["Producer licensing does not authorize the insurer.","Financial ratings do not replace legal authority.","Collecting premiums can itself be prohibited assistance.","Section 4-203 prohibits this assistance when no exception applies."],"topics":["1.2.03"],"review":3,"lesson":"04","domain":0,"explanation":"Section 4-203 prohibits this assistance when no exception applies."}]},{"id":"05","number":5,"title":"Agency and producer authority","version":1,"questions":[{"id":"L05-01","prompt":"In an insurer-producer agency relationship, the insurer authorizes the producer to act on its behalf. Which is the principal?","options":["The applicant","The beneficiary","The insurer","The producer’s receptionist"],"answer":2,"explanations":["An applicant is the prospective insured or owner.","A beneficiary receives designated benefits.","The insurer is the party granting authority in these facts.","No authority-granting role is stated for the receptionist."],"topics":["2.3.02"],"review":0,"lesson":"05","domain":1,"explanation":"The insurer is the party granting authority in these facts."},{"id":"L05-02","prompt":"A written agreement specifically permits a producer to collect initial premiums using an approved receipt. What type of authority is described?","options":["Express","Apparent only","Authority created by the applicant","Unlimited binding authority"],"answer":0,"explanations":["The permission is directly granted.","No third-party appearance is needed to establish the explicit grant.","The applicant does not grant insurer authority.","Permission to use a receipt does not authorize every coverage promise."],"topics":["2.3.03"],"review":1,"lesson":"05","domain":1,"explanation":"The permission is directly granted."},{"id":"L05-03","prompt":"A producer explains the insurer’s approved form as a necessary part of an authorized application submission. Which authority best describes that incidental act?","options":["Judicial","Implied","Authority to waive exclusions","Authority from a beneficiary"],"answer":1,"explanations":["No court has granted this working authority.","The act is incidental to carrying out the express task.","Explaining a form does not permit deleting policy terms.","No beneficiary grant is involved."],"topics":["2.3.04"],"review":2,"lesson":"05","domain":1,"explanation":"The act is incidental to carrying out the express task."},{"id":"L05-04","prompt":"Which fact is most relevant to apparent authority?","options":["The producer secretly wishes to change the policy.","The applicant hopes all losses are covered.","An insurer’s conduct reasonably presents the producer as authorized for the task.","The producer earns a commission."],"answer":2,"explanations":["A private wish creates no appearance from the principal.","A hope alone does not establish reasonable reliance on the principal.","The principal’s manifestations and reasonable reliance are central.","Compensation alone does not establish the scope of apparent authority."],"topics":["2.3.05"],"review":3,"lesson":"05","domain":1,"explanation":"The principal’s manifestations and reasonable reliance are central."},{"id":"L05-05","prompt":"An independent producer represents three insurers. What follows?","options":["The producer may change all three insurers’ underwriting rules.","One appointment automatically authorizes every insurer.","The producer needs no insurance license.","Authority must still be established for the insurer and transaction."],"answer":3,"explanations":["Independent status does not permit rewriting underwriting.","Appointments do not automatically extend to unrelated insurers.","Licensing requirements still apply.","Multiple relationships do not remove limits on authority."],"topics":["2.3.01"],"review":4,"lesson":"05","domain":1,"explanation":"Multiple relationships do not remove limits on authority."},{"id":"L05-06","prompt":"A client asks the producer to guarantee approval before underwriting. Which response is appropriate?","options":["Promise approval to keep the client interested.","Explain the process and obtain the insurer’s decision.","Sign the application for the client.","Remove answers that might cause a delay."],"answer":1,"explanations":["An unsupported guarantee misrepresents the process.","The producer should accurately explain the limits of their authority.","Forging the client’s signature is prohibited.","Material information must not be concealed."],"topics":["2.3.06"],"review":1,"lesson":"05","domain":1,"explanation":"The producer should accurately explain the limits of their authority."},{"id":"L05-07","prompt":"Which statement correctly separates a license from a producer agreement?","options":["They are interchangeable documents.","The agreement replaces state permission.","The license concerns state authority; the agreement sets the insurer-producer working relationship.","The license guarantees every application’s acceptance."],"answer":2,"explanations":["The documents serve different purposes.","Contractual terms do not eliminate licensing law.","Regulatory permission and contractual working authority are separate.","Underwriting acceptance is separate from producer licensing."],"topics":["2.3.03","2.3.01"],"review":4,"lesson":"05","domain":1,"explanation":"Regulatory permission and contractual working authority are separate."},{"id":"L05-08","prompt":"A producer notices a material application answer is wrong. What best fulfills the producer’s responsibility?","options":["Follow the insurer’s correction procedure with the applicant.","Ignore it because the client signed.","Submit a different answer without the applicant’s knowledge.","Promise to repair it only if there is a claim."],"answer":0,"explanations":["Correct and document the information through the approved process.","A signature does not justify knowingly submitting a false answer.","Unauthorized alteration is not an acceptable correction.","The application should be accurate before submission or corrected promptly when discovered."],"topics":["2.3.06"],"review":5,"lesson":"05","domain":1,"explanation":"Correct and document the information through the approved process."}]},{"id":"06","number":6,"title":"Building the insurance contract","version":1,"questions":[{"id":"L06-01","prompt":"An insurer responds to an application by offering a higher premium than requested. What does that response commonly represent?","options":["Automatic acceptance on the original terms","A counteroffer","Payment of a death benefit","A beneficiary designation"],"answer":1,"explanations":["The offered terms differ.","Different proposed terms are a counteroffer requiring acceptance under the transaction’s rules.","No insured death is described.","The response concerns contract terms, not a benefit recipient."],"topics":["2.4.01"],"review":0,"lesson":"06","domain":1,"explanation":"Different proposed terms are a counteroffer requiring acceptance under the transaction’s rules."},{"id":"L06-02","prompt":"Which is the insurer’s consideration in the ordinary life-insurance exchange?","options":["The applicant’s medical statement","The producer’s sales goal","Its contractual promise to pay covered benefits","The beneficiary’s personal savings"],"answer":2,"explanations":["The applicant supplies application statements.","A sales goal is not consideration to the applicant.","The insurer exchanges its contractual promise for the applicant’s consideration.","The beneficiary’s savings are unrelated."],"topics":["2.4.02"],"review":1,"lesson":"06","domain":1,"explanation":"The insurer exchanges its contractual promise for the applicant’s consideration."},{"id":"L06-03","prompt":"Which issue concerns legal capacity rather than underwriting classification?","options":["Whether a party has legal ability to enter the agreement","Whether the premium is standard or substandard","Whether the insurer expects more claims in a pool","Whether a policy’s dividend scale changes"],"answer":0,"explanations":["Capacity concerns legal ability to contract.","Risk classification is an underwriting issue.","Expected claims concern insurance pricing.","Dividend experience is a policy-performance issue."],"topics":["2.4.03"],"review":1,"lesson":"06","domain":1,"explanation":"Capacity concerns legal ability to contract."},{"id":"L06-04","prompt":"The insurer drafts standard terms that the applicant generally accepts or rejects. Which characteristic fits?","options":["Indemnity","Aleatory","Collateral assignment","Adhesion"],"answer":3,"explanations":["Indemnity concerns compensation for loss.","Aleatory concerns uncertain and potentially unequal exchange.","Assignment transfers rights.","Adhesion describes the standard-form drafting relationship."],"topics":["2.4.04"],"review":2,"lesson":"06","domain":1,"explanation":"Adhesion describes the standard-form drafting relationship."},{"id":"L06-05","prompt":"A covered death triggers a benefit much larger than premiums paid so far. Which characteristic does this illustrate?","options":["Bilateral negotiation of every clause","Aleatory exchange","Absence of consideration","A guarantee of investment profit"],"answer":1,"explanations":["The facts concern value, not negotiated wording.","An uncertain event can produce unequal values exchanged.","The premium and insurer promise still provide consideration.","A death benefit is not a guaranteed investment profit."],"topics":["2.4.05"],"review":2,"lesson":"06","domain":1,"explanation":"An uncertain event can produce unequal values exchanged."},{"id":"L06-06","prompt":"Which statement reconciles “unilateral” with “conditional”?","options":["Neither party makes an enforceable promise.","The owner must pay premiums forever regardless of policy terms.","The insurer promises covered benefits, subject to applicable conditions.","Every claim must be paid even after valid coverage ends."],"answer":2,"explanations":["The insurer makes a contractual promise.","Stopping premiums can have policy consequences without a universal lifelong payment obligation.","These characteristics address different aspects of the contract.","Conditions and coverage periods still matter."],"topics":["2.4.07"],"review":3,"lesson":"06","domain":1,"explanation":"These characteristics address different aspects of the contract."},{"id":"L06-07","prompt":"Why does ordinary life insurance differ from strict indemnity?","options":["It always pays every expense a family claims.","It has no financial purpose.","It cannot name a beneficiary.","Its death benefit is generally stated by the contract rather than measured after death from actual expenses."],"answer":3,"explanations":["The contract controls the amount.","Life coverage addresses financial consequences.","Life policies commonly name beneficiaries.","The stated benefit is the key distinction."],"topics":["2.4.09"],"review":4,"lesson":"06","domain":1,"explanation":"The stated benefit is the key distinction."},{"id":"L06-08","prompt":"Marcus assigns ownership rights in his life policy under permitted terms. Which fact ordinarily remains unchanged merely because of that assignment?","options":["The identity of the insured life","Every ownership right","The owner’s ability to choose a new beneficiary","The assignee’s economic rights"],"answer":0,"explanations":["Assignment transfers rights in the policy; it does not substitute a new insured life.","Ownership rights are exactly what an absolute assignment may transfer.","Control over beneficiary changes can be affected.","The assignment can create or transfer economic rights."],"topics":["2.4.06"],"review":4,"lesson":"06","domain":1,"explanation":"Assignment transfers rights in the policy; it does not substitute a new insured life."}]},{"id":"07","number":7,"title":"Truth, interpretation and enforceability","version":1,"questions":[{"id":"L07-01","prompt":"A client expected a benefit that a clearly written exclusion removes. Which conclusion is sound from these facts alone?","options":["The client’s expectation always overrides the exclusion.","Disappointment alone does not establish an ambiguity.","The producer can erase the exclusion verbally.","Every exclusion is invalid because the insurer drafted it."],"answer":1,"explanations":["Reasonable-expectations principles are not a universal override.","Look for more than one reasonable meaning in context.","Producer authority and the written contract still matter.","Adhesion does not invalidate all clear exclusions."],"topics":["2.4.08"],"review":0,"lesson":"07","domain":1,"explanation":"Look for more than one reasonable meaning in context."},{"id":"L07-02","prompt":"How does Maryland §12–207 classify statements in a life-insurance application?","options":["As representations rather than warranties","As guaranteed predictions of future health","As insurer dividends","As beneficiary assignments"],"answer":0,"explanations":["The statute expressly treats them as representations.","Applicants supply facts, not a guarantee of future outcomes.","Dividends are a separate policy feature.","Application statements are not transfers of ownership rights."],"topics":["2.4.11","2.4.12"],"review":1,"lesson":"07","domain":1,"explanation":"The statute expressly treats them as representations."},{"id":"L07-03","prompt":"Which statement correctly addresses a false answer under Maryland’s life-policy application rule?","options":["Only a criminal conviction can affect recovery.","Every error automatically cancels coverage.","A material incorrect statement can matter even without proving deliberate deception in every case.","Calling it a representation makes it irrelevant."],"answer":2,"explanations":["The statute has policy-recovery standards, not only criminal ones.","Statutory conditions and materiality matter.","The statute contains alternative grounds; fraud is not the sole test.","Representations can still affect recovery under the statute."],"topics":["2.4.11"],"review":2,"lesson":"07","domain":1,"explanation":"The statute contains alternative grounds; fraud is not the sole test."},{"id":"L07-04","prompt":"An applicant deliberately withholds requested material information to obtain coverage. Which description best captures the dishonest conduct?","options":["Ordinary policy assignment","An accidental loss","A dividend election","Concealment that may also constitute fraud"],"answer":3,"explanations":["No ownership transfer is described.","The conduct is deliberate disclosure behavior.","No dividend is involved.","Intentional withholding can raise concealment and fraud issues."],"topics":["2.4.10","2.4.13"],"review":3,"lesson":"07","domain":1,"explanation":"Intentional withholding can raise concealment and fraud issues."},{"id":"L07-05","prompt":"An insurer knowingly and voluntarily gives up a contractual right. Which doctrine is most directly described?","options":["Waiver","Adverse selection","Indemnity","Apparent authority"],"answer":0,"explanations":["Waiver is relinquishment of a known right.","Adverse selection concerns who seeks coverage.","Indemnity concerns compensation for loss.","Apparent authority concerns the principal’s manifestations of agent authority."],"topics":["2.4.14"],"review":4,"lesson":"07","domain":1,"explanation":"Waiver is relinquishment of a known right."},{"id":"L07-06","prompt":"A party’s misleading conduct causes another to reasonably rely and suffer harm when the first party reverses position. Which doctrine is implicated?","options":["Aleatory exchange","Estoppel","Nonforfeiture","Risk avoidance"],"answer":1,"explanations":["Aleatory describes uncertain and potentially unequal exchange.","Inconsistent conduct and detrimental reliance are key estoppel ideas.","Nonforfeiture preserves policy value under stated options.","No exposure was avoided."],"topics":["2.4.14"],"review":4,"lesson":"07","domain":1,"explanation":"Inconsistent conduct and detrimental reliance are key estoppel ideas."},{"id":"L07-07","prompt":"A producer discovers a wrong answer in an application already submitted. What should happen next?","options":["Leave it because an electronic signature exists.","Wait until a claim makes it relevant.","Promptly follow the insurer’s documented correction procedure.","Change it secretly and remove the earlier version."],"answer":2,"explanations":["A signature does not make incorrect information accurate.","Prompt correction is appropriate.","Accurate disclosure and a documented correction protect the file’s integrity.","Secret alteration defeats an accurate record."],"topics":["2.4.10","2.4.11"],"review":5,"lesson":"07","domain":1,"explanation":"Accurate disclosure and a documented correction protect the file’s integrity."},{"id":"L07-08","prompt":"Which pair must be analyzed under different Maryland statutory standards?","options":["A policy’s two identical copies","The same answer read twice","Two applicants requesting the same coverage","A material statement in a life-policy application and one in a producer-license application"],"answer":3,"explanations":["Identical copies do not establish different standards.","Repeated reading does not change the legal issue.","The distinction is the applicable rule, not merely two applicants.","Policy recovery under §12–207 and license discipline under §10–126 have different elements."],"topics":["2.4.11"],"review":2,"lesson":"07","domain":1,"explanation":"Policy recovery under §12–207 and license discipline under §10–126 have different elements."}]},{"id":"08","number":8,"title":"Federal rules and industry organizations","version":1,"questions":[{"id":"L08-01","prompt":"An insurer offers less favorable terms partly because of a consumer report. Which statement is correct?","options":["Only a total denial can be an adverse action.","The reporting agency automatically made the insurance decision.","Required FCRA adverse-action notice may apply even though coverage is offered.","A producer can keep the report’s source secret in every case."],"answer":2,"explanations":["Less favorable terms can qualify.","The insurer makes the underwriting decision.","Adverse action is broader than a complete rejection.","Required notice includes reporting-agency information."],"topics":["2.5.01"],"review":1,"lesson":"08","domain":1,"explanation":"Adverse action is broader than a complete rejection."},{"id":"L08-02","prompt":"After a report-based adverse-action notice, how long does the consumer have to request the associated free report under the FCRA right described here?","options":["5 days","15 days","30 days","60 days"],"answer":3,"explanations":["Five days is not this free-report request period.","Fifteen days is not this federal period.","Thirty days is not this free-report request period.","The notice explains the right to request a free report within 60 days."],"topics":["2.5.01"],"review":1,"lesson":"08","domain":1,"explanation":"The notice explains the right to request a free report within 60 days."},{"id":"L08-03","prompt":"A person falls within a federal §1033 insurance-work prohibition. What does an ordinary state producer license alone establish about the required federal consent?","options":["It is not a substitute for the required written consent.","It automatically removes every federal restriction.","It transfers the restriction to the insurer.","It makes the prior conviction irrelevant to all laws."],"answer":0,"explanations":["State licensing and required federal consent are separate.","Federal restrictions can still apply.","The person’s restriction is not transferred away.","The applicable laws must still be considered."],"topics":["2.5.02"],"review":2,"lesson":"08","domain":1,"explanation":"State licensing and required federal consent are separate."},{"id":"L08-04","prompt":"Which statement about variable life is correct?","options":["It has no securities requirements because it is called insurance.","Insurance authority and applicable securities requirements both matter.","A prospectus guarantees positive investment returns.","FINRA issues every Maryland insurance license."],"answer":1,"explanations":["Variable life has securities features and requirements.","Both regulatory frameworks can apply.","A prospectus discloses risks; it does not guarantee returns.","MIA is the state insurance regulator."],"topics":["2.5.03"],"review":3,"lesson":"08","domain":1,"explanation":"Both regulatory frameworks can apply."},{"id":"L08-05","prompt":"NAIC adopts a model law. What must a Maryland learner avoid assuming?","options":["That it may inform policy discussions","That regulators can coordinate through NAIC","That adoption by NAIC alone automatically makes it enforceable Maryland law","That model wording can be reviewed by a state"],"answer":2,"explanations":["Model laws can inform discussion.","Coordination is an NAIC function.","A model is not automatically enacted state law.","States can evaluate model wording."],"topics":["2.6.01"],"review":4,"lesson":"08","domain":1,"explanation":"A model is not automatically enacted state law."},{"id":"L08-06","prompt":"Which function belongs to the Insurance Compact commission?","options":["Granting every producer’s personal license","Guaranteeing policy investment returns","Acting as every consumer’s private lawyer","Coordinated filing and review of covered products under uniform standards"],"answer":3,"explanations":["Individual licensing remains a separate state function.","Product review is not a return guarantee.","The commission does not serve as private counsel.","Covered product standards and coordinated review are its role."],"topics":["2.6.02"],"review":4,"lesson":"08","domain":1,"explanation":"Covered product standards and coordinated review are its role."},{"id":"L08-07","prompt":"Which description best fits NCOIL?","options":["An organization of state legislators working on insurance policy and model legislation","A federal consumer-reporting agency","A life-insurance company owned by shareholders","The office that decides every Maryland claim"],"answer":0,"explanations":["Its role concerns legislators and insurance public policy.","It is not a consumer-reporting agency.","It is not this insurer structure.","It does not adjudicate every claim."],"topics":["2.6.03"],"review":5,"lesson":"08","domain":1,"explanation":"Its role concerns legislators and insurance public policy."},{"id":"L08-08","prompt":"A producer joins a professional insurance association. What does membership ordinarily provide?","options":["Automatic appointment with every insurer","Professional resources and representation, without replacing licensing requirements","Permission to skip a prospectus","A guarantee of approval for all applications"],"answer":1,"explanations":["Appointments require separate authority.","Membership can support professional work but does not replace legal requirements.","Securities disclosures still apply.","Underwriting decisions remain separate."],"topics":["2.6.04"],"review":5,"lesson":"08","domain":1,"explanation":"Membership can support professional work but does not replace legal requirements."}]},{"id":"09","number":9,"title":"Maryland licensing: who may do what?","version":1,"questions":[{"id":"L09-01","prompt":"Elena’s agency has a Maryland life producer license. Elena has not obtained her own required license. What does the agency license alone permit her to assume?","options":["That she can sell any life policy personally","That her personal licensing requirement is already satisfied","That entity authority and her individual authority must still be distinguished","That exam registration grants temporary selling authority"],"answer":2,"explanations":["An agency license is not each worker’s personal license.","Individual qualifications and authority remain separate.","The license belongs to its holder; both levels must be checked.","Registering for an exam is not a producer license."],"topics":["1.1.01","1.1.03","1.1.08"],"review":0,"lesson":"09","domain":0,"explanation":"The license belongs to its holder; both levels must be checked."},{"id":"L09-02","prompt":"Which statement reflects Maryland’s removal of mandatory prelicensing education in October 2024?","options":["The regular life producer exam was abolished.","Renewal continuing education was abolished.","A course completion automatically issues a license.","The education prerequisite changed, while exam and renewal CE requirements remain."],"answer":3,"explanations":["The examination requirement remains applicable.","The change did not remove renewal CE.","Licensing still requires the applicable application and qualifications.","Prelicensing education, the licensing exam and renewal CE are different requirements."],"topics":["1.1.02"],"review":1,"lesson":"09","domain":0,"explanation":"Prelicensing education, the licensing exam and renewal CE are different requirements."},{"id":"L09-03","prompt":"Which condition ordinarily supports obtaining and maintaining a Maryland nonresident producer license?","options":["A resident license in good standing in the home state, with applicable Maryland requirements met","A client’s verbal permission to skip licensing","An employer’s business card in place of an application","A life policy owned in any state"],"answer":0,"explanations":["Home-state standing and the applicable reciprocity, application and fee rules matter.","Client permission does not waive licensing law.","A business card does not establish state authority.","Owning insurance is not being licensed to transact it."],"topics":["1.1.03"],"review":2,"lesson":"09","domain":0,"explanation":"Home-state standing and the applicable reciprocity, application and fee rules matter."},{"id":"L09-04","prompt":"What must a business entity designate for its Maryland producer licensing relationship with MIA?","options":["Any customer with an active policy","A licensed insurance producer as its principal contact","A reinsurer as its beneficiary","An unlicensed volunteer to replace all licensed staff"],"answer":1,"explanations":["A customer is not the required designated producer.","§10–106 requires a designated licensed producer.","Reinsurance and beneficiaries are unrelated to this designation.","The contact must have the required producer license."],"topics":["1.1.03"],"review":2,"lesson":"09","domain":0,"explanation":"§10–106 requires a designated licensed producer."},{"id":"L09-05","prompt":"An assistant performs only qualifying clerical tasks and receives no policy commission. What is the best next step before relying on an exception?","options":["Assume all agency employees are exempt.","Allow policy solicitation because the person is salaried.","Check the actual duties and every applicable statutory condition.","Replace the license requirement with an internal title."],"answer":2,"explanations":["The employee exception has conditions.","Salary alone does not exempt selling or solicitation.","The law looks at conduct and compensation, not just title.","An internal title does not create legal authority."],"topics":["1.1.04"],"review":4,"lesson":"09","domain":0,"explanation":"The law looks at conduct and compensation, not just title."},{"id":"L09-06","prompt":"A qualifying Maryland temporary producer license under §10–120 expires how long after its effective date?","options":["30 days","90 days","180 days","15 months"],"answer":3,"explanations":["Thirty days is the stated application-decision period.","Ninety days is not this temporary-license duration.","Do not import another state’s temporary-license period.","The Maryland statute specifies fifteen months."],"topics":["1.1.04"],"review":5,"lesson":"09","domain":0,"explanation":"The Maryland statute specifies fifteen months."},{"id":"L09-07","prompt":"Which statement accurately treats the Maryland adviser subtitle?","options":["A licensed producer acting as a producer for a client is a listed exception.","Every mention of insurance requires an adviser license.","An advisory title itself grants unlimited authority.","The adviser subtitle replaces all producer licensing rules."],"answer":0,"explanations":["§10–202 lists this exception, so ordinary licensed producer work must be distinguished.","The statute defines a specific role and exceptions.","A title cannot substitute for required authority.","The licensing frameworks have different scopes."],"topics":["1.1.03"],"review":3,"lesson":"09","domain":0,"explanation":"§10–202 lists this exception, so ordinary licensed producer work must be distinguished."},{"id":"L09-08","prompt":"Under Maryland §8–603, when must a viatical settlement provider register?","options":["Only after receiving its first death benefit","Before acting or representing itself as a provider","Only if a consumer files a complaint","At the next ordinary producer renewal, regardless of activity"],"answer":1,"explanations":["Registration cannot wait until a benefit is paid.","The provider must register before acting or holding itself out in that role.","The duty exists without a complaint.","Separate settlement registration is not postponed to ordinary renewal."],"topics":["1.1.04"],"review":3,"lesson":"09","domain":0,"explanation":"The provider must register before acting or holding itself out in that role."}]},{"id":"10","number":10,"title":"Keep the license active","version":1,"questions":[{"id":"L10-01","prompt":"For a typical resident Maryland life producer subject to the regular requirement, which CE statement is correct?","options":["24 approved hours including at least 3 ethics hours","24 hours plus a separate additional 24 in ethics","Any 3 hours every ten years","No education after the first licensing exam"],"answer":0,"explanations":["Ethics is included within the regular twenty-four hours.","The statute does not impose this doubled requirement.","This is not the regular biennial requirement.","Removal of prelicensing education did not abolish renewal CE."],"topics":["1.1.05"],"review":1,"lesson":"10","domain":0,"explanation":"Ethics is included within the regular twenty-four hours."},{"id":"L10-02","prompt":"Under the current Maryland producer CE statute, required education must be completed no later than when?","options":["On the day after expiration","15 days before license expiration","60 days after license expiration","Only after a renewal application is denied"],"answer":1,"explanations":["Education has an earlier statutory deadline.","§10–116(a)(2) states fifteen days before expiration.","The reinstatement rules do not replace the CE deadline.","The producer must meet the renewal requirement proactively."],"topics":["1.1.05"],"review":1,"lesson":"10","domain":0,"explanation":"§10–116(a)(2) states fifteen days before expiration."},{"id":"L10-03","prompt":"A producer’s license expired and reinstatement is not yet effective. What is the correct approach to new insurance business?","options":["Continue because reinstatement might later be retroactive.","Use the former license number without checking status.","Stop insurance business until reinstatement is effective.","Treat the one-year reinstatement window as selling authority."],"answer":2,"explanations":["Potential retroactive reinstatement is not permission to operate while expired.","A number does not establish active authority.","§10–116.1 prohibits insurance business until reinstatement is effective.","The window provides a reinstatement process, not a business grace period."],"topics":["1.1.05"],"review":2,"lesson":"10","domain":0,"explanation":"§10–116.1 prohibits insurance business until reinstatement is effective."},{"id":"L10-04","prompt":"A producer applies for reinstatement 70 days after expiration and otherwise meets the requirements. Which effective-date rule applies?","options":["Automatic retroactivity to expiration","Retroactivity only to the first sale after expiration","Effectiveness on the date the original license was issued","Prospective reinstatement under the more-than-60-day rule"],"answer":3,"explanations":["The statutory retroactive rule concerns applications within sixty days.","A sale does not set the reinstatement date.","The original issue date does not restart this license.","Applications after sixty days receive prospective reinstatement."],"topics":["1.1.05"],"review":2,"lesson":"10","domain":0,"explanation":"Applications after sixty days receive prospective reinstatement."},{"id":"L10-05","prompt":"Marcus changes the email address on his individual producer license. What is the ordinary reporting period under §10–117?","options":["30 days after the change","At the next two-year renewal only","10 years after the change","Only after a mailed notice is returned"],"answer":0,"explanations":["The licensee change rule includes email and specifies thirty days.","Waiting until renewal can miss the deadline.","Ten years is not the statutory period.","The duty arises from the change, not a failed mailing."],"topics":["1.1.06"],"review":3,"lesson":"10","domain":0,"explanation":"The licensee change rule includes email and specifies thirty days."},{"id":"L10-06","prompt":"What starts the thirty-day reporting period for a covered criminal prosecution under Maryland §10–126?","options":["The final conviction in every case","The initial court appearance","The next insurance renewal date","The date a client asks about the case"],"answer":1,"explanations":["The criminal rule does not generally wait for conviction.","The statute ties this report to initial court appearance.","Renewal is a separate calendar event.","A client’s inquiry does not start the statutory clock."],"topics":["1.1.07"],"review":4,"lesson":"10","domain":0,"explanation":"The statute ties this report to initial court appearance."},{"id":"L10-07","prompt":"What starts the report deadline for a covered adverse administrative action in another jurisdiction?","options":["The producer’s next birthday","The first newspaper story","Final disposition of the administrative matter","The next policy commission payment"],"answer":2,"explanations":["The birthday is relevant to ordinary individual-license expiration.","News coverage is not the stated event.","The covered administrative action is reported within thirty days of final disposition.","Compensation timing does not control this duty."],"topics":["1.1.07"],"review":4,"lesson":"10","domain":0,"explanation":"The covered administrative action is reported within thirty days of final disposition."},{"id":"L10-08","prompt":"The designated producer contact for a business entity changes information specifically required under §10–106(c)(1). Which reporting period belongs to that provision?","options":["90 days","60 days","30 days in every possible licensing context","10 days after the change"],"answer":3,"explanations":["Ninety days concerns different residency provisions.","Sixty days is a reinstatement dividing point.","Do not apply one general deadline to a distinct specific duty.","The designated-contact provision requires written notice within ten days."],"topics":["1.1.03","1.1.06"],"review":3,"lesson":"10","domain":0,"explanation":"The designated-contact provision requires written notice within ten days."}]},{"id":"11","number":11,"title":"Appointments, oversight and discipline","version":2,"questions":[{"id":"L11-01","prompt":"Elena has a state life producer license. Which separate question must she answer before acting for a particular insurer?","options":["Whether completing continuing education alone creates insurer authority","Whether an appointment or a specific lawful exception supports that activity","Whether passing the state exam permits representation of every insurer","Whether receiving a referral from a client establishes the insurer relationship"],"answer":1,"explanations":["Continuing education maintains knowledge and licensing compliance; it does not itself create appointment authority.","State licensing and insurer appointment authority are distinct.","Exam passage does not authorize every insurer relationship.","A client referral does not establish authority from the insurer."],"topics":["1.1.08"],"review":0,"lesson":"11","domain":0,"explanation":"State licensing and insurer appointment authority are distinct."},{"id":"L11-02","prompt":"An authorized insurer initially accepts a life application from an appropriately licensed but unappointed producer. What does §10–118 require within 30 days?","options":["Automatic policy approval at the requested rate","The applicant’s appointment as a producer","Rejection under applicable law, or appointment and required register entry","Cancellation of the producer’s state license"],"answer":2,"explanations":["Processing acceptance is not automatic underwriting approval.","The applicant is applying for coverage, not appointment.","The statute sets these alternatives for the insurer.","An insurer does not cancel the state license through this application process."],"topics":["1.1.09"],"review":1,"lesson":"11","domain":0,"explanation":"The statute sets these alternatives for the insurer."},{"id":"L11-03","prompt":"An insurer has appointed Elena and provided written documentation, but its timely register entry is still pending. Under COMAR 31.03.13.06, what is correct?","options":["The written documentation has no significance.","She automatically has authority for every insurer.","She must apply for a temporary state license.","She may act for that insurer within authority before the register entry is completed."],"answer":3,"explanations":["The regulation expressly relies on written appointment documentation.","Authority is specific to the insurer and permitted activity.","This is not a temporary-license situation.","The regulation permits action on appointment with the required written documentation."],"topics":["1.1.08"],"review":2,"lesson":"11","domain":0,"explanation":"The regulation permits action on appointment with the required written documentation."},{"id":"L11-04","prompt":"How long must a Maryland producer retain required appointment information after that appointment terminates?","options":["At least 5 years","Only until the final commission arrives","15 days","No time if stored electronically"],"answer":0,"explanations":["COMAR 31.03.13.05 sets the five-year minimum after termination.","Commission payment is not the retention trigger.","Fifteen days is a different termination-notice clock.","Electronic records are still subject to retention requirements."],"topics":["1.2.04"],"review":2,"lesson":"11","domain":0,"explanation":"COMAR 31.03.13.05 sets the five-year minimum after termination."},{"id":"L11-05","prompt":"After an insurer provides a required discipline-related termination notice to the Commissioner, when must it send the prescribed copy to the producer?","options":["At the next renewal only","Within 15 days","Only if the producer requests it","After every possible appeal ends"],"answer":1,"explanations":["The notice-copy rule has an earlier fixed period.","§10–118(g)(1) specifies fifteen days after the required regulator notice.","The insurer has an affirmative copy duty.","The copy does not wait for all potential appeals."],"topics":["1.1.10"],"review":3,"lesson":"11","domain":0,"explanation":"§10–118(g)(1) specifies fifteen days after the required regulator notice."},{"id":"L11-06","prompt":"Which statement accurately describes the penalty in Maryland §10–126(c)?","options":["Exactly $100 for every case, with no other remedy","A producer chooses any amount it wishes","$100–$5,000 per violation, available instead of or in addition to suspension or revocation","Only a private insurer can impose it"],"answer":2,"explanations":["The statute supplies a range and other remedies.","The producer does not set the statutory penalty.","The range and relationship to licensing sanctions are stated in the statute.","This is a power of the Commissioner."],"topics":["1.1.11","1.1.12"],"review":5,"lesson":"11","domain":0,"explanation":"The range and relationship to licensing sanctions are stated in the statute."},{"id":"L11-07","prompt":"An insurer ends one of Marcus’s appointments for a business reason. Which conclusion follows from that fact alone?","options":["His Maryland license is automatically revoked.","Every insurer must immediately appoint him.","He may keep representing the terminating insurer without permission.","The appointment ended; any state-license discipline is a separate matter."],"answer":3,"explanations":["Appointment termination is not itself state revocation.","Other insurers make their own lawful appointment decisions.","He must respect the end of the insurer relationship.","The insurer relationship and state authority are different."],"topics":["1.1.10","1.1.11"],"review":3,"lesson":"11","domain":0,"explanation":"The insurer relationship and state authority are different."},{"id":"L11-08","prompt":"An independent producer has good-faith cause to believe insurance fraud has occurred. Which response matches Maryland’s reporting rule?","options":["Report the suspected fraud in writing to the Fraud Division","Wait for a conviction before ever reporting","Delete the file so it cannot cause trouble","Accuse the client publicly instead of using the required channel"],"answer":0,"explanations":["§27–802 specifies written reporting to the Fraud Division for an independent producer.","The trigger is good-faith cause to suspect fraud, not necessarily a conviction.","Destroying records is not a proper response.","A public accusation is not the required report."],"topics":["1.1.13"],"review":5,"lesson":"11","domain":0,"explanation":"§27–802 specifies written reporting to the Fraud Division for an independent producer."},{"id":"L11-09","prompt":"Who has the Maryland insurance-law enforcement role described in this lesson?","options":["The applicant’s employer in every case","The Insurance Commissioner","Any person using the title financial coach","A producer’s preferred social-media platform"],"answer":1,"explanations":["An employer does not replace the state insurance regulator.","The Commissioner enforces the Insurance Article within the statutory authority.","A marketing title does not create regulatory powers.","A platform is not Maryland’s insurance regulator."],"topics":["1.2.01"],"review":4,"lesson":"11","domain":0,"explanation":"The Commissioner enforces the Insurance Article within the statutory authority."},{"id":"L11-10","prompt":"Elena is properly licensed, but the proposed insurer lacks authority for the Maryland life business. What does her license establish?","options":["Permission to ignore the insurer’s status","A certificate of authority for that insurer","Her own producer authority, which does not cure the insurer’s lack of authority","Automatic approval of every policy form"],"answer":2,"explanations":["Her license does not override insurer requirements.","Producer and insurer authority are distinct.","Both the role and the appropriate insurer authority must be checked.","Policy-form approval is a separate regulatory matter."],"topics":["1.2.02"],"review":0,"lesson":"11","domain":0,"explanation":"Both the role and the appropriate insurer authority must be checked."}]},{"id":"12","number":12,"title":"Handle money, records and compensation","version":1,"questions":[{"id":"L12-01","prompt":"Aisha wants to use a client’s premium to pay agency rent and replace it next week. What is the correct assessment?","options":["It is permitted whenever the agency expects future income.","It is permitted if the client never notices.","Premium funds cannot be treated as an agency loan for operating expenses.","Calling the withdrawal a commission makes the entire premium available."],"answer":2,"explanations":["Expected income does not change ownership of the current funds.","Lack of discovery does not make misuse lawful.","The money must be safeguarded and handled for its authorized purpose.","Only permitted commission amounts and transfers may be made."],"topics":["1.2.06"],"review":0,"lesson":"12","domain":0,"explanation":"The money must be safeguarded and handled for its authorized purpose."},{"id":"L12-02","prompt":"How does Maryland’s premium-account regulation define prompt remittance?","options":["Any time before the next annual statement","Within five calendar months","Only after the customer files a claim","No later than the close of the fifth business day following receipt"],"answer":3,"explanations":["An annual statement is not the deadline.","Five months is not prompt remittance under this rule.","A claim is unrelated to the remittance deadline.","The regulation specifies the fifth business day following receipt."],"topics":["1.2.06"],"review":1,"lesson":"12","domain":0,"explanation":"The regulation specifies the fifth business day following receipt."},{"id":"L12-03","prompt":"If a producer does not make prompt remittance of premium money, where must that money be maintained under the rule taught here?","options":["In one or more premium accounts separate from operating and personal accounts","In the producer’s personal spending account","In a cash drawer labeled future commission","In any employee’s account until requested"],"answer":0,"explanations":["The rule requires a separate premium account for money not promptly remitted.","A personal spending account does not meet the requirement.","A label does not make an improper arrangement compliant.","An employee’s personal account is not the required premium account."],"topics":["1.2.06"],"review":1,"lesson":"12","domain":0,"explanation":"The rule requires a separate premium account for money not promptly remitted."},{"id":"L12-04","prompt":"Which statement about premium-account deposits is accurate?","options":["Every voluntary deposit by the producer is prohibited.","Specified voluntary deposits are permitted, without turning the account into an operating account.","All carriers’ funds must always be in different banks.","Any deposit permits unlimited personal withdrawals."],"answer":1,"explanations":["The regulation specifically permits voluntary deposits.","Permitted deposits do not remove the account’s restrictions.","Multiple-carrier premium accounts can be allowed subject to the stated limits.","Withdrawal purposes and minimum balances remain restricted."],"topics":["1.2.06"],"review":2,"lesson":"12","domain":0,"explanation":"Permitted deposits do not remove the account’s restrictions."},{"id":"L12-05","prompt":"A proposed withdrawal would leave the premium account below required unremitted obligations. What should happen?","options":["Make it because the bank permits the transaction.","Make it if the agency owner promises repayment.","Do not make the withdrawal that breaches the required balance.","Classify all remaining obligations as profit."],"answer":2,"explanations":["Bank processing permission is not regulatory permission.","A repayment promise does not cure the prohibited balance.","COMAR prohibits a withdrawal leaving less than the required aggregate amounts.","Obligations do not become profit by relabeling."],"topics":["1.2.06"],"review":2,"lesson":"12","domain":0,"explanation":"COMAR prohibits a withdrawal leaving less than the required aggregate amounts."},{"id":"L12-06","prompt":"An insurer pays no commissions on a placement with a $1,000 premium, and the specified placement-service fee exception applies. What is the fee ceiling under that exception?","options":["$15","$50","$100","$150"],"answer":3,"explanations":["Fifteen percent of one thousand is not fifteen.","Five percent is not the stated ceiling.","Ten percent is below, but not equal to, the stated ceiling.","One thousand multiplied by fifteen percent equals one hundred fifty."],"topics":["1.2.05"],"review":4,"lesson":"12","domain":0,"explanation":"One thousand multiplied by fifteen percent equals one hundred fifty."},{"id":"L12-07","prompt":"A former properly licensed and appointed life producer receives a renewal commission on an existing policy under the statutory exception. Which statement is accurate?","options":["This can be permitted even though the person is no longer licensed for new sales.","It automatically grants authority for new sales.","Every deferred commission is criminal without exception.","The payment appoints the former producer with every insurer."],"answer":0,"explanations":["§10–130 distinguishes permitted renewal or deferred payments from current new-sales authority.","Receiving a permitted old commission does not create an active license.","The statute contains an express exception.","An old payment does not establish new appointments."],"topics":["1.2.05"],"review":3,"lesson":"12","domain":0,"explanation":"§10–130 distinguishes permitted renewal or deferred payments from current new-sales authority."},{"id":"L12-08","prompt":"Under the Maryland annuity recommendation record rule taught here, how long must covered transaction records be retained or available?","options":["One year after the first client meeting","Seven years after the insurer completes the transaction","Only until the first commission is paid","Five business days after the application is signed"],"answer":1,"explanations":["This is not the rule’s period or trigger.","COMAR 31.09.12.10 specifies seven years after completed transaction.","Commission payment does not end retention duties.","Five business days is a different premium-remittance concept."],"topics":["1.2.04"],"review":5,"lesson":"12","domain":0,"explanation":"COMAR 31.09.12.10 specifies seven years after completed transaction."}]},{"id":"13","number":13,"title":"Recognize unfair sales practices","version":2,"questions":[{"id":"L13-01","prompt":"A producer hides a new surrender charge while urging Marcus to exchange his policy. Which practice best fits these facts?","options":["Reinsurance","Twisting","Lawful dividend distribution","Ordinary risk pooling"],"answer":1,"explanations":["No insurer-to-insurer transfer is described.","The incomplete comparison is used to induce a policy exchange.","A dividend is not the issue.","Pooling does not involve this deceptive comparison."],"topics":["1.2.11","1.2.07"],"review":0,"lesson":"13","domain":0,"explanation":"The incomplete comparison is used to induce a policy exchange."},{"id":"L13-02","prompt":"A competitor circulates a false financial-collapse story calculated to injure an insurer. Which term best fits?","options":["Conversion","Nonforfeiture","Insurance defamation","Implied authority"],"answer":2,"explanations":["No conversion right is involved.","Nonforfeiture concerns policy values.","The facts match the financial-condition and injury elements.","Agency authority does not describe the false attack."],"topics":["1.2.08"],"review":1,"lesson":"13","domain":0,"explanation":"The facts match the financial-condition and injury elements."},{"id":"L13-03","prompt":"Which offer fits the specific Maryland promotional-merchandise exception described here?","options":["A $500 gift after policy issue","A personal premium rebate for buying today","A cash refund available only after purchase","A qualifying $20 promotional notebook with no purchase condition"],"answer":3,"explanations":["The amount exceeds the stated merchandise ceiling.","The off-contract inducement is not justified by this exception.","A purchase condition fails the exception.","The merchandise cost and absence of a purchase condition fit the stated rule."],"topics":["1.2.10"],"review":2,"lesson":"13","domain":0,"explanation":"The merchandise cost and absence of a purchase condition fit the stated rule."},{"id":"L13-04","prompt":"What is the best explanation of unfair discrimination in life insurance under the general rule taught here?","options":["Unfair differences among people of the same class and equal expectation of life","Every premium difference between any two people","Any request for relevant underwriting facts","Using any actuarial information whatsoever"],"answer":0,"explanations":["This is the statutory comparison; specific protections also apply.","Lawful risk differences can support different treatment.","Relevant fact gathering is not itself unfair discrimination.","The law does not prohibit all actuarial information."],"topics":["1.2.10"],"review":3,"lesson":"13","domain":0,"explanation":"This is the statutory comparison; specific protections also apply."},{"id":"L13-05","prompt":"A lender requires a borrower to buy protection through one designated producer as a condition of a loan. What is the concern?","options":["The borrower has too much freedom of choice.","The condition can violate Maryland’s prohibition on forcing a particular insurance seller.","All insurance connected with any loan is automatically prohibited.","The producer becomes the Insurance Commissioner."],"answer":1,"explanations":["The condition restricts the protected choice.","§27–214 distinguishes required protection from coercing the seller.","The law does not support this blanket statement.","The transaction creates no regulatory office."],"topics":["1.2.09"],"review":4,"lesson":"13","domain":0,"explanation":"§27–214 distinguishes required protection from coercing the seller."},{"id":"L13-06","prompt":"An unlicensed employee actively recommends policy terms but calls the resulting payment a referral fee. What controls the analysis?","options":["The referral label alone, regardless of what the employee did","Whether the fee is a flat amount rather than a percentage","The actual sales activity and applicable licensing and payment rules","Whether a licensed producer was available elsewhere in the office"],"answer":2,"explanations":["A label cannot override the actual sales conduct.","A flat fee does not authorize unlicensed policy recommendations.","The activity determines which authority and compensation requirements apply.","Another producer’s presence does not license the employee’s conduct."],"topics":["1.2.11","1.2.04"],"review":5,"lesson":"13","domain":0,"explanation":"The activity determines which authority and compensation requirements apply."},{"id":"L13-07","prompt":"A client is asked to sign a blank application to save time. What should the producer do?","options":["Fill in invented answers after the signature","Ask a colleague to sign for the client","Leave all material answers blank permanently","Complete accurate answers and obtain the required review and signatures"],"answer":3,"explanations":["Inventing facts creates serious accuracy and fraud concerns.","Unauthorized signing is not an acceptable shortcut.","A permanently incomplete application does not solve the problem.","The proper process establishes truthful information and informed signatures."],"topics":["1.2.11"],"review":5,"lesson":"13","domain":0,"explanation":"The proper process establishes truthful information and informed signatures."},{"id":"L13-08","prompt":"A producer changes an insurer’s financial record to hide a liability from an authorized examiner. Which description is most accurate?","options":["Deceptive financial recordkeeping prohibited by the financial-statement rule","A permitted promotional exception","A normal beneficiary change","An automatic premium loan"],"answer":0,"explanations":["The false record is intended to deceive an examiner.","Promotional rules do not authorize falsifying records.","No beneficiary designation is involved.","A policy loan is not the issue."],"topics":["1.2.08"],"review":1,"lesson":"13","domain":0,"explanation":"The false record is intended to deceive an examiner."}]},{"id":"14","number":14,"title":"Clear presentations and private information","version":2,"questions":[{"id":"L14-01","prompt":"An advertisement describes projected life-policy dividends as guaranteed savings-account interest. What needs correction?","options":["Remove savings account but keep describing the dividends as guaranteed","Add the insurer’s financial rating while keeping both descriptions","Correct the misleading product and guarantee descriptions","Keep the wording if the applicant acknowledges reading it"],"answer":2,"explanations":["Changing the product label alone leaves the false dividend guarantee.","A financial rating does not guarantee illustrated dividends.","Both the product and nonguaranteed values must be described accurately.","Acknowledgment does not make the misleading claim accurate."],"topics":["1.2.07","1.2.08","3.8.01"],"review":0,"lesson":"14","domain":0,"explanation":"Both the product and nonguaranteed values must be described accurately."},{"id":"L14-02","prompt":"Which statement correctly describes nonguaranteed values in a life illustration?","options":["They become contract guarantees merely because the insurer issued the illustration.","They cannot ever decline.","They eliminate all future premium obligations.","Their assumptions can change and actual results may be higher or lower."],"answer":3,"explanations":["The illustration must distinguish guaranteed from nonguaranteed elements.","Illustrated nonguaranteed results are not certain.","Future premiums or charges may remain necessary.","The uncertainty must be explained and properly labeled."],"topics":["3.8.03","3.8.05"],"review":1,"lesson":"14","domain":2,"explanation":"The uncertainty must be explained and properly labeled."},{"id":"L14-03","prompt":"An insurer issues a life policy on terms different from the application illustration. What is the appropriate illustration response?","options":["Provide a revised illustration matching the issued policy, with required signatures and copies by delivery","Keep the old version because it looks better","Remove every guaranteed value","Ask the client to sign an empty illustration page"],"answer":0,"explanations":["The revised version must conform to the actual issued policy.","The old version may misrepresent the issued terms.","Required guarantees must still be disclosed.","An empty signature page does not satisfy the presentation requirements."],"topics":["3.8.03"],"review":2,"lesson":"14","domain":2,"explanation":"The revised version must conform to the actual issued policy."},{"id":"L14-04","prompt":"Which document is primarily general consumer guidance about understanding and comparing life insurance?","options":["A particular policy’s beneficiary form","The buyer’s guide","A producer’s commission statement","A medical laboratory report"],"answer":1,"explanations":["A beneficiary form designates recipients.","The guide provides general consumer education.","A commission statement describes compensation.","A lab report is underwriting information."],"topics":["3.8.04"],"review":3,"lesson":"14","domain":2,"explanation":"The guide provides general consumer education."},{"id":"L14-05","prompt":"When may the buyer’s guide be provided with the policy instead of before acceptance of the initial premium under the exception taught here?","options":["Whenever the producer is busy","Only if the applicant is an insurer employee","When the policy has an unconditional refund provision of at least 10 days","Whenever the premium exceeds $1,000"],"answer":2,"explanations":["Convenience is not the exception.","Employment is not the stated trigger.","COMAR 31.15.03.05 provides this delivery exception.","The premium amount is not the stated trigger."],"topics":["3.8.04"],"review":3,"lesson":"14","domain":2,"explanation":"COMAR 31.15.03.05 provides this delivery exception."},{"id":"L14-06","prompt":"For a disclosure governed by the nonaffiliated-third-party opt-out rule, which set of facts supports proceeding?","options":["No notice and no opportunity to object","The producer assumes silence before giving any notice","The client explicitly opted out","Required notices, a reasonable opportunity, and no opt-out by the consumer"],"answer":3,"explanations":["The required notice process is missing.","Silence before notice is not the specified process.","The consumer’s direction must be respected.","These are the core conditions, subject to the actual rule and exceptions."],"topics":["1.2.12","3.8.07","3.8.09"],"review":4,"lesson":"14","domain":0,"explanation":"These are the core conditions, subject to the actual rule and exceptions."},{"id":"L14-07","prompt":"Which facts fit the current-customer annual privacy notice exception described in the lesson?","options":["Only specified permitted disclosures are made and previously disclosed policies and practices have not changed","Only the absence of new claims, even if information-sharing practices changed","Only delivering an initial notice years ago, without checking present disclosures","Only describing every information recipient as a trusted service provider"],"answer":0,"explanations":["Both conditions are required for the stated annual-notice exception.","Claim activity does not establish the disclosure and unchanged-practice conditions.","An old initial notice does not itself establish the current exception.","A label for recipients does not establish permitted disclosures or unchanged practices."],"topics":["1.2.12"],"review":5,"lesson":"14","domain":0,"explanation":"Both conditions are required for the stated annual-notice exception."},{"id":"L14-08","prompt":"A life producer has medical information for an authorized underwriting task. Which action best respects the privacy limits taught here?","options":["Post the diagnosis to an unrelated marketing group","Use the approved underwriting channel for the actual permitted purpose","Treat every possible disclosure as automatically authorized","Sell the medical details because the applicant requested a quote"],"answer":1,"explanations":["That is not the underwriting purpose.","The information should follow the applicable authorized process.","The listed exception does not eliminate all other limits.","Requesting a quote is not blanket marketing permission."],"topics":["1.2.12","3.8.07"],"review":5,"lesson":"14","domain":0,"explanation":"The information should follow the applicable authorized process."}]},{"id":"15","number":15,"title":"Replace coverage with full information","version":1,"questions":[{"id":"L15-01","prompt":"Marcus buys a new life policy and reduces the old one to paid-up coverage because of that purchase. What is the correct starting point?","options":["No replacement is possible unless every old benefit is canceled.","The new policy automatically qualifies as a tax-free exchange.","The linked reduction can meet Maryland’s replacement definition.","The old insurer becomes the new beneficiary automatically."],"answer":2,"explanations":["The definition includes specified reductions and changes.","Tax treatment needs separate requirements.","A replacement can occur without total cancellation.","No such automatic beneficiary change follows."],"topics":["1.3.01","3.8.06"],"review":0,"lesson":"15","domain":0,"explanation":"A replacement can occur without total cancellation."},{"id":"L15-02","prompt":"Aisha borrows from old life-policy values to pay a new life premium. What is this called under the replacement rules?","options":["A beneficiary settlement option","An insurer’s reinsurance treaty","A policyholder dividend guarantee","A financed purchase"],"answer":3,"explanations":["The transaction funds new coverage rather than paying a beneficiary.","No insurer-to-insurer risk transfer is described.","A loan does not guarantee a dividend.","Use of existing life values to fund the new premium fits financed purchase."],"topics":["1.3.01"],"review":1,"lesson":"15","domain":0,"explanation":"Use of existing life values to fund the new premium fits financed purchase."},{"id":"L15-03","prompt":"For an applicant with existing coverage in a covered transaction, when must the producer present the replacement notice?","options":["No later than taking the application","Only after the first death claim","Whenever the old insurer happens to request it","After the new policy’s return period expires"],"answer":0,"explanations":["The producer’s notice duty occurs by application.","The duty arises much earlier than a claim.","It is an affirmative producer duty.","That would be too late for the required process."],"topics":["1.3.01","3.8.06"],"review":2,"lesson":"15","domain":0,"explanation":"The producer’s notice duty occurs by application."},{"id":"L15-04","prompt":"The applicant declines to have the replacement notice read aloud. Which statement is correct?","options":["The entire notice requirement disappears.","The notice must still be presented, properly acknowledged and left with the applicant.","The producer signs the applicant’s name.","The insurer may ignore the existing coverage."],"answer":1,"explanations":["Declining reading is not declining all notice duties.","The rule permits declining the reading while retaining the other requirements.","Unauthorized signing is not permitted.","Existing coverage remains relevant."],"topics":["1.3.01"],"review":2,"lesson":"15","domain":0,"explanation":"The rule permits declining the reading while retaining the other requirements."},{"id":"L15-05","prompt":"A replacing insurer’s home office receives the specified completed application identifying a replacement. What is the notification period for another affected existing insurer?","options":["30 calendar months","One year","5 business days","Only at the next market-conduct examination"],"answer":2,"explanations":["This is not the rule’s period.","One year is not the notification period.","COMAR 31.09.05.06 uses five business days from the applicable event.","Examination timing relates to certain records, not this notice."],"topics":["1.3.01"],"review":3,"lesson":"15","domain":0,"explanation":"COMAR 31.09.05.06 uses five business days from the applicable event."},{"id":"L15-06","prompt":"How long after delivery is the covered replacement return period taught here?","options":["5 business days","10 calendar days","15 months","30 days"],"answer":3,"explanations":["Five business days applies to certain insurer communications.","Ten days is a different disclosure exception.","Fifteen months concerns Maryland temporary licenses.","The replacement return right runs thirty days after delivery."],"topics":["1.3.01"],"review":4,"lesson":"15","domain":0,"explanation":"The replacement return right runs thirty days after delivery."},{"id":"L15-07","prompt":"For a variable contract returned under the replacement rule, which description is accurate?","options":["The rule uses cash surrender value plus specified fees and charges, so do not promise automatic reversal of market losses.","Every investment loss is guaranteed to be erased.","Only the producer’s commission is returned.","No refund formula exists."],"answer":0,"explanations":["The regulation distinguishes variable contracts from the ordinary full-premium refund.","That promise does not follow from the stated formula.","The formula is broader and different.","The regulation expressly provides the calculation."],"topics":["1.3.01"],"review":4,"lesson":"15","domain":0,"explanation":"The regulation distinguishes variable contracts from the ordinary full-premium refund."},{"id":"L15-08","prompt":"Which is the best next step before surrendering old coverage for a proposed new policy?","options":["Assume the application proves the new coverage is effective.","Verify coverage conditions and compare the material costs, guarantees and rights of both contracts.","Compare only the most favorable illustrated value.","Ignore existing loans because both contracts are life insurance."],"answer":1,"explanations":["Application and effective coverage are different.","An informed comparison considers the actual transaction and coverage status.","One projected value is not a complete comparison.","Loans can materially affect values and benefits."],"topics":["3.8.06","1.3.01"],"review":5,"lesson":"15","domain":2,"explanation":"An informed comparison considers the actual transaction and coverage status."}]},{"id":"16","number":16,"title":"Maryland group life rights","version":1,"questions":[{"id":"L16-01","prompt":"In the employer-group example, who generally holds the master life policy?","options":["Each beneficiary separately","The employer or qualifying trustees","The employee’s personal physician","Every employee jointly as an insurer"],"answer":1,"explanations":["A beneficiary receives benefits rather than holding the employer’s master policy.","The employer or eligible trustees are the group policyholder.","The physician is not the group policyholder.","Employees do not become insurers by enrolling."],"topics":["1.3.02"],"review":0,"lesson":"16","domain":0,"explanation":"The employer or eligible trustees are the group policyholder."},{"id":"L16-02","prompt":"A group life plan requires employees to pay part of the premium. Which label fits?","options":["Noncontributory","Paid-up additions","Contributory","Reinsurance"],"answer":2,"explanations":["Noncontributory means no employee premium contribution.","Paid-up additions are a different life-policy concept.","Employee contributions make this a contributory plan.","Reinsurance is between insurers."],"topics":["1.3.02"],"review":1,"lesson":"16","domain":0,"explanation":"Employee contributions make this a contributory plan."},{"id":"L16-03","prompt":"An employee has $40,000 of life coverage under the covered Maryland group arrangement. What limit applies to a covered dependent’s amount under §17–209?","options":["It must be exactly $100,000.","It must always be twice the employee amount.","There is no limit connected to the employee amount.","It may not exceed the employee’s $40,000 amount."],"answer":3,"explanations":["The statute does not create that required amount.","Twice the employee amount exceeds the stated limit.","The statute expressly links the limit to the employee amount.","Dependent coverage cannot exceed the employee or member coverage."],"topics":["1.3.02"],"review":1,"lesson":"16","domain":0,"explanation":"Dependent coverage cannot exceed the employee or member coverage."},{"id":"L16-04","prompt":"Marcus’s qualifying employment termination ends his group life insurance. Which statement describes the ordinary conversion right?","options":["Apply and pay the first premium within 31 days, subject to notice extensions, without new evidence of insurability","Wait five years after leaving before applying","Keep the group premium guaranteed forever","Convert only to term insurance"],"answer":0,"explanations":["This states the core deadline and underwriting protection.","Five years is not the waiting period for this conversion.","The individual premium follows the statutory rating conditions.","The ordinary statutory conversion form excludes term."],"topics":["1.3.03"],"review":2,"lesson":"16","domain":0,"explanation":"This states the core deadline and underwriting protection."},{"id":"L16-05","prompt":"An employee loses $80,000 of group life and is eligible for $30,000 under another group policy within 31 days. Using only the amount rule taught here, what is the maximum conversion amount?","options":["$110,000","$50,000","$30,000","$80,000 regardless of new eligibility"],"answer":1,"explanations":["The rule subtracts qualifying new group protection.","Eighty thousand minus thirty thousand equals fifty thousand.","That is the new-group amount, not the remaining conversion maximum.","The specified offset must be applied."],"topics":["1.3.03"],"review":3,"lesson":"16","domain":0,"explanation":"Eighty thousand minus thirty thousand equals fifty thousand."},{"id":"L16-06","prompt":"An insured dies while entitled to the statutory conversion but before the individual policy is effective and before applying. What does §17–311 provide?","options":["No benefit can ever be due.","Only the employer’s premium is returned.","The amount available for conversion is payable as a group-policy claim.","The family must pass a medical examination."],"answer":2,"explanations":["The statute specifically protects this situation.","It addresses the conversion amount, not just a premium return.","The application and first premium need not already have been made.","A family medical exam is not the stated condition."],"topics":["1.3.03"],"review":3,"lesson":"16","domain":0,"explanation":"The application and first premium need not already have been made."},{"id":"L16-07","prompt":"The entire group policy ends after an employee has been insured for six years. Which statement fits the separate group-termination provision?","options":["The employee must prove insurability in every case.","The rule guarantees unlimited replacement coverage.","Only one day of prior insurance is required under this provision.","The policy may cap conversion at the lesser of the adjusted lost coverage or $10,000."],"answer":3,"explanations":["The provision incorporates the statutory conversion conditions.","The statute permits a specific amount limit.","The stated eligibility condition is at least five years.","This is the permitted cap for the described group-policy or class termination."],"topics":["1.3.03"],"review":4,"lesson":"16","domain":0,"explanation":"This is the permitted cap for the described group-policy or class termination."},{"id":"L16-08","prompt":"Under a valid arrangement, an insured assigns the group-life right to name a beneficiary. Who receives that assigned right?","options":["The assignee, according to the terms of the assignment","Every coworker equally","The state automatically","No one, because group rights can never be assigned"],"answer":0,"explanations":["§17–104 allows the specified rights to vest in the assignee.","Coworkers do not receive rights merely from group membership.","The state does not automatically become the assignee.","Maryland expressly permits qualifying assignments."],"topics":["1.3.04"],"review":5,"lesson":"16","domain":0,"explanation":"§17–104 allows the specified rights to vest in the assignee."}]},{"id":"17","number":17,"title":"Claims and the insurer safety net","version":1,"questions":[{"id":"L17-01","prompt":"An insurer denies a life claim solely because it wants to reduce this month’s payouts, despite the available claim facts. Which principle is most directly implicated?","options":["The producer’s appointment register","The prohibition on an arbitrary or capricious claim refusal","The beneficiary’s conversion right","The policyowner’s dividend option"],"answer":1,"explanations":["Appointments concern producer authority rather than this claim reason.","A refusal must not be arbitrary or capricious in light of available information.","Conversion concerns changing eligible coverage, not this denial.","Dividend selection does not justify arbitrary refusal."],"topics":["1.2.02"],"review":1,"lesson":"17","domain":0,"explanation":"A refusal must not be arbitrary or capricious in light of available information."},{"id":"L17-02","prompt":"A reviewer sees one act prohibited by §27–303 but has not established a general business practice under §27–304. What follows?","options":["The act is automatically permitted.","The insurer must first repeat it on 100 claims.","The individual prohibition can still apply on its own terms.","Only a policy cancellation can be reviewed."],"answer":2,"explanations":["The separate provision does not require that conclusion.","This invents a threshold for the individual prohibition.","The sections have different requirements; a missing pattern does not erase §27–303.","Unfair claim practices are not limited to cancellations."],"topics":["1.2.02"],"review":1,"lesson":"17","domain":0,"explanation":"The sections have different requirements; a missing pattern does not erase §27–303."},{"id":"L17-03","prompt":"Proof of death is submitted 200 days after death, and the covered Maryland life claim is paid 20 days after proof. Under the stated interest rule, when does interest begin?","options":["At policy issue","At the end of the grace period","Thirty days after proof","When proof of death is submitted"],"answer":3,"explanations":["Issue is not the claim-interest trigger.","Premium grace is a different issue.","The late-proof rule does not add this waiting period.","Proof received after 180 days moves the interest start to submission."],"topics":["5.1.12"],"review":2,"lesson":"17","domain":4,"explanation":"Proof received after 180 days moves the interest start to submission."},{"id":"L17-04","prompt":"What best describes Maryland’s Life and Health Insurance Guaranty Corporation?","options":["A private nonprofit nonstock corporation funded through member-insurer assessments","A state department guaranteeing every insurance investment","A producer association that approves all claims","An insurer rating agency financed by beneficiaries"],"answer":0,"explanations":["This describes its legal structure and core funding mechanism.","It is not a state department and has limits.","It is not a producer association or universal claim reviewer.","Its statutory role differs from ratings."],"topics":["1.3.05","2.2.09"],"review":3,"lesson":"17","domain":0,"explanation":"This describes its legal structure and core funding mechanism."},{"id":"L17-05","prompt":"Assume two otherwise covered life policies on the same life at the failed insurer have total death obligations of $500,000, with no other adjustments. Which is the Maryland life death-benefit ceiling taught here?","options":["$100,000","$300,000","$500,000","$600,000"],"answer":1,"explanations":["This is the life net cash-value sublimit.","The one-life death-benefit ceiling is $300,000 regardless of policy count.","The contractual total exceeds the stated ceiling.","Two policies do not double the ceiling."],"topics":["1.3.05"],"review":4,"lesson":"17","domain":0,"explanation":"The one-life death-benefit ceiling is $300,000 regardless of policy count."},{"id":"L17-06","prompt":"Which obligation is excluded under the rule covering nonguaranteed portions and owner-borne risk?","options":["An otherwise eligible contractual general-account guarantee within limits","An otherwise covered death obligation within limits","The owner’s separate-account investment loss","An eligible covered obligation transferred to a solvent insurer"],"answer":2,"explanations":["A qualifying guarantee is distinct from owner-borne market risk.","A covered death obligation is not excluded simply because it is a claim.","The owner-borne investment risk is outside this protection.","A transfer is one way eligible obligations may be continued."],"topics":["1.3.05"],"review":4,"lesson":"17","domain":0,"explanation":"The owner-borne investment risk is outside this protection."},{"id":"L17-07","prompt":"A delivered contract exceeds the applicable guaranty limits. Which producer action fits the Maryland distinction taught here?","options":["Use the corporation’s name to promise risk-free returns.","Say the State owes every unpaid policy dollar.","Omit the notice because the policy is approved.","Provide the required separate notice without using protection as a sales inducement."],"answer":3,"explanations":["Using protection to sell insurance is prohibited.","The corporation’s debts are not state debts.","Form approval does not remove the separate notice requirement.","The notice duty and the sales-use prohibition must both be observed."],"topics":["1.3.05","3.8.02"],"review":5,"lesson":"17","domain":0,"explanation":"The notice duty and the sales-use prohibition must both be observed."},{"id":"L17-08","prompt":"An insurer uses an approved life policy form. A producer wants to add a new promised benefit orally. What is the sound conclusion?","options":["Form approval does not authorize the producer to rewrite the policy’s benefit.","Approval gives every producer unlimited contracting authority.","An oral sales promise always expands guaranty coverage.","The insurer’s form approval is replaced by the applicant’s signature."],"answer":0,"explanations":["The actual approved contract and authority govern the benefit.","Producer authority remains limited.","Guaranty coverage does not generally include extra-contractual marketing claims.","Signing an application does not replace the form-review process."],"topics":["1.2.02"],"review":0,"lesson":"17","domain":0,"explanation":"The actual approved contract and authority govern the benefit."}]},{"id":"18","number":18,"title":"Who owns it, whose life, who benefits?","version":1,"questions":[{"id":"L18-01","prompt":"Aisha owns a policy on Marcus. Daniel pays its premiums, and Elena is the beneficiary. Whose life is insured?","options":["Aisha’s","Daniel’s","Marcus’s","Elena’s"],"answer":2,"explanations":["Aisha is the stated owner.","Premium payment does not identify the insured.","Marcus is the person whose life the facts say is covered.","Elena is the stated benefit recipient."],"topics":["3.1.03"],"review":0,"lesson":"18","domain":2,"explanation":"Marcus is the person whose life the facts say is covered."},{"id":"L18-02","prompt":"Daniel pays premiums on a policy owned by Aisha. What does that payment alone establish?","options":["Daniel has an unrestricted right to change the beneficiary.","Daniel is automatically the insured.","Daniel owns the policy’s cash value.","Daniel is the premium payer."],"answer":3,"explanations":["Ownership rights do not arise solely from payment.","The insured must be identified separately.","The stated owner and contract govern policy rights.","This is the role established by the payment fact."],"topics":["5.1.01","3.1.03"],"review":0,"lesson":"18","domain":4,"explanation":"This is the role established by the payment fact."},{"id":"L18-03","prompt":"Marcus, with competent legal capacity, genuinely obtains insurance on his own life. Under Maryland’s own-life rule, for whose benefit may he obtain it?","options":["Any person, subject to the contract and applicable law","Only a person who is owed an existing debt","Only a blood relative","Only his estate"],"answer":0,"explanations":["§12–201 expressly permits an own-life purchase for any person’s benefit.","The rule is not restricted to creditors.","The own-life rule is broader than this.","The estate is one possible choice, not the only choice."],"topics":["3.1.03"],"review":1,"lesson":"18","domain":2,"explanation":"§12–201 expressly permits an own-life purchase for any person’s benefit."},{"id":"L18-04","prompt":"Elena seeks coverage on her spouse based on their close family relationship. Which interest does Maryland recognize?","options":["Only the amount of a written loan","A substantial interest engendered by love and affection","Only the spouse’s current salary","Only a business buy-sell obligation"],"answer":1,"explanations":["Close-family interest does not require a loan.","This is the statutory close blood-or-law family category.","Salary is not the only basis for this family interest.","Buy-sell interest is a separate category."],"topics":["3.1.01"],"review":2,"lesson":"18","domain":2,"explanation":"This is the statutory close blood-or-law family category."},{"id":"L18-05","prompt":"Which fact best supports a lawful economic insurable interest in Daniel’s continued life?","options":["A stranger expects a profit only when Daniel dies.","An investor has no relationship with Daniel but likes the death benefit.","A business would suffer a substantial lawful economic loss if its key employee Daniel died.","A producer expects a commission from any policy application."],"answer":2,"explanations":["A death-created wagering interest is not the required interest.","Wanting the benefit alone does not qualify.","This identifies a substantial economic interest in continued life.","A sales commission is not the client’s insurable interest in Daniel."],"topics":["3.1.01"],"review":3,"lesson":"18","domain":2,"explanation":"This identifies a substantial economic interest in continued life."},{"id":"L18-06","prompt":"For the stated general rule when one person procures coverage on another for an interested beneficiary, when must the qualifying insurable interest exist?","options":["Only when the first claim form is signed","Only after the insured dies","At every premium anniversary without exception","When the insurance contract is made"],"answer":3,"explanations":["Claim paperwork is not the statutory timing.","The test is not postponed until death.","This invents a recurring universal test.","§12–201 identifies contract formation as the relevant time."],"topics":["3.1.02"],"review":4,"lesson":"18","domain":2,"explanation":"§12–201 identifies contract formation as the relevant time."},{"id":"L18-07","prompt":"A producer confirms insurable interest in an ordinary individual-life application. What should happen next concerning consent?","options":["Apply the consent rule and any specific exception to the actual facts.","Assume interest automatically eliminates every consent requirement.","Assume every group and individual contract has the identical consent rule.","Let the producer sign the insured’s name if the premium is paid."],"answer":0,"explanations":["Interest and consent are separate checkpoints under Maryland law.","Insurable interest does not erase the separate statute.","Group life is outside the cited subsection and specific exceptions exist.","Payment does not authorize forgery."],"topics":["3.1.03"],"review":5,"lesson":"18","domain":2,"explanation":"Interest and consent are separate checkpoints under Maryland law."},{"id":"L18-08","prompt":"An unrelated investor causes a stranger’s life policy to be procured for the investor’s profit and relies only on the stranger’s signature to call it an own-life purchase. Which issue needs examination?","options":["Whether every beneficiary must be a sibling","Who actually procured the coverage and whether the transaction satisfies insurable-interest law","Whether a signed application guarantees claim payment","Whether premiums are always paid by beneficiaries"],"answer":1,"explanations":["The own-life rule is not limited to siblings.","The substance of procurement matters; a label or signature does not resolve a wagering scheme.","Signing alone does not guarantee every claim.","The payer is a separate role and need not be the beneficiary."],"topics":["3.1.01","3.1.03"],"review":1,"lesson":"18","domain":2,"explanation":"The substance of procurement matters; a label or signature does not resolve a wagering scheme."}]},{"id":"19","number":19,"title":"Build a protection plan from real needs","version":1,"questions":[{"id":"L19-01","prompt":"Which approach starts with the financial value of future earnings or household contributions?","options":["The human-life-value approach","The policy-loan method","The current cash-surrender calculation","The insurer’s premium-mode calculation"],"answer":0,"explanations":["This approach values future economic contributions.","Borrowing does not define the exposure-estimation method.","Current surrender value is a policy value, not future human earnings.","Payment mode concerns premium frequency."],"topics":["3.4.01"],"review":1,"lesson":"19","domain":2,"explanation":"This approach values future economic contributions."},{"id":"L19-02","prompt":"A family lists specific survivor obligations and subtracts resources available to meet them. Which approach is it using?","options":["A financial-strength rating","Needs-based analysis","A viatical settlement valuation","A dividend illustration"],"answer":1,"explanations":["A rating evaluates an insurer, not this household gap.","This is the needs approach.","A settlement concerns selling an existing policy.","Dividends do not determine the complete survivor-needs calculation."],"topics":["3.4.02"],"review":1,"lesson":"19","domain":2,"explanation":"This is the needs approach."},{"id":"L19-03","prompt":"Using only the stated simplified assumptions, what is $3,000 per month of income support for ten years, with no interest or inflation?","options":["$30,000","$36,000","$360,000","$3,600,000"],"answer":2,"explanations":["This omits twelve months in each year.","That covers one year rather than ten.","Three thousand times twelve times ten equals $360,000.","This overstates the multiplication by a factor of ten."],"topics":["3.4.05"],"review":2,"lesson":"19","domain":2,"explanation":"Three thousand times twelve times ten equals $360,000."},{"id":"L19-04","prompt":"The stated lump-sum needs are $220,000 and income need is $360,000. Available savings are $80,000 and existing coverage is $100,000. What is the simplified remaining gap?","options":["$180,000","$580,000","$760,000","$400,000"],"answer":3,"explanations":["That is the resource total rather than the gap.","This is the total before subtracting resources.","This incorrectly adds resources to needs.","The $580,000 total less $180,000 resources leaves $400,000."],"topics":["3.4.02","3.4.04"],"review":3,"lesson":"19","domain":2,"explanation":"The $580,000 total less $180,000 resources leaves $400,000."},{"id":"L19-05","prompt":"The estimate already includes paying the mortgage off at death. What should the agent check in the ongoing monthly income need?","options":["That the same future mortgage payments are not counted again","That all mortgage payments are added a second time","That childcare is always excluded","That no savings can ever be considered"],"answer":0,"explanations":["This avoids counting the same obligation twice.","That duplicates the same need.","Childcare can create a legitimate separate cost.","Truly available savings may be relevant resources."],"topics":["3.2.06","3.4.03"],"review":2,"lesson":"19","domain":2,"explanation":"This avoids counting the same obligation twice."},{"id":"L19-06","prompt":"A family owns a valuable business but needs cash for estate obligations and wants to avoid a forced sale. Which pair of purposes best fits?","options":["Premium mode and underwriting classification","Liquidity and estate conservation","Reinsurance and retrocession","Cash dividends and automatic premium loans"],"answer":1,"explanations":["Those concepts do not describe the stated estate problem.","Ready funds can meet obligations while helping preserve assets.","Those are insurer risk-transfer transactions.","These are particular policy mechanisms, not the best description of the objective."],"topics":["3.2.02","3.2.04","3.2.05"],"review":4,"lesson":"19","domain":2,"explanation":"Ready funds can meet obligations while helping preserve assets."},{"id":"L19-07","prompt":"Which statement accurately distinguishes cash accumulation from the death benefit?","options":["Every term policy has immediately available cash equal to its face amount.","Accumulated values always bypass policy charges.","Some permanent policies develop values during life subject to their terms; this is a different feature from the death payment.","Cash accumulation makes premium affordability irrelevant."],"answer":2,"explanations":["Term generally does not build cash value, and face amount is not immediate cash.","Contract charges and conditions can apply.","This separates the two uses without promising universal access.","Funding and affordability still matter."],"topics":["3.2.03"],"review":4,"lesson":"19","domain":2,"explanation":"This separates the two uses without promising universal access."},{"id":"L19-08","prompt":"Which fact most strongly calls for checking a possible Social Security survivor income gap?","options":["The family has an annual policy review.","The policyowner pays premiums monthly.","The insurer is formed in another state.","A spouse’s caregiving eligibility may end before age-based survivor eligibility begins."],"answer":3,"explanations":["An annual review is useful but does not itself establish that gap.","Premium frequency does not determine SSA eligibility.","Insurer domicile does not determine these federal benefits.","Different eligibility periods can leave a period without that spouse benefit."],"topics":["3.4.06","3.2.01"],"review":5,"lesson":"19","domain":2,"explanation":"Different eligibility periods can leave a period without that spouse benefit."}]},{"id":"20","number":20,"title":"Selling a life policy: settlements","version":1,"questions":[{"id":"L20-01","prompt":"Daniel receives money from a third party in exchange for rights to his life policy. Which transaction does this describe most directly?","options":["A policy surrender to the original insurer","A settlement transferring policy rights","An automatic premium loan","A dividend left at interest"],"answer":1,"explanations":["Surrender is a transaction with the insurer ending the policy for its surrender value.","The transfer to a third party is the defining feature here.","An automatic premium loan pays a premium under the policy provision.","An interest-accumulated dividend does not itself transfer ownership."],"topics":["3.3.01"],"review":0,"lesson":"20","domain":2,"explanation":"The transfer to a third party is the defining feature here."},{"id":"L20-02","prompt":"In a Maryland settlement, whom does the broker represent under the statutory fiduciary rule?","options":["The provider whenever it pays compensation","The later purchaser of the policy","Only the viator","The original insurer in every case"],"answer":2,"explanations":["Payment source does not change the statutory duty.","The later purchaser is a separate party.","The broker represents only the viator and owes the stated fiduciary duty.","The original insurer is not automatically the broker’s statutory client."],"topics":["3.3.08"],"review":1,"lesson":"20","domain":2,"explanation":"The broker represents only the viator and owes the stated fiduciary duty."},{"id":"L20-03","prompt":"Which statement about broker authority is accurate under the Maryland definition taught here?","options":["A property-only license is enough for compensated life-settlement brokering.","Every unlicensed employee may negotiate if called a referral agent.","Registration eliminates the life-producer qualification.","The broker needs the required life-producer authority and applicable registration, subject to stated professional exceptions."],"answer":3,"explanations":["The broker definition specifies life authority.","A label does not authorize active negotiation.","Authority and registration are separate requirements.","This distinguishes the requirements and preserves the statutory exceptions."],"topics":["3.3.02"],"review":1,"lesson":"20","domain":2,"explanation":"This distinguishes the requirements and preserves the statutory exceptions."},{"id":"L20-04","prompt":"Which fact meets the stated Maryland settlement definition of terminal illness?","options":["An illness reasonably expected to cause death in 24 months or less","Any diagnosis regardless of prognosis","A preference to sell an older policy","An inability to afford the next premium"],"answer":0,"explanations":["This is the statutory time-and-illness definition.","A diagnosis alone does not state the required prognosis.","A sale preference is not a medical definition.","Premium affordability does not establish terminal illness."],"topics":["3.3.06"],"review":2,"lesson":"20","domain":2,"explanation":"This is the statutory time-and-illness definition."},{"id":"L20-05","prompt":"A broker receives an offer for the viator’s policy. What is the stated deadline to forward it to the viator?","options":["15 calendar days after proceeds arrive","Within 72 hours after the broker receives it","Only when all parties sign","Two years after policy issue"],"answer":1,"explanations":["That clock relates to rescission, not forwarding an offer.","§8–605.1 uses seventy-two hours after receipt for offers and related responses.","Waiting until signing defeats the offer-disclosure duty.","The two-year restriction concerns early-policy settlements."],"topics":["3.3.03"],"review":3,"lesson":"20","domain":2,"explanation":"§8–605.1 uses seventy-two hours after receipt for offers and related responses."},{"id":"L20-06","prompt":"Daniel receives his settlement proceeds on the stated date. Which rescission period applies under the Maryland rule taught here?","options":["Thirty-one days after policy issue","Three business days after application","Fifteen calendar days after receipt of proceeds, with the required repayments","Seventy-two hours after receiving a broker’s offer"],"answer":2,"explanations":["This combines an unrelated deadline and wrong trigger.","That is not the rescission clock.","The receipt of proceeds starts the fifteen-calendar-day period.","The offer duty is a separate rule."],"topics":["3.3.04"],"review":4,"lesson":"20","domain":2,"explanation":"The receipt of proceeds starts the fifteen-calendar-day period."},{"id":"L20-07","prompt":"Which conduct most clearly illustrates a fraudulent viatical settlement act?","options":["Correcting an accidental address typo openly","Disclosing a provider’s compensation arrangement","Requesting verification of existing coverage","Knowingly submitting a materially false prognosis to influence the settlement"],"answer":3,"explanations":["Open correction alone is not knowing material deception.","Required accurate disclosure is proper conduct.","A proper verification request is part of due diligence.","This knowingly presents material false information in the settlement process."],"topics":["3.3.05","3.3.07"],"review":5,"lesson":"20","domain":2,"explanation":"This knowingly presents material false information in the settlement process."},{"id":"L20-08","prompt":"Which statement correctly describes the Maryland settlement scope discussed here?","options":["A viator is not limited to owners of policies on terminally or chronically ill insureds.","Every settlement requires a terminal diagnosis.","A policy’s marketing label conclusively determines legal scope.","An agreement to transfer rights later is always outside the definition."],"answer":0,"explanations":["§8–605 expressly prevents that narrow limitation.","The statute is broader than terminal illness.","The transaction’s facts and statutory definitions govern.","The definition includes specified later-transfer agreements."],"topics":["3.3.01","3.3.04"],"review":0,"lesson":"20","domain":2,"explanation":"§8–605 expressly prevents that narrow limitation."}]},{"id":"21","number":21,"title":"Protect the business and its people","version":1,"questions":[{"id":"L21-01","prompt":"Which problem is a death-funded buy-sell arrangement primarily designed to address?","options":["Paying every employee’s retirement pension","Funding a purchase of the deceased owner’s business interest","Calculating the insurer’s mortality table","Replacing the family’s health coverage"],"answer":1,"explanations":["That is not the ownership-transfer purpose.","The agreement and funding coordinate the purchase.","Mortality pricing is an insurer function.","That is outside this life succession arrangement."],"topics":["3.5.01"],"review":1,"lesson":"21","domain":2,"explanation":"The agreement and funding coordinate the purchase."},{"id":"L21-02","prompt":"Elena owns a life policy on co-owner Daniel and will use its proceeds to buy his interest under their agreement. Which structure is described?","options":["Entity purchase","Executive bonus","Cross-purchase","Group conversion"],"answer":2,"explanations":["The business would own the funding policy and buy the interest.","A bonus supports an employee-owned personal policy.","One owner holds coverage on another to fund the purchase.","Conversion is a separate coverage right."],"topics":["3.5.01"],"review":2,"lesson":"21","domain":2,"explanation":"One owner holds coverage on another to fund the purchase."},{"id":"L21-03","prompt":"In the stated entity-purchase example, who owns the funding policy and receives its covered proceeds?","options":["The deceased owner’s child in every case","The surviving owner individually","The producer who wrote the agreement","The business entity"],"answer":3,"explanations":["The family may receive a purchase price but is not the stated policy beneficiary.","That describes the cross-purchase buyer instead.","The producer is not the policyowner in these facts.","The entity owns the policy, receives proceeds and makes the purchase."],"topics":["3.5.01"],"review":3,"lesson":"21","domain":2,"explanation":"The entity owns the policy, receives proceeds and makes the purchase."},{"id":"L21-04","prompt":"A company buys coverage on a specialist to fund recruitment and offset lost revenue if the specialist dies. Which purpose fits?","options":["Key-person protection","An individual mortgage-protection need","A beneficiary’s fixed-period settlement option","An executive’s personal policy bonus"],"answer":0,"explanations":["The company is protecting its own operational economic exposure.","The stated loss belongs to the company, not a household mortgage.","A payment option does not describe this insurance purpose.","The executive-bonus policy serves a different ownership and beneficiary arrangement."],"topics":["3.5.02"],"review":4,"lesson":"21","domain":2,"explanation":"The company is protecting its own operational economic exposure."},{"id":"L21-05","prompt":"An executive owns a personal life policy and the employer provides an agreed bonus to help pay for it. What does that payment alone do?","options":["Transfer all ownership rights to the employer","Provide compensation support without automatically transferring policy ownership","Make the employer the only possible beneficiary","Convert the arrangement into a qualified pension plan"],"answer":1,"explanations":["Payment alone does not establish a transfer.","The employee remains the owner in the stated arrangement.","The employer does not automatically receive beneficiary rights.","A bonus arrangement is not automatically a qualified retirement plan."],"topics":["3.5.03"],"review":5,"lesson":"21","domain":2,"explanation":"The employee remains the owner in the stated arrangement."},{"id":"L21-06","prompt":"A buy-sell agreement requires a $600,000 purchase, while the funding policy pays $500,000. What is the stated funding gap before other resources?","options":["$500,000","$1,100,000","$100,000","$0 because the policy changes the agreement"],"answer":2,"explanations":["That is the available proceeds, not the gap.","This incorrectly adds obligation and resources.","Subtract the $500,000 funding from the $600,000 obligation.","The agreement does not automatically change to match the policy."],"topics":["3.5.01"],"review":1,"lesson":"21","domain":2,"explanation":"Subtract the $500,000 funding from the $600,000 obligation."},{"id":"L21-07","prompt":"Three owners use the conventional arrangement in which each owns a separate policy on each of the other two. How many policies are involved?","options":["Two","Three","Nine","Six"],"answer":3,"explanations":["Two covers only the two-owner example.","Each of three owners needs two policies in these facts.","No owner is buying a funding policy on themself in the specified count.","Three owners times two other owners equals six."],"topics":["3.5.01"],"review":2,"lesson":"21","domain":2,"explanation":"Three owners times two other owners equals six."},{"id":"L21-08","prompt":"Which pairing accurately matches the described purpose and benefit flow?","options":["Key-person coverage: business owns the policy and receives proceeds for its financial loss","Executive bonus: employer automatically receives every death benefit","Cross-purchase: the business entity always owns all policies","Entity purchase: each owner individually buys the other’s interest"],"answer":0,"explanations":["This matches the stated key-person arrangement.","An executive-owned policy does not automatically name the employer.","The stated cross-purchase structure has owner-held policies.","This describes the cross-purchase buyer rather than the entity."],"topics":["3.5.02","3.5.03","3.5.01"],"review":5,"lesson":"21","domain":2,"explanation":"This matches the stated key-person arrangement."}]},{"id":"22","number":22,"title":"Classify coverage and understand its price","version":2,"questions":[{"id":"L22-01","prompt":"Which set of labels can consistently describe one policy?","options":["Individual, permanent and participating","Group and individual as the same master-contract arrangement","Temporary only because the owner pays monthly","Variable only because an insurer declares dividends"],"answer":0,"explanations":["These labels describe different compatible dimensions.","The arrangement facts must distinguish individual ownership from a group master contract.","Payment mode alone does not determine temporary coverage.","Dividends do not by themselves establish a variable product."],"topics":["3.6.01","3.6.02","3.6.03","3.6.04"],"review":0,"lesson":"22","domain":2,"explanation":"These labels describe different compatible dimensions."},{"id":"L22-02","prompt":"A participating policy illustration shows future dividends. What can the producer infer solely from participating status?","options":["The illustrated dividend is a contractual guarantee.","The policy may pay dividends, but participation alone does not guarantee them.","Every required premium is eliminated.","The owner necessarily invests in separate-account subaccounts."],"answer":1,"explanations":["Participation does not make the illustrated amount guaranteed.","This is the correct participation distinction.","Premium obligations remain subject to the contract.","That concerns variable design, a separate classification."],"topics":["3.6.04"],"review":1,"lesson":"22","domain":2,"explanation":"This is the correct participation distinction."},{"id":"L22-03","prompt":"Which statement best distinguishes variable life from a fixed design?","options":["Variable means the policy has no insurance component.","Fixed means no charges or funding conditions can apply.","The variable owner bears the specified investment risk, and securities requirements also apply.","A producer’s ordinary life authority alone proves all variable-product authority."],"answer":2,"explanations":["Variable life still includes life insurance.","The actual fixed contract still has conditions and charges.","This connects the risk and regulatory distinctions.","Insurance authority and securities requirements are separate."],"topics":["3.6.05","3.6.06"],"review":1,"lesson":"22","domain":2,"explanation":"This connects the risk and regulatory distinctions."},{"id":"L22-04","prompt":"Holding other assumptions constant, higher expected mortality has what general effect on the cost of death protection?","options":["It eliminates acquisition expenses.","It guarantees policy dividends.","It automatically lowers every existing premium.","It tends to increase the expected benefit cost."],"answer":3,"explanations":["Expenses are a separate pricing factor.","Dividend guarantees do not follow from mortality assumptions.","The relationship is not an automatic contract repricing rule.","More expected death benefits increase the expected cost, other things equal."],"topics":["3.7.01"],"review":2,"lesson":"22","domain":2,"explanation":"More expected death benefits increase the expected cost, other things equal."},{"id":"L22-05","prompt":"For the same specified future benefit, what can a higher assumed interest rate do to the amount needed now, holding other assumptions constant?","options":["Reduce its present value","Make mortality irrelevant","Add an identical guaranteed dividend","Require the premium always to equal the face amount"],"answer":0,"explanations":["Higher assumed earnings reduce the present amount needed for that fixed future amount.","Mortality remains relevant to expected benefits.","The pricing assumption is not a dividend guarantee.","The relationship does not make premium equal to face amount."],"topics":["3.7.02"],"review":2,"lesson":"22","domain":2,"explanation":"Higher assumed earnings reduce the present amount needed for that fixed future amount."},{"id":"L22-06","prompt":"Which premium description includes applicable expense loading?","options":["A benefit-only net single premium","The gross premium","The death benefit face amount","The beneficiary’s settlement amount"],"answer":1,"explanations":["The simplified net premium excludes expense loading.","The gross price includes the applicable loading and other pricing provisions.","The face amount is protection, not the premium charged.","A benefit settlement is a different amount."],"topics":["3.7.03","3.7.05"],"review":4,"lesson":"22","domain":2,"explanation":"The gross price includes the applicable loading and other pricing provisions."},{"id":"L22-07","prompt":"Using the stated one-year example, what is the expected $100,000 death benefit cost at mortality 0.002, before discounting and expenses?","options":["$20","$2,000","$200","$100,000"],"answer":2,"explanations":["This understates the multiplication by a factor of ten.","This overstates the multiplication by a factor of ten.","0.002 multiplied by $100,000 equals $200.","The full benefit is not the probability-weighted expected cost."],"topics":["3.7.01","3.7.04"],"review":3,"lesson":"22","domain":2,"explanation":"0.002 multiplied by $100,000 equals $200."},{"id":"L22-08","prompt":"Discount the stated $200 year-end expected benefit for one year at 5%. Which amount is the approximate net single premium in this simplified example?","options":["$210.00","$200.00","$195.00","$190.48"],"answer":3,"explanations":["This compounds forward instead of discounting.","This omits discounting.","Subtracting five dollars is not the stated present-value calculation.","$200 divided by 1.05 is approximately $190.48."],"topics":["3.7.02","3.7.04"],"review":3,"lesson":"22","domain":2,"explanation":"$200 divided by 1.05 is approximately $190.48."},{"id":"L22-09","prompt":"Which issue must be considered when converting a single funding amount into a level annual premium calculation?","options":["The timing and likelihood of future premium payments, as well as interest","Dividing the net single premium by the number of scheduled payments without discounting","Adding acquisition expenses while ignoring the time value of later payments","Assuming all scheduled life-contingent premiums will be paid regardless of death"],"answer":0,"explanations":["A future premium stream has timing and mortality-related payment conditions.","A simple division omits present value and payment-contingency factors.","Expenses matter to gross pricing but do not replace premium-stream valuation.","The likelihood that later payments are made must be considered."],"topics":["3.7.04","3.7.05"],"review":4,"lesson":"22","domain":2,"explanation":"A future premium stream has timing and mortality-related payment conditions."},{"id":"L22-10","prompt":"A policy costs $480 annually or $42 monthly in the stated example. How much more do twelve monthly payments cost?","options":["$12","$24","$42","$480"],"answer":1,"explanations":["The annualized difference is not twelve dollars.","Twelve times $42 is $504, which exceeds $480 by $24.","One monthly payment is not the annual cost difference.","That is the stated annual payment, not the difference."],"topics":["3.7.06"],"review":5,"lesson":"22","domain":2,"explanation":"Twelve times $42 is $504, which exceeds $480 by $24."}]},{"id":"23","number":23,"title":"Build an accurate application file","version":1,"questions":[{"id":"L23-01","prompt":"A producer records application answers and relevant observations, then submits them for the insurer’s decision. What is this activity?","options":["Home-office claim adjudication","Field underwriting","Policy reinstatement","Contract assignment"],"answer":1,"explanations":["No claim is being evaluated.","The producer gathers and communicates risk information in the field.","Reinstatement restores eligible lapsed coverage.","Assignment transfers specified rights."],"topics":["3.8.08","3.9.01"],"review":0,"lesson":"23","domain":2,"explanation":"The producer gathers and communicates risk information in the field."},{"id":"L23-02","prompt":"A signed application contains an incorrect medication date. What should the producer do?","options":["Erase the answer without keeping a record.","Leave it because all signed answers become warranties.","Use the approved correction process and obtain required acknowledgment.","Sign the applicant’s initials without permission."],"answer":2,"explanations":["A secret change undermines the accuracy and authorization of the record.","Maryland treats the statements as representations; the error should still be addressed.","This preserves a properly corrected, authorized record.","The producer may not manufacture the applicant’s acknowledgment."],"topics":["3.8.10","3.8.11"],"review":1,"lesson":"23","domain":2,"explanation":"This preserves a properly corrected, authorized record."},{"id":"L23-03","prompt":"An applicant leaves a required health question blank. What is the appropriate response before submission?","options":["Treat the blank as a no answer.","Fill it from the producer’s assumption.","Delete the question from the approved form.","Ask for the answer or clarification through the carrier’s process."],"answer":3,"explanations":["A blank does not establish a negative answer.","The applicant’s actual response is needed.","The producer cannot rewrite the approved questionnaire.","Resolve the missing information accurately."],"topics":["3.8.11"],"review":1,"lesson":"23","domain":2,"explanation":"Resolve the missing information accurately."},{"id":"L23-04","prompt":"Which statement best reflects Maryland’s treatment of life-application answers?","options":["They are representations, but fraudulent or material incorrect information can still affect recovery.","They are absolute warranties that make every typo fatal.","They are optional if the producer knows the applicant.","They cannot affect recovery unless a criminal conviction has occurred."],"answer":0,"explanations":["This preserves both the representation rule and the statutory consequences.","The statute does not treat every statement as an absolute warranty.","Personal familiarity does not replace the application requirements.","The statutory test does not require a criminal conviction."],"topics":["3.8.12"],"review":2,"lesson":"23","domain":2,"explanation":"This preserves both the representation rule and the statutory consequences."},{"id":"L23-05","prompt":"A medical consumer report is requested during underwriting. Which statement is correct?","options":["An information-practices notice removes every consent requirement.","The required permission must be obtained before the reporting agency supplies the medical report.","The producer can request it for personal curiosity.","Only a signed beneficiary change authorizes any medical report."],"answer":1,"explanations":["Notice and permission are different obligations.","The FCRA requires the applicant’s permission for this medical-information report.","The request needs an authorized insurance purpose and the required permission.","A beneficiary change is not the general authorization for medical underwriting information."],"topics":["3.8.07","3.8.14"],"review":3,"lesson":"23","domain":2,"explanation":"The FCRA requires the applicant’s permission for this medical-information report."},{"id":"L23-06","prompt":"An applicant asks for a rapid surrender payment to an unrelated person and avoids explaining the source of funds. What should the producer do?","options":["Ignore it because the applicant paid the premium.","Declare the applicant guilty of money laundering.","Document the facts and follow the insurer’s AML escalation process.","Suggest splitting the payment to avoid review."],"answer":2,"explanations":["Payment does not resolve the unusual transaction facts.","The pattern warrants review, not an unsupported accusation.","Follow the trained process and let the responsible team investigate.","Helping avoid controls would undermine the program."],"topics":["3.8.15"],"review":4,"lesson":"23","domain":2,"explanation":"Follow the trained process and let the responsible team investigate."},{"id":"L23-07","prompt":"Which statement about the federal insurance-company AML rule is accurate?","options":["Every agent must create a separate insurer program solely because of the agency role.","The insurer can exclude all agent activities from its program.","The rule makes ordinary term without cash value identical to permanent cash-value coverage.","The insurer integrates relevant agents and brokers into its covered-product program."],"answer":3,"explanations":["Other roles can create duties, but this rule does not impose that separate program merely for being an agent.","Relevant agent and broker activities are included.","The rule has a defined covered-product scope.","This correctly identifies the insurer’s responsibility and agent participation."],"topics":["3.8.15"],"review":4,"lesson":"23","domain":2,"explanation":"This correctly identifies the insurer’s responsibility and agent participation."},{"id":"L23-08","prompt":"A consumer report contributes to an adverse underwriting decision. Which explanation belongs in the required notice?","options":["The reporting agency supplied information but did not make the insurer’s decision; report and dispute rights apply.","The reporting agency is the insurer and must pay the policy benefit.","No notice is required unless the report was the only reason.","The applicant has no right to question inaccurate report information."],"answer":0,"explanations":["This correctly separates the report source, insurer decision and consumer rights.","A reporting agency is not the carrier that issues coverage.","A partial contribution can trigger the notice.","The consumer has the stated report and dispute rights."],"topics":["3.8.09"],"review":5,"lesson":"23","domain":2,"explanation":"This correctly separates the report source, insurer decision and consumer rights."}]},{"id":"24","number":24,"title":"Understand a fair underwriting decision","version":1,"questions":[{"id":"L24-01","prompt":"The insurer asks Marcus’s treating physician for records clarifying a recent treatment. Which source is being requested?","options":["An attending physician statement","The producer’s commission schedule","An investigative interview with a neighbor","A beneficiary assignment"],"answer":0,"explanations":["The treating medical professional supplies the relevant history.","Compensation information does not provide the treatment record.","That is a different information source.","An assignment transfers rights rather than supplying medical history."],"topics":["3.9.02"],"review":0,"lesson":"24","domain":2,"explanation":"The treating medical professional supplies the relevant history."},{"id":"L24-02","prompt":"A policy advertises that an examination may not be required. What can an applicant correctly infer?","options":["There will be no underwriting information of any kind.","The insurer may still evaluate other authorized underwriting evidence.","A preferred rate is guaranteed.","Every answer on the application becomes optional."],"answer":1,"explanations":["An exam waiver does not establish the absence of underwriting.","Authorized reports and other evidence may still be considered.","Classification depends on the insurer’s standards and evidence.","The application still requires accurate, complete responses."],"topics":["3.9.05"],"review":1,"lesson":"24","domain":2,"explanation":"Authorized reports and other evidence may still be considered."},{"id":"L24-03","prompt":"A reporting agency interviews people acquainted with the applicant about general reputation and mode of living. What does this describe?","options":["An attending physician statement","A policy illustration","An investigative consumer report","A reinstatement premium receipt"],"answer":2,"explanations":["An APS comes from the treating medical professional.","An illustration describes policy values and benefits under assumptions.","Personal-interview information is a distinguishing feature of this report.","A receipt concerns a payment and its conditions."],"topics":["3.9.03"],"review":2,"lesson":"24","domain":2,"explanation":"Personal-interview information is a distinguishing feature of this report."},{"id":"L24-04","prompt":"MIB information conflicts with an answer on the application. What is the appropriate underwriting response?","options":["Treat MIB as the insurer that automatically declines coverage.","Delete the application answer without informing the applicant.","Assume the report is a complete and current medical chart.","Resolve the discrepancy through authorized verification and correction procedures."],"answer":3,"explanations":["MIB supplies information; it does not issue the insurer’s decision.","The record should not be secretly altered.","The information is not a substitute for every current medical fact.","Verification and correction address the conflict fairly."],"topics":["3.9.04","3.9.01"],"review":3,"lesson":"24","domain":2,"explanation":"Verification and correction address the conflict fairly."},{"id":"L24-05","prompt":"An applicant meets the carrier’s more favorable risk criteria and is offered the corresponding lower rate. Which classification is described?","options":["Preferred","Declined","Substandard","Uninsurable by every carrier"],"answer":0,"explanations":["This is the favorable accepted risk category.","The company is offering coverage.","That describes an accepted higher-risk category.","One favorable decision does not establish that unrelated conclusion."],"topics":["3.9.08"],"review":4,"lesson":"24","domain":2,"explanation":"This is the favorable accepted risk category."},{"id":"L24-06","prompt":"An accepted applicant fits the insurer’s ordinary risk assumptions for the applicable class. Which label best fits?","options":["Preferred","Standard","Declined","Automatically exempt from premiums"],"answer":1,"explanations":["Preferred meets more favorable criteria.","Standard fits the ordinary assumptions for that class.","The application has been accepted.","Classification does not eliminate the payment obligation."],"topics":["3.9.09"],"review":4,"lesson":"24","domain":2,"explanation":"Standard fits the ordinary assumptions for that class."},{"id":"L24-07","prompt":"The insurer accepts an application with a permitted additional premium because of a higher assessed risk. Which result is described?","options":["Declined","Preferred","Substandard","Unsubmitted"],"answer":2,"explanations":["A decline would be a refusal to accept the application.","Preferred reflects more favorable criteria.","This is an accepted higher-risk offer.","The application has been evaluated and an offer made."],"topics":["3.9.10"],"review":4,"lesson":"24","domain":2,"explanation":"This is an accepted higher-risk offer."},{"id":"L24-08","prompt":"The insurer refuses to accept this application under its current product requirements. What has occurred?","options":["A guaranteed conversion","A standard offer","A substandard acceptance","A declined application"],"answer":3,"explanations":["Conversion is a separate contract right with its own requirements.","No ordinary accepted offer was made.","No higher-risk acceptance was made.","The insurer declined this application; another application or carrier requires its own evaluation."],"topics":["3.9.11"],"review":4,"lesson":"24","domain":2,"explanation":"The insurer declined this application; another application or carrier requires its own evaluation."},{"id":"L24-09","prompt":"Which statement best reflects Maryland’s domestic-violence rule?","options":["Victim status cannot be used for the prohibited adverse treatment, while the statute separately permits consideration of medical conditions regardless of cause.","An insurer may add a surcharge solely because the applicant is an abuse victim.","No medical condition may ever be considered if the applicant has experienced abuse.","The insurer must pay the person who willfully caused the covered injury."],"answer":0,"explanations":["This preserves the protection and the separate statutory provisions.","That is among the prohibited uses of the information.","The statute expressly addresses medical conditions separately.","The law does not require that payment."],"topics":["3.9.06","3.9.07"],"review":5,"lesson":"24","domain":2,"explanation":"This preserves the protection and the separate statutory provisions."},{"id":"L24-10","prompt":"A consumer report played a small part in an adverse decision. Which statement about the federal notice is correct?","options":["It is unnecessary because another factor mattered more.","It explains report and dispute rights, including requesting a free report within 60 days.","It states that the reporting agency made the coverage decision.","It eliminates the applicant’s right to challenge inaccurate report information."],"answer":1,"explanations":["A partial contribution can trigger the notice.","This is part of the required consumer-rights explanation.","The notice must explain that the agency did not make the decision.","The notice explains the right to dispute inaccurate or incomplete information."],"topics":["3.8.09","3.9.03","3.9.04"],"review":2,"lesson":"24","domain":2,"explanation":"This is part of the required consumer-rights explanation."}]},{"id":"25","number":25,"title":"Know when protection actually begins","version":1,"questions":[{"id":"L25-01","prompt":"Marcus pays an initial premium. What must be examined to determine any protection before full policy issue?","options":["Only the producer’s expected commission","The actual receipt or temporary agreement and its conditions","Only the requested beneficiary’s age","Only the date the applicant first considered insurance"],"answer":1,"explanations":["Compensation does not determine temporary coverage.","The document and its conditions establish the relevant protection.","The beneficiary’s age alone does not resolve the receipt.","Considering insurance does not establish coverage."],"topics":["3.8.13"],"review":0,"lesson":"25","domain":2,"explanation":"The document and its conditions establish the relevant protection."},{"id":"L25-02","prompt":"A receipt states coverage begins on the later of application and required examination if the applicant was insurable exactly as applied for then. All conditions are met. Application is June 3, examination June 7 and approval June 12. What is the conditional starting date?","options":["June 3","June 12","June 7","The first policy anniversary"],"answer":2,"explanations":["The required examination occurred later.","Approval confirms the stated condition in this example; it is not the specified starting date.","June 7 is the later of the two dates named by the receipt.","An anniversary is unrelated to the stated receipt condition."],"topics":["3.8.13"],"review":1,"lesson":"25","domain":2,"explanation":"June 7 is the later of the two dates named by the receipt."},{"id":"L25-03","prompt":"Change only the receipt: it expressly requires home-office approval before protection starts. Approval occurs June 12. Which date follows that stated condition?","options":["June 3","June 7","June 1","June 12"],"answer":3,"explanations":["Payment and application do not remove the approval requirement.","The examination alone does not satisfy this receipt.","No stated event supports June 1.","The required approval occurs June 12."],"topics":["3.8.13"],"review":2,"lesson":"25","domain":2,"explanation":"The required approval occurs June 12."},{"id":"L25-04","prompt":"An applicant dies while underwriting is pending. Which response is most accurate before reviewing the receipt and facts?","options":["Pending underwriting alone does not establish whether coverage exists.","Pending underwriting always means no coverage.","Every initial-premium receipt guarantees the full applied-for benefit.","The producer may choose the benefit from the family’s needs."],"answer":0,"explanations":["The actual agreement and satisfied conditions must be reviewed.","Conditional or temporary protection may apply.","Receipts may have conditions, limits and exclusions.","The contract and applicable law determine the benefit."],"topics":["3.8.13"],"review":2,"lesson":"25","domain":2,"explanation":"The actual agreement and satisfied conditions must be reviewed."},{"id":"L25-05","prompt":"A policy is sent to the producer subject to first-premium payment and the required unchanged-health confirmation. What is the correct next step?","options":["Assume mailing alone satisfied the conditions.","Complete the stated requirements truthfully and follow delivery instructions.","Tell the applicant that the health question no longer matters.","Replace the policy date with the producer’s preferred date."],"answer":1,"explanations":["The described conditions remain outstanding.","The facts require completion of the delivery process.","The producer cannot waive the stated requirement.","The producer cannot invent a new contract date."],"topics":["3.8.16","3.8.17"],"review":3,"lesson":"25","domain":2,"explanation":"The facts require completion of the delivery process."},{"id":"L25-06","prompt":"Before completing that conditional delivery, Elena reports a new hospitalization. What should the producer do?","options":["Have her sign unchanged health to avoid a delay.","Remove the hospitalization from the file.","Report the facts and follow the insurer’s review instructions.","Automatically declare every prior agreement void."],"answer":2,"explanations":["The statement would be false.","Concealment undermines the record.","The insurer must review the actual facts and coverage conditions.","An agent cannot invent a cancellation of previously effective protection."],"topics":["3.8.17"],"review":4,"lesson":"25","domain":2,"explanation":"The insurer must review the actual facts and coverage conditions."},{"id":"L25-07","prompt":"The insurer offers a different premium and amount than requested. Which statement is correct?","options":["The original application forces acceptance of the changed offer.","The producer can omit the change if the benefit is still useful.","The beneficiary alone must accept every owner’s offer.","The changes must be explained and accepted through the required process."],"answer":3,"explanations":["An application does not accept every possible counteroffer.","Material differences must be explained.","Acceptance follows the actual ownership and application arrangement.","This preserves informed acceptance of the modified offer."],"topics":["3.8.16"],"review":4,"lesson":"25","domain":2,"explanation":"This preserves informed acceptance of the modified offer."},{"id":"L25-08","prompt":"Which delivery situation best fits the teaching concept of constructive delivery?","options":["An accepted policy is released unconditionally for delivery even before physical handoff.","A policy is held pending an unpaid first premium.","An unsigned modified offer is still awaiting acceptance.","A producer asks for a quote before an application exists."],"answer":0,"explanations":["Unconditional release is the distinguishing fact in this example.","An outstanding payment condition changes the facts.","Acceptance is still unresolved.","A quote request is not policy delivery."],"topics":["3.8.16"],"review":3,"lesson":"25","domain":2,"explanation":"Unconditional release is the distinguishing fact in this example."}]},{"id":"26","number":26,"title":"Read term insurance along a timeline","version":1,"questions":[{"id":"L26-01","prompt":"A policy is described only as having a level death benefit. Which additional fact is still needed to establish the future price?","options":["The producer’s job title","The premium guarantee period and renewal schedule","The beneficiary’s preferred payment method","Whether the applicant has a printer"],"answer":1,"explanations":["The job title does not define the policy’s price.","A level benefit does not by itself establish a permanently level premium.","Claim payment preferences do not establish the premium guarantee.","Printing capability does not determine insurance cost."],"topics":["4.1.01","4.1.03"],"review":0,"lesson":"26","domain":3,"explanation":"A level benefit does not by itself establish a permanently level premium."},{"id":"L26-02","prompt":"Which description best fits annual renewable term?","options":["Permanent paid-up coverage after one payment","A decreasing premium guaranteed for life","One-year term periods with the stated renewal rights and commonly increasing age-based premiums","A guaranteed cash-value account with no death benefit"],"answer":2,"explanations":["That describes a different funding and protection pattern.","Renewable term does not make this lifetime price promise.","This connects the coverage period, right and typical premium pattern.","Ordinary term provides death protection and generally no cash accumulation."],"topics":["4.1.02"],"review":1,"lesson":"26","domain":3,"explanation":"This connects the coverage period, right and typical premium pattern."},{"id":"L26-03","prompt":"Marcus’s health worsens during a renewable term policy. What does a valid, timely renewal right generally preserve?","options":["The original premium forever","Conversion to any insurer’s product","Renewal after every maximum age without payment","The right to renew under the terms without new evidence of insurability"],"answer":3,"explanations":["Renewal premiums follow the contract’s schedule.","Renewal is not an unrestricted conversion right.","Timing, age and payment conditions remain.","This is the key protection of the renewal provision."],"topics":["4.1.02"],"review":2,"lesson":"26","domain":3,"explanation":"This is the key protection of the renewal provision."},{"id":"L26-04","prompt":"Which action exercises conversion rather than renewal?","options":["Using an available right to change term coverage to an eligible permanent policy","Continuing another term period at the scheduled renewal premium","Changing the premium payment mode from annual to monthly","Naming a different contingent beneficiary"],"answer":0,"explanations":["Conversion changes the kind of coverage under its terms.","That is renewal of term coverage.","Payment frequency is a separate feature.","A beneficiary change does not convert the policy type."],"topics":["4.1.04"],"review":3,"lesson":"26","domain":3,"explanation":"Conversion changes the kind of coverage under its terms."},{"id":"L26-05","prompt":"A conversion right requires no new health evidence. What does that mean for the premium?","options":["The permanent premium must equal the old term premium.","The new premium still follows the conversion terms, commonly using attained age.","No premium is due after conversion.","The producer may select any price below the illustration."],"answer":1,"explanations":["The health-evidence right does not preserve the old term price.","Apply the contract’s premium basis and available permanent product.","Conversion does not automatically make the policy paid up.","The insurer’s terms determine the price."],"topics":["4.1.04"],"review":3,"lesson":"26","domain":3,"explanation":"Apply the contract’s premium basis and available permanent product."},{"id":"L26-06","prompt":"A benefit starts at $200,000 and decreases by $10,000 after each anniversary while the premium stays level. What is the benefit after five decreases?","options":["$200,000","$190,000","$150,000","$50,000"],"answer":2,"explanations":["This ignores the decreases.","This subtracts only one decrease.","$200,000 minus five times $10,000 equals $150,000.","That is the total decrease, not the remaining benefit."],"topics":["4.1.05"],"review":4,"lesson":"26","domain":3,"explanation":"$200,000 minus five times $10,000 equals $150,000."},{"id":"L26-07","prompt":"A stated increasing term benefit starts at $100,000 and adds $5,000 at each anniversary. What is it after two increases?","options":["$105,000","$110,250","$200,000","$110,000"],"answer":3,"explanations":["This includes only one increase.","This uses a compound-percentage calculation the question did not specify.","The benefit does not double under the stated formula.","Two fixed $5,000 additions produce $110,000."],"topics":["4.1.06"],"review":4,"lesson":"26","domain":3,"explanation":"Two fixed $5,000 additions produce $110,000."},{"id":"L26-08","prompt":"Which statement about return-of-premium term is accurate?","options":["The refund depends on the contract’s survival, payment and other conditions; early cancellation may have different values.","Every early cancellation returns all payments plus interest.","Every separate rider charge must be included.","The feature eliminates the need to compare the premium with other protection options."],"answer":0,"explanations":["Read the actual refund and early-exit terms.","A full interest-bearing refund is not automatic.","The contract defines qualifying payments and exclusions.","The feature can carry a higher cost and should be compared."],"topics":["4.1.07"],"review":5,"lesson":"26","domain":3,"explanation":"Read the actual refund and early-exit terms."}]},{"id":"27","number":27,"title":"Whole life: coverage and payment schedules","version":1,"questions":[{"id":"L27-01","prompt":"Elena needs a lifelong benefit and is reviewing a traditional continuous-pay whole life contract. Which statement describes its payment structure?","options":["Premiums necessarily increase every year with age.","Level scheduled premiums are due over the stated long payment period.","Only one premium may be charged.","All premiums stop after the first illustrated dividend."],"answer":1,"explanations":["Aging does not require an annually increasing scheduled whole-life premium.","The contract specifies the continuing level-premium period.","That describes a single-premium design.","A dividend is not a guarantee that the required premium obligation ends."],"topics":["4.2.01"],"review":1,"lesson":"27","domain":3,"explanation":"The contract specifies the continuing level-premium period."},{"id":"L27-02","prompt":"Marcus completes every required premium on a 20-pay whole life policy. Which result follows the stated design?","options":["The policy must be surrendered.","The death benefit must be paid immediately.","Whole-life coverage continues with the required premium schedule completed.","Coverage becomes a new 20-year term policy."],"answer":2,"explanations":["Completing premiums is not a surrender instruction.","Being paid up is not the insured’s death or the policy’s maturity.","Limited pay shortens the funding period while retaining the stated permanent protection.","It does not convert the design to term."],"topics":["4.2.02"],"review":2,"lesson":"27","domain":3,"explanation":"Limited pay shortens the funding period while retaining the stated permanent protection."},{"id":"L27-03","prompt":"Compared with otherwise comparable continuous-pay whole life, a policy funded in ten required annual payments will generally have what annual premium pattern?","options":["Lower annual payments because the insured ages more slowly","The same annual amount regardless of funding period","No contractual payment schedule","Higher annual payments because funding is compressed into fewer years"],"answer":3,"explanations":["The shorter payment period does not change the insured’s rate of aging.","The funding period affects the amount needed each year.","Limited-payment coverage has a stated schedule.","Fewer required payments generally mean larger payments for comparable coverage."],"topics":["4.2.02"],"review":2,"lesson":"27","domain":3,"explanation":"Fewer required payments generally mean larger payments for comparable coverage."},{"id":"L27-04","prompt":"Which description identifies single-premium whole life?","options":["Permanent coverage funded by one required premium at issue","One year of coverage renewed with a new premium annually","Twenty required annual premiums for permanent coverage","A permanent policy that necessarily has no cash value"],"answer":0,"explanations":["It is a limited-payment design with one required payment.","That describes an annual term pattern.","That describes twenty-pay whole life.","Single-premium whole life provides the contract’s cash values."],"topics":["4.2.06"],"review":3,"lesson":"27","domain":3,"explanation":"It is a limited-payment design with one required payment."},{"id":"L27-05","prompt":"A whole life schedule charges $300 in year 1, $400 in year 2, and $500 annually thereafter while the benefit stays level. What is graded?","options":["The benefit paid at death","The premium schedule","The beneficiary’s share","The policy’s renewal period"],"answer":1,"explanations":["The question expressly keeps the benefit level.","The scheduled premium changes during the initial period.","No beneficiary share changes are described.","This is a permanent-policy premium schedule, not a sequence of term renewals."],"topics":["4.2.05"],"review":4,"lesson":"27","domain":3,"explanation":"The scheduled premium changes during the initial period."},{"id":"L27-06","prompt":"Under the stated graded schedule of $300, $400, then $500, how much is paid over the first three annual premiums?","options":["$900","$1,000","$1,200","$1,500"],"answer":2,"explanations":["That uses the first-year amount for all three years.","That does not add all three stated payments.","$300 + $400 + $500 = $1,200.","That uses the later level amount for all three years."],"topics":["4.2.05"],"review":4,"lesson":"27","domain":3,"explanation":"$300 + $400 + $500 = $1,200."},{"id":"L27-07","prompt":"An in-force traditional policy has a stated $100,000 death benefit and $20,000 cash value. Assume no loans or other adjustments. What death payment follows those facts?","options":["$20,000 because only cash value is payable","$80,000 after subtracting cash value","$120,000 by always adding cash value","$100,000 under the stated death-benefit provision"],"answer":3,"explanations":["That confuses surrender value with the death benefit.","The cash value is not subtracted in this stated example.","Cash value is not automatically paid as an additional benefit.","Apply the stated benefit and the explicit no-adjustment assumption."],"topics":["4.2.01"],"review":5,"lesson":"27","domain":3,"explanation":"Apply the stated benefit and the explicit no-adjustment assumption."},{"id":"L27-08","prompt":"A continuous-pay illustration projects dividends covering all premiums after year 15. What should the producer explain?","options":["The projection is not a contractual guarantee that required premiums end in year 15.","The policy is automatically a guaranteed 15-pay policy.","The owner can stop paying even if future dividends are lower.","The insurer must pay the projected dividend in every later year."],"answer":0,"explanations":["Future dividends are nonguaranteed; the actual required payment schedule still matters.","An illustrated offset does not rewrite the contract’s payment period.","Lower dividends can leave a premium obligation.","A dividend projection is not a guaranteed payment."],"topics":["4.2.01","4.2.02"],"review":5,"lesson":"27","domain":3,"explanation":"Future dividends are nonguaranteed; the actual required payment schedule still matters."}]},{"id":"28","number":28,"title":"Universal and indexed life: follow the funding","version":1,"questions":[{"id":"L28-01","prompt":"Elena temporarily reduces payments on her universal life policy. Which statement best explains the immediate funding issue?","options":["Policy charges stop whenever a premium is skipped.","The planned premium is always a lifetime guarantee.","Charges can continue and reduce available policy value.","Flexible premiums eliminate every lapse condition."],"answer":2,"explanations":["The contract’s deductions can continue without a payment.","A planned payment must be distinguished from an actual guarantee.","The remaining value may be used to support continuing costs.","Funding and any guarantee conditions still matter."],"topics":["4.3.02"],"review":0,"lesson":"28","domain":3,"explanation":"The remaining value may be used to support continuing costs."},{"id":"L28-02","prompt":"A teaching account starts at $1,000, receives $190 net funding and $20 interest, and deducts $130. What is its ending value?","options":["$880","$1,070","$1,210","$1,080"],"answer":3,"explanations":["This omits or changes the stated incoming amounts.","This subtracts the assumed premium charge a second time.","This fails to deduct the $130 charge.","$1,000 + $190 + $20 − $130 = $1,080."],"topics":["4.3.02"],"review":1,"lesson":"28","domain":3,"explanation":"$1,000 + $190 + $20 − $130 = $1,080."},{"id":"L28-03","prompt":"Remove only the $190 net funding from the prior teaching account: $1,000 opening, $20 interest and $130 deductions. What remains?","options":["$890","$1,000","$1,020","$1,080"],"answer":0,"explanations":["$1,000 + $20 − $130 = $890.","That ignores the net effect of interest and charges.","That omits the charge.","That incorrectly retains the removed funding."],"topics":["4.3.02"],"review":1,"lesson":"28","domain":3,"explanation":"$1,000 + $20 − $130 = $890."},{"id":"L28-04","prompt":"An indeterminate-premium whole life contract changes its current premium based on stated assumptions. Which limit is central to that design?","options":["The premium can never change after issue.","The premium cannot exceed its contractual guaranteed maximum.","The owner may choose any premium with no funding consequences.","The current premium must equal the lowest illustrated amount forever."],"answer":1,"explanations":["The design permits the stated current-premium adjustments.","A current premium and the guaranteed ceiling are distinct.","That incorrectly substitutes unrestricted funding for the stated schedule.","Current assumptions are not a permanent guarantee."],"topics":["4.2.03"],"review":2,"lesson":"28","domain":3,"explanation":"A current premium and the guaranteed ceiling are distinct."},{"id":"L28-05","prompt":"An indexed strategy states 8% index growth, 75% participation, a 5% cap, no spread and a 0% floor. What rate is credited before policy charges?","options":["8%","6%","5%","0%"],"answer":2,"explanations":["The strategy does not credit the full index return.","Participation produces 6%, but the cap still applies.","The 6% participation result is limited to the stated 5% cap.","The positive calculated credit exceeds the floor."],"topics":["4.2.04"],"review":4,"lesson":"28","domain":3,"explanation":"The 6% participation result is limited to the stated 5% cap."},{"id":"L28-06","prompt":"An indexed strategy credits 0% after a negative index year. Policy deductions continue. Which result remains possible?","options":["The owner receives the index’s full negative return as a separate charge.","Every policy deduction is automatically refunded.","Net policy value must remain unchanged.","Policy value can decline because a crediting floor does not remove deductions."],"answer":3,"explanations":["The stated floor governs the index-interest calculation; it does not authorize that separate invented charge.","The floor does not cancel contractual charges.","Zero interest and continuing deductions can reduce value.","A minimum credited rate is different from a net-value guarantee."],"topics":["4.2.04","4.3.02"],"review":4,"lesson":"28","domain":3,"explanation":"A minimum credited rate is different from a net-value guarantee."},{"id":"L28-07","prompt":"What best describes the index connection in the stated indexed universal life example?","options":["A contractual interest formula references an external index.","The owner directly holds every stock in the index through the policy.","The insurer guarantees the published index return as net cash-value growth.","All dividends paid by index companies are necessarily passed through."],"answer":0,"explanations":["The contract specifies how index changes affect interest crediting.","Indexed crediting is not direct stock ownership.","Caps, participation and charges prevent that conclusion.","The stated strategy and index method determine what is included."],"topics":["4.2.04"],"review":3,"lesson":"28","domain":3,"explanation":"The contract specifies how index changes affect interest crediting."},{"id":"L28-08","prompt":"A strategy expressly credits 7% index growth minus a 2-percentage-point spread, with no cap and a 0% floor. What is the credited rate before deductions?","options":["7%","5%","6.86%","2%"],"answer":1,"explanations":["That omits the stated spread.","7% − 2 percentage points = 5%.","That multiplies by 98% instead of subtracting the stated spread.","The spread itself is not the credited rate."],"topics":["4.2.04"],"review":3,"lesson":"28","domain":3,"explanation":"7% − 2 percentage points = 5%."},{"id":"L28-09","prompt":"A universal policy includes a no-lapse guarantee. What must a producer examine before saying it still protects the policy?","options":["Only the original illustration’s best-case values","Only the word permanent on the cover","The guarantee’s period and actual funding and other conditions","Only whether last month’s index return was positive"],"answer":2,"explanations":["Illustrated values do not prove guarantee compliance.","The product label does not establish the guarantee’s status.","The actual conditions and time period determine its application.","Index performance alone does not resolve all guarantee conditions."],"topics":["4.3.02"],"review":2,"lesson":"28","domain":3,"explanation":"The actual conditions and time period determine its application."},{"id":"L28-10","prompt":"A policy option expressly pays a $200,000 stated amount plus $30,000 account value. Assume no loans or other adjustments. What is its death benefit?","options":["$170,000","$200,000","$30,000","$230,000"],"answer":3,"explanations":["The stated option adds the account value.","That uses a level-benefit assumption contrary to the question.","That omits the stated amount.","$200,000 + $30,000 = $230,000 under this expressly stated option."],"topics":["4.3.02"],"review":5,"lesson":"28","domain":3,"explanation":"$200,000 + $30,000 = $230,000 under this expressly stated option."}]},{"id":"29","number":29,"title":"Variable and adjustable life: identify the moving part","version":1,"questions":[{"id":"L29-01","prompt":"Which fact identifies investment exposure in the variable-life example?","options":["A premium is paid annually.","A beneficiary is named.","The owner selects separate-account investment options and bears their specified performance risk.","The policy uses a printed application."],"answer":2,"explanations":["Payment frequency alone does not identify a variable design.","Fixed and variable policies can both have beneficiaries.","The investment options and owner’s exposure identify the variable feature.","Application format does not identify the investment structure."],"topics":["4.2.07","4.2.08"],"review":0,"lesson":"29","domain":3,"explanation":"The investment options and owner’s exposure identify the variable feature."},{"id":"L29-02","prompt":"A scheduled-premium variable whole-life contract guarantees a minimum death benefit if its conditions are met. What does that establish about cash value?","options":["Cash value must equal the guaranteed death benefit.","Cash value cannot decline after issue.","Every illustrated cash value is guaranteed.","The death-benefit minimum does not itself guarantee variable cash value."],"answer":3,"explanations":["These are different policy measures.","Separate-account performance and charges can reduce value.","An illustration is not a cash-value guarantee.","Identify the specific benefit covered by the guarantee."],"topics":["4.2.07"],"review":1,"lesson":"29","domain":3,"explanation":"Identify the specific benefit covered by the guarantee."},{"id":"L29-03","prompt":"Which distinction best separates the two variable designs described in this lesson?","options":["Scheduled premiums in variable whole life versus flexible funding in variable universal life","Investment risk only in variable whole life","Cash values only in variable universal life","Securities requirements only in variable universal life"],"answer":0,"explanations":["Both expose the owner to investment results, but their payment structures differ.","Variable universal life also carries investment risk.","Both designs can have cash values.","Both variable designs involve securities requirements."],"topics":["4.2.07","4.2.08"],"review":2,"lesson":"29","domain":3,"explanation":"Both expose the owner to investment results, but their payment structures differ."},{"id":"L29-04","prompt":"A $10,000 account loses 10%, then deducts an assumed $400 charge. What remains?","options":["$9,600","$8,600","$8,640","$9,000"],"answer":1,"explanations":["That subtracts the charge without applying the loss.","$10,000 × 90% = $9,000; $9,000 − $400 = $8,600.","That reverses the explicitly stated calculation order.","That stops before deducting the charge."],"topics":["4.2.07","4.2.08"],"review":3,"lesson":"29","domain":3,"explanation":"$10,000 × 90% = $9,000; $9,000 − $400 = $8,600."},{"id":"L29-05","prompt":"Marcus reduces VUL funding while investment results are poor. What should be evaluated?","options":["Only whether his original premium was paid","Only whether the policy has a cash-value label","Remaining value, continuing charges and any actual no-lapse conditions","Whether all future premiums are automatically waived"],"answer":2,"explanations":["Original payment does not establish future funding sufficiency.","The label does not quantify the remaining resources.","These facts determine the funding and protection position.","Reduced funding does not create a waiver."],"topics":["4.2.08"],"review":2,"lesson":"29","domain":3,"explanation":"These facts determine the funding and protection position."},{"id":"L29-06","prompt":"Elena requests a larger insured amount under an adjustable policy. Which response is most accurate?","options":["Every increase is guaranteed without underwriting.","The insured automatically changes to whoever pays the next premium.","The premium and protection period can never be affected.","Apply the contract’s increase provisions, including any evidence-of-insurability requirement."],"answer":3,"explanations":["An increase may require evidence unless a specific right says otherwise.","An ordinary adjustment does not substitute a new insured.","Permitted adjustments can affect related elements.","The stated right and its conditions control the change."],"topics":["4.3.01"],"review":4,"lesson":"29","domain":3,"explanation":"The stated right and its conditions control the change."},{"id":"L29-07","prompt":"A proposed adjustable-plan change lowers payments while retaining the face amount. What should be checked before describing the result?","options":["Whether the change affects protection duration or other contract terms","Only the new payment’s first due date","Whether the beneficiary prefers a shorter form","Whether all guarantees necessarily remain identical"],"answer":0,"explanations":["Changing funding can affect the protection plan under the actual contract.","Timing alone does not establish the resulting coverage.","Form preference does not establish policy mechanics.","That is the conclusion to verify, not an assumption to make."],"topics":["4.3.01"],"review":4,"lesson":"29","domain":3,"explanation":"Changing funding can affect the protection plan under the actual contract."},{"id":"L29-08","prompt":"What does a producer need to recognize before transacting variable life?","options":["A life license automatically grants all securities authority.","Applicable securities registration and FINRA requirements accompany insurance authority; the prospectus provides material product information.","Investment losses are covered by a universal bank-deposit guarantee.","A favorable illustration replaces the need to discuss expenses."],"answer":1,"explanations":["Insurance authority alone does not provide every securities permission.","FINRA requirements, securities registration and insurance authority must all be addressed; the prospectus explains material product information.","A variable life policy is not an ordinary insured bank deposit.","Expenses and risks still need to be understood."],"topics":["4.2.07","4.2.08","3.6.06"],"review":5,"lesson":"29","domain":3,"explanation":"FINRA requirements, securities registration and insurance authority must all be addressed; the prospectus explains material product information."}]},{"id":"30","number":30,"title":"Family, joint, juvenile and credit life","version":1,"questions":[{"id":"L30-01","prompt":"Marcus’s children are named beneficiaries on a policy insuring Marcus. What does that fact establish?","options":["The children are also insured under the base policy.","The children are designated recipients of the applicable benefit on Marcus’s covered death.","Each child has a separate permanent policy.","A child’s death automatically triggers Marcus’s base benefit."],"answer":1,"explanations":["Being a beneficiary is different from being an insured.","The designation addresses who receives the stated benefit.","No separate child policy is described.","The base policy insures Marcus’s life."],"topics":["4.4.01"],"review":0,"lesson":"30","domain":3,"explanation":"The designation addresses who receives the stated benefit."},{"id":"L30-02","prompt":"A family plan includes a child term rider that pays on the insured child’s covered death. Which event triggers that stated rider benefit?","options":["The adult owner changes jobs.","The adult owner names another beneficiary.","The covered child dies while the rider is in force.","The child starts a new school."],"answer":2,"explanations":["A job change is not the stated death-benefit trigger.","A designation change is not a death claim.","This is the event specified by the rider.","Enrollment does not trigger the stated life benefit."],"topics":["4.4.01"],"review":0,"lesson":"30","domain":3,"explanation":"This is the event specified by the rider."},{"id":"L30-03","prompt":"A joint first-death base policy covers Marcus and Elena with one $300,000 benefit and no extra features. Marcus dies first. What follows the stated design?","options":["It waits until Elena also dies.","It pays $150,000 now and necessarily reserves $150,000 for Elena’s death.","It promises a separate $300,000 payment on each death.","The stated $300,000 benefit is payable at Marcus’s covered death."],"answer":3,"explanations":["That describes last-survivor timing.","No split-payment feature is stated.","Two insured names do not create two promised base payments.","The first covered death triggers this one-benefit contract."],"topics":["4.4.02"],"review":1,"lesson":"30","domain":3,"explanation":"The first covered death triggers this one-benefit contract."},{"id":"L30-04","prompt":"A couple has only a second-to-die base policy with no first-death rider. One insured dies while the other remains alive. Is its base benefit then payable?","options":["No; its stated trigger is the second insured’s death.","Yes; second-to-die means the second listed beneficiary.","Yes; all joint policies pay at either death.","Half is necessarily payable immediately."],"answer":0,"explanations":["Last-survivor coverage waits for the specified final death.","The term refers to the insured lives, not beneficiary order.","First-death and last-survivor triggers differ.","No split benefit is stated."],"topics":["4.4.03"],"review":2,"lesson":"30","domain":3,"explanation":"Last-survivor coverage waits for the specified final death."},{"id":"L30-05","prompt":"Elena owns a juvenile policy insuring her daughter. Who is the insured under the base policy?","options":["Elena because she pays","Her daughter, whose life the policy covers","The producer who delivered it","Whoever later receives the death benefit"],"answer":1,"explanations":["Payment does not identify the insured life.","The insured is the child named in the coverage.","Delivery does not make the producer insured.","The beneficiary and insured are separate roles."],"topics":["4.4.04"],"review":3,"lesson":"30","domain":3,"explanation":"The insured is the child named in the coverage."},{"id":"L30-06","prompt":"A child insured under a parent-owned juvenile policy becomes an adult. What should be checked before declaring the child the policyowner?","options":["Only the child’s birthday","Only whether the policy has cash value","The contract’s ownership provisions and any completed transfer process","Only the parent’s last premium amount"],"answer":2,"explanations":["Age alone does not establish the ownership result for every contract.","Cash value does not identify the owner.","The actual ownership terms and transfer determine control.","Payment size does not transfer rights."],"topics":["4.4.04"],"review":3,"lesson":"30","domain":3,"explanation":"The actual ownership terms and transfer determine control."},{"id":"L30-07","prompt":"Which arrangement describes group credit life in Maryland?","options":["A creditor is automatically insured for all business losses.","A debtor receives a permanent policy with no loan connection.","A group policy necessarily names each debtor’s family as the only payee.","A creditor holds a term group policy covering debtors’ lives for the credit arrangement."],"answer":3,"explanations":["The insured lives are the covered debtors.","Credit life connects term protection to a specific debt.","The insured debt and actual beneficiary provisions govern payment.","This matches the statutory group form."],"topics":["4.6.02"],"review":4,"lesson":"30","domain":3,"explanation":"This matches the statutory group form."},{"id":"L30-08","prompt":"What distinguishes the individual credit-life form in Maryland?","options":["A term life policy is issued to the debtor for the credit transaction.","The debtor becomes the insurer.","The creditor necessarily receives permanent whole-life cash values.","The policy pays for every missed installment regardless of cause."],"answer":0,"explanations":["This is the statutory individual-life form.","The debtor is an insured party, not the insurer.","Credit life is issued on a term plan under the stated law.","Life coverage addresses the covered death rather than every payment difficulty."],"topics":["4.6.01"],"review":4,"lesson":"30","domain":3,"explanation":"This is the statutory individual-life form."},{"id":"L30-09","prompt":"An ordinary credit-life example has $12,000 total repayable under the debt contract and no statutory exception. What initial amount follows the general Maryland ceiling?","options":["Any amount the creditor selects","No more than $12,000 under this stated limit","$25,000 because the family also has expenses","Exactly twice the total repayable amount"],"answer":1,"explanations":["The statute supplies a limit.","The general initial limit is the total amount repayable.","Additional family needs do not override this credit-life ceiling.","The general rule does not double the debt."],"topics":["4.6.01","4.6.02"],"review":5,"lesson":"30","domain":3,"explanation":"The general initial limit is the total amount repayable."},{"id":"L30-10","prompt":"A credit-life contract has a $10,000 payable benefit, with $9,000 due the creditor. A designated second beneficiary is entitled to the excess. How is the $1,000 excess handled?","options":["The creditor automatically keeps it.","It is ignored because only the loan matters.","It is paid to the entitled second beneficiary.","It becomes an automatic producer bonus."],"answer":2,"explanations":["The rule directs payable excess to the entitled recipient.","A payable excess is not erased.","The stated entitlement and the Maryland rule determine the recipient.","The excess is a benefit, not compensation."],"topics":["4.6.01","4.6.02"],"review":5,"lesson":"30","domain":3,"explanation":"The stated entitlement and the Maryland rule determine the recipient."}]},{"id":"31","number":31,"title":"Group life: follow the contract and the covered lives","version":1,"questions":[{"id":"L31-01","prompt":"Elena has employer group life and receives a certificate. Which document is held by the employer or qualifying trustees?","options":["Elena’s individual conversion policy","The master group contract","Each beneficiary’s claim release","A separate juvenile policy on every worker"],"answer":1,"explanations":["A conversion policy is issued when a qualifying conversion occurs.","The group policyholder holds the master contract; Elena receives the certificate.","A claim release is not the group insurance contract.","Group enrollment does not imply juvenile coverage."],"topics":["4.5.01","4.5.02","3.6.01"],"review":0,"lesson":"31","domain":3,"explanation":"The group policyholder holds the master contract; Elena receives the certificate."},{"id":"L31-02","prompt":"A Maryland labor union holds a group policy on eligible members. Which statement fits the statutory arrangement?","options":["The union must be the only death beneficiary.","Each member is automatically the master policyholder.","The union is the policyholder, with benefits for persons other than the union and its specified officials or representatives.","Only the union’s buildings are insured."],"answer":2,"explanations":["The statute directs benefits away from the union and the listed union parties.","The union holds this master policy.","This distinguishes policyholding from the benefit recipients.","This is life coverage on members."],"topics":["4.5.04"],"review":0,"lesson":"31","domain":3,"explanation":"This distinguishes policyholding from the benefit recipients."},{"id":"L31-03","prompt":"Two employers establish a qualifying trust for group life coverage. Who can hold the master policy under the stated trust arrangement?","options":["Every employee’s physician","Only an individual death beneficiary","An unrelated lender without any group role","The trust or trustees identified by the arrangement"],"answer":3,"explanations":["Medical involvement does not make someone the group policyholder.","A death beneficiary is not necessarily the group policyholder.","No creditor arrangement is stated.","The trust or trustees are the policyholder under the qualifying structure."],"topics":["4.5.05"],"review":1,"lesson":"31","domain":3,"explanation":"The trust or trustees are the policyholder under the qualifying structure."},{"id":"L31-04","prompt":"Which association most clearly fails the requirements taught from Maryland §17-204?","options":["A ten-person club created yesterday solely to obtain insurance","A qualifying association with 200 members and three years of active existence","A qualifying association with annual meetings and member voting rights","A qualifying established association that collects required dues"],"answer":0,"explanations":["It fails the stated size, history and noninsurance-purpose requirements.","Those stated facts satisfy the size and history requirements, assuming the remaining conditions.","Those governance facts support the statutory conditions.","Collecting dues can satisfy the stated funding/governance condition."],"topics":["4.5.06"],"review":1,"lesson":"31","domain":3,"explanation":"It fails the stated size, history and noninsurance-purpose requirements."},{"id":"L31-05","prompt":"A creditor group insures debtors’ lives. What distinguishes its ordinary benefit purpose from employee family protection?","options":["It necessarily pays the employer for lost productivity.","It addresses the insured obligation under the creditor-group rules.","It guarantees every missed installment regardless of cause.","It transfers ownership of every debtor’s personal policy to the creditor."],"answer":1,"explanations":["That describes a different business-loss purpose.","The debt connection identifies this group type; payable excess follows the governing rule.","Life coverage is not every-cause payment protection.","A creditor group does not automatically assign unrelated personal policies."],"topics":["4.5.03"],"review":1,"lesson":"31","domain":3,"explanation":"The debt connection identifies this group type; payable excess follows the governing rule."},{"id":"L31-06","prompt":"A plan requires evidence for a late entrant’s requested amount. Which conclusion is accurate?","options":["Group life can never require individual evidence.","The requirement automatically turns every certificate into whole life.","Apply the actual enrollment and insurability conditions; group status does not eliminate them.","The applicant can omit requested facts because other employees are covered."],"answer":2,"explanations":["Group underwriting does not remove every individual evidence condition.","Evidence requirements do not identify a whole-life design.","Read the requested amount, timing and governing plan.","Other members’ enrollment does not excuse inaccurate answers."],"topics":["4.5.07"],"review":2,"lesson":"31","domain":3,"explanation":"Read the requested amount, timing and governing plan."},{"id":"L31-07","prompt":"Elena pays part of her group premium and names her spouse as beneficiary, with no spouse rider. Which pairing is correct?","options":["Noncontributory; spouse automatically insured","Contributory; employer automatically receives the benefit","Noncontributory; spouse owns the master policy","Contributory; spouse is the designated benefit recipient, without separate spouse coverage established"],"answer":3,"explanations":["Employee contributions make it contributory; designation does not insure the spouse.","Funding does not replace the beneficiary designation.","Neither claim follows the facts.","Separate the source of premium from the insured life and benefit recipient."],"topics":["4.5.08","4.5.09","4.5.11"],"review":3,"lesson":"31","domain":3,"explanation":"Separate the source of premium from the insured life and benefit recipient."},{"id":"L31-08","prompt":"An eligible employee loses covered group life upon leaving employment. Under the ordinary Maryland conversion rule, what is protected?","options":["An opportunity to apply and pay within the applicable period for individual coverage without new evidence of insurability","An unchanged group premium for life","An automatic new policy requiring no application or payment","A right to any unlimited death benefit selected later"],"answer":0,"explanations":["The right has timing, amount, form and premium conditions.","Individual conversion does not freeze the group price.","Application and first premium are normally required.","The statutory amount and form limits still apply."],"topics":["4.5.10"],"review":4,"lesson":"31","domain":3,"explanation":"The right has timing, amount, form and premium conditions."},{"id":"L31-09","prompt":"Which pairing correctly identifies a federal life program?","options":["FEGLI — a cash-value account automatically owned by every veteran","SGLI — term life coverage for eligible service members","VGLI — a Maryland employer’s master policy for all residents","FEGLI — insurance only on a federal employee’s mortgage"],"answer":1,"explanations":["FEGLI is federal employee group term, not a veteran cash-value account.","This is the program’s stated population and coverage type.","VGLI is a qualifying post-service federal program.","FEGLI is not limited to mortgage debt."],"topics":["3.6.07"],"review":5,"lesson":"31","domain":2,"explanation":"This is the program’s stated population and coverage type."},{"id":"L31-10","prompt":"A qualifying former service member applies for VGLI within 240 days after separation. What is the significance of that timing under the current VA guidance taught here?","options":["Every premium is waived permanently.","The coverage becomes whole life with guaranteed cash values.","The application does not require health evidence within that period.","The applicant has missed the ordinary final application deadline."],"answer":2,"explanations":["The no-health-review rule does not waive premiums.","VGLI is term coverage.","The health-evidence exception is distinct from the longer application deadline.","The ordinary stated final deadline is one year and 120 days, subject to eligibility."],"topics":["3.6.07"],"review":5,"lesson":"31","domain":2,"explanation":"The health-evidence exception is distinct from the longer application deadline."}]},{"id":"32","number":32,"title":"Policy ownership: rights, assignments and the contract","version":1,"questions":[{"id":"L32-01","prompt":"Elena owns a policy insuring Marcus and names their adult daughter as revocable beneficiary. Who ordinarily exercises the reserved owner rights?","options":["Marcus solely because he is insured","The daughter solely because she is beneficiary","Elena, subject to the contract and any valid restrictions","Whoever makes the most recent payment"],"answer":2,"explanations":["Insured status and ownership are different roles.","A revocable beneficiary designation does not itself transfer ownership.","Elena is the stated owner; other interests and terms can limit a particular action.","Payment alone does not transfer ownership."],"topics":["5.1.01"],"review":0,"lesson":"32","domain":4,"explanation":"Elena is the stated owner; other interests and terms can limit a particular action."},{"id":"L32-02","prompt":"Which fact can require additional consent before an owner changes a beneficiary designation?","options":["The policy has an annual anniversary.","The insured is a different person from the owner.","Premiums were paid by bank draft.","The existing beneficiary designation is irrevocable."],"answer":3,"explanations":["An anniversary does not alone create a consent right.","Different roles do not alone make the beneficiary irrevocable.","Payment method does not identify beneficiary rights.","An irrevocable interest can restrict the owner’s ability to change it."],"topics":["5.1.01"],"review":1,"lesson":"32","domain":4,"explanation":"An irrevocable interest can restrict the owner’s ability to change it."},{"id":"L32-03","prompt":"What distinguishes a valid absolute assignment from a beneficiary designation?","options":["It transfers ownership rights instead of merely naming a benefit recipient.","It automatically substitutes a new insured life.","It necessarily cancels all policy debt.","It only sets the premium-payment frequency."],"answer":0,"explanations":["Ownership control and benefit-recipient status are different.","A transfer of owner rights ordinarily preserves the insured life.","Existing debts and superior interests do not disappear merely on assignment.","That is not the purpose of an absolute assignment."],"topics":["5.1.02"],"review":2,"lesson":"32","domain":4,"explanation":"Ownership control and benefit-recipient status are different."},{"id":"L32-04","prompt":"A $100,000 payable benefit is subject to a valid collateral assignment securing $20,000 due. No other deductions or claims apply. How is the benefit divided in this example?","options":["$100,000 to the lender; nothing to the beneficiary","$20,000 to the lender; $80,000 to the beneficiary","$80,000 to the lender; $20,000 to the beneficiary","$20,000 to the lender; $100,000 to the beneficiary"],"answer":1,"explanations":["The secured interest is the stated $20,000 amount.","The assignment secures the amount due; the remainder is $80,000.","That reverses the secured amount and remainder.","The benefit is $100,000 total, not $120,000."],"topics":["5.1.02"],"review":3,"lesson":"32","domain":4,"explanation":"The assignment secures the amount due; the remainder is $80,000."},{"id":"L32-05","prompt":"After the secured loan is paid off, what is the appropriate next assignment step?","options":["Assume payment automatically erases every insurer record.","Change the insured life to the lender.","Obtain the required collateral release and follow the insurer’s recording process.","Treat the lender as permanent absolute owner in every case."],"answer":2,"explanations":["The release and recording process still need attention.","Debt repayment does not replace the insured.","This documents that the security interest has ended as provided.","Collateral security is different from an absolute ownership transfer."],"topics":["5.1.02"],"review":4,"lesson":"32","domain":4,"explanation":"This documents that the security interest has ended as provided."},{"id":"L32-06","prompt":"Which statement best describes Maryland’s individual-life entire-contract provision?","options":["Every sales brochure becomes a policy rider automatically.","Only the producer’s verbal explanation controls.","An application is always a warranty even without fraud.","The policy, or the policy with the endorsed or attached application, constitutes the entire contract."],"answer":3,"explanations":["An outside brochure is not automatically incorporated.","Informal statements do not replace the issued contract.","Included application statements are representations in the absence of fraud.","This identifies the statutory contract documents."],"topics":["5.1.03"],"review":5,"lesson":"32","domain":4,"explanation":"This identifies the statutory contract documents."},{"id":"L32-07","prompt":"An attached application forms part of the policy. In the absence of fraud, how does §16-204 treat its statements?","options":["As representations rather than warranties","As an automatic waiver of premium","As a guarantee that no claim can ever be reviewed","As a substitute for every issued policy provision"],"answer":0,"explanations":["This is the distinction specified by the statute.","The classification does not waive premiums.","Other lawful claim and contestability rules remain relevant.","The application is part of the contract, not a replacement for all its provisions."],"topics":["5.1.03"],"review":5,"lesson":"32","domain":4,"explanation":"This is the distinction specified by the statute."},{"id":"L32-08","prompt":"A producer wants to change an applicant’s written answer after signature. No administrative-only insurer insertion is involved. Which action follows the Maryland rule taught here?","options":["Change it silently if the producer thinks it is more accurate.","Obtain the applicant’s written consent through the required correction process.","Treat the correction as the beneficiary’s decision.","Destroy the original application and omit the change from the record."],"answer":1,"explanations":["The rule requires the applicant’s written consent for this alteration.","Correct the record transparently with the required authorization.","Beneficiary status does not authorize rewriting the applicant’s answer.","Concealing the change does not satisfy the rule."],"topics":["5.1.03"],"review":5,"lesson":"32","domain":4,"explanation":"Correct the record transparently with the required authorization."}]},{"id":"33","number":33,"title":"Beneficiaries: follow the intended payment","version":1,"questions":[{"id":"L33-01","prompt":"Marcus names Elena as 100% primary and an adult daughter as contingent. Elena survives and is eligible under all stated conditions. Who ordinarily receives the benefit?","options":["Each receives half because two people are named.","The daughter receives all because contingent means final.","The estate receives all despite the eligible primary.","Elena receives the stated primary benefit."],"answer":3,"explanations":["Primary and contingent are successive priorities, not an automatic equal split.","Contingent is the backup priority.","An eligible named primary generally receives the benefit under the designation.","The eligible primary has the stated first priority."],"topics":["5.2.05"],"review":0,"lesson":"33","domain":4,"explanation":"The eligible primary has the stated first priority."},{"id":"L33-02","prompt":"A $300,000 per-stirpes example preserves two child branches. One child survives; the other died leaving two living children. What does the stated branch arrangement pay?","options":["$150,000 to the surviving child and $75,000 to each grandchild in the other branch","$100,000 to all three living people regardless of branch","$300,000 to the surviving child and nothing to the deceased child’s branch","$150,000 to each grandchild and nothing to the surviving child"],"answer":0,"explanations":["Half belongs to each original child branch; the deceased child’s half divides between two descendants.","Equal per-head division ignores the stated two-branch arrangement.","That ignores the preserved branch.","It excludes the surviving child’s branch without a stated basis."],"topics":["5.2.01"],"review":0,"lesson":"33","domain":4,"explanation":"Half belongs to each original child branch; the deceased child’s half divides between two descendants."},{"id":"L33-03","prompt":"Which designation ordinarily sends life proceeds into the insured’s estate administration?","options":["An eligible adult named directly","The insured’s estate","A properly designated continuing trust","An eligible contingent taking under the policy"],"answer":1,"explanations":["A direct eligible beneficiary generally receives the proceeds outside probate.","The estate designation directs payment into estate administration.","A continuing trust is a different recipient and management arrangement.","A contingent can receive directly when eligible under the designation."],"topics":["5.2.02"],"review":1,"lesson":"33","domain":4,"explanation":"The estate designation directs payment into estate administration."},{"id":"L33-04","prompt":"An owner wants benefits managed for a young child. What needs attention beyond naming the child?","options":["Only the producer’s commission schedule","Whether the child prefers monthly premium notices","A lawful recipient or management arrangement appropriate for the minor","An automatic change of the insured to the guardian"],"answer":2,"explanations":["Compensation does not solve benefit management.","Premium notice preference does not supply legal authority.","The minor’s entitlement and the authority to receive/manage funds are distinct.","Naming a manager does not change the insured life."],"topics":["5.2.03"],"review":1,"lesson":"33","domain":4,"explanation":"The minor’s entitlement and the authority to receive/manage funds are distinct."},{"id":"L33-05","prompt":"A properly established trust is the designated beneficiary. Who manages the received funds under that arrangement?","options":["Every relative can withdraw freely.","The producer personally decides all distributions.","The insurer necessarily changes the insured to the trustee.","The trustee acts under the trust’s terms and applicable law."],"answer":3,"explanations":["A trust does not grant unrestricted access to every relative.","The producer does not gain trustee authority from selling the policy.","A beneficiary arrangement does not substitute the insured.","The trust supplies the governing management arrangement."],"topics":["5.2.04"],"review":1,"lesson":"33","domain":4,"explanation":"The trust supplies the governing management arrangement."},{"id":"L33-06","prompt":"Which label concerns whether a beneficiary interest can restrict changes without consent?","options":["Irrevocable","Contingent","Per capita","Estate"],"answer":0,"explanations":["Irrevocability concerns protected rights and restrictions on changing them.","Contingent concerns succession priority.","Per capita concerns class distribution.","Estate identifies a recipient."],"topics":["5.2.06"],"review":2,"lesson":"33","domain":4,"explanation":"Irrevocability concerns protected rights and restrictions on changing them."},{"id":"L33-07","prompt":"In the Maryland policy example discussed in MIA Bulletin 26-22, the former spouse remained the named beneficiary after divorce. What did the Administration require?","options":["Automatic payment to the insured’s newest spouse","Payment to the named former spouse under the Maryland policy, rather than importing Pennsylvania’s automatic divorce rule","Automatic cancellation of the policy at divorce","Return of premiums without considering the designation"],"answer":1,"explanations":["The facts did not establish a new designation.","The bulletin’s result depended on the governing Maryland policy and unchanged designation.","Divorce did not automatically cancel this life contract.","The valid benefit designation was central to the claim."],"topics":["5.2.07"],"review":3,"lesson":"33","domain":4,"explanation":"The bulletin’s result depended on the governing Maryland policy and unchanged designation."},{"id":"L33-08","prompt":"A stated policy requires the primary beneficiary to survive the insured by 30 days. The primary dies two days later; an eligible contingent survives. Apply only that stated valid clause. Who takes?","options":["The primary’s estate necessarily takes because two days is enough.","The insurer keeps every premium and benefit.","The contingent takes because the primary failed the required period.","Every relative receives an equal share."],"answer":2,"explanations":["The clause expressly requires 30 days.","The clause redirects the benefit; it does not automatically forfeit it.","The stated survival requirement was not met by the primary.","No equal-relative distribution is stated."],"topics":["5.2.08"],"review":4,"lesson":"33","domain":4,"explanation":"The stated survival requirement was not met by the primary."},{"id":"L33-09","prompt":"As of September 12, 2026, before Chapter 509 takes effect, a Maryland policy has no contrary distribution clause and there is insufficient evidence the insured and primary died other than simultaneously. Which assumption follows the current §10-804?","options":["The beneficiary is always deemed to survive by 30 days.","The benefit is always forfeited.","The insurer may select whichever assumption costs less.","Distribute as though the insured survived the beneficiary."],"answer":3,"explanations":["The pre-October statute does not create that 30-day assumption.","The statute directs distribution rather than forfeiture.","The statutory assumption is not discretionary pricing.","This is the expressly dated current rule; the lesson separately identifies the October change."],"topics":["5.2.08"],"review":4,"lesson":"33","domain":4,"explanation":"This is the expressly dated current rule; the lesson separately identifies the October change."},{"id":"L33-10","prompt":"What best describes a facility-of-payment provision?","options":["A limited permission to pay specified eligible recipients under stated conditions","An unrestricted power to ignore any valid beneficiary","An automatic transfer of ownership to every claimant","A guarantee that all claims pay the employer"],"answer":0,"explanations":["The actual clause and statutory conditions govern it.","The permission has defined circumstances and recipients.","Payment authority is different from assigning ownership.","There is no universal employer-payment rule."],"topics":["5.2.09"],"review":5,"lesson":"33","domain":4,"explanation":"The actual clause and statutory conditions govern it."}]},{"id":"34","number":34,"title":"Policy clocks: return, premium grace and contestability","version":1,"questions":[{"id":"L34-01","prompt":"Which event starts the general ten-day return opportunity described in Maryland §16-105?","options":["The applicant’s next birthday","Delivery of the policy to the policyholder","The first anniversary regardless of delivery","The beneficiary’s later claim"],"answer":1,"explanations":["A birthday is not the stated trigger.","The notice measures the period from delivery.","An anniversary does not replace delivery.","The return opportunity is not measured from a death claim."],"topics":["5.1.04"],"review":1,"lesson":"34","domain":4,"explanation":"The notice measures the period from delivery."},{"id":"L34-02","prompt":"Which statement correctly distinguishes the refund rules taught here?","options":["All life contracts always require the same refund formula.","A thirty-day grace period is a thirty-day full-refund period.","Read the general statutory notice, any more favorable policy right and the separate replacement rule.","Variable replacement returns always erase every investment loss."],"answer":2,"explanations":["Contract and transaction rules can differ.","Grace concerns premium payment and continuing coverage.","These sources answer distinct return questions.","The variable replacement formula is not a guarantee against investment loss."],"topics":["5.1.04"],"review":1,"lesson":"34","domain":4,"explanation":"These sources answer distinct return questions."},{"id":"L34-03","prompt":"Using only the teaching amounts, how much more do twelve $55 monthly payments cost than a $600 annual payment?","options":["$5","$55","$660","$60"],"answer":3,"explanations":["The monthly amount alone does not give the annual difference.","Subtract the annual totals, not one installment.","$660 is the monthly plan’s total, before comparison.","Twelve times $55 is $660; subtract $600 to obtain $60."],"topics":["5.1.05"],"review":2,"lesson":"34","domain":4,"explanation":"Twelve times $55 is $660; subtract $600 to obtain $60."},{"id":"L34-04","prompt":"Which premium ordinarily receives the standard individual-life grace protection described in §16-202?","options":["A required premium after the first","Every initial application premium even when no coverage exists","Only premiums owed after the insured dies","Only a producer’s licensing fee"],"answer":0,"explanations":["The statute expressly addresses premiums after the first.","Initial coverage depends on the actual agreement, not automatic renewal grace.","The provision concerns continuing premium obligations.","A licensing fee is not a policy premium."],"topics":["5.1.06"],"review":3,"lesson":"34","domain":4,"explanation":"The statute expressly addresses premiums after the first."},{"id":"L34-05","prompt":"A covered death occurs during valid grace. The stated benefit is $100,000 and a permitted $600 overdue-premium deduction is the only adjustment. What is the net amount?","options":["$100,600","$99,400","$600","$0 because the due date passed"],"answer":1,"explanations":["The overdue premium is deducted, not added.","$100,000 minus $600 equals $99,400.","The premium deduction is not the death benefit.","The stated grace period keeps coverage in force."],"topics":["5.1.06"],"review":3,"lesson":"34","domain":4,"explanation":"$100,000 minus $600 equals $99,400."},{"id":"L34-06","prompt":"What is the lifetime condition in Maryland’s standard individual-life incontestability provision?","options":["Two years after the beneficiary files a claim","Thirty days after every premium due date","Two years in force during the insured’s lifetime after issue","Five years after the insured’s death"],"answer":2,"explanations":["The claim-filing date is not the starting event.","That is not the validity-contest period.","This identifies the statutory lifetime condition.","A post-death waiting period is not the rule."],"topics":["5.1.08"],"review":4,"lesson":"34","domain":4,"explanation":"This identifies the statutory lifetime condition."},{"id":"L34-07","prompt":"The insured dies 18 months after issue, but the claim is submitted after 30 months. What does the later claim date establish about the two-year lifetime condition?","options":["It automatically adds twelve months to the insured’s lifetime.","It automatically makes every application answer immaterial.","It requires immediate forfeiture without investigation.","It does not establish two years in force during the insured’s lifetime."],"answer":3,"explanations":["Time after death is not additional lifetime coverage.","Materiality and other claim rules remain separate.","A contestable claim still requires lawful review.","The insured lived only eighteen months after issue in these facts."],"topics":["5.1.08"],"review":4,"lesson":"34","domain":4,"explanation":"The insured lived only eighteen months after issue in these facts."},{"id":"L34-08","prompt":"After three years in force during the insured’s lifetime, a covered death occurs during valid grace. No exclusion applies. A $100,000 benefit has only a permitted $500 overdue-premium deduction. Which result follows?","options":["$99,500, with grace and incontestability addressing separate issues","$0 solely because the premium due date passed","$100,500 because the premium becomes an additional benefit","The insurer can ignore the stated lifetime period and cancel for any old answer"],"answer":0,"explanations":["Apply the deduction while separately respecting continuing grace and validity protections.","Valid grace prevents that immediate-lapse assumption.","An overdue premium is deducted.","The validity challenge is constrained by the incontestability provision."],"topics":["5.1.06","5.1.08"],"review":5,"lesson":"34","domain":4,"explanation":"Apply the deduction while separately respecting continuing grace and validity protections."}]},{"id":"35","number":35,"title":"Reinstatement, exclusions and accurate policy dates","version":1,"questions":[{"id":"L35-01","prompt":"For the standard ordinary individual-life reinstatement provision, the three-year window runs from which event?","options":["The due date of the first premium in default","The most recent beneficiary change","The date the producer first calls after lapse","The date a future death claim is filed"],"answer":0,"explanations":["The first defaulted premium’s due date is the statutory trigger.","Changing a beneficiary does not restart this window.","A service call does not establish the statutory start.","A death claim is not the reinstatement-window trigger."],"topics":["5.1.07"],"review":0,"lesson":"35","domain":4,"explanation":"The first defaulted premium’s due date is the statutory trigger."},{"id":"L35-02","prompt":"An ordinary policy lapsed one year ago but was later surrendered for its cash value. Which conclusion fits the standard provision?","options":["Reinstatement is automatic because fewer than three years passed.","Cash surrender prevents use of this stated reinstatement provision.","Only a beneficiary’s signature is needed.","The original premium is automatically refunded again."],"answer":1,"explanations":["Time alone does not satisfy eligibility.","The standard provision excludes a policy surrendered for cash.","A signature does not reverse the cash surrender under this rule.","The provision does not promise a second surrender payment."],"topics":["5.1.07"],"review":0,"lesson":"35","domain":4,"explanation":"The standard provision excludes a policy surrendered for cash."},{"id":"L35-03","prompt":"Which statement is central to the contest allowed by Maryland §16-107 after reinstatement?","options":["Every statement on any old application becomes contestable forever.","The reinstated policy can never be contested.","The disputed fact was fraudulent or misrepresented and material to reinstatement, under the applicable period and conditions.","A beneficiary change restarts every original policy exclusion."],"answer":2,"explanations":["The statute has a subject, period and conditions.","It expressly permits the specified reinstatement contest.","This identifies the relevant statement and legal limitations.","A beneficiary change is not the described reinstatement event."],"topics":["5.1.07","5.1.08"],"review":1,"lesson":"35","domain":4,"explanation":"This identifies the relevant statement and legal limitations."},{"id":"L35-04","prompt":"Use the expressly stated proportional formula: $100,000 coverage, $200 paid, and $250 needed at the correct age for that same coverage. What is the adjusted benefit?","options":["$125,000","$100,000","$50,000","$80,000"],"answer":3,"explanations":["That reverses the premium ratio.","The assumed correct-age rate purchases less coverage.","The paid premium is 80%, not 50%, of the correct amount.","$200 ÷ $250 × $100,000 = $80,000."],"topics":["5.1.09"],"review":2,"lesson":"35","domain":4,"explanation":"$200 ÷ $250 × $100,000 = $80,000."},{"id":"L35-05","prompt":"A policy contains a misstated-sex adjustment clause using the insurance charge at the correct lawful rate. What should the producer apply?","options":["The actual permitted adjustment formula in that contract","Automatic cancellation in every state","The age-only statute as proof no contract can mention sex","An assumed equal-dollar benefit change for every insured"],"answer":0,"explanations":["The contract mechanism and governing law determine the correction.","An adjustment clause does not establish universal cancellation.","An age statute does not describe every product’s full clause.","No equal-dollar universal formula is supplied."],"topics":["5.1.09"],"review":2,"lesson":"35","domain":4,"explanation":"The contract mechanism and governing law determine the correction."},{"id":"L35-06","prompt":"Which statement accurately describes the Maryland suicide-exclusion rules taught here?","options":["Every new issue restarts two years for every dollar of replaced coverage.","Read the permitted period, same-insurer continuity rules and actual minimum or more favorable payment terms.","Every excluded claim necessarily pays zero.","Incontestability and suicide exclusion are the same provision."],"answer":1,"explanations":["The statute has continuity rules for prior coverage.","These separate conditions determine the result.","The statute provides a payment floor for permitted exclusions.","One concerns a stated cause; the other limits a validity contest."],"topics":["5.1.10"],"review":3,"lesson":"35","domain":4,"explanation":"These separate conditions determine the result."},{"id":"L35-07","prompt":"A hypothetical permitted clause excludes death caused by war. An insured service member dies of an unrelated illness in peacetime. What does military membership alone prove under this stated wording?","options":["It proves death was caused by war.","It automatically cancels the contract.","It does not establish the required war-related cause.","It converts the policy into accidental-death coverage."],"answer":2,"explanations":["Membership and cause of death are different facts.","The stated cause-based clause requires its trigger.","Apply the wording actually supplied rather than invent a status clause.","No conversion is described."],"topics":["5.1.11"],"review":4,"lesson":"35","domain":4,"explanation":"Apply the wording actually supplied rather than invent a status clause."},{"id":"L35-08","prompt":"A producer falsely dates an application two months earlier so the insured appears eligible for a lower age-based premium. Is the six-month policy-date rule permission for that act?","options":["Yes, any application date within six months is permitted.","Yes, if the beneficiary agrees.","Yes, because only the policyholder can violate the statute.","No; the statute separately prohibits the described false earlier application date."],"answer":3,"explanations":["A policy-date allowance is not permission to falsify the application.","Beneficiary consent does not remove the prohibition.","The producer is expressly addressed.","Section 16-104(b) separately governs that conduct."],"topics":["5.1.13"],"review":5,"lesson":"35","domain":4,"explanation":"Section 16-104(b) separately governs that conduct."},{"id":"L35-09","prompt":"A policy reduces an otherwise payable benefit solely because the same insurer issued another policy on the insured. Which rule is relevant?","options":["Maryland’s prohibition on that same-insurer reduction provision","The primary beneficiary’s survival period","The industrial-life reinstatement deadline","The contingent beneficiary’s priority"],"answer":0,"explanations":["Section 16-216 directly addresses this prohibited provision.","Survival timing does not authorize this reduction.","Reinstatement timing is a different issue.","Recipient priority does not authorize this reduction."],"topics":["5.1.13"],"review":5,"lesson":"35","domain":4,"explanation":"Section 16-216 directly addresses this prohibited provision."}]},{"id":"36","number":36,"title":"Death-benefit payment options: what is fixed?","version":1,"questions":[{"id":"L36-01","prompt":"A beneficiary receives the entire payable death benefit in one check. Which payment form is this?","options":["Fixed amount installments","Lump sum","Interest only","Life with a period certain"],"answer":1,"explanations":["Installments require a payment series.","One payment of the proceeds is a lump sum.","Interest only leaves principal under an arrangement.","A lifetime payment promise is not described."],"topics":["5.3.01"],"review":0,"lesson":"36","domain":4,"explanation":"One payment of the proceeds is a lump sum."},{"id":"L36-02","prompt":"An available arrangement retains $100,000 principal and pays simple annual interest at an assumed 3%, with no other adjustment. What is the full-year interest?","options":["$300","$30,000","$3,000","$103,000"],"answer":2,"explanations":["That is 0.3% of the principal.","That is 30% of the principal.","$100,000 multiplied by 0.03 is $3,000.","$103,000 combines principal and interest, rather than interest alone."],"topics":["5.3.02"],"review":1,"lesson":"36","domain":4,"explanation":"$100,000 multiplied by 0.03 is $3,000."},{"id":"L36-03","prompt":"Elena first selects a ten-year distribution period. The insurer determines the scheduled amount from proceeds and applicable interest. Which option is described?","options":["Interest only","Straight single life","Fixed amount","Fixed period"],"answer":3,"explanations":["The example distributes over a chosen period rather than paying only earnings.","Ten years alone is not a lifetime promise.","Here she selected years first, not a dollar payment.","The selected duration identifies fixed period."],"topics":["5.3.03"],"review":2,"lesson":"36","domain":4,"explanation":"The selected duration identifies fixed period."},{"id":"L36-04","prompt":"Assume $120,000, no interest and no fees. A fixed-amount option pays $2,000 monthly. How long does that principal support payments?","options":["60 months","120 months","24 months","The beneficiary’s entire lifetime regardless of age"],"answer":0,"explanations":["$120,000 divided by $2,000 is sixty monthly payments.","That would correspond to $1,000 monthly under these assumptions.","Twenty-four payments would use only $48,000.","No lifetime guarantee is included."],"topics":["5.3.04"],"review":3,"lesson":"36","domain":4,"explanation":"$120,000 divided by $2,000 is sixty monthly payments."},{"id":"L36-05","prompt":"A straight single-life income option has no period-certain or refund feature. What ends its payments?","options":["A ten-year anniversary in every case","Death of its measuring life","The original life policy’s first premium anniversary","Death of any relative named in a will"],"answer":1,"explanations":["No fixed ten-year ending is supplied.","The measuring lifetime determines this stated form.","An original premium anniversary is unrelated to this income duration.","The specified measuring life matters."],"topics":["5.3.05","5.3.06"],"review":4,"lesson":"36","domain":4,"explanation":"The measuring lifetime determines this stated form."},{"id":"L36-06","prompt":"Life income with ten years certain begins. The measuring life survives for 16 years. Which statement fits the stated option?","options":["Payments necessarily stopped after ten years.","The tenth anniversary required repayment of all earlier income.","Lifetime payments continue beyond ten years while that person lives.","The option automatically becomes interest-only in year eleven."],"answer":2,"explanations":["The ten-year term is a minimum guarantee, not the end of the lifetime promise.","No repayment condition is described.","The lifetime component continues beyond the guaranteed minimum.","No automatic conversion is stated."],"topics":["5.3.05","5.3.06"],"review":4,"lesson":"36","domain":4,"explanation":"The lifetime component continues beyond the guaranteed minimum."},{"id":"L36-07","prompt":"A joint-and-survivor option explicitly continues 75% of an initial $2,000 monthly payment after the first covered person dies. What does the survivor receive?","options":["$2,750","$500","$2,000","$1,500"],"answer":3,"explanations":["The continuation is multiplication, not addition.","$500 is the reduction, not the remaining payment.","That would require a 100% continuation feature.","0.75 times $2,000 equals $1,500."],"topics":["5.3.07"],"review":4,"lesson":"36","domain":4,"explanation":"0.75 times $2,000 equals $1,500."},{"id":"L36-08","prompt":"Under Maryland §16-109, proof of death is first submitted more than 180 days after death. Proceeds are paid later. What is the statutory interest starting point?","options":["The date proof of death is submitted","Always the date the policy was originally issued","Always the insured’s birth date","Thirty days after the beneficiary’s first withdrawal"],"answer":0,"explanations":["The late-proof exception uses the submitted-proof date.","Policy issue is not the death-proceeds interest start.","A birth date is not part of this calculation.","A later settlement withdrawal is a separate event."],"topics":["5.1.12"],"review":5,"lesson":"36","domain":4,"explanation":"The late-proof exception uses the submitted-proof date."},{"id":"L36-09","prompt":"A producer discusses a settlement option listed in a textbook. What should be confirmed before representing that a beneficiary can choose it?","options":["Only the beneficiary’s preferred nickname","The actual contract’s available options and any binding owner instructions","That every insurer uses the same current interest rate","That the policy can still be sold after the insured’s death"],"answer":1,"explanations":["Naming preferences do not establish a payment right.","Availability and binding instructions determine the actual choice.","There is no universal current rate.","A policy sale is a different transaction from death-claim distribution."],"topics":["5.3.01"],"review":0,"lesson":"36","domain":4,"explanation":"Availability and binding instructions determine the actual choice."}]},{"id":"37","number":37,"title":"Stopping premiums: preserve the value already built","version":1,"questions":[{"id":"L37-01","prompt":"A policy’s current value is $12,000 before a separately listed $2,000 debt. No other adjustment applies. What cash-surrender payment follows?","options":["$14,000","$12,000","$10,000","$2,000"],"answer":2,"explanations":["Debt is deducted rather than added.","The stated value is before the debt.","$12,000 minus $2,000 equals $10,000.","The debt is the deduction, not the remaining value."],"topics":["5.4.01"],"review":1,"lesson":"37","domain":4,"explanation":"$12,000 minus $2,000 equals $10,000."},{"id":"L37-02","prompt":"A surrender quote expressly states $9,500 NET of all debt and charges. What payment follows if there are no later adjustments?","options":["$11,000","$8,000","$1,500","$9,500"],"answer":3,"explanations":["The net quote already reflects adjustments.","That would deduct an already included adjustment again.","The question gives the final quote, not a separate payable debt.","Use the stated net amount without subtracting debt twice."],"topics":["5.4.01"],"review":1,"lesson":"37","domain":4,"explanation":"Use the stated net amount without subtracting debt twice."},{"id":"L37-03","prompt":"The policy table offers $100,000 of extended term for eight years. No riders or debt apply. Which covered death falls within that stated protection?","options":["Death seven years after the extended term begins","Death nine years after the extended term begins","Only death on the first day","Every later death because the former policy was whole life"],"answer":0,"explanations":["Seven years is within the eight-year purchased period.","Nine years exceeds it.","The protection lasts for the stated period, not one day.","The selected option provides a limited term."],"topics":["5.4.02"],"review":2,"lesson":"37","domain":4,"explanation":"Seven years is within the eight-year purchased period."},{"id":"L37-04","prompt":"An owner selects reduced paid-up whole life of $32,000 instead of continuing premiums on $100,000 coverage. Which description fits?","options":["An additional $32,000 rider on top of the old amount","A smaller permanent base benefit with no further required premiums for that benefit","The same $100,000 benefit for precisely eight years","A cash payment of $32,000 followed by full original coverage"],"answer":1,"explanations":["The choice reduces the base benefit; it does not add to it.","This identifies reduced paid-up nonforfeiture.","That describes a different hypothetical extended-term offer.","Reduced paid-up is continuing insurance, not that cash transaction."],"topics":["5.4.03"],"review":3,"lesson":"37","domain":4,"explanation":"This identifies reduced paid-up nonforfeiture."},{"id":"L37-05","prompt":"No other available option is elected within the stated sixty-day Maryland period. Which benefit becomes effective under §16-303(c)?","options":["Extended term in every policy regardless of wording","Full cash surrender in every policy","The paid-up nonforfeiture benefit specified in the policy","The original full benefit with every future premium waived"],"answer":2,"explanations":["The statute refers to the specified benefit, not one universal form.","It does not automatically choose cash in every case.","The policy’s specified default controls under the applicable rule.","That would invent an unlimited waiver."],"topics":["5.4.02","5.4.03"],"review":4,"lesson":"37","domain":4,"explanation":"The policy’s specified default controls under the applicable rule."},{"id":"L37-06","prompt":"A client’s stated objective is a smaller permanent death benefit with no further base premiums. Which offered option best matches that objective?","options":["Cash surrender","Extended term","An automatic premium loan","Reduced paid-up whole life"],"answer":3,"explanations":["Cash surrender ends the surrendered protection.","Extended term is temporary.","A premium loan adds debt to pay a premium.","It supplies the stated smaller permanent paid-up benefit."],"topics":["5.4.03"],"review":5,"lesson":"37","domain":4,"explanation":"It supplies the stated smaller permanent paid-up benefit."},{"id":"L37-07","prompt":"A policy offers surrender value in year two under terms more favorable than the statutory minimum. What should the producer explain?","options":["Apply the actual more favorable value in the policy.","Every ordinary policy must show zero until year three.","The beneficiary alone receives surrender value.","Earlier value converts the policy into an annuity."],"answer":0,"explanations":["The statutory minimum does not prohibit more favorable value.","That confuses a minimum requirement with a prohibition.","Surrender is an owner right subject to applicable restrictions.","Earlier value does not change the contract type."],"topics":["5.4.01"],"review":4,"lesson":"37","domain":4,"explanation":"The statutory minimum does not prohibit more favorable value."},{"id":"L37-08","prompt":"A client chooses cash surrender, receives the net amount and ends the policy. What should not be promised under the standard Maryland reinstatement provision?","options":["That the surrendered death protection ends","An automatic right to restore the cash-surrendered policy later","That tax consequences should be reviewed","That the current surrender quote matters"],"answer":1,"explanations":["That is a consequence of the stated surrender.","Cash surrender is an express exclusion from the standard reinstatement right.","Reviewing consequences is appropriate.","The current quote is relevant."],"topics":["5.4.01"],"review":1,"lesson":"37","domain":4,"explanation":"Cash surrender is an express exclusion from the standard reinstatement right."}]},{"id":"38","number":38,"title":"Policy loans and withdrawals: follow the remaining value","version":1,"questions":[{"id":"L38-01","prompt":"What primarily limits a policy cash loan under the stated feature?","options":["The policy’s entire face amount regardless of value","Available loan value and the applicable contractual conditions","The beneficiary’s desired inheritance","The original application’s requested amount even if declined"],"answer":1,"explanations":["Face amount alone is not available loan value.","The current value and conditions establish the permitted advance.","An inheritance preference does not create loan security.","A requested but unissued amount does not establish a loan right."],"topics":["5.5.01"],"review":0,"lesson":"38","domain":4,"explanation":"The current value and conditions establish the permitted advance."},{"id":"L38-02","prompt":"A covered $200,000 benefit has $20,000 loan principal and $1,000 unpaid interest. No other adjustment applies. What is payable?","options":["$180,000","$181,000","$179,000","$200,000"],"answer":2,"explanations":["This omits the unpaid interest.","Interest is deducted rather than added.","$200,000 minus $21,000 equals $179,000.","Outstanding debt affects the stated net proceeds."],"topics":["5.5.01"],"review":1,"lesson":"38","domain":4,"explanation":"$200,000 minus $21,000 equals $179,000."},{"id":"L38-03","prompt":"Which statement accurately distinguishes Maryland’s automatic-premium-loan provision from its use?","options":["Every term policy must automatically lend its face amount.","The owner’s election never matters.","A provision guarantees sufficient cash value for every premium.","Covered policies provide the stated provision, but its use depends on election and the applicable value and conditions."],"answer":3,"explanations":["Term policies are outside §16-207 and face amount is not loan value.","The statute expressly makes use subject to election.","A provision does not create unlimited security.","This preserves the distinction between required provision and eligible elected use."],"topics":["5.5.02","5.5.05"],"review":2,"lesson":"38","domain":4,"explanation":"This preserves the distinction between required provision and eligible elected use."},{"id":"L38-04","prompt":"An elected automatic premium loan pays a $600 premium. Assume 5% simple interest for a full year, no payments and no other debt. What debt results?","options":["$630","$600","$570","$30"],"answer":0,"explanations":["Five percent of $600 is $30, added to principal.","This omits the assumed interest.","Loan interest increases rather than decreases the debt.","$30 is interest alone."],"topics":["5.5.02"],"review":2,"lesson":"38","domain":4,"explanation":"Five percent of $600 is $30, added to principal."},{"id":"L38-05","prompt":"Which action removes part of a permitted policy’s value rather than creating a loan balance under that transaction?","options":["Automatic premium loan","Partial withdrawal","Policy cash loan","Capitalizing unpaid loan interest"],"answer":1,"explanations":["This creates debt to fund premium.","A withdrawal removes value under the feature.","A cash loan creates debt secured by the policy.","Capitalizing interest increases debt."],"topics":["5.5.03"],"review":3,"lesson":"38","domain":4,"explanation":"A withdrawal removes value under the feature."},{"id":"L38-06","prompt":"Marcus uses an ordinary policy loan to pay tuition. What follows from the educational use alone?","options":["It becomes a federal student loan.","Interest automatically disappears.","It remains a policy loan with its contractual consequences.","The death benefit can no longer be reduced by its unpaid balance."],"answer":2,"explanations":["The use does not change the lender or legal loan program.","The policy-loan interest provision still applies.","Purpose alone does not replace the loan mechanism.","Its unpaid balance still affects the applicable net benefit."],"topics":["5.5.04"],"review":4,"lesson":"38","domain":4,"explanation":"Purpose alone does not replace the loan mechanism."},{"id":"L38-07","prompt":"Which answer correctly describes the standard rate choices in Maryland §16-208 for policies issued on or after July 1, 1983?","options":["A universal fixed 6% maximum only","An unlimited adjustable rate without a formula","A zero rate for every loan used by a parent","A fixed maximum no greater than 8%, or an adjustable maximum under the statutory formula"],"answer":3,"explanations":["The modern section provides the two stated alternatives.","The adjustable maximum has a legal formula.","The owner’s family role does not erase interest.","This identifies the statutory alternatives without promising a particular carrier rate."],"topics":["5.5.01"],"review":5,"lesson":"38","domain":4,"explanation":"This identifies the statutory alternatives without promising a particular carrier rate."},{"id":"L38-08","prompt":"Under §16-207’s deferral provision, which loan is treated differently from other policy loans?","options":["A loan to pay a premium to the insurer","A loan used for a vacation","A loan used for an unrelated household purchase","A loan used for a private tuition bill"],"answer":0,"explanations":["The provision excepts the premium-payment purpose from the six-month deferral.","A vacation purpose does not create this statutory exception.","An unrelated purchase is not payment of premium to the insurer.","A tuition payment is not the stated premium-purpose exception."],"topics":["5.5.01","5.5.02"],"review":5,"lesson":"38","domain":4,"explanation":"The provision excepts the premium-payment purpose from the six-month deferral."},{"id":"L38-09","prompt":"Which condition belongs to the stated debt-based termination provision in §16-207(e)?","options":["Termination whenever the owner changes a beneficiary","Debt reaching the loan value and at least thirty days’ mailed notice to the specified parties","Automatic termination after any small cash withdrawal","Termination without notice whenever an interest rate changes"],"answer":1,"explanations":["Changing a beneficiary is not that debt trigger.","Both the debt threshold and stated notice requirements matter.","A withdrawal is a different transaction and not this automatic rule.","The statutes include notice and adjustable-rate protections."],"topics":["5.5.01"],"review":5,"lesson":"38","domain":4,"explanation":"Both the debt threshold and stated notice requirements matter."}]},{"id":"39","number":39,"title":"Dividends: choose what the money does","version":1,"questions":[{"id":"L39-01","prompt":"What does participating describe in a life policy?","options":["Eligibility to share in policy dividends under its terms","A guarantee that next year’s dividend equals this year’s","A guarantee that the policy is temporary","A promise that premiums stop after the first dividend"],"answer":0,"explanations":["Participation concerns the policy’s share in divisible surplus.","Future dividends are not guaranteed by past payments.","Duration is a separate policy classification.","A dividend does not end every future premium obligation."],"topics":["3.6.04"],"review":0,"lesson":"39","domain":2,"explanation":"Participation concerns the policy’s share in divisible surplus."},{"id":"L39-02","prompt":"A $400 declared dividend is applied to a $1,200 premium. With no other credits, what remains due?","options":["$1,600","$800","$400","$1,200"],"answer":1,"explanations":["Applying a credit reduces the amount due.","$1,200 minus $400 equals $800.","That is the dividend applied, not the remaining premium.","This ignores the stated dividend credit."],"topics":["5.6.02"],"review":1,"lesson":"39","domain":4,"explanation":"$1,200 minus $400 equals $800."},{"id":"L39-03","prompt":"Elena wants to receive her declared dividend as money while keeping the policy under its terms. Which choice fits?","options":["Reduced paid-up nonforfeiture","Full policy surrender","Cash dividend","One-year term purchase"],"answer":2,"explanations":["That changes the base insurance using policy value.","That ends the surrendered protection.","Cash distributes the available dividend without being a full surrender.","That buys temporary additional protection."],"topics":["5.6.01"],"review":1,"lesson":"39","domain":4,"explanation":"Cash distributes the available dividend without being a full surrender."},{"id":"L39-04","prompt":"A $400 dividend remains for one full year at 3% simple interest, with no other changes. What is the resulting balance before tax?","options":["$12","$388","$403","$412"],"answer":3,"explanations":["That is interest alone.","Interest is added rather than subtracted.","Three percent of $400 is $12, not $3.","$400 plus $12 equals $412."],"topics":["5.6.03"],"review":2,"lesson":"39","domain":4,"explanation":"$400 plus $12 equals $412."},{"id":"L39-05","prompt":"Which available dividend choice buys additional temporary protection for the stated year?","options":["One-year term purchase","Paid-up additional whole life","Reduced paid-up whole life","Interest accumulation"],"answer":0,"explanations":["This purchases the specified temporary additional insurance.","Paid-up additional whole life is permanent.","That is a base-policy nonforfeiture choice.","That leaves money to earn interest instead of buying the stated coverage."],"topics":["5.6.04"],"review":3,"lesson":"39","domain":4,"explanation":"This purchases the specified temporary additional insurance."},{"id":"L39-06","prompt":"A stated offer uses a $400 dividend to purchase $2,000 of paid-up additional whole life. Which conclusion is correct?","options":["The owner can immediately withdraw $2,000 cash with no insurance consequence.","The addition requires no further premiums for that purchased benefit, while the base policy may still require premiums.","The original base policy is automatically fully paid up.","The additional protection must expire in one year."],"answer":1,"explanations":["The $2,000 is insurance amount, not an immediate cash account.","Paid-up status describes the purchased addition in these facts.","An addition does not discharge the base premium obligation.","The offer is additional whole life, not one-year term."],"topics":["5.6.05"],"review":3,"lesson":"39","domain":4,"explanation":"Paid-up status describes the purchased addition in these facts."},{"id":"L39-07","prompt":"A projection shows future dividends covering premiums from year fifteen. What must the producer explain?","options":["Every projected dividend becomes guaranteed once illustrated.","The owner has already elected reduced paid-up nonforfeiture.","Projected premium offset is not confirmation of paid-up status, and lower dividends can require further payments.","The projection automatically converts additions to cash."],"answer":2,"explanations":["An illustration does not guarantee future dividends.","A projection is not that separate election.","The owner must distinguish contingent funding from an actual completed obligation.","No such automatic conversion follows from the projection."],"topics":["5.6.06","5.6.02"],"review":4,"lesson":"39","domain":4,"explanation":"The owner must distinguish contingent funding from an actual completed obligation."},{"id":"L39-08","prompt":"Under a permitted arrangement, actual accumulated dividend values complete the amount needed to pay up the existing policy earlier. What objective does that describe?","options":["Buying a new one-year term addition","Taking the dividend in cash","Leaving every dividend unused indefinitely","Shortening the existing premium-paying period to achieve paid-up insurance"],"answer":3,"explanations":["The scenario concerns funding the existing policy.","The values are applied to an insurance objective, not distributed as cash.","The stated values are being used.","This is the paid-up-insurance objective described in the outline."],"topics":["5.6.06"],"review":4,"lesson":"39","domain":4,"explanation":"This is the paid-up-insurance objective described in the outline."},{"id":"L39-09","prompt":"Which statement fits Maryland’s participating-policy dividend provision?","options":["It specifies listed choices and permits additional options, subject to its stated exceptions and scope.","It requires every textbook option on every life policy.","It guarantees a positive dividend every year.","It gives the producer sole authority to ignore the owner’s election."],"answer":0,"explanations":["The statutory list and its exceptions must be applied as written.","The provision does not require every optional design universally.","Annual determination does not guarantee a positive amount.","The contract and entitled person’s election govern."],"topics":["5.6.01","5.6.02","5.6.03","5.6.04","5.6.05","5.6.06"],"review":5,"lesson":"39","domain":4,"explanation":"The statutory list and its exceptions must be applied as written."}]},{"id":"40","number":40,"title":"Disability riders: follow the person and the benefit","version":1,"questions":[{"id":"L40-01","prompt":"A rider approves waiver of a $100 monthly premium during qualifying disability. What benefit is established by those facts?","options":["A $100 increase in death benefit each month","The specified premium obligation is waived during the approved period","An automatic $100 spending check plus waiver","A loan of $100 each month secured by cash value"],"answer":1,"explanations":["Premium waiver is not that increasing death benefit.","This identifies the stated waiver.","A separate cash income benefit was not stated.","Waiver does not create automatic policy debt."],"topics":["5.7.01"],"review":1,"lesson":"40","domain":4,"explanation":"This identifies the stated waiver."},{"id":"L40-02","prompt":"A universal-life owner plans to pay $200 monthly. A rider waives only the stated $60 monthly deduction. Which conclusion follows?","options":["The insurer deposits $200 every month.","The owner receives $260 in cash.","The covered $60 charge is waived; a $200 premium deposit has not been promised.","All policy loans disappear when waiver starts."],"answer":2,"explanations":["A waived deduction is different from a premium deposit.","Neither cash payment is supplied by these facts.","Follow the actual deduction covered by the rider.","The waiver does not erase unrelated debt."],"topics":["5.7.02"],"review":2,"lesson":"40","domain":4,"explanation":"Follow the actual deduction covered by the rider."},{"id":"L40-03","prompt":"A rider pays $250 monthly income and separately waives a $60 policy charge. How much spendable income is specified?","options":["$310","$60","$190","$250"],"answer":3,"explanations":["The waived charge is not another cash payment.","That is the waived obligation, not the income benefit.","The scenario does not deduct the waived charge from income.","The rider’s stated income payment is $250."],"topics":["5.7.03"],"review":3,"lesson":"40","domain":4,"explanation":"The rider’s stated income payment is $250."},{"id":"L40-04","prompt":"Elena owns a life policy on her child. The payor rider covers Elena’s qualifying death or disability. Which person’s event activates that rider?","options":["Elena’s qualifying event as the covered adult payer","Only the child’s death","Any beneficiary’s unemployment","Any relative’s retirement"],"answer":0,"explanations":["The rider identifies Elena as the covered payor.","That concerns the child’s base insured event.","Unemployment is not the stated qualifying condition.","Retirement of any relative is not the named trigger."],"topics":["5.7.04"],"review":4,"lesson":"40","domain":4,"explanation":"The rider identifies Elena as the covered payor."},{"id":"L40-05","prompt":"A particular rider requires six consecutive months of total disability. The insured has been disabled for two months. Which response uses the stated facts correctly?","options":["The full waiting requirement is already satisfied.","The two months do not yet satisfy that six-month requirement.","Every disability rider requires exactly two months.","The requirement disappears because the base policy is whole life."],"answer":1,"explanations":["Two months is shorter than the stated requirement.","Apply the actual waiting period given.","The scenario does not create a universal rule.","The base design does not erase rider conditions."],"topics":["5.7.01","5.7.02"],"review":5,"lesson":"40","domain":4,"explanation":"Apply the actual waiting period given."},{"id":"L40-06","prompt":"A client has just submitted a disability-waiver claim. What is the appropriate next explanation?","options":["Stop all premiums immediately regardless of the rider.","The producer can declare the claim approved.","Follow the rider’s payment and proof requirements while the insurer reviews the claim.","The policy automatically becomes reduced paid-up whole life."],"answer":2,"explanations":["Premature nonpayment can endanger coverage.","Approval must follow the applicable claim process.","Submission alone is not approval or a universal payment waiver.","Claim submission is not a nonforfeiture election."],"topics":["5.7.01"],"review":1,"lesson":"40","domain":4,"explanation":"Submission alone is not approval or a universal payment waiver."},{"id":"L40-07","prompt":"The covered parent dies while the child remains alive. The juvenile rider’s conditions are satisfied. Which distinction is correct?","options":["The child’s base death benefit is automatically payable.","The child becomes disabled by definition.","The policy must be surrendered for cash.","The payor benefit can protect premiums without triggering the child’s base death benefit."],"answer":3,"explanations":["The base insured child has not died.","A parent’s death does not define the child as disabled.","The stated rider does not require that surrender.","The rider and base policy insure different stated events."],"topics":["5.7.04"],"review":4,"lesson":"40","domain":4,"explanation":"The rider and base policy insure different stated events."},{"id":"L40-08","prompt":"A rider lists a six-month waiting requirement and a maximum ten-year income-payment period. What do those provisions measure?","options":["Required disability duration before qualification and the maximum income-benefit duration, respectively","The same clock stated two ways","The parent’s age and the child’s age","The policy’s cash value and loan interest"],"answer":0,"explanations":["Waiting and benefit periods serve different functions.","Six months and ten years refer to different conditions.","Neither fact is described as an age.","They are time conditions, not policy-value figures."],"topics":["5.7.03"],"review":5,"lesson":"40","domain":4,"explanation":"Waiting and benefit periods serve different functions."}]},{"id":"41","number":41,"title":"Accelerated benefits: money before death changes what remains","version":1,"questions":[{"id":"L41-01","prompt":"What distinguishes an accelerated life benefit from an ordinary benefit added on top of the original death amount?","options":["Acceleration always creates an equal new policy loan.","Acceleration pays an eligible portion early and reduces the later death benefit.","Acceleration requires the insured to have died.","Acceleration leaves the full original death benefit unchanged in every case."],"answer":1,"explanations":["A loan is a separate mechanism; some acceleration designs use a lien.","This is the essential early-payment and remaining-benefit relationship.","The qualifying payment occurs during the insured’s life.","Reduction is part of the accelerated-benefit concept."],"topics":["5.8.01","5.8.05"],"review":0,"lesson":"41","domain":4,"explanation":"This is the essential early-payment and remaining-benefit relationship."},{"id":"L41-02","prompt":"A rider requires expected confinement for the rest of the insured’s life in an eligible institution. Which fact alone is insufficient?","options":["Medical evidence that the expected confinement is permanent","Confirmation that the institution qualifies","A brief rehabilitation stay with expected discharge","Evidence addressing the actual rider conditions"],"answer":2,"explanations":["This addresses the stated permanence condition.","Facility eligibility is relevant to the trigger.","Temporary confinement does not establish expected lifelong confinement.","Evidence of the actual conditions is relevant."],"topics":["5.8.02"],"review":1,"lesson":"41","domain":4,"explanation":"Temporary confinement does not establish expected lifelong confinement."},{"id":"L41-03","prompt":"Which pair contains two activities of daily living named in the referenced Maryland definition?","options":["Shopping and driving","Investing and budgeting","Cooking and housekeeping","Bathing and dressing"],"answer":3,"explanations":["Those are not the named personal-care activities.","Those financial functions are not the listed activities.","Those household tasks are different from the listed activities.","Bathing and dressing are expressly included."],"topics":["5.8.03"],"review":2,"lesson":"41","domain":4,"explanation":"Bathing and dressing are expressly included."},{"id":"L41-04","prompt":"A $200,000 death benefit has $100,000 accelerated. A stated $10,000 discount produces $90,000 cash. No other change applies. What benefit remains?","options":["$100,000","$110,000","$90,000","$200,000"],"answer":0,"explanations":["Subtract the $100,000 benefit accelerated from $200,000.","That incorrectly subtracts only the cash check.","That is the immediate cash paid, not the remaining benefit.","The original benefit is reduced by the stated acceleration."],"topics":["5.8.05"],"review":3,"lesson":"41","domain":4,"explanation":"Subtract the $100,000 benefit accelerated from $200,000."},{"id":"L41-05","prompt":"When is the stated agent-solicited accelerated-benefit description provided under COMAR 31.09.16.07?","options":["Only after the first claim is denied","Before or concurrently with the application","Only after the insured dies","Only if no illustration is ever supplied"],"answer":1,"explanations":["The disclosure is part of the application process.","That is the stated agent-solicited timing.","An accelerated benefit is a lifetime payment feature.","The description requirement is not removed by that condition."],"topics":["5.8.04"],"review":5,"lesson":"41","domain":4,"explanation":"That is the stated agent-solicited timing."},{"id":"L41-06","prompt":"Which explanation of cash values and loans after acceleration is appropriate?","options":["All existing debt is forgiven automatically.","Every policy must leave cash value unchanged.","Use the actual proportional-reduction or lien method and its effects on value, debt and future access.","The owner can always borrow the entire former death benefit."],"answer":2,"explanations":["Acceleration does not universally forgive debt.","The permitted methods can affect cash value or its availability.","The actual financing method and legal restrictions control.","Former face amount is not unlimited loan value."],"topics":["5.8.06","5.8.07"],"review":4,"lesson":"41","domain":4,"explanation":"The actual financing method and legal restrictions control."},{"id":"L41-07","prompt":"What must be explained at claim time concerning premiums for the remaining life policy?","options":["Premiums automatically stop in every case.","The beneficiary must always pay double.","Only the old illustration matters.","Any continuing premium requirements needed to keep the policy in force."],"answer":3,"explanations":["A waiver is not automatic in every acceleration design.","The rule does not impose that invented obligation.","Current continuing requirements need explanation.","COMAR .09 expressly requires that explanation."],"topics":["5.8.09"],"review":4,"lesson":"41","domain":4,"explanation":"COMAR .09 expressly requires that explanation."},{"id":"L41-08","prompt":"Which statement correctly separates a rider’s trigger from federal tax treatment?","options":["The contract’s benefit trigger and the federal requirements for excluding the payment must each be checked.","Every contract must use the IRS 24-month period as its benefit trigger.","Every accelerated payment is tax-free regardless of recipient and circumstances.","A tax exclusion proves eligibility for every government benefit program."],"answer":0,"explanations":["Contract eligibility and tax treatment are separate analyses.","The federal definition is not automatically every contract’s trigger.","The exclusions have conditions and exceptions.","Government-benefit eligibility can be affected independently."],"topics":["5.8.08"],"review":5,"lesson":"41","domain":4,"explanation":"Contract eligibility and tax treatment are separate analyses."},{"id":"L41-09","prompt":"An irrevocable beneficiary’s rights apply and no exception is stated. What must the insurer obtain under COMAR .05 before acceleration is paid?","options":["Only the producer’s verbal approval","The required signed acknowledgment of concurrence for payout","An automatic replacement application","A new beneficiary designation signed only by the producer"],"answer":1,"explanations":["The identified rights require the stated acknowledgment.","This is the required concurrence under the provision.","Acceleration is not necessarily a replacement transaction.","The producer cannot unilaterally change those rights."],"topics":["5.8.04"],"review":5,"lesson":"41","domain":4,"explanation":"This is the required concurrence under the provision."}]},{"id":"42","number":42,"title":"Family riders: identify whose life is covered","version":1,"questions":[{"id":"L42-01","prompt":"Marcus has a $250,000 base life policy and a $50,000 term rider on Elena. Elena has a covered death while Marcus lives. With no other benefits or adjustments, what is triggered?","options":["$300,000 combined family benefit","$250,000 base benefit","$50,000 Elena rider benefit","No benefit because only base insureds can have coverage"],"answer":2,"explanations":["Marcus’s living status does not trigger his death benefit.","The base benefit insures Marcus’s life.","The stated rider covers Elena’s death.","An eligible other-insured rider can cover another person."],"topics":["5.9.01"],"review":1,"lesson":"42","domain":4,"explanation":"The stated rider covers Elena’s death."},{"id":"L42-02","prompt":"A children’s rider provides $10,000 on each of three eligible children. One child has a covered death. No other benefit applies. What is payable?","options":["$30,000","$20,000","$3,333.33","$10,000"],"answer":3,"explanations":["That combines coverage on living siblings.","Two children’s amounts are not triggered.","The benefit is per child, not one shared amount divided three ways.","The stated benefit on the child who died is $10,000."],"topics":["5.9.02"],"review":2,"lesson":"42","domain":4,"explanation":"The stated benefit on the child who died is $10,000."},{"id":"L42-03","prompt":"A child is named as beneficiary of a parent’s life policy. What does that fact alone establish?","options":["The child is designated to receive the applicable proceeds under the beneficiary terms.","The child’s own life is automatically insured for the base amount.","A children’s rider has automatically been issued.","The child owns every policy right regardless of age and wording."],"answer":0,"explanations":["Beneficiary designation concerns receipt of proceeds.","Insuring the child’s life requires its own coverage.","A designation does not issue a rider.","Ownership is a separate role."],"topics":["5.9.02"],"review":0,"lesson":"42","domain":4,"explanation":"Beneficiary designation concerns receipt of proceeds."},{"id":"L42-04","prompt":"Which description fits a family term structure with separate amounts on a spouse and eligible children?","options":["It must pay the combined amount only at the second spouse’s death.","It assigns coverage to the identified family members under the applicable rider terms.","It automatically insures every distant relative.","It converts every term benefit into permanent whole life."],"answer":1,"explanations":["That describes a different survivorship trigger.","The insured-person map and rider terms control.","Eligibility is defined by the actual contract.","Term coverage does not automatically become permanent."],"topics":["5.9.03"],"review":3,"lesson":"42","domain":4,"explanation":"The insured-person map and rider terms control."},{"id":"L42-05","prompt":"A stated child rider permits conversion of $10,000 coverage into up to five times that amount. What is the stated maximum?","options":["$15,000","$10,005","$50,000","$100,000"],"answer":2,"explanations":["The rule specifies multiplication by five.","Adding five dollars is not the stated calculation.","$10,000 times five equals $50,000.","That would be ten times the original amount."],"topics":["5.9.02"],"review":4,"lesson":"42","domain":4,"explanation":"$10,000 times five equals $50,000."},{"id":"L42-06","prompt":"A conversion right allows an eligible child to convert without new evidence of insurability. What must still be checked?","options":["Nothing; unlimited coverage is free.","Only the former beneficiary’s income","Only the base policy’s original application date","The election deadline, permitted amount, available plan and new premium terms"],"answer":3,"explanations":["Waived evidence does not waive every other condition or premium.","That does not identify the conversion conditions.","The actual conversion provision contains the controlling conditions.","These conditions remain relevant despite the health-evidence protection."],"topics":["5.9.02"],"review":4,"lesson":"42","domain":4,"explanation":"These conditions remain relevant despite the health-evidence protection."},{"id":"L42-07","prompt":"A whole-life base policy includes a term rider on a spouse. Which statement is correct?","options":["The spouse rider can have a different duration and ending conditions from the base policy.","The spouse rider must last for life because the base is permanent.","The spouse is automatically the base insured.","The spouse rider and the beneficiary designation are the same feature."],"answer":0,"explanations":["A term rider follows its own issued terms.","Permanent base coverage does not guarantee permanent rider duration.","The named base insured remains a separate role.","A coverage feature and a proceeds designation are different."],"topics":["5.9.01"],"review":1,"lesson":"42","domain":4,"explanation":"A term rider follows its own issued terms."},{"id":"L42-08","prompt":"A question states that a child rider continues paid-up term coverage after the base insured’s death until a specified date. How should the agent apply it?","options":["Assume permanent coverage without any ending date.","Apply the stated continuation, ending date and any conversion provisions.","Pay the child’s death benefit immediately even though the child lives.","Replace the stated provision with another carrier’s default rule."],"answer":1,"explanations":["Paid-up term can still have an ending date.","Use the actual terms supplied in the scenario.","The child’s insured death has not occurred.","Another contract does not override the given provision."],"topics":["5.9.02","5.9.03"],"review":5,"lesson":"42","domain":4,"explanation":"Use the actual terms supplied in the scenario."}]},{"id":"43","number":43,"title":"Additional riders: match the benefit to its trigger","version":2,"questions":[{"id":"L43-01","prompt":"A covered $200,000 base death benefit and a qualifying $50,000 accidental-death benefit apply. No adjustments apply. What is payable?","options":["$400,000","$250,000","$200,000","$50,000"],"answer":1,"explanations":["That assumes the rider equals the base amount.","Add the two benefits actually stated.","That omits the qualifying rider benefit.","That omits the covered base benefit."],"topics":["5.10.01"],"review":1,"lesson":"43","domain":4,"explanation":"Add the two benefits actually stated."},{"id":"L43-02","prompt":"A death is covered by the base life policy but fails the accidental-death rider’s stated cause requirement. Which result follows from these facts?","options":["Neither benefit can be paid.","The base benefit must be doubled.","The covered base benefit may be paid, while the rider benefit is not triggered.","The accident rider replaces the base benefit."],"answer":2,"explanations":["The facts expressly state that the base policy covers this death.","The rider’s condition was not met.","Apply each provision’s trigger separately.","An additional rider is not automatically a replacement benefit."],"topics":["5.10.01"],"review":1,"lesson":"43","domain":4,"explanation":"Apply each provision’s trigger separately."},{"id":"L43-03","prompt":"An active guaranteed-insurability rider provides a $25,000 option at the stated date without new evidence of insurability. The insured’s health has worsened. What remains necessary?","options":["A new full medical examination in every case","An unlimited increase instead of the option amount","Automatic election by the beneficiary","Timely election within the option’s limits and payment of the applicable premium"],"answer":3,"explanations":["That contradicts the protected no-new-evidence opportunity.","The stated amount limit still applies.","The contract’s election requirements control.","The health-evidence protection does not waive these conditions."],"topics":["5.10.02"],"review":2,"lesson":"43","domain":4,"explanation":"The health-evidence protection does not waive these conditions."},{"id":"L43-04","prompt":"Which feature most directly preserves specified opportunities to buy additional coverage despite a later health change?","options":["Guaranteed-insurability rider","Accidental-death rider","Premium-linked death rider","An existing policy’s ordinary grace period"],"answer":0,"explanations":["That is the protected purchase opportunity.","This adds a benefit for a qualifying accidental death.","This adds a contract-defined death amount.","Grace concerns a late premium on existing coverage."],"topics":["5.10.02"],"review":5,"lesson":"43","domain":4,"explanation":"That is the protected purchase opportunity."},{"id":"L43-05","prompt":"A stated cost-of-living adjustment increases $100,000 of coverage by 3%. What is the new coverage?","options":["$3,000","$103,000","$100,003","$130,000"],"answer":1,"explanations":["That is only the increase.","Add $3,000 to the original $100,000.","Three percent is not three dollars.","That applies a 30% increase."],"topics":["5.10.03"],"review":3,"lesson":"43","domain":4,"explanation":"Add $3,000 to the original $100,000."},{"id":"L43-06","prompt":"What does a stated CPI-based life coverage adjustment primarily change?","options":["The insurer’s actual stock-market return","A guaranteed cash dividend paid to the owner","The amount of coverage under the rider’s formula","The policyowner’s tax bracket automatically"],"answer":2,"explanations":["CPI is an inflation measure, not the insurer’s investment result.","Coverage adjustment and dividends are different features.","The formula determines the insurance adjustment.","That is not a rider function."],"topics":["5.10.03"],"review":3,"lesson":"43","domain":4,"explanation":"The formula determines the insurance adjustment."},{"id":"L43-07","prompt":"A stated death rider adds $12,000 of eligible premiums to a covered $200,000 base benefit. No deductions apply. What is the total?","options":["$188,000","$200,000","$12,000","$212,000"],"answer":3,"explanations":["The stated rider adds the amount.","That omits the rider benefit.","That omits the base benefit.","$200,000 plus $12,000 equals $212,000."],"topics":["5.10.04"],"review":4,"lesson":"43","domain":4,"explanation":"$200,000 plus $12,000 equals $212,000."},{"id":"L43-08","prompt":"Which question best distinguishes a premium-linked death rider from a return-of-premium term survival feature?","options":["Does payment follow a covered death or survival to the stated term’s end?","Does the schedule refer to premiums paid under the contract?","Does the benefit use a maximum dollar amount?","Does the feature appear with a term-insurance base policy?"],"answer":0,"explanations":["The trigger distinguishes the death rider from the term-survival benefit.","Both kinds of promise can refer to premiums; the trigger still matters.","A maximum amount alone does not establish when payment occurs.","A term base alone does not identify the rider’s or feature’s trigger."],"topics":["5.10.04"],"review":4,"lesson":"43","domain":4,"explanation":"The trigger distinguishes the death rider from the term-survival benefit."}]},{"id":"44","number":44,"title":"Annuities: who controls the contract and when income begins","version":2,"questions":[{"id":"L44-01","prompt":"Which risk is most directly addressed by income guaranteed for the covered person’s entire life?","options":["A future increase in a mortgage interest rate","Every possible market loss in other investments","Outliving income resources","An early death benefit owed to a creditor"],"answer":2,"explanations":["That is not the lifetime-payment trigger.","Other investments keep their own risks.","Lifetime income addresses longevity risk.","That is a different life-insurance need."],"topics":["6.1.06"],"review":0,"lesson":"44","domain":5,"explanation":"Lifetime income addresses longevity risk."},{"id":"L44-02","prompt":"Rosa funds a deferred annuity and has not converted it into income payments. Its value follows the issued crediting rules. Which phase is described?","options":["A death-claim period","A guaranteed-period payout","Annuitization","Accumulation"],"answer":3,"explanations":["No death claim is stated.","No payout election is stated.","The facts say income conversion has not occurred.","The contract is holding and developing value before income conversion."],"topics":["6.1.01"],"review":1,"lesson":"44","domain":5,"explanation":"The contract is holding and developing value before income conversion."},{"id":"L44-03","prompt":"What best describes annuitization?","options":["Converting applicable value into payments under a selected income option","Changing the beneficiary’s address","Making any monthly withdrawal from an account","Paying the first premium on every life policy"],"answer":0,"explanations":["That is the income-conversion decision.","An address update does not establish income payments.","Withdrawals can occur without annuitization.","Life-policy funding is a different transaction."],"topics":["6.1.02"],"review":2,"lesson":"44","domain":5,"explanation":"That is the income-conversion decision."},{"id":"L44-04","prompt":"A permitted contract names Rosa owner and David annuitant. Which statement identifies their roles?","options":["David owns all rights merely because he is annuitant.","Rosa exercises permitted owner rights; David supplies the measuring life for the stated life-based benefit.","Rosa is automatically the death-benefit recipient.","David’s role requires the contract to pay only a death benefit."],"answer":1,"explanations":["Ownership is a separately identified role.","This separates control from the measuring life.","Beneficiary designation is another role.","Annuities can provide payments during life."],"topics":["6.1.03","6.1.04"],"review":3,"lesson":"44","domain":5,"explanation":"This separates control from the measuring life."},{"id":"L44-05","prompt":"Maya is named beneficiary, but the selected income option provides life-only payments with no continuation or refund. What does her designation alone accomplish?","options":["It guarantees return of every premium.","It creates a ten-year guarantee.","It identifies a recipient of applicable benefits but does not create a benefit excluded by the selected option.","It gives her the owner’s withdrawal rights immediately."],"answer":2,"explanations":["A refund requires an applicable promise.","A guarantee is not created by naming someone.","Recipient designation and benefit entitlement are separate.","Ownership rights do not follow from this designation alone."],"topics":["6.1.05"],"review":4,"lesson":"44","domain":5,"explanation":"Recipient designation and benefit entitlement are separate."},{"id":"L44-06","prompt":"Which fact is especially relevant before placing funds needed for an essential expense next month into an annuity with a long surrender period?","options":["Whether the projected long-term return is attractive even if access is costly","Whether naming a beneficiary will waive withdrawal restrictions","Whether tax deferral makes the cash automatically available without charges","The client’s liquidity needs and the contract’s withdrawal restrictions and costs"],"answer":3,"explanations":["An attractive projection does not solve an immediate cash-access conflict.","A beneficiary designation does not generally waive surrender restrictions.","Tax deferral does not remove contract withdrawal costs or limits.","Near-term access and potential charges directly affect this decision."],"topics":["6.1.07"],"review":5,"lesson":"44","domain":5,"explanation":"Near-term access and potential charges directly affect this decision."},{"id":"L44-07","prompt":"A contract pays income for exactly ten years, with no lifetime continuation. The recipient lives for twenty more years. Which conclusion follows?","options":["The stated payments can end after ten years while the recipient is still living.","All annuities must extend payments for life.","The beneficiary must fund the second ten years.","The payments automatically double after year ten."],"answer":0,"explanations":["A fixed period is not a lifetime promise.","The actual payment option determines duration.","No such beneficiary obligation is stated.","No such increase is stated."],"topics":["6.1.06"],"review":0,"lesson":"44","domain":5,"explanation":"A fixed period is not a lifetime promise."},{"id":"L44-08","prompt":"A client receives monthly withdrawals from an annuity’s account value. What additional fact is needed before calling the arrangement annuitization?","options":["Whether recurring payments are scheduled monthly","Whether the client elected conversion to annuity payments under an income option","Whether ordinary withdrawals are being deposited automatically","Whether the account value still supports the selected recurring withdrawals"],"answer":1,"explanations":["Frequency alone cannot distinguish withdrawals from annuitization.","The contractual income election distinguishes the transaction.","Automatic delivery can be used for ordinary withdrawals too.","An account-funded withdrawal schedule is not itself an annuitization election."],"topics":["6.1.02"],"review":2,"lesson":"44","domain":5,"explanation":"The contractual income election distinguishes the transaction."}]},{"id":"45","number":45,"title":"Immediate or deferred: separate funding from access","version":1,"questions":[{"id":"L45-01","prompt":"David pays one premium and chooses income beginning ten years later. How is the arrangement classified?","options":["Single-premium immediate","Flexible-premium immediate","Single-premium deferred","Periodic-premium immediate"],"answer":2,"explanations":["The income is postponed for ten years.","Only one premium is stated, with deferred income.","Funding is single-premium and income timing is deferred.","Neither the stated funding nor timing fits."],"topics":["6.2.02","6.2.03"],"review":0,"lesson":"45","domain":5,"explanation":"Funding is single-premium and income timing is deferred."},{"id":"L45-02","prompt":"Rosa pays one premium for annuity income beginning next month. Which timing category applies?","options":["Deferred accumulation for life","Deferred because a lump sum is used","Variable because payment is monthly","Immediate"],"answer":3,"explanations":["Income begins next month, not after extended accumulation.","A lump sum can fund an immediate contract.","Payment frequency does not identify investment design.","Next-month income is within one year."],"topics":["6.2.01"],"review":0,"lesson":"45","domain":5,"explanation":"Next-month income is within one year."},{"id":"L45-03","prompt":"Which description addresses premium pattern rather than investment guarantees?","options":["The owner may vary accepted contributions within stated limits.","The insurer guarantees a minimum credited interest rate.","Separate-account value follows investment performance.","Interest is credited using an index formula."],"answer":0,"explanations":["That describes flexible-premium funding.","That describes an interest guarantee.","That describes variable investment exposure.","That describes indexed crediting."],"topics":["6.2.03"],"review":1,"lesson":"45","domain":5,"explanation":"That describes flexible-premium funding."},{"id":"L45-04","prompt":"A $100,000 account has a 5% full-surrender charge on the entire value. No free allowance or other adjustment applies. What is payable before tax?","options":["$100,000","$95,000","$90,000","$5,000"],"answer":1,"explanations":["That ignores the stated charge.","Subtract $5,000 from $100,000.","That applies a 10% charge.","That is the charge, not the net payment."],"topics":["6.2.05"],"review":2,"lesson":"45","domain":5,"explanation":"Subtract $5,000 from $100,000."},{"id":"L45-05","prompt":"Which statement properly describes a paid-up deferred annuity benefit under the applicable provisions?","options":["The insurer must refund all gross premiums immediately.","The owner loses all value when contributions stop.","Existing value supports the defined later benefit without further contributions.","All credited rates become fixed at the original advertised rate forever."],"answer":2,"explanations":["Paid-up benefits are not the same as an unrestricted refund.","The provision preserves specified benefits.","That is the paid-up benefit concept.","The provision does not create that universal crediting promise."],"topics":["6.2.04"],"review":3,"lesson":"45","domain":5,"explanation":"That is the paid-up benefit concept."},{"id":"L45-06","prompt":"A fictional bailout clause applies when the renewed credited rate falls below 3%. The renewed rate is 2.5%. What should the owner check next?","options":["Only whether the stock market gained 3%","Only the original premium payment frequency","Whether the policy is automatically tax-exempt","The election window and the charges and value covered by the clause"],"answer":3,"explanations":["The clause uses the stated credited-rate test.","Payment frequency does not complete the election.","The clause does not establish tax exemption.","The trigger is met, but the remaining contract conditions still apply."],"topics":["6.2.06"],"review":4,"lesson":"45","domain":5,"explanation":"The trigger is met, but the remaining contract conditions still apply."},{"id":"L45-07","prompt":"An insurer allows a withdrawal without its surrender charge. Which statement is correct?","options":["Federal income tax or an additional distribution tax may still apply.","All federal tax is necessarily waived.","The withdrawal cannot reduce any contract benefit.","The withdrawal must count as annuitization."],"answer":0,"explanations":["The insurer’s waiver and tax rules are separate.","The insurer does not waive federal taxes.","Withdrawals can affect remaining values and benefits.","A withdrawal is not automatically income conversion."],"topics":["6.2.05","6.2.06"],"review":2,"lesson":"45","domain":5,"explanation":"The insurer’s waiver and tax rules are separate."},{"id":"L45-08","prompt":"A stated accumulation-stage death benefit is the greater of $80,000 adjusted premiums or $90,000 account value. No adjustment applies. What is the benefit?","options":["$80,000","$90,000","$170,000","$10,000"],"answer":1,"explanations":["The contract promises the greater amount.","$90,000 is the greater of the two stated values.","The formula compares the values rather than adding them.","That is their difference, not the specified benefit."],"topics":["6.2.07"],"review":5,"lesson":"45","domain":5,"explanation":"$90,000 is the greater of the two stated values."},{"id":"L45-09","prompt":"Why should an agent check §16-501 before applying Maryland’s individual deferred-annuity nonforfeiture formula?","options":["It makes all annuity benefits tax-free.","It fixes every product’s current credited rate.","It identifies categories excluded from that subtitle.","It supplies every insurer’s surrender schedule."],"answer":2,"explanations":["Tax treatment is governed separately.","A statutory scope section does not quote product rates.","The law excludes specified categories, including variable and immediate annuities.","The issued contract supplies its schedule subject to applicable law."],"topics":["6.2.04"],"review":3,"lesson":"45","domain":5,"explanation":"The law excludes specified categories, including variable and immediate annuities."}]},{"id":"46","number":46,"title":"Choose the income promise: life, years or a stated amount","version":1,"questions":[{"id":"L46-01","prompt":"David selects life-only income with no refund or guaranteed period and dies shortly after payments begin. What follows under those terms?","options":["The beneficiary receives every unpaid premium automatically.","Payments continue for ten years automatically.","The policy converts to joint-and-survivor income.","Life-only payments stop at his death."],"answer":3,"explanations":["No refund was selected.","No certain period was selected.","No such conversion is stated.","That is the pure-life payment condition."],"topics":["6.3.01","6.3.02"],"review":0,"lesson":"46","domain":5,"explanation":"That is the pure-life payment condition."},{"id":"L46-02","prompt":"Life income with ten years certain has made exactly four years of payments when the annuitant dies. What remains under the guarantee?","options":["Six years of payments to the designated recipient","Ten new years beginning at death","No further payments","Payments for the beneficiary’s lifetime"],"answer":0,"explanations":["Ten guaranteed years minus four completed years leaves six.","The guarantee does not restart at death.","The certain-period guarantee has not been exhausted.","A period guarantee does not insure the beneficiary’s lifetime."],"topics":["6.3.02"],"review":1,"lesson":"46","domain":5,"explanation":"Ten guaranteed years minus four completed years leaves six."},{"id":"L46-03","prompt":"The annuitant remains alive after ten years under life income with ten years certain. What happens?","options":["All payments must stop.","Life payments continue while the annuitant lives.","Only the beneficiary can receive more payments.","The original premium is refunded and the contract ends."],"answer":1,"explanations":["Ten years is a minimum, not the life-payment limit.","The lifetime promise continues beyond the certain period.","The annuitant is living and the life promise applies.","No such refund election is stated."],"topics":["6.3.01","6.3.02"],"review":1,"lesson":"46","domain":5,"explanation":"The lifetime promise continues beyond the certain period."},{"id":"L46-04","prompt":"A refund option guarantees a stated $100,000 total. The annuitant dies after receiving $30,000. No adjustment applies. What remains under that refund promise?","options":["$100,000","$130,000","$70,000","$30,000"],"answer":2,"explanations":["Prior payments count toward the specified total.","The promise is not the total plus prior payments.","$100,000 minus $30,000 leaves $70,000.","That is the amount already received."],"topics":["6.3.02"],"review":2,"lesson":"46","domain":5,"explanation":"$100,000 minus $30,000 leaves $70,000."},{"id":"L46-05","prompt":"How does installment refund differ from cash refund under the stated minimum-total design?","options":["Installment refund necessarily pays for the beneficiary’s entire life.","Cash refund always doubles the purchase amount.","Installment refund has no minimum-total protection.","Installment refund continues scheduled payments to satisfy the total; cash refund pays the remaining amount at once."],"answer":3,"explanations":["The promise is the stated remaining total.","No such doubling is implied.","It has a minimum-total protection with a different payment method.","This identifies the payment-method distinction."],"topics":["6.3.02"],"review":2,"lesson":"46","domain":5,"explanation":"This identifies the payment-method distinction."},{"id":"L46-06","prompt":"A joint-and-survivor option pays $2,000 monthly while both live and 75% to the survivor after the stated death. What is the survivor’s monthly payment?","options":["$1,500","$750","$2,000","$2,750"],"answer":0,"explanations":["$2,000 multiplied by 0.75 equals $1,500.","That is not 75% of $2,000.","That would be a full-survivor percentage.","The survivor percentage reduces rather than adds to the stated payment."],"topics":["6.3.03"],"review":3,"lesson":"46","domain":5,"explanation":"$2,000 multiplied by 0.75 equals $1,500."},{"id":"L46-07","prompt":"A fixed-period-only option promises ten years of payments. The recipient remains alive after year ten. What happens under those terms?","options":["Payments continue for life.","The promised period ends after ten years.","The period restarts automatically.","The payment doubles for the survivor."],"answer":1,"explanations":["No life continuation is stated.","A fixed-period-only promise ends at its stated duration.","There is no automatic restart.","No such survivor change is stated."],"topics":["6.3.04"],"review":1,"lesson":"46","domain":5,"explanation":"A fixed-period-only promise ends at its stated duration."},{"id":"L46-08","prompt":"With exactly $60,000 available, no interest, fees or other adjustments, how long do $1,500 monthly payments last?","options":["60 months","90 months","40 months","30 months"],"answer":2,"explanations":["That would apply to $1,000 monthly payments.","That would require more money under these assumptions.","$60,000 divided by $1,500 equals 40.","That would apply to $2,000 monthly payments."],"topics":["6.3.05"],"review":4,"lesson":"46","domain":5,"explanation":"$60,000 divided by $1,500 equals 40."},{"id":"L46-09","prompt":"Which statement correctly distinguishes fixed-period and fixed-amount options?","options":["Both necessarily guarantee income for life.","A fixed amount guarantees a number of years regardless of available funds.","A fixed period guarantees repayment only at death.","A fixed period sets duration; a fixed amount sets payment size and lets funds and interest determine duration."],"answer":3,"explanations":["Neither label alone guarantees lifetime income.","Payment size alone does not guarantee duration.","A fixed period describes scheduled payments over time.","These are the separate quantities each option fixes."],"topics":["6.3.04","6.3.05"],"review":4,"lesson":"46","domain":5,"explanation":"These are the separate quantities each option fixes."}]},{"id":"47","number":47,"title":"Annuity designs: follow the guarantee and the risk","version":1,"questions":[{"id":"L47-01","prompt":"A fixed annuity guarantees a 2% minimum and declares 4% for the current one-year period. What is supported by those facts?","options":["4% is guaranteed for life.","A later declared rate may change within the contract’s limits.","The owner directly controls the insurer’s general-account investments.","The 2% minimum is an index participation rate."],"answer":1,"explanations":["The specified period is one year.","Separate the current period from the minimum promise.","That is not an ownership right established here.","The fact expressly identifies a minimum interest guarantee."],"topics":["6.4.01"],"review":1,"lesson":"47","domain":5,"explanation":"Separate the current period from the minimum promise."},{"id":"L47-02","prompt":"Which allocation directly exposes the owner to the selected portfolio’s investment performance?","options":["A traditional fixed general-account guarantee","A life-only payment’s mortality pooling alone","A variable annuity investment subaccount","A fixed amount selected for a beneficiary address change"],"answer":2,"explanations":["That describes a different guarantee structure.","Mortality pooling is not a portfolio allocation.","This is separate-account variable exposure.","An administrative change is not an investment allocation."],"topics":["6.4.02"],"review":2,"lesson":"47","domain":5,"explanation":"This is separate-account variable exposure."},{"id":"L47-03","prompt":"A $50,000 variable allocation loses 10%, with no fees, withdrawals or other changes. What is its resulting value?","options":["$55,000","$49,990","$5,000","$45,000"],"answer":3,"explanations":["That adds rather than subtracts 10%.","Ten percent is not ten dollars.","That is the loss amount only.","Subtract the $5,000 loss from $50,000."],"topics":["6.4.02"],"review":2,"lesson":"47","domain":5,"explanation":"Subtract the $5,000 loss from $50,000."},{"id":"L47-04","prompt":"A stated fixed indexed method applies 50% participation to an 8% index gain, then a 3% cap. No other adjustments apply. What rate is credited?","options":["3%","4%","8%","1%"],"answer":0,"explanations":["The preliminary 4% result is capped at 3%.","That ignores the cap.","That ignores participation and the cap.","The cap limits the result; it is not subtracted."],"topics":["6.4.03"],"review":3,"lesson":"47","domain":5,"explanation":"The preliminary 4% result is capped at 3%."},{"id":"L47-05","prompt":"What does a zero index-credit floor alone establish?","options":["Surrender always returns all original premiums.","The applicable index credit will not be negative.","Every optional rider is free.","The owner holds the index’s stocks directly."],"answer":1,"explanations":["Surrender charges and other provisions remain relevant.","That is the limited protection described.","A credit floor does not waive rider costs.","An index formula does not create stock ownership."],"topics":["6.4.03"],"review":3,"lesson":"47","domain":5,"explanation":"That is the limited protection described."},{"id":"L47-06","prompt":"A client assumes a RILA cannot incur an index-related loss because another fixed indexed contract has a zero-credit floor. Which response is correct?","options":["The two products have identical loss rules.","Only variable annuities can ever lose value.","A RILA can expose value to index losses under its own terms.","A zero credit guarantees a positive net return."],"answer":2,"explanations":["Their loss protections can differ.","That excludes other products that can incur losses.","Use the particular registered index-linked design.","Zero credit does not mean positive return after costs."],"topics":["6.4.03"],"review":3,"lesson":"47","domain":5,"explanation":"Use the particular registered index-linked design."},{"id":"L47-07","prompt":"An early surrender has $100,000 value, a stated $2,000 negative MVA and a separate $3,000 surrender charge. No other effects apply. What is available before tax?","options":["$98,000","$97,000","$105,000","$95,000"],"answer":3,"explanations":["That omits the surrender charge.","That omits the MVA.","Both stated effects are reductions.","Subtract both independent amounts."],"topics":["6.4.04"],"review":4,"lesson":"47","domain":5,"explanation":"Subtract both independent amounts."},{"id":"L47-08","prompt":"Under a typical MVA formula, relevant market interest rates have risen since the guarantee began. What early-exit effect should be investigated?","options":["A possible negative adjustment under the actual formula","An automatic positive index credit","A mandatory refund of all surrender charges","An automatic change of annuitant"],"answer":0,"explanations":["Higher rates can produce a downward adjustment; the actual formula controls.","MVA is a different mechanism from indexed crediting.","No refund follows from the rate direction alone.","Rate changes do not establish this administrative change."],"topics":["6.4.04"],"review":4,"lesson":"47","domain":5,"explanation":"Higher rates can produce a downward adjustment; the actual formula controls."},{"id":"L47-09","prompt":"A fixed income option pays the same dollar amount every month while prices rise. What can happen?","options":["The stated payment automatically becomes variable.","The payment buys less despite the unchanged dollar promise.","The guaranteed dollar amount must rise with CPI.","The contract necessarily has failed to pay its promise."],"answer":1,"explanations":["Inflation does not itself change the elected design.","Level dollars and level purchasing power are different.","An inflation increase requires an applicable promise.","Paying the promised amount is different from preserving purchasing power."],"topics":["6.4.01"],"review":1,"lesson":"47","domain":5,"explanation":"Level dollars and level purchasing power are different."}]},{"id":"48","number":48,"title":"Annuity uses and Maryland’s best-interest standard","version":1,"questions":[{"id":"L48-01","prompt":"Rosa receives a lump sum but needs part for an essential expense next month. What should occur before recommending a long-surrender-period annuity?","options":["Commit the whole sum because it is available.","Rely only on the introductory crediting rate.","Evaluate the needed liquid funds, other resources and contract access costs.","Assume the beneficiary can always withdraw it without charges."],"answer":2,"explanations":["Availability does not establish suitability for commitment.","The rate does not address the imminent cash need.","Those facts determine whether the commitment fits.","Beneficiary status does not create a general withdrawal waiver."],"topics":["6.5.01","6.5.05","6.5.08"],"review":0,"lesson":"48","domain":5,"explanation":"Those facts determine whether the commitment fits."},{"id":"L48-02","prompt":"What distinguishes a retirement plan or IRA from an annuity used to fund it?","options":["Only annuities can have beneficiaries.","The annuity eliminates the plan’s distribution rules.","The plan supplies every insurance guarantee.","The plan or IRA supplies its tax framework; the annuity supplies its contractual insurance features."],"answer":3,"explanations":["Other retirement arrangements can have beneficiaries.","The account’s applicable rules remain relevant.","Insurance guarantees arise from the contract.","These are separate layers that must be evaluated together."],"topics":["6.5.02","6.5.03"],"review":1,"lesson":"48","domain":5,"explanation":"These are separate layers that must be evaluated together."},{"id":"L48-03","prompt":"A producer claims an annuity inside a traditional tax-deferred IRA doubles the tax deferral. Which conclusion is correct?","options":["The IRA does not gain an additional layer of tax deferral from the annuity.","All IRA annuity earnings become permanently tax-free.","The annuity doubles the IRA contribution limit.","The annuity makes every contribution deductible."],"answer":0,"explanations":["A recommendation must consider the insurance features and costs.","Deferral and exemption are different.","A funding contract does not double the limit.","Deductibility follows the applicable IRA rules."],"topics":["6.5.03","6.5.04"],"review":1,"lesson":"48","domain":5,"explanation":"A recommendation must consider the insurance features and costs."},{"id":"L48-04","prompt":"What does tax-deferred growth in an eligible nonqualified annuity generally mean?","options":["The personal premium is automatically deductible.","Tax on earnings is postponed until a taxable distribution under the applicable rules.","Every beneficiary distribution is tax-free life insurance.","The insurer pays all of the owner’s eventual tax."],"answer":1,"explanations":["Nonqualified personal premiums generally use after-tax funds.","Deferral postpones taxation rather than eliminating it.","Annuity death taxation differs from the life-insurance general rule.","That obligation is not created by tax deferral."],"topics":["6.5.04"],"review":1,"lesson":"48","domain":5,"explanation":"Deferral postpones taxation rather than eliminating it."},{"id":"L48-05","prompt":"David plans to use a personally owned nonqualified annuity withdrawal for tuition. Which assumption is unsafe?","options":["Surrender provisions must be examined.","The contract’s access timing matters.","An IRA education exception automatically exempts this nonqualified-annuity distribution from additional tax.","The actual distribution’s tax rules must be checked."],"answer":2,"explanations":["That is a necessary part of the review.","Timing is relevant to funding the expense.","An exception for a particular account type is not universal.","That is the appropriate distinction."],"topics":["6.5.06"],"review":2,"lesson":"48","domain":5,"explanation":"An exception for a particular account type is not universal."},{"id":"L48-06","prompt":"A covered Maryland organization intends to issue donor charitable gift annuity agreements. What is required under §16-114 before issuance?","options":["Only a producer’s verbal endorsement","Only a promise that all payments will be tax-free","Only the donor’s beneficiary designation","The Commissioner’s applicable special permit"],"answer":3,"explanations":["That is not the statutory authorization.","The promise is not a substitute for a permit or tax analysis.","That identifies a possible recipient, not issuer authority.","The covered organization must first obtain the permit."],"topics":["6.5.07"],"review":2,"lesson":"48","domain":5,"explanation":"The covered organization must first obtain the permit."},{"id":"L48-07","prompt":"Which group identifies Maryland’s best-interest obligations for a covered annuity recommendation?","options":["Care, disclosure, conflict of interest and documentation","Only rate comparison and client signature","Only lowest commission and highest illustrated return","Only carrier appointment and application delivery"],"answer":0,"explanations":["All four obligations apply under the standard.","That omits required duties.","Neither shortcut replaces the required analysis.","Those steps do not exhaust the best-interest standard."],"topics":["6.5.08"],"review":3,"lesson":"48","domain":5,"explanation":"All four obligations apply under the standard."},{"id":"L48-08","prompt":"A consumer requests more information about cash compensation before purchase. What must the producer disclose under the rule?","options":["Only that a commission may exist","A reasonable estimate, potentially a range or percentage, and the applicable recurrence details","Only the insurer’s total annual revenue","Only the compensation after the first death claim"],"answer":1,"explanations":["The request triggers the more specific information requirement.","The rule permits this form of estimate and requires recurrence information.","That does not answer the compensation question.","That is not the required timing."],"topics":["6.5.08"],"review":3,"lesson":"48","domain":5,"explanation":"The rule permits this form of estimate and requires recurrence information."},{"id":"L48-09","prompt":"A proposed replacement includes a bonus, new surrender restrictions and lost benefits. The client also replaced an annuity 48 months ago. What must the review consider?","options":["Only the bonus because it is immediate","Only whether the previous replacement was within 36 months","The whole transaction and the prior replacement within the 60-month consideration period","Only the new carrier’s financial rating"],"answer":2,"explanations":["A bonus does not resolve costs and benefits over the product’s life.","Maryland’s cited rule states 60 months.","Both the transaction effects and recent history matter.","Insurer characteristics are relevant but not the whole comparison."],"topics":["6.5.08"],"review":4,"lesson":"48","domain":5,"explanation":"Both the transaction effects and recent history matter."},{"id":"L48-10","prompt":"The insurer completed a covered annuity transaction today. What retention period does COMAR 31.09.12.10 specify for the required records?","options":["Until the first premium clears","Two years after application","Five years after the producer’s appointment","Seven years after the insurer completes the transaction"],"answer":3,"explanations":["That is too short and uses the wrong trigger.","That does not match the rule.","That uses the wrong duration and event.","Both the duration and starting event matter."],"topics":["6.5.08"],"review":5,"lesson":"48","domain":5,"explanation":"Both the duration and starting event matter."},{"id":"L48-11","prompt":"A new producer subject to the annuity training rule has completed only this exam-preparation lesson. Which conclusion is correct?","options":["The approved four-credit training and applicable product knowledge are still required.","This lesson automatically grants the approved credits.","The historical one-credit transition option applies to every new producer.","A client signature replaces the training requirement."],"answer":0,"explanations":["Exam preparation is not represented as approved annuity training.","No such approval or credit is claimed.","The transition provision is not a universal new-producer substitute.","Consent does not replace required training."],"topics":["6.5.08"],"review":5,"lesson":"48","domain":5,"explanation":"Exam preparation is not represented as approved annuity training."},{"id":"L48-12","prompt":"A consumer refuses relevant financial information but the producer wants to recommend a purchase anyway. What is the correct approach?","options":["Treat any signed form as proof that the recommendation is suitable.","Document the refusal and its consequences as required, and do not invent a sound recommendation from missing facts.","Omit the refusal so the insurer will not question the application.","Tell the consumer not to answer the insurer’s confirmation questions truthfully."],"answer":1,"explanations":["A signature does not supply the missing reasoning.","Documentation and a reasonable basis are separate requirements.","Concealing the facts undermines the required review.","Dissuading truthful confirmation is prohibited."],"topics":["6.5.08"],"review":4,"lesson":"48","domain":5,"explanation":"Documentation and a reasonable basis are separate requirements."}]},{"id":"49","number":49,"title":"Life insurance taxes: identify the event first","version":2,"questions":[{"id":"L49-01","prompt":"A qualifying personally owned life policy grows in cash value without a distribution. What is the general federal income-tax treatment of that inside growth?","options":["All growth is wages each year.","It generally is not taxed to the owner merely because value increased.","The premium becomes an itemized deduction.","The entire death benefit becomes taxable immediately."],"answer":1,"explanations":["Inside buildup is not wages.","The distribution event and qualifying status matter.","Growth does not create this deduction.","No death payment or such tax trigger is stated."],"topics":["7.1.01"],"review":0,"lesson":"49","domain":6,"explanation":"The distribution event and qualifying status matter."},{"id":"L49-02","prompt":"An $800 policy dividend is entirely a return within remaining premium basis. Separately, it earns $40 interest on deposit with the commercial insurer. What is generally taxable?","options":["All $840 as capital gain","$800 only","$40 of interest","Neither amount under all circumstances"],"answer":2,"explanations":["The stated dividend qualifies as a premium return.","That reverses the classifications.","The separately earned interest is generally taxable.","The deposit interest is not excluded by the dividend’s treatment."],"topics":["7.1.02"],"review":1,"lesson":"49","domain":6,"explanation":"The separately earned interest is generally taxable."},{"id":"L49-03","prompt":"An ordinary loan from an in-force non-MEC life policy is generally not taxable when made. What can change the later tax result?","options":["Changing only the revocable beneficiary, without transferring ownership","Continuing the same loan while the non-MEC policy remains in force","Repaying the loan principal from outside funds","A later lapse or surrender discharging policy debt"],"answer":3,"explanations":["A beneficiary-only change is not the stated distribution or debt-discharge event.","The described continuing loan is not the later termination event.","Repaying principal does not itself create a policy distribution to the owner.","Debt discharge can be included in the distribution and create taxable gain."],"topics":["7.1.03","7.1.04"],"review":2,"lesson":"49","domain":6,"explanation":"Debt discharge can be included in the distribution and create taxable gain."},{"id":"L49-04","prompt":"A full surrender pays $55,000, with $40,000 adjusted investment and no loan or other effects. What is the taxable gain?","options":["$15,000 of ordinary income","$55,000 of ordinary income","$40,000 of interest","$15,000 of capital gain"],"answer":0,"explanations":["Only the excess over adjusted investment is the stated gain.","That taxes recovered basis again.","Basis is not the interest or gain.","The surrender gain is ordinary income."],"topics":["7.1.04"],"review":3,"lesson":"49","domain":6,"explanation":"Only the excess over adjusted investment is the stated gain."},{"id":"L49-05","prompt":"Under the ordinary exclusion with no exception, a beneficiary receives a $200,000 life death benefit and $3,000 separately stated interest. What enters federal gross income from these amounts?","options":["$203,000","$3,000 of interest","$200,000 of death benefit","$0 because the interest follows a death"],"answer":1,"explanations":["The assumed exclusion covers the death benefit.","Interest is separate from the excluded benefit.","That reverses the treatment.","Death-related interest is not automatically excluded."],"topics":["7.1.05"],"review":4,"lesson":"49","domain":6,"explanation":"Interest is separate from the excluded benefit."},{"id":"L49-06","prompt":"An insurer holds an excluded $200,000 benefit for 100 installments of $2,400 under the stated fixed-installment rule. How much of each installment is interest?","options":["$2,400","$2,000","$400","$200"],"answer":2,"explanations":["That includes the excluded benefit recovery.","That is the excluded recovery per installment.","Subtract $200,000 ÷ 100 from $2,400.","That does not follow the provided figures."],"topics":["7.1.06"],"review":4,"lesson":"49","domain":6,"explanation":"Subtract $200,000 ÷ 100 from $2,400."},{"id":"L49-07","prompt":"The insured retains the power to change beneficiaries until death, but payment goes directly to a named individual. What is the correct distinction?","options":["Direct payment always prevents gross-estate inclusion.","Income-tax exclusion always means estate-tax exclusion.","Probate and all tax questions have the same answer.","Direct beneficiary payment and federal gross-estate inclusion require separate analysis."],"answer":3,"explanations":["Retained incidents of ownership still matter.","They are distinct tax rules.","They answer different questions.","The payment route does not erase ownership-based inclusion."],"topics":["7.1.07"],"review":5,"lesson":"49","domain":6,"explanation":"The payment route does not erase ownership-based inclusion."},{"id":"L49-08","prompt":"A buyer acquires a life policy for valuable consideration. What should be checked before promising a fully income-tax-free death payment?","options":["The transfer-for-value and reportable-policy-sale rules and applicable exceptions","Only whether the insured’s death was from a covered cause","Only whether premiums were paid with after-tax money","Only whether the buyer kept the policy beyond the contestability period"],"answer":0,"explanations":["These transfer rules can limit the ordinary income-tax exclusion.","A payable contractual claim does not settle the tax treatment after a transfer.","After-tax premiums do not by themselves eliminate transfer-related limitations.","Incontestability concerns policy validity rather than these income-tax transfer rules."],"topics":["7.1.05"],"review":4,"lesson":"49","domain":6,"explanation":"These transfer rules can limit the ordinary income-tax exclusion."}]},{"id":"50","number":50,"title":"Modified endowment contracts: funding changes access taxes","version":2,"questions":[{"id":"L50-01","prompt":"Which statement best describes a MEC?","options":["A policy that automatically loses all death coverage","A policy whose beneficiary must be the estate","A qualifying life contract with MEC status and different living-distribution tax rules","Any life policy paid monthly"],"answer":2,"explanations":["MEC status is a tax classification, not automatic cancellation.","That beneficiary restriction is not part of the definition.","It remains life insurance while the access-tax rules differ.","Payment frequency alone does not establish MEC status."],"topics":["7.2.01"],"review":0,"lesson":"50","domain":6,"explanation":"It remains life insurance while the access-tax rules differ."},{"id":"L50-02","prompt":"At the stated testing point, the cumulative seven-pay limit is $20,000 and counted premiums are $22,000. No correction or exception applies. What follows?","options":["It passes because the excess is less than the face amount.","It passes automatically after the next anniversary.","Only this year’s last premium matters.","It exceeds the stated cumulative limit by $2,000."],"answer":3,"explanations":["The test compares the cumulative funding amounts.","The passage of time does not undo the stated failure.","The test uses cumulative amounts at the point in question.","Subtract $20,000 from $22,000."],"topics":["7.2.02"],"review":1,"lesson":"50","domain":6,"explanation":"Subtract $20,000 from $22,000."},{"id":"L50-03","prompt":"A policy passed its initial testing period. The owner later requests a material change. Which statement is correct?","options":["The material change can require a new testing period with appropriate adjustments.","No policy older than seven years can ever become a MEC.","Passing the first test makes every later increase in benefits exempt from review.","Keeping the same insurer automatically prevents another testing period."],"answer":0,"explanations":["Material changes have their own statutory testing treatment.","Qualifying later changes remain relevant after the initial period.","An initial test does not exempt every later material change.","Insurer identity does not remove the material-change rules."],"topics":["7.2.02"],"review":2,"lesson":"50","domain":6,"explanation":"Material changes have their own statutory testing treatment."},{"id":"L50-04","prompt":"A MEC has $70,000 cash value and $50,000 adjusted investment. A $15,000 withdrawal has no other adjustments. How much is taxable gain?","options":["$0","$15,000","$20,000","$50,000"],"answer":1,"explanations":["MECs apply income-first treatment.","The withdrawal is entirely within the available $20,000 gain.","The distribution is only $15,000.","That is the stated investment, not the withdrawn gain."],"topics":["7.2.03"],"review":3,"lesson":"50","domain":6,"explanation":"The withdrawal is entirely within the available $20,000 gain."},{"id":"L50-05","prompt":"With $20,000 gain available, a MEC owner instead withdraws $25,000 under the stated ordinary allocation rule. Which split is correct?","options":["$25,000 gain and no basis","$5,000 gain and $20,000 basis","$20,000 gain and $5,000 basis","No gain until all premiums have been recovered"],"answer":2,"explanations":["Only $20,000 gain is stated.","That reverses income-first treatment.","Exhaust the gain first, then recover the remainder from basis.","That imports the wrong ordering rule."],"topics":["7.2.03"],"review":3,"lesson":"50","domain":6,"explanation":"Exhaust the gain first, then recover the remainder from basis."},{"id":"L50-06","prompt":"The owner calls a $15,000 payment from a MEC a policy loan. At least $15,000 gain is available, with no exception or other adjustment. What is the general tax result?","options":["Loan labeling guarantees no distribution treatment.","The entire policy value is automatically taxable.","The debt is automatically forgiven.","The loan generally is treated as a distribution taxable to the extent of available gain."],"answer":3,"explanations":["The MEC loan rule is different.","The amount of the transaction and gain limit matter.","Tax treatment does not forgive the contract debt.","Naming it a loan does not avoid MEC distribution treatment."],"topics":["7.2.03"],"review":4,"lesson":"50","domain":6,"explanation":"Naming it a loan does not avoid MEC distribution treatment."},{"id":"L50-07","prompt":"A 45-year-old receives $15,000 taxable gain from a MEC distribution with no applicable exception. What is the additional tax under §72(v)?","options":["$1,500, in addition to ordinary income tax","$15,000 instead of ordinary income tax","$7,000 based on the $70,000 policy value","$0 because every policy loan is exempt"],"answer":0,"explanations":["Ten percent applies to the taxable $15,000 portion.","That is the taxable amount, not the additional-tax calculation.","The base is the taxable distribution portion.","MEC distributions do not receive that blanket exemption."],"topics":["7.2.03"],"review":5,"lesson":"50","domain":6,"explanation":"Ten percent applies to the taxable $15,000 portion."},{"id":"L50-08","prompt":"A MEC distribution occurs after the owner reaches 59½. What does that age exception by itself do?","options":["It makes all future MEC gain tax-free.","It removes the §72(v) additional tax for the distribution, while ordinary gain taxation can remain.","It converts the MEC into a non-MEC.","It erases all outstanding policy debt."],"answer":1,"explanations":["Ordinary income treatment is separate.","The exception concerns the additional tax.","Age does not reclassify the contract.","Age does not repay debt."],"topics":["7.2.03"],"review":5,"lesson":"50","domain":6,"explanation":"The exception concerns the additional tax."},{"id":"L50-09","prompt":"A life insurance policy is received in exchange for a MEC under the applicable exchange rule. Which status follows?","options":["It is automatically non-MEC if the new premium is lower.","It cannot have cash value.","The received life policy is also a MEC.","It becomes an IRA merely because value moved."],"answer":2,"explanations":["The exchange history retains MEC treatment.","Cash value is not prohibited by this rule.","The definition specifically includes this exchange.","An insurance exchange does not create IRA status."],"topics":["7.2.01"],"review":2,"lesson":"50","domain":6,"explanation":"The definition specifically includes this exchange."}]},{"id":"51","number":51,"title":"Annuity withdrawals: find the gain before calculating tax","version":1,"questions":[{"id":"L51-01","prompt":"Rosa owns a personal annuity outside an IRA and employer plan. Why does intending it for retirement not itself make it an IRA?","options":["IRA status depends on the required account arrangement, not the owner’s spending goal.","Any contract owned after age 59½ is an IRA.","An annuity becomes an IRA when its first interest is credited.","Only annuities funded with more than one premium can be nonqualified."],"answer":0,"explanations":["Intended use does not establish the tax arrangement.","Age does not establish IRA status.","Interest crediting is not IRA establishment.","Premium frequency does not decide qualified status."],"topics":["7.3.01"],"review":0,"lesson":"51","domain":6,"explanation":"Intended use does not establish the tax arrangement."},{"id":"L51-02","prompt":"A 2020 individual nonqualified annuity has $90,000 cash value and $60,000 adjusted investment. Before annuitization, a $20,000 partial withdrawal occurs with no special adjustment. How much is ordinary income?","options":["$0","$20,000","$6,667","$30,000"],"answer":1,"explanations":["The available earnings are distributed first.","The $30,000 available gain covers the entire $20,000 payment.","That incorrectly applies a proportional allocation.","The payment is only $20,000."],"topics":["7.3.01"],"review":1,"lesson":"51","domain":6,"explanation":"The $30,000 available gain covers the entire $20,000 payment."},{"id":"L51-03","prompt":"Using the original $90,000 value and $60,000 investment, a $40,000 withdrawal occurs instead. What allocation follows?","options":["$40,000 taxable and no investment recovery","$10,000 taxable and $30,000 investment recovery","$30,000 taxable and $10,000 investment recovery","$0 taxable and $40,000 investment recovery"],"answer":2,"explanations":["Gain is limited to $30,000 in these facts.","That reverses the amounts.","Earnings are used first, then the remaining $10,000 recovers investment.","The earnings-first rule applies."],"topics":["7.3.01"],"review":2,"lesson":"51","domain":6,"explanation":"Earnings are used first, then the remaining $10,000 recovers investment."},{"id":"L51-04","prompt":"After that independent $40,000 withdrawal, how much of the original $60,000 investment remains?","options":["$20,000","$30,000","$60,000","$50,000"],"answer":3,"explanations":["Only $10,000 of the withdrawal recovered investment.","Taxable earnings do not reduce investment by that amount.","The $10,000 tax-free recovery reduces investment.","$60,000 minus the $10,000 recovered investment leaves $50,000."],"topics":["7.3.01"],"review":2,"lesson":"51","domain":6,"explanation":"$60,000 minus the $10,000 recovered investment leaves $50,000."},{"id":"L51-05","prompt":"A full surrender pays $85,000 net of contract charges. Unrecovered investment is $60,000, with no debt or other adjustment. What is the gain?","options":["$25,000","$85,000","$30,000","$0"],"answer":0,"explanations":["Net proceeds less unrecovered investment equal $25,000.","The recovered investment is not taxed again.","That would use a different $90,000 amount rather than the stated net payment.","Surrender can realize taxable gain."],"topics":["7.3.01"],"review":3,"lesson":"51","domain":6,"explanation":"Net proceeds less unrecovered investment equal $25,000."},{"id":"L51-06","prompt":"A 45-year-old receives $20,000 taxable nonqualified annuity income in an early withdrawal, with no exception. What is the additional federal tax?","options":["$20,000","$2,000","$9,000","$0 if the insurer waives its surrender charge"],"answer":1,"explanations":["The taxable amount is the calculation base, not the tax.","Ten percent of $20,000 is $2,000, separate from ordinary income tax.","Account value is not the stated taxable distribution base.","A contract-charge waiver does not itself waive federal tax."],"topics":["7.3.01"],"review":4,"lesson":"51","domain":6,"explanation":"Ten percent of $20,000 is $2,000, separate from ordinary income tax."},{"id":"L51-07","prompt":"A nonqualified annuity owner reaches 59½ and takes a withdrawal containing gain. What does that age exception establish?","options":["All gain becomes capital gain.","The contract must be surrendered.","The §72(q) additional tax exception can apply; ordinary income on gain can remain.","Every future distribution is excluded from income."],"answer":2,"explanations":["An age exception does not change gain to capital gain.","Age does not require surrender.","The additional tax and ordinary income tax are separate.","It does not create a blanket exclusion."],"topics":["7.3.01"],"review":4,"lesson":"51","domain":6,"explanation":"The additional tax and ordinary income tax are separate."},{"id":"L51-08","prompt":"An owner proposes a loan from a nonqualified annuity because ordinary non-MEC life loans can be treated as debt. What should the agent recognize?","options":["All insurance contracts have the same loan tax treatment.","Calling it a loan prevents distribution treatment.","Only a full surrender can realize annuity gain.","An annuity loan or pledge generally can trigger distribution treatment under its own rules."],"answer":3,"explanations":["Contract tax categories differ.","The transaction label does not override the rule.","Partial transactions also can create income.","Apply the annuity rule and the actual gain calculation."],"topics":["7.3.01"],"review":5,"lesson":"51","domain":6,"explanation":"Apply the annuity rule and the actual gain calculation."}]},{"id":"52","number":52,"title":"Annuity income, death payments and corporate ownership","version":1,"questions":[{"id":"L52-01","prompt":"A fixed nonqualified annuity’s General Rule calculation supplies $100,000 adjusted investment and $200,000 expected return. What is the exclusion percentage?","options":["50%","100%","200%","The insurer’s currently credited interest rate"],"answer":0,"explanations":["Investment divided by expected return is 50%.","That would exclude twice the supplied proportion.","That reverses the division.","A credited rate is a different measure."],"topics":["7.3.02"],"review":0,"lesson":"52","domain":6,"explanation":"Investment divided by expected return is 50%."},{"id":"L52-02","prompt":"With that 50% percentage and a fixed $20,000 annual payment, how is a full year allocated while sufficient investment remains?","options":["$20,000 excluded and $0 taxable","$10,000 investment recovery and $10,000 taxable","$0 excluded and $20,000 taxable","$5,000 investment recovery and $15,000 taxable"],"answer":1,"explanations":["Only the stated recovery portion is excluded.","Apply 50% to the $20,000 payment.","That ignores remaining investment recovery.","That uses 25%, not the stated 50%."],"topics":["7.3.02"],"review":1,"lesson":"52","domain":6,"explanation":"Apply 50% to the $20,000 payment."},{"id":"L52-03","prompt":"The annuity started in 2026 and has now returned all stated investment tax-free. What happens to later payments under these facts?","options":["Payments must stop even though lifetime income was selected.","The same 50% remains excluded indefinitely.","Continuing payments are fully taxable.","Payments become life insurance death proceeds."],"answer":2,"explanations":["The lifetime promise can continue.","Investment cannot be recovered tax-free more than once under this rule.","The recovery limit has been reached.","The contract and payment type have not changed to life death proceeds."],"topics":["7.3.02"],"review":1,"lesson":"52","domain":6,"explanation":"The recovery limit has been reached."},{"id":"L52-04","prompt":"A beneficiary receives $120,000 in a nonqualified annuity death lump sum with $80,000 unrecovered investment and no adjustment. How much is generally taxable?","options":["$0","$80,000","$120,000","$40,000"],"answer":3,"explanations":["A death trigger does not exclude all annuity earnings.","That is the investment amount.","Unrecovered investment is not taxed again.","The payment less unrecovered investment leaves $40,000 earnings."],"topics":["7.3.03"],"review":2,"lesson":"52","domain":6,"explanation":"The payment less unrecovered investment leaves $40,000 earnings."},{"id":"L52-05","prompt":"For the modern nonqualified contract described, the owner dies before the annuity starting date. What is the general distribution rule before considering specified alternatives?","options":["Distribute the entire interest within five years.","Always leave it untouched until the beneficiary reaches age 73.","Automatically pay every beneficiary tax-free over ten years.","Use only the minimum payment previously paid to the owner."],"answer":0,"explanations":["The five-year rule applies, subject to specified alternatives.","That imports unrelated retirement-account age assumptions.","Neither a universal ten-year period nor blanket exclusion follows.","The owner had not begun annuity payments."],"topics":["7.3.03"],"review":3,"lesson":"52","domain":6,"explanation":"The five-year rule applies, subject to specified alternatives."},{"id":"L52-06","prompt":"Which fact supports the statutory individual-beneficiary life-expectancy alternative after death before annuitization?","options":["Any beneficiary can postpone the first payment indefinitely.","A designated individual receives payments within the permitted life-expectancy period and begins them on time, generally within one year.","The beneficiary simply requests a higher credited rate.","The contract owner was a corporation, so deadlines cannot apply."],"answer":1,"explanations":["Timely commencement is required.","Both duration and commencement requirements matter.","An interest-rate request does not establish the alternative.","Nonindividual ownership does not create that blanket exemption."],"topics":["7.3.03"],"review":3,"lesson":"52","domain":6,"explanation":"Both duration and commencement requirements matter."},{"id":"L52-07","prompt":"An owner dies after the annuity starting date. What does the general §72(s) rule require for remaining distributions?","options":["They must restart a new accumulation period.","They always must be paid in one sum the next day.","They must be distributed at least as rapidly as under the existing method.","The beneficiary can suspend every payment for life."],"answer":2,"explanations":["The rule does not create a new deferral period.","An immediate lump sum is not universally required.","The existing distribution pace establishes the general minimum pace.","Indefinite suspension conflicts with the rule."],"topics":["7.3.03"],"review":3,"lesson":"52","domain":6,"explanation":"The existing distribution pace establishes the general minimum pace."},{"id":"L52-08","prompt":"A corporation owns all rights in a nonqualified annuity and names an employee as annuitant. No §72(u) exception applies. Which tax concern follows?","options":["Naming an individual automatically supplies individual-owner deferral.","The employee becomes owner without any assignment.","The annuity automatically becomes a qualified pension plan.","Contract income generally is subject to current ordinary income taxation under the non-natural-owner rule."],"answer":3,"explanations":["The annuitant and owner are different roles.","Naming a measuring life does not transfer ownership.","An annuity purchase alone does not establish plan qualification.","Apply the actual corporate ownership and the stated absence of an exception."],"topics":["7.3.04"],"review":4,"lesson":"52","domain":6,"explanation":"Apply the actual corporate ownership and the stated absence of an exception."},{"id":"L52-09","prompt":"Why should an agent examine a trust-owned annuity’s actual beneficial ownership before applying §72(u)?","options":["An entity genuinely holding as agent for a natural person is treated differently under the rule.","Every trust is automatically a qualified retirement plan.","Every trust makes all annuity death proceeds excluded life benefits.","The annuitant’s age eliminates all trust ownership rules."],"answer":0,"explanations":["The statute requires attention to the actual agency and ownership facts.","Trust form alone does not establish retirement qualification.","Trust ownership does not change annuity earnings to life proceeds.","Age does not replace the ownership analysis."],"topics":["7.3.04"],"review":4,"lesson":"52","domain":6,"explanation":"The statute requires attention to the actual agency and ownership facts."}]},{"id":"53","number":53,"title":"Traditional IRAs: contribution, deduction and withdrawal","version":2,"questions":[{"id":"L53-01","prompt":"Marcus, age 45, has $4,000 qualifying compensation in 2026 and no spousal contribution rule. What is his maximum regular combined traditional/Roth IRA contribution under these facts?","options":["$4,000","$7,500","$8,600","$11,500"],"answer":0,"explanations":["The lower compensation limit controls.","That ignores the lower compensation amount.","The age-50 catch-up does not apply and compensation still limits funding.","Savings plus compensation is not the rule."],"topics":["7.4.01"],"review":1,"lesson":"53","domain":6,"explanation":"The lower compensation limit controls."},{"id":"L53-02","prompt":"A 61-year-old with sufficient compensation and no other restriction asks for the 2026 general IRA dollar limit including catch-up. What is it?","options":["$8,000","$8,600","$7,500","$11,250"],"answer":1,"explanations":["That is an older year’s age-50 amount.","$7,500 plus $1,100 equals $8,600.","That omits the applicable catch-up.","That figure concerns a different employer-plan catch-up category."],"topics":["7.4.01"],"review":1,"lesson":"53","domain":6,"explanation":"$7,500 plus $1,100 equals $8,600."},{"id":"L53-03","prompt":"A taxpayer is covered by a workplace retirement plan. What should be checked before promising a deduction for a traditional IRA contribution?","options":["Only whether the contribution is below the regular annual dollar limit","Only whether the taxpayer has qualifying compensation","Filing status, modified AGI and the applicable coverage rules","Only whether the IRA is funded by a traditional fixed annuity"],"answer":2,"explanations":["The dollar limit does not settle deduction phaseouts.","Compensation relates to contribution eligibility, not the entire deduction analysis.","These facts control the relevant deduction restrictions.","The funding investment alone does not settle deductibility."],"topics":["7.4.01"],"review":2,"lesson":"53","domain":6,"explanation":"These facts control the relevant deduction restrictions."},{"id":"L53-04","prompt":"A taxpayer makes a permitted nondeductible traditional IRA contribution. Why maintain Form 8606 records?","options":["To convert every distribution into capital gain","To make the IRA jointly owned","To waive every RMD","To track after-tax basis for the required distribution allocation"],"answer":3,"explanations":["IRA basis tracking does not create capital-gain treatment.","IRAs remain individually owned.","Basis records do not eliminate RMDs.","The records support recovery of amounts already taxed."],"topics":["7.4.01","7.4.03"],"review":2,"lesson":"53","domain":6,"explanation":"The records support recovery of amounts already taxed."},{"id":"L53-05","prompt":"An IRA annuity was funded entirely with deductible contributions and untaxed earnings. What is the general treatment of its ordinary payments?","options":["Fully taxable income under those facts","Half excluded under every annuity’s 50% ratio","Entirely excluded once the owner turns 59½","Excluded as life insurance death proceeds"],"answer":0,"explanations":["There is no stated after-tax basis to recover.","The Part 52 ratio was a stated nonqualified example.","Age can affect additional tax without excluding ordinary income.","These are retirement payments, not life death proceeds."],"topics":["7.4.03"],"review":3,"lesson":"53","domain":6,"explanation":"There is no stated after-tax basis to recover."},{"id":"L53-06","prompt":"A 45-year-old takes a $6,000 taxable traditional IRA distribution with no exception. What is the usual additional federal tax?","options":["$6,000","$600","$0 because the money is for retirement","$60"],"answer":1,"explanations":["That is the taxable amount, not 10% of it.","Ten percent of $6,000 is $600, separate from ordinary income tax.","The arrangement’s purpose does not remove the early-distribution rule.","That is 1%, not 10%."],"topics":["7.4.02"],"review":3,"lesson":"53","domain":6,"explanation":"Ten percent of $6,000 is $600, separate from ordinary income tax."},{"id":"L53-07","prompt":"An owner turns 73 in 2026. If the first traditional IRA RMD is delayed to the usual final deadline, when must it be taken?","options":["December 31, 2036","April 1, 2026","April 1, 2027","Only after the owner retires"],"answer":2,"explanations":["That imports a beneficiary deadline.","The first RMD is for 2026, with the stated deadline in the following year.","The usual first deadline is April 1 of the following year.","Still working does not postpone this traditional IRA requirement."],"topics":["7.4.03"],"review":4,"lesson":"53","domain":6,"explanation":"The usual first deadline is April 1 of the following year."},{"id":"L53-08","prompt":"An owner subject to the 2026 first RMD deadline waits until April 1, 2027. When is the separate 2027 RMD generally due?","options":["April 1, 2028","December 31, 2028","It is waived because the first payment was in 2027.","December 31, 2027"],"answer":3,"explanations":["The later annual deadline is generally December 31 of that year.","This postpones a year too long.","The first payment does not waive the second year.","Two required amounts can be paid during 2027."],"topics":["7.4.03"],"review":4,"lesson":"53","domain":6,"explanation":"Two required amounts can be paid during 2027."},{"id":"L53-09","prompt":"An adult nonspouse beneficiary subject to the ten-year rule inherits from an owner who died after the required beginning date. Which warning is accurate?","options":["Annual beneficiary distributions generally apply as well as the tenth-year deadline.","No distribution can be made until the tenth year.","All inherited earnings are excluded life insurance proceeds.","The beneficiary automatically becomes the original owner."],"answer":0,"explanations":["The ten-year deadline does not automatically eliminate earlier annual requirements.","Earlier withdrawals are not prohibited.","Pretax retirement amounts retain their income-tax character.","Nonspouse beneficiaries do not have a blanket owner-election right."],"topics":["7.4.04"],"review":5,"lesson":"53","domain":6,"explanation":"The ten-year deadline does not automatically eliminate earlier annual requirements."}]},{"id":"54","number":54,"title":"Roth IRAs: distinguish contributions, conversions and earnings","version":1,"questions":[{"id":"L54-01","prompt":"Which statement correctly describes a regular Roth IRA contribution?","options":["It is not deductible.","It always reduces current taxable income.","It automatically qualifies any later earnings distribution.","It is available without compensation or income restrictions."],"answer":0,"explanations":["Regular Roth contributions use after-tax funds.","That describes a possible traditional deduction, not Roth treatment.","Later qualification has separate tests.","Roth contribution eligibility still has requirements."],"topics":["7.4.05"],"review":0,"lesson":"54","domain":6,"explanation":"Regular Roth contributions use after-tax funds."},{"id":"L54-02","prompt":"Elena is 40, has sufficient compensation, qualifies for a full direct Roth contribution, and put $3,000 into a traditional IRA for 2026. How much of the combined regular limit remains?","options":["$7,500","$4,500","$8,600","$10,500"],"answer":1,"explanations":["The traditional contribution already uses part of the combined limit.","$7,500 less $3,000 leaves $4,500.","She is not in the age-50 catch-up category.","The two accounts do not create additive full limits."],"topics":["7.4.05"],"review":1,"lesson":"54","domain":6,"explanation":"$7,500 less $3,000 leaves $4,500."},{"id":"L54-03","prompt":"A nonqualified Roth IRA distribution occurs. Which category generally is distributed first under the ordinary ordering rule?","options":["Earnings","The most recent taxable conversion","Unrecovered regular contributions","All categories in equal proportions"],"answer":2,"explanations":["Earnings normally come last.","Conversions follow regular contributions and use their own order.","Regular contributions are reached first.","This is not an equal-allocation rule."],"topics":["7.4.06"],"review":2,"lesson":"54","domain":6,"explanation":"Regular contributions are reached first."},{"id":"L54-04","prompt":"A Roth owner has $12,000 unrecovered regular contributions, $3,000 earnings and no conversions, prior distributions or adjustments. How is an ordinary $5,000 withdrawal treated?","options":["All $5,000 is taxable earnings.","$1,000 is earnings using proportional allocation.","$3,000 is earnings before contributions are used.","It recovers regular contributions without income or usual early-distribution additional tax under these facts."],"answer":3,"explanations":["Regular contributions come first.","That is not the Roth IRA ordering rule.","Earnings do not precede regular contributions.","The remaining regular contributions cover the entire withdrawal."],"topics":["7.4.06"],"review":2,"lesson":"54","domain":6,"explanation":"The remaining regular contributions cover the entire withdrawal."},{"id":"L54-05","prompt":"Rosa first contributed to a Roth IRA for 2021 and receives a distribution in 2026 at age 61. What is true of the stated qualification tests?","options":["Both the five-tax-year and age conditions are met.","The time period runs until 2031 because she is over 60.","Age alone satisfies every Roth qualification requirement.","The distribution cannot be qualified unless she stops working."],"answer":0,"explanations":["The 2021–2025 period has elapsed and she is over 59½.","Age does not add five more years to that clock.","The time test is independently required.","Retirement from work is not one of these conditions."],"topics":["7.4.06"],"review":3,"lesson":"54","domain":6,"explanation":"The 2021–2025 period has elapsed and she is over 59½."},{"id":"L54-06","prompt":"An owner first contributes for 2026 and withdraws earnings in 2026 at age 61. Why is age alone insufficient for a qualified distribution?","options":["The owner must be 73.","The five-tax-year qualification period has not been met.","Every Roth earnings payment is taxable forever.","The owner must make a conversion first."],"answer":1,"explanations":["That is not the Roth qualified-distribution age.","Age and the time test are separate.","Qualified earnings payments can be excluded.","Conversion is not required for qualification."],"topics":["7.4.06"],"review":3,"lesson":"54","domain":6,"explanation":"Age and the time test are separate."},{"id":"L54-07","prompt":"A 45-year-old withdraws amounts attributable to a taxable 2026 Roth conversion in 2028 with no exception and all relevant ordering facts satisfied. What issue should be checked?","options":["A second current deduction for the conversion","A fresh $7,500 contribution limit for the withdrawal","The conversion’s separate five-year additional-tax rule","An automatic reset to traditional IRA status"],"answer":2,"explanations":["Conversions do not provide that deduction.","A withdrawal is not a regular contribution.","Early access to taxable converted amounts can trigger recapture.","The withdrawal does not convert the arrangement back."],"topics":["7.4.06"],"review":4,"lesson":"54","domain":6,"explanation":"Early access to taxable converted amounts can trigger recapture."},{"id":"L54-08","prompt":"What is the Roth IRA owner’s lifetime RMD requirement under current law?","options":["Start at 59½.","Start at 73 in every case.","Start five years after opening.","There is no owner lifetime RMD requirement."],"answer":3,"explanations":["That age concerns a distribution qualification/exception condition.","The traditional IRA rule does not apply to a Roth owner’s lifetime.","The qualification clock is not an RMD clock.","Beneficiary rules still apply after death."],"topics":["7.4.06"],"review":5,"lesson":"54","domain":6,"explanation":"Beneficiary rules still apply after death."},{"id":"L54-09","prompt":"Why does a Roth IRA’s lifetime RMD exemption not mean an inherited Roth IRA can remain untouched forever?","options":["Beneficiary distribution rules still apply.","Every Roth becomes a traditional IRA at death.","Death erases the contribution record.","Only annuities can name a beneficiary."],"answer":0,"explanations":["The owner’s lifetime rule and beneficiary rules differ.","That automatic conversion does not occur.","Records still matter, including any remaining qualification period.","IRAs can name beneficiaries."],"topics":["7.4.06"],"review":5,"lesson":"54","domain":6,"explanation":"The owner’s lifetime rule and beneficiary rules differ."}]},{"id":"55","number":55,"title":"Move retirement money: transfer, rollover or conversion?","version":1,"questions":[{"id":"L55-01","prompt":"Rosa transfers her traditional IRA directly between trustees. How does the IRA one-rollover-per-year rule apply?","options":["It does not limit this trustee-to-trustee transfer.","It permits only one such transfer per account each year.","It imposes a mandatory 20% withholding charge.","It requires Rosa to spend the money within 60 days."],"answer":0,"explanations":["Direct trustee transfers are outside that limit.","The limit concerns covered owner-received rollovers.","That imports the employer-plan owner-payment rule.","This transaction is not a spending requirement."],"topics":["7.5.02"],"review":1,"lesson":"55","domain":6,"explanation":"Direct trustee transfers are outside that limit."},{"id":"L55-02","prompt":"An eligible plan rollover check is delivered to David but is payable to the receiving IRA for his benefit. Which fact is decisive for the direct-payment distinction?","options":["David touched the envelope.","The check is payable to the eligible receiving arrangement rather than David personally.","The check uses paper instead of an electronic transfer.","David is still under age 73."],"answer":1,"explanations":["Physical delivery alone does not determine the payee.","The named payee and direct-rollover instructions matter.","A check can implement a direct rollover.","Age alone does not establish the payment method."],"topics":["7.5.01","7.5.02"],"review":1,"lesson":"55","domain":6,"explanation":"The named payee and direct-rollover instructions matter."},{"id":"L55-03","prompt":"An ordinary eligible rollover distribution is paid personally to an owner. What is the usual rollover completion deadline without special relief?","options":["By the next birthday","Within 30 business days","Within 60 days after receipt","By the next tax-return extension date in every case"],"answer":2,"explanations":["A birthday is not the ordinary deadline.","This is not the stated rollover period.","The ordinary period runs from receipt.","Special deadlines cannot be assumed for every distribution."],"topics":["7.5.01"],"review":2,"lesson":"55","domain":6,"explanation":"The ordinary period runs from receipt."},{"id":"L55-04","prompt":"A $50,000 pretax eligible employer-plan payment to David has 20% withheld. How much cash does he receive?","options":["$50,000","$10,000","$30,000","$40,000"],"answer":3,"explanations":["The $10,000 withholding is not paid to him.","That is the withheld amount.","That subtracts 40%, not 20%.","$50,000 minus $10,000 equals $40,000."],"topics":["7.5.01"],"review":3,"lesson":"55","domain":6,"explanation":"$50,000 minus $10,000 equals $40,000."},{"id":"L55-05","prompt":"David wants to roll over that entire $50,000 while receiving only $40,000. What is required under the stated ordinary rules?","options":["Deposit the $40,000 plus $10,000 from other funds within the rollover deadline.","Deposit $40,000 and count withholding as already deposited in the IRA.","Ask the agent to label the $10,000 as a regular contribution without checking limits.","Wait indefinitely for a tax refund before completing the rollover."],"answer":0,"explanations":["A full rollover includes replacement of the withheld amount.","Withholding went to the IRS, not the receiving IRA.","A label does not replace the rollover requirement.","The usual deadline still applies."],"topics":["7.5.01"],"review":3,"lesson":"55","domain":6,"explanation":"A full rollover includes replacement of the withheld amount."},{"id":"L55-06","prompt":"An owner completed a covered IRA-to-IRA 60-day rollover six months ago. Does opening another IRA create a new rollover allowance?","options":["Yes, one allowance applies to each account.","No, the applicable 12-month restriction generally aggregates the owner’s IRAs.","Yes, if the new account uses an annuity.","Yes, as long as the owner elects zero withholding."],"answer":1,"explanations":["The rule is not account-by-account.","Opening another account does not reset the clock.","An annuity funding choice does not reset the rule.","Withholding elections do not change rollover frequency limits."],"topics":["7.5.01"],"review":4,"lesson":"55","domain":6,"explanation":"Opening another account does not reset the clock."},{"id":"L55-07","prompt":"Which amount cannot be rolled over merely by promptly depositing it into another retirement account?","options":["An otherwise eligible pretax plan distribution","An otherwise eligible IRA distribution satisfying the frequency rule","A required minimum distribution","An otherwise eligible direct plan rollover"],"answer":2,"explanations":["Eligible distributions can qualify when all requirements are met.","The question states that relevant eligibility condition is met.","An RMD is excluded from rollover eligibility.","A properly eligible direct rollover is permitted."],"topics":["7.5.01"],"review":5,"lesson":"55","domain":6,"explanation":"An RMD is excluded from rollover eligibility."},{"id":"L55-08","prompt":"Why must the agent identify a nonspouse beneficiary’s inherited IRA before arranging a transfer?","options":["Inherited IRA earnings are automatically life death proceeds.","Every beneficiary can treat it as their own IRA immediately.","An inherited account has no distribution rules.","A permitted direct transfer must preserve inherited identity and follow beneficiary restrictions."],"answer":3,"explanations":["Retirement income keeps its applicable character.","Nonspouse beneficiaries lack that blanket election.","Inherited accounts have specific rules.","The correct status and method must be maintained."],"topics":["7.5.02"],"review":5,"lesson":"55","domain":6,"explanation":"The correct status and method must be maintained."}]},{"id":"56","number":56,"title":"Section 1035: permitted exchanges do not erase every cost","version":1,"questions":[{"id":"L56-01","prompt":"Assuming all other requirements are met, which direction is permitted under §1035?","options":["Life insurance to an annuity","Annuity to life insurance","Annuity to an endowment","Endowment to life insurance"],"answer":0,"explanations":["Life-to-annuity is a permitted direction.","That reverse direction is not permitted.","That reverse direction is not permitted.","Endowment-to-life is not a permitted direction."],"topics":["7.6.01"],"review":1,"lesson":"56","domain":6,"explanation":"Life-to-annuity is a permitted direction."},{"id":"L56-02","prompt":"An owner proposes an endowment-to-endowment exchange. Which additional payment-date condition matters?","options":["The new payments must start later.","The new regular payments must begin no later than under the old contract.","Both contracts must have the same premium amount.","The owner must first receive a cash surrender check."],"answer":1,"explanations":["A later starting date fails this condition.","The statute includes this timing requirement.","Matching premiums does not replace the payment-date rule.","Owner-received cash is not required and can defeat the intended method."],"topics":["7.6.01"],"review":1,"lesson":"56","domain":6,"explanation":"The statute includes this timing requirement."},{"id":"L56-03","prompt":"Marcus wants to exchange a policy on his own life for one on a different person while claiming the same §1035 treatment. What is the concern?","options":["A different insurer can never participate.","Only the new face amount matters.","The required insured identity is not preserved.","Every policy exchange must use a cash payment to Marcus."],"answer":2,"explanations":["Different insurers can handle a qualifying exchange.","Face amount alone does not settle eligibility.","A change of insured is not simply the same contract interest continued.","A proper exchange does not require payment to the owner."],"topics":["7.6.01"],"review":2,"lesson":"56","domain":6,"explanation":"A change of insured is not simply the same contract interest continued."},{"id":"L56-04","prompt":"An insurer pays a nonqualified annuity surrender check to Rosa, who endorses it to a new insurer. What does Revenue Ruling 2007-24 establish?","options":["Endorsing the check always makes it a §1035 exchange.","She has a universal 60-day nonqualified rollover period.","All proceeds become a new IRA contribution.","The endorsement does not itself create a qualifying exchange; distribution tax rules apply."],"answer":3,"explanations":["The ruling rejects that result.","The personal contract does not get that blanket rollover rule.","An annuity surrender does not create IRA status.","Actual payment to the owner followed by reinvestment is the problem in the ruling."],"topics":["7.6.01"],"review":3,"lesson":"56","domain":6,"explanation":"Actual payment to the owner followed by reinvestment is the problem in the ruling."},{"id":"L56-05","prompt":"A fully qualifying exchange moves an $80,000 annuity with $50,000 basis into an equal-value annuity, with no cash, debt, charges or adjustments. What basis carries over?","options":["$50,000","$80,000","$30,000","$0"],"answer":0,"explanations":["The stated old basis carries into the new contract.","Current value does not automatically reset basis.","That is the deferred gain, not basis.","The investment record is not erased."],"topics":["7.6.01"],"review":4,"lesson":"56","domain":6,"explanation":"The stated old basis carries into the new contract."},{"id":"L56-06","prompt":"In that same exchange, how is the $30,000 gain treated under the stated assumptions?","options":["It is permanently erased.","It is not recognized currently; future tax treatment still matters.","It becomes a current premium deduction.","It must always be paid directly to the owner."],"answer":1,"explanations":["Nonrecognition is not permanent gain elimination.","The exchange continues the investment with the stated basis.","An exchange does not create that deduction.","Owner cash is not required."],"topics":["7.6.01"],"review":4,"lesson":"56","domain":6,"explanation":"The exchange continues the investment with the stated basis."},{"id":"L56-07","prompt":"An annuity exchange qualifies for tax nonrecognition. What should the Maryland producer still assess?","options":["Nothing, because tax eligibility proves best interest.","Only the new commission.","Surrender costs, lost benefits, new restrictions and the consumer’s actual objectives under the applicable duties.","Only whether the same company issues both contracts."],"answer":2,"explanations":["Tax and recommendation requirements are separate.","Compensation is not the sole client-interest analysis.","The whole transaction still requires review.","Issuer identity alone does not decide the recommendation."],"topics":["7.6.01"],"review":5,"lesson":"56","domain":6,"explanation":"The whole transaction still requires review."},{"id":"L56-08","prompt":"A life policy is received in exchange for a MEC. What should the agent recognize about the exchange history?","options":["The new policy is automatically non-MEC.","MEC status disappears after any insurer change.","The exchange guarantees all loans are tax-free.","The received life policy is also a MEC under the applicable rule."],"answer":3,"explanations":["The exchange does not cleanse MEC status.","Insurer change does not reset that history.","MEC loan rules still require review.","This exchange is specifically included in the MEC definition."],"topics":["7.6.01"],"review":4,"lesson":"56","domain":6,"explanation":"This exchange is specifically included in the MEC definition."}]},{"id":"57","number":57,"title":"Qualified plans: tax treatment comes with requirements","version":1,"questions":[{"id":"L57-01","prompt":"A business calls an owner’s personal savings account a qualified plan without adopting or operating a compliant arrangement. What is missing?","options":["Qualification requires compliant terms and actual operation.","Qualification requires only a high investment return.","Any account named retirement automatically qualifies.","An insurance-company account needs no legal plan requirements."],"answer":0,"explanations":["A label cannot replace the applicable requirements.","Investment performance does not create qualified status.","The account name does not create legal qualification.","An insurer funding choice does not waive plan requirements."],"topics":["8.1.01"],"review":0,"lesson":"57","domain":7,"explanation":"A label cannot replace the applicable requirements."},{"id":"L57-02","prompt":"Which use conflicts with the qualified-plan exclusive-benefit principle?","options":["Paying permitted retirement benefits to participants","Diverting plan assets to the employer’s unrelated business expenses","Maintaining assets for employee beneficiaries","Investing plan assets under the applicable plan rules"],"answer":1,"explanations":["This is the plan’s intended benefit purpose.","The assets are held for participants and beneficiaries.","Beneficiaries are within the exclusive-benefit purpose.","Proper plan investment is consistent with its purpose."],"topics":["8.1.01"],"review":0,"lesson":"57","domain":7,"explanation":"The assets are held for participants and beneficiaries."},{"id":"L57-03","prompt":"Does nondiscrimination necessarily require an equal dollar contribution for every eligible employee?","options":["Yes, compensation can never affect a formula.","Yes, every plan must use a flat dollar contribution.","No, a lawful formula can reflect compensation while meeting the applicable rules.","No, the employer may favor any selected owner without testing or limits."],"answer":2,"explanations":["Lawful formulas can reflect compensation.","Different qualifying designs use different formulas.","Equal dollars and legal nondiscrimination are different concepts.","The rules do not authorize arbitrary owner favoritism."],"topics":["8.1.01"],"review":1,"lesson":"57","domain":7,"explanation":"Equal dollars and legal nondiscrimination are different concepts."},{"id":"L57-04","prompt":"Elena has $5,000 of her own deferrals and $4,000 of employer contributions that are 60% vested. With no other adjustments, what is vested?","options":["$9,000","$5,400","$2,400","$7,400"],"answer":3,"explanations":["The employer portion is not yet fully vested.","That incorrectly applies 60% to the whole account.","That omits the fully vested employee deferrals.","$5,000 plus 60% of $4,000 is $7,400."],"topics":["8.1.01"],"review":2,"lesson":"57","domain":7,"explanation":"$5,000 plus 60% of $4,000 is $7,400."},{"id":"L57-05","prompt":"What is the general effect of an allowable employer plan-contribution deduction?","options":["It reduces the employer’s taxable income within applicable rules and limits.","It always reduces the final tax bill dollar-for-dollar.","It makes every employee distribution permanently excluded.","It lets the employer recover vested employee deferrals."],"answer":0,"explanations":["A deduction reduces the income subject to tax.","That confuses a deduction with a credit.","Later distributions have their own tax character.","A deduction does not change employee ownership rights."],"topics":["8.2.01"],"review":3,"lesson":"57","domain":7,"explanation":"A deduction reduces the income subject to tax."},{"id":"L57-06","prompt":"How is an ordinary allowed pretax employee 401(k) deferral generally treated?","options":["Excluded from every federal and payroll tax forever","Excluded from current federal income-tax wages but normally subject to applicable Social Security and Medicare taxes","Treated as an employer tax credit only","Included in current income exactly like a designated Roth deferral"],"answer":1,"explanations":["Tax deferral is not permanent exclusion from every tax.","The income-tax and payroll-tax rules differ.","This describes an employee deferral, not that credit.","Pretax and designated Roth deferrals differ currently."],"topics":["8.2.02"],"review":3,"lesson":"57","domain":7,"explanation":"The income-tax and payroll-tax rules differ."},{"id":"L57-07","prompt":"David, age 45, takes $10,000 of fully pretax qualified-plan cash with no rollover or exception. What is the usual additional tax, separate from ordinary income tax?","options":["$10,000","$100","$1,000","$0 because the plan qualified"],"answer":2,"explanations":["The 10% additional tax is not 100% of the payment.","That incorrectly uses 1%.","10% of the $10,000 taxable payment is $1,000.","Qualified status does not eliminate early-distribution tax."],"topics":["8.2.03"],"review":4,"lesson":"57","domain":7,"explanation":"10% of the $10,000 taxable payment is $1,000."},{"id":"L57-08","prompt":"Which statement correctly describes the ordinary age-55 separation exception?","options":["It applies to every IRA after age 55.","It removes ordinary income tax on all pretax payments.","It applies whenever an earlier-separated worker later reaches 55.","It can cover qualifying employer-plan distributions after separation during or after the year the employee reaches 55."],"answer":3,"explanations":["This specific exception does not apply to IRAs.","It addresses the additional tax, not all income tax.","The timing of separation itself matters.","Both the arrangement and separation timing matter."],"topics":["8.2.03"],"review":4,"lesson":"57","domain":7,"explanation":"Both the arrangement and separation timing matter."},{"id":"L57-09","prompt":"A worker turns 73 in 2026, remains with the sponsoring employer, is not a 5% owner and has a plan permitting the applicable RMD delay. What may occur?","options":["The required beginning date for that plan can be delayed until retirement.","Every traditional IRA also receives the same delay.","All prior-employer accounts automatically receive the delay.","The entire account becomes tax-free when employment ends."],"answer":0,"explanations":["The stated current-employer and ownership conditions support this delay.","Traditional IRA rules do not provide that still-working delay.","Current employment does not automatically defer former-plan requirements.","Retirement does not erase pretax income."],"topics":["8.2.03"],"review":5,"lesson":"57","domain":7,"explanation":"The stated current-employer and ownership conditions support this delay."}]},{"id":"58","number":58,"title":"Match the employer to the retirement plan","version":1,"questions":[{"id":"L58-01","prompt":"A regular SEP plan makes retirement deposits into eligible workers’ individual arrangements. Who makes the SEP plan contributions?","options":["The employer","Only employees through a new SARSEP salary election","The life-insurance beneficiary","Only employees using a 403(b) election"],"answer":0,"explanations":["Employer contributions define the regular SEP design.","A new regular SEP is not a newly established SARSEP.","A life beneficiary is unrelated to this contribution structure.","403(b) salary elections describe a different arrangement."],"topics":["8.3.01"],"review":0,"lesson":"58","domain":7,"explanation":"Employer contributions define the regular SEP design."},{"id":"L58-02","prompt":"How are employer contributions to an employee’s SEP IRA vested?","options":["Only after five years","Immediately and fully","Only at age 59½","Only after the employee contributes a matching amount"],"answer":1,"explanations":["SEP deposits are not subject to that vesting delay.","The employee immediately owns the contributions.","Tax access ages do not delay SEP ownership.","A regular SEP does not require that employee match for vesting."],"topics":["8.3.01"],"review":0,"lesson":"58","domain":7,"explanation":"The employee immediately owns the contributions."},{"id":"L58-03","prompt":"What does Keogh or HR-10 terminology generally refer to in an exam question?","options":["A specific variable-life rider","A plan available only to public-school employees","Qualified retirement-plan arrangements associated with self-employed individuals","An exemption from covering every otherwise eligible employee"],"answer":2,"explanations":["It is retirement-plan terminology, not a rider.","That describes a different sponsor category.","The older name is associated with self-employed qualified plans.","The name does not waive employee coverage requirements."],"topics":["8.3.02"],"review":1,"lesson":"58","domain":7,"explanation":"The older name is associated with self-employed qualified plans."},{"id":"L58-04","prompt":"Which statement distinguishes a profit-sharing employer contribution from a 401(k) employee-deferral feature?","options":["Profit-sharing contributions must come only from current profits.","Every 401(k) is funded only by the employer.","An employee salary election is the same as employer contribution discretion.","Profit sharing generally permits employer contribution discretion; a 401(k) feature permits employee salary deferrals."],"answer":3,"explanations":["Actual current profits are not a universal prerequisite.","Employees can elect salary deferrals.","These are different contribution decisions.","A plan can combine these distinct features."],"topics":["8.3.03"],"review":2,"lesson":"58","domain":7,"explanation":"A plan can combine these distinct features."},{"id":"L58-05","prompt":"An eligible small employer offers salary-reduction contributions and must make an allowed employer contribution, with all IRA deposits immediately vested. Which arrangement fits?","options":["SIMPLE IRA plan","Regular SEP with no salary-reduction feature","A personal nonqualified annuity alone","A life policy’s paid-up-additions option"],"answer":0,"explanations":["Those are key SIMPLE IRA characteristics.","The described employee salary-reduction feature distinguishes SIMPLE.","An investment alone does not establish those employer-plan duties.","Dividend options do not describe a retirement plan."],"topics":["8.3.04"],"review":3,"lesson":"58","domain":7,"explanation":"Those are key SIMPLE IRA characteristics."},{"id":"L58-06","prompt":"Rosa’s public school offers a plan commonly called a tax-sheltered annuity plan. Which statement is accurate about 403(b) funding?","options":["Only insurance annuity contracts are ever permitted.","A qualifying mutual-fund custodial account can be permitted as well as an annuity.","Any private for-profit employer qualifies by buying an annuity.","No employee salary reductions are allowed."],"answer":1,"explanations":["The common nickname does not describe every permitted funding form.","403(b) includes qualifying custodial-account funding.","The sponsor must meet the relevant eligibility rules.","Employee elective deferrals commonly fund 403(b) benefits."],"topics":["8.3.05"],"review":4,"lesson":"58","domain":7,"explanation":"403(b) includes qualifying custodial-account funding."},{"id":"L58-07","prompt":"A SIMPLE IRA participant takes a taxable early distribution within the first two years of participation with no exception. What usual additional-tax rate applies?","options":["2%","10% in every year","25%","0% because the funds were immediately vested"],"answer":2,"explanations":["That is not the applicable early-distribution rate.","The special initial two-year rule increases the rate.","The special rule uses 25% rather than the ordinary 10%.","Vesting establishes ownership, not exemption from tax."],"topics":["8.3.04"],"review":3,"lesson":"58","domain":7,"explanation":"The special rule uses 25% rather than the ordinary 10%."},{"id":"L58-08","prompt":"An older study sheet says SEP and SIMPLE arrangements can never permit Roth contributions. How should it be corrected?","options":["Every SEP and SIMPLE contribution is now automatically Roth.","Roth treatment depends only on choosing an annuity investment.","Roth contributions erase all beneficiary distribution rules.","Current law permits specified Roth SEP and SIMPLE options under applicable requirements."],"answer":3,"explanations":["Permitted options are not automatic treatment of all funds.","Investment choice does not make the tax election.","Beneficiary rules still need separate review.","The blanket prohibition is outdated."],"topics":["8.3.01","8.3.04"],"review":5,"lesson":"58","domain":7,"explanation":"The blanket prohibition is outdated."}]},{"id":"59","number":59,"title":"Family workshop: follow the decision from need to claim","version":1,"questions":[{"id":"L59-01","prompt":"Using the workshop’s zero-interest assumptions, what income need results from $35,000 annually for 15 years?","options":["$525,000","$350,000","$725,000","$600,000"],"answer":0,"explanations":["Multiply the annual amount by the stated 15 years.","That calculation uses only ten years.","That includes the separate immediate obligations.","That is the final gap after the other adjustments."],"topics":["3.4.05"],"review":0,"lesson":"59","domain":2,"explanation":"Multiply the annual amount by the stated 15 years."},{"id":"L59-02","prompt":"Add $200,000 of separate obligations to the $525,000 income need, then subtract $125,000 of available resources. What is the illustrative gap?","options":["$850,000","$600,000","$400,000","$725,000"],"answer":1,"explanations":["That adds resources instead of subtracting them.","$525,000 + $200,000 − $125,000 = $600,000.","That omits the separate immediate obligations.","That is the total before subtracting resources."],"topics":["3.4.02","3.4.04"],"review":0,"lesson":"59","domain":2,"explanation":"$525,000 + $200,000 − $125,000 = $600,000."},{"id":"L59-03","prompt":"Marcus owns insurance on his own life and names Elena primary beneficiary. Which statement follows?","options":["Elena’s life is automatically insured by the base policy.","Marcus cannot be both owner and insured.","Marcus holds ownership rights; Elena’s designation identifies the intended primary recipient.","Elena’s beneficiary status automatically gives her every owner right."],"answer":2,"explanations":["Beneficiary status does not insure that life.","One person can fill both distinct roles.","The stated roles have different functions.","Beneficiary rights depend on the designation and contract; they are not all owner rights."],"topics":["3.1.01","3.1.03","5.1.01"],"review":2,"lesson":"59","domain":2,"explanation":"The stated roles have different functions."},{"id":"L59-04","prompt":"Marcus submitted an application and initial premium. What should the producer check before stating that coverage has begun?","options":["Only whether Marcus remembers the quoted premium","Only whether the producer shook Marcus’s hand","Only the amount of the requested death benefit","The receipt conditions, underwriting action and applicable delivery/effective-date requirements"],"answer":3,"explanations":["Remembering a quote does not establish coverage.","A handshake does not override the relevant documents.","Requested face amount does not establish the effective date.","The actual conditions and facts determine coverage."],"topics":["3.8.13","3.8.16","3.8.17"],"review":3,"lesson":"59","domain":2,"explanation":"The actual conditions and facts determine coverage."},{"id":"L59-05","prompt":"A premium after the first is missed on a standard Maryland individual policy governed by §16-202. Which statement is correct?","options":["The required grace provision continues coverage for one month of at least 30 days.","Coverage always ends at midnight on the due date.","Every policy receives exactly a 10-day grace period.","Grace is another name for automatic reinstatement after every lapse."],"answer":0,"explanations":["That is the statutory minimum-period formulation in this scope.","The grace protection prevents that blanket conclusion.","That is not the standard individual-life requirement.","Grace and reinstatement are separate provisions."],"topics":["5.1.06","5.1.07"],"review":4,"lesson":"59","domain":4,"explanation":"That is the statutory minimum-period formulation in this scope."},{"id":"L59-06","prompt":"A covered $100,000 death claim has a $12,000 loan and $600 accrued loan interest, with no other adjustments. What is paid?","options":["$88,000","$87,400","$112,600","$100,600"],"answer":1,"explanations":["That omits the accrued interest deduction.","Both principal and accrued interest reduce the stated benefit.","The debt is deducted, not added.","Interest on the outstanding loan is not an added death benefit."],"topics":["5.5.01"],"review":5,"lesson":"59","domain":4,"explanation":"Both principal and accrued interest reduce the stated benefit."},{"id":"L59-07","prompt":"Why should the family avoid counting the same mortgage payments both in a payoff amount and again in survivor income needs?","options":["Mortgage debt can never be a coverage need.","Only gross salary can be used to estimate protection.","That double counts the same obligation and can overstate the estimate.","Existing resources must always be ignored."],"answer":2,"explanations":["A payoff can be a legitimate stated need.","Needs analysis can use specific household obligations.","Separate categories must avoid overlapping amounts.","Genuinely available resources matter to the gap."],"topics":["3.4.02","3.4.03"],"review":0,"lesson":"59","domain":2,"explanation":"Separate categories must avoid overlapping amounts."},{"id":"L59-08","prompt":"What should be assessed before replacing the family’s existing life policy?","options":["Only the new illustrated cash value","Only whether the new premium is lower in year one","Only whether the new policy has the same face amount","Required replacement duties, lost benefits, costs, guarantees and the family’s actual needs"],"answer":3,"explanations":["An illustration alone omits other material consequences.","First-year price alone does not establish a better result.","Matching face amounts does not make contracts equivalent.","The whole transaction and applicable duties require review."],"topics":["3.8.06"],"review":1,"lesson":"59","domain":2,"explanation":"The whole transaction and applicable duties require review."}]},{"id":"60","number":60,"title":"Business and retirement workshop: put the rules together","version":1,"questions":[{"id":"L60-01","prompt":"A company wants money to recruit and train a replacement if an essential employee dies. Which purpose is described?","options":["Key-person business protection","A cross-purchase obligation to buy shares in every case","A family contingent-beneficiary designation","An annuity certain-period income guarantee"],"answer":0,"explanations":["The stated loss is the business’s loss of essential services.","No ownership-purchase obligation is stated.","That describes family claim recipients, not the business loss.","The question concerns death protection, not annuity income."],"topics":["3.5.02"],"review":0,"lesson":"60","domain":2,"explanation":"The stated loss is the business’s loss of essential services."},{"id":"L60-02","prompt":"Under a stated cross-purchase buy-sell funding arrangement, who typically owns the policies on the other owners?","options":["Only an outside lender","The individual business owners","Only the deceased owner’s children","The insurance regulator"],"answer":1,"explanations":["A lender is not the ordinary cross-purchase policyowner.","The owners fund their purchase obligations through the stated arrangement.","Family beneficiaries are not the stated purchasing owners.","The regulator is not a party funding the purchase."],"topics":["3.5.01"],"review":0,"lesson":"60","domain":2,"explanation":"The owners fund their purchase obligations through the stated arrangement."},{"id":"L60-03","prompt":"David properly completes a direct rollover of eligible pretax 401(k) funds into a traditional IRA. Which statement follows from those facts?","options":["It automatically converts the full amount into Roth income.","It requires 20% of the direct payment to be withheld.","Mandatory 20% withholding does not apply to that direct rollover payment.","It uses David’s regular annual IRA contribution allowance."],"answer":2,"explanations":["The stated destination is traditional, not Roth.","Mandatory owner-payment withholding differs from this direct method.","The eligible direct payment avoids that withholding.","An eligible rollover is distinct from a regular annual contribution."],"topics":["7.5.01","7.5.02"],"review":1,"lesson":"60","domain":6,"explanation":"The eligible direct payment avoids that withholding."},{"id":"L60-04","prompt":"Why is additional tax deferral alone an inadequate reason to put an annuity inside a traditional IRA?","options":["IRAs can never hold annuities.","Every annuity in an IRA guarantees the highest income.","Annuities in IRAs are always immediately liquid.","The IRA already provides tax deferral; the annuity’s other features and costs need evaluation."],"answer":3,"explanations":["The issue is the reason for the choice, not a blanket prohibition.","No such universal income guarantee follows.","Surrender terms and other restrictions can apply.","Tax deferral already exists at the account level."],"topics":["6.5.03","6.5.04"],"review":1,"lesson":"60","domain":5,"explanation":"Tax deferral already exists at the account level."},{"id":"L60-05","prompt":"Rosa dies after 24 monthly payments from a life-with-10-year-certain option promising 120 minimum monthly payments. Under the stated facts, how many guaranteed monthly payments remain?","options":["96","120","24","0"],"answer":0,"explanations":["120 guaranteed payments minus 24 paid leaves 96.","That ignores the payments already made.","That is the number paid, not the remainder.","That would confuse the option with pure life."],"topics":["6.3.02"],"review":3,"lesson":"60","domain":5,"explanation":"120 guaranteed payments minus 24 paid leaves 96."},{"id":"L60-06","prompt":"Rosa is still living after ten years under that life-with-10-year-certain option. What happens to the stated lifetime income?","options":["It stops automatically at the end of the certain period.","It continues while she lives.","It becomes a death benefit for her beneficiary immediately.","It must convert into a new IRA without her election."],"answer":1,"explanations":["The certain period is a minimum guarantee, not a maximum life-payment term.","The option includes lifetime payments as well as the minimum period.","She is living, and the contract still provides lifetime income.","No automatic IRA conversion follows from the payment guarantee."],"topics":["6.3.01","6.3.02"],"review":3,"lesson":"60","domain":5,"explanation":"The option includes lifetime payments as well as the minimum period."},{"id":"L60-07","prompt":"David’s stated 2020 nonqualified annuity has $90,000 value and $60,000 basis. He takes a $20,000 ordinary partial withdrawal before annuitization. How much is taxable under the stated facts?","options":["$0","$6,666.67","$20,000","$30,000"],"answer":2,"explanations":["There is enough gain to cover the whole withdrawal.","A simple proportional allocation is not the stated gain-first rule.","The $30,000 gain is reached first, covering all $20,000 withdrawn.","That is the gain in the contract, but only $20,000 was withdrawn."],"topics":["7.3.01"],"review":4,"lesson":"60","domain":6,"explanation":"The $30,000 gain is reached first, covering all $20,000 withdrawn."},{"id":"L60-08","prompt":"David is 64 when taking that taxable partial annuity withdrawal. Which statement is correct?","options":["His age excludes all income tax on the withdrawal.","His age automatically adds a 25% SIMPLE tax.","Every annuity withdrawal at any age has the usual 10% early-age additional tax.","The ordinary age-based 10% additional tax does not apply, while income tax still can."],"answer":3,"explanations":["Age relief from an additional tax is not income exclusion.","This is a personal nonqualified annuity, not the stated SIMPLE case.","The usual early-age rule does not apply at 64.","Keep ordinary income tax separate from the additional-age rule."],"topics":["7.3.01"],"review":4,"lesson":"60","domain":6,"explanation":"Keep ordinary income tax separate from the additional-age rule."}]}]};
